INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51560, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が切れ目なく続くこと。また、そのさま。", "primary_collocate": null, "pronunciation": "れんぞく", "ipa": "ɾeɲzokɯ", "syllable_count": 4, "sentences": [{"text": "最初の一年は、美しい田園風景とは裏腹に、泥にまみれた過酷な肉体労働の連続でした。", "target_word": "連続", "complexity_tier": "T3", "furigana": "最初[さいしょ]の一年[いちねん]は、美[うつく]しい田園風景[でんえんふうけい]とは裏腹[うらはら]に、泥[どろ]にまみれた過酷[かこく]な肉体労働[にくたいろうどう]の連続[れんぞく]でした。", "sentence_source": "mined"}, {"text": "十日連続で雨が降り、洗濯物が乾かなかった。", "target_word": "連続", "complexity_tier": "T3", "furigana": "十日[とおか]連続[れんぞく]で雨[あめ]が降[ふ]り、洗濯物[せんたくもの]が乾[かわ]かなかった。", "sentence_source": "generated"}, {"text": "彼は三年連続で大会に出場している。", "target_word": "連続", "complexity_tier": "T3", "furigana": "彼[かれ]は三年[さんねん]連続[れんぞく]で大会[たいかい]に出場[しゅつじょう]している。", "sentence_source": "generated"}, {"text": "工事の音が朝から連続して聞こえ、頭が痛くなった。", "target_word": "連続", "complexity_tier": "T3", "furigana": "工事[こうじ]の音[おと]が朝[あさ]から連続[れんぞく]して聞[き]こえ、頭[あたま]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "今日は会議の連続で、昼食をとる時間もなかった。", "target_word": "連続", "complexity_tier": "T3", "furigana": "今日[きょう]は会議[かいぎ]の連続[れんぞく]で、昼食[ちゅうしょく]をとる時間[じかん]もなかった。", "sentence_source": "generated"}, {"text": "連続した休みが取れたので、旅行に出かけた。", "target_word": "連続", "complexity_tier": "T3", "furigana": "連続[れんぞく]した休[やす]みが取[と]れたので、旅行[りょこう]に出[で]かけた。", "sentence_source": "generated"}, {"text": "彼女は五試合連続でゴールを決めた。", "target_word": "連続", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は五試合[ごしあい]連続[れんぞく]でゴールを決[き]めた。", "sentence_source": "generated"}, {"text": "睡眠は連続して取るほうが体によいと言われる。", "target_word": "連続", "complexity_tier": "T3", "furigana": "睡眠[すいみん]は連続[れんぞく]して取[と]るほうが体[からだ]によいと言[い]われる。", "sentence_source": "generated"}, {"text": "失敗の連続でも、彼はあきらめなかった。", "target_word": "連続", "complexity_tier": "T3", "furigana": "失敗[しっぱい]の連続[れんぞく]でも、彼[かれ]はあきらめなかった。", "sentence_source": "generated"}, {"text": "夜道で連続した小さな音が聞こえて、足を止めた。", "target_word": "連続", "complexity_tier": "T3", "furigana": "夜道[よみち]で連続[れんぞく]した小[ちい]さな音[おと]が聞[き]こえて、足[あし]を止[と]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連続する", "label": "終止形"}, {"form": "連続して", "label": "て形"}, {"form": "連続した", "label": "た形"}, {"form": "連続で", "label": "で格"}], "register": "neutral", "sense_fingerprint": "物事が途切れずに続くこと・続いている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7d6c3d-f83b-4e4e-9225-ca1e02731215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51560, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連続", "is_correct": true, "explanation": "「肉体労働の連続」で、苦しい労働が途切れず続いたという意味になり、文に合う。"}, {"text": "沈黙", "is_correct": false, "explanation": "「沈黙」は声や音がない状態の意味で、労働の説明にならない。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹」はお腹がすいた状態の意味で、労働の内容を表せない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は空模様の意味で、肉体労働の説明には合わない。"}], "explanations": {"連続": "「肉体労働の連続」で、苦しい労働が途切れず続いたという意味になり、文に合う。", "沈黙": "「沈黙」は声や音がない状態の意味で、労働の説明にならない。", "空腹": "「空腹」はお腹がすいた状態の意味で、労働の内容を表せない。", "天気": "「天気」は空模様の意味で、肉体労働の説明には合わない。"}, "sentence_index": 0, "correct_answer": "連続"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父が残した財産を連続した。", "explanation": "ここは〈相続〉の意味。連続は同じことが続くことで、財産を受け継ぐ意味はない。"}, {"text": "食料を被災地に連続した。", "explanation": "ここは〈配給〉の意味。物資を配って届ける意味は連続では表せない。"}, {"text": "会期を二週間連続した。", "explanation": "ここは〈延長〉の意味。連続は期間を長くすることではないので、会期を延ばす場合には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51560, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連続", "is_correct": true, "explanation": "「五試合連続で」は続けて試合に出たという意味で、文に合う。"}, {"text": "中止", "is_correct": false, "explanation": "「五試合中止で」は試合が取りやめになる意味で、ゴールを決めた文と矛盾する。"}, {"text": "謙遜", "is_correct": false, "explanation": "「謙遜」は控えめな態度の意味で、試合数を表せない。"}, {"text": "好評", "is_correct": false, "explanation": "「好評」は人気の意味で、試合の数の説明にならない。"}], "explanations": {"連続": "「五試合連続で」は続けて試合に出たという意味で、文に合う。", "中止": "「五試合中止で」は試合が取りやめになる意味で、ゴールを決めた文と矛盾する。", "謙遜": "「謙遜」は控えめな態度の意味で、試合数を表せない。", "好評": "「好評」は人気の意味で、試合の数の説明にならない。"}, "sentence_index": 6, "correct_answer": "連続"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二台の機械を連続した。", "explanation": "ここは〈接続〉の意味。機械をつなぐことは連続では表せない。"}, {"text": "ごみが公園のあちこちに連続していた。", "explanation": "ここは〈散在〉の意味。点々と散らばる様子は連続では表せない。"}, {"text": "書類をデータとして連続した。", "explanation": "ここは〈保存〉の意味。書類を残しておく意味は連続にはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51560, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は四年連続に大会に出場した。", "corrected_sentence": "私は四年連続で大会に出場した。", "error_description": "「連続」に続く助詞が「に」になっている。副詞的に「連続で」と使うのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51560, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警報が連続を鳴り、住民は避難した。", "corrected_sentence": "警報が連続して鳴り、住民は避難した。", "error_description": "「連続」に続く「を」が誤り。「連続して」で動詞「鳴る」を修飾する形が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51561, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作り上げる」の対象（目的語）は「を」で示す。「強い肉体を作り上げた」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」を使うと肉体が主語になり、作り上げる主体が彼である文と合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」で名詞をつなぐと、「作り上げた」が続く文の形にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、「肉体と作り上げた」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「作り上げる」の対象（目的語）は「を」で示す。「強い肉体を作り上げた」が正しい。", "が": "「が」を使うと肉体が主語になり、作り上げる主体が彼である文と合わない。", "の": "「の」で名詞をつなぐと、「作り上げた」が続く文の形にならない。", "と": "「と」は相手や並列を示すので、「肉体と作り上げた」では意味が通らない。"}, "error_tags": {"が": "主語", "の": "名詞をつなぐ形では文が成立しない", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51561, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「酷使する」の対象（目的語）は「を」で示す。「肉体を酷使する」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」を使うと肉体が主語になり、酷使する主体が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「酷使する」は対象を「を」で示すので、「に」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、「肉体と酷使する」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「酷使する」の対象（目的語）は「を」で示す。「肉体を酷使する」が正しい。", "が": "「が」を使うと肉体が主語になり、酷使する主体が合わない。", "に": "「酷使する」は対象を「を」で示すので、「に」では文が成り立たない。", "と": "「と」は相手や並列を示すので、「肉体と酷使する」では文が成り立たない。"}, "error_tags": {"が": "主語", "に": "酷使の対象を示さない", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51561, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人のからだのこと。", "primary_collocate": null, "pronunciation": "にくたい", "ipa": "nikɯtai", "syllable_count": 4, "sentences": [{"text": "年をとると、肉体は少しずつ衰えていく。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "年[とし]をとると、肉体[にくたい]は少[すこ]しずつ衰[おとろ]えていく。", "sentence_source": "generated"}, {"text": "彼は毎日鍛えて、強い肉体を作り上げた。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "彼[かれ]は毎日[まいにち]鍛[きた]えて、強[つよ]い肉体[にくたい]を作[つく]り上[あ]げた。", "sentence_source": "generated"}, {"text": "肉体はつかれていても、心は元気だった。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "肉体[にくたい]はつかれていても、心[こころ]は元気[げんき]だった。", "sentence_source": "generated"}, {"text": "この映画では、俳優の鍛えられた肉体が話題になった。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "この映画[えいが]では、俳優[はいゆう]の鍛[きた]えられた肉体[にくたい]が話題[わだい]になった。", "sentence_source": "generated"}, {"text": "肉体が滅んでも、思い出は人の心に残る。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "肉体[にくたい]が滅[ほろ]んでも、思[おも]い出[で]は人[ひと]の心[こころ]に残[のこ]る。", "sentence_source": "generated"}, {"text": "長い旅で、肉体と精神の両方がつかれた。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "長[なが]い旅[たび]で、肉体[にくたい]と精神[せいしん]の両方[りょうほう]がつかれた。", "sentence_source": "generated"}, {"text": "彼女は肉体の美しさより、心の強さを大切にしている。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は肉体[にくたい]の美[うつく]しさより、心[こころ]の強[つよ]さを大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "肉体を酷使する仕事を続けたせいで、四十代で腰を痛めた。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "肉体[にくたい]を酷使[こくし]する仕事[しごと]を続[つづ]けたせいで、四十代[よんじゅうだい]で腰[こし]を痛[いた]めた。", "sentence_source": "generated"}, {"text": "若いころの肉体には、もう戻れない。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "若[わか]いころの肉体[にくたい]には、もう戻[もど]れない。", "sentence_source": "generated"}, {"text": "医者は、患者の肉体だけでなく、心の状態にも気を配る。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、患者[かんじゃ]の肉体[にくたい]だけでなく、心[こころ]の状態[じょうたい]にも気[き]を配[くば]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "肉体", "label": "基本形"}], "register": "やや硬い", "sense_fingerprint": "心や精神に対する、人の体そのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51561, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肉体", "is_correct": true, "explanation": "人のからだを指す「肉体」が、年をとると衰えるものとして自然につながる。"}, {"text": "会社", "is_correct": false, "explanation": "会社は衰えていくものとして文が成り立たないので合わない。"}, {"text": "予算", "is_correct": false, "explanation": "予算は年をとると衰えるものではないので、この文の主語として合わない。"}, {"text": "家計", "is_correct": false, "explanation": "家計は人の年齢と結びつく主語ではなく、衰えていく文には合わない。"}], "explanations": {"肉体": "人のからだを指す「肉体」が、年をとると衰えるものとして自然につながる。", "会社": "会社は衰えていくものとして文が成り立たないので合わない。", "予算": "予算は年をとると衰えるものではないので、この文の主語として合わない。", "家計": "家計は人の年齢と結びつく主語ではなく、衰えていく文には合わない。"}, "sentence_index": 0, "correct_answer": "肉体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の肉体は、やわらかくて味が濃い。", "explanation": "ここは「肉」の意味。食材の肉は肉体とは言わず、人のからだを指す肉体は使わない。"}, {"text": "会議で肉体の意見が割れた。", "explanation": "ここは「意見」の意味。考えや主張は意見と言い、人のからだを指す肉体とは合わない。"}, {"text": "寝不足が続き、肉体が大きく落ちてしまった。", "explanation": "ここは「体力」の意味。からだの力や耐える力は体力と言い、からだそのものを指す肉体とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51561, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肉体", "is_correct": true, "explanation": "人のからだを指す「肉体」が、心と並べて美しさを語る対象として自然につながる。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は美しさを比べる対象にならないので、この文には合わない。"}, {"text": "予算", "is_correct": false, "explanation": "予算には美しさを語る性質がなく、心の強さと比べる文には合わない。"}, {"text": "手続き", "is_correct": false, "explanation": "手続きは美しさを語る対象ではないので、この文の主語として合わない。"}], "explanations": {"肉体": "人のからだを指す「肉体」が、心と並べて美しさを語る対象として自然につながる。", "郵便": "郵便は美しさを比べる対象にならないので、この文には合わない。", "予算": "予算には美しさを語る性質がなく、心の強さと比べる文には合わない。", "手続き": "手続きは美しさを語る対象ではないので、この文の主語として合わない。"}, "sentence_index": 6, "correct_answer": "肉体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この市場の肉体は、ここ数年で大きく変わった。", "explanation": "ここは「市場」の意味。取引の場や需要の状態は市場と言い、人のからだを指す肉体とは合わない。"}, {"text": "医者は、患者の肉体を毎朝量っている。", "explanation": "ここは「体重」の意味。量れるのは体重で、肉体そのものは量る対象ではない。"}, {"text": "台風の肉体が、夜になって九州を通過した。", "explanation": "ここは「勢力」の意味。台風の強さは勢力と言い、人のからだを指す肉体は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51561, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日、肉体が鍛えて、強い体を作る。", "corrected_sentence": "毎日、肉体を鍛えて、強い体を作る。", "error_description": "誤りは「肉体が」の「が」。「鍛える」の対象は目的語なので「を」で示す。「肉体が鍛えて」では肉体が主語になり、文が成り立たない。「肉体を鍛えて」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51561, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医者は、患者の肉体にいたわる言葉をかけた。", "corrected_sentence": "医者は、患者の肉体をいたわる言葉をかけた。", "error_description": "誤りは「肉体に」の「に」。「いたわる」は対象を「を」で示す動詞。「肉体にいたわる」は誤りで、「肉体をいたわる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51563, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "矮小", "is_correct": true, "explanation": "「壮大」の対義語。ちっぽけで小さい様子で、とても大きく圧倒的な意味と対になる。"}, {"text": "繊細", "is_correct": false, "explanation": "細やかで感じやすい様子を言う語で、規模の大小とは関係しない。"}, {"text": "地味", "is_correct": false, "explanation": "派手さのない様子を言う語で、規模の大小を表すわけではないので対義語にならない。"}, {"text": "穏やか", "is_correct": false, "explanation": "波風のない落ち着いた様子を言う語で、規模の大きさとは関係しない。"}], "correct_answer": "矮小", "explanations": {"矮小": "「壮大」の対義語。ちっぽけで小さい様子で、とても大きく圧倒的な意味と対になる。", "繊細": "細やかで感じやすい様子を言う語で、規模の大小とは関係しない。", "地味": "派手さのない様子を言う語で、規模の大小を表すわけではないので対義語にならない。", "穏やか": "波風のない落ち着いた様子を言う語で、規模の大きさとは関係しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
