INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51563, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても大きくて、すごいこと。", "primary_collocate": null, "pronunciation": "そうだい", "ipa": "soːdai", "syllable_count": 4, "sentences": [{"text": "富士山の壮大な姿に、誰もが見とれた。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "富士山[ふじさん]の壮大[そうだい]な姿[すがた]に、誰[だれ]もが見[み]とれた。", "sentence_source": "generated"}, {"text": "壮大な自然の中で、小さな悩みを忘れた。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "壮大[そうだい]な自然[しぜん]の中[なか]で、小[ちい]さな悩[なや]みを忘[わす]れた。", "sentence_source": "generated"}, {"text": "彼の話は壮大すぎて、現実とは思えなかった。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は壮大[そうだい]すぎて、現実[げんじつ]とは思[おも]えなかった。", "sentence_source": "generated"}, {"text": "大草原の壮大な広がりを前に、私たちは言葉を失った。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "大草原[だいそうげん]の壮大[そうだい]な広[ひろ]がりを前[まえ]に、私[わたし]たちは言葉[ことば]を失[うしな]った。", "sentence_source": "generated"}, {"text": "夜空いっぱいに広がる壮大な星の海を見上げた。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "夜空[よぞら]いっぱいに広[ひろ]がる壮大[そうだい]な星[ほし]の海[うみ]を見上[みあ]げた。", "sentence_source": "generated"}, {"text": "壮大な城の門をくぐると、広い庭が見えた。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "壮大[そうだい]な城[しろ]の門[もん]をくぐると、広[ひろ]い庭[にわ]が見[み]えた。", "sentence_source": "generated"}, {"text": "子どもの頃、壮大な冒険の物語に夢中になった。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "子[こ]どもの頃[ころ]、壮大[そうだい]な冒険[ぼうけん]の物語[ものがたり]に夢中[むちゅう]になった。", "sentence_source": "generated"}, {"text": "壮大な計画だが、お金も人も足りない。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "壮大[そうだい]な計画[けいかく]だが、お金[かね]も人[ひと]も足[た]りない。", "sentence_source": "generated"}, {"text": "グランドキャニオンは、壮大な谷として知られている。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "グランドキャニオンは、壮大[そうだい]な谷[たに]として知[し]られている。", "sentence_source": "generated"}, {"text": "彼は壮大な話をするのが好きで、いつも皆を笑わせる。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "彼[かれ]は壮大[そうだい]な話[はなし]をするのが好[す]きで、いつも皆[みな]を笑[わら]わせる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "壮大だ", "label": "終止形"}, {"form": "壮大な", "label": "連体形"}, {"form": "壮大に", "label": "連用形"}, {"form": "壮大で", "label": "連用形(で)"}], "register": "neutral", "sense_fingerprint": "とても大きくて圧倒されるほどすごいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7d6c3d-f83b-4e4e-9225-ca1e02731215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51563, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "壮大", "is_correct": true, "explanation": "「富士山の壮大な姿」の、とても大きく圧倒されるさまを表す語で、文脈に合う。"}, {"text": "元気", "is_correct": false, "explanation": "「元気な姿」は人や生き物の活力を言う語で、山の姿には使わないので文に入らない。"}, {"text": "器用", "is_correct": false, "explanation": "「器用な姿」は手際の良さを言う語で、山の姿を修飾すると不自然になる。"}, {"text": "健気", "is_correct": false, "explanation": "「健気な姿」は人のひたむきさを言う語で、山には使えない。"}], "explanations": {"壮大": "「富士山の壮大な姿」の、とても大きく圧倒されるさまを表す語で、文脈に合う。", "元気": "「元気な姿」は人や生き物の活力を言う語で、山の姿には使わないので文に入らない。", "器用": "「器用な姿」は手際の良さを言う語で、山の姿を修飾すると不自然になる。", "健気": "「健気な姿」は人のひたむきさを言う語で、山には使えない。"}, "sentence_index": 0, "correct_answer": "壮大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は壮大な人で、家族をずっと支えてきた。", "explanation": "ここは〈偉大〉の意味。人の立派さや功績の大きさを言う語で、壮大は人の性質には使わない。"}, {"text": "台風は壮大な被害をもたらし、町は一週間停電した。", "explanation": "ここは〈甚大〉の意味。損害の大きさを言う語で、壮大は被害の程度には使わない。"}, {"text": "彼女は壮大な人見知りで、客が来ると隠れてしまう。", "explanation": "ここは〈内気〉の意味。人見知りの様子は壮大では表せず、規模の大きさとは関係ない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51563, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "壮大", "is_correct": true, "explanation": "「子どもの頃、壮大な冒険の物語」の、とても大きくすごいさまを表す語で、文脈に合う。"}, {"text": "平気", "is_correct": false, "explanation": "「平気な冒険の物語」は心の平然さを言う語で、物語を修飾すると不自然になる。"}, {"text": "健康", "is_correct": false, "explanation": "「健康な冒険の物語」は人や体の状態を言う語で、物語には使えない。"}, {"text": "不器用", "is_correct": false, "explanation": "「不器用な冒険の物語」は手際の悪さを言う語で、物語の修飾にはならない。"}], "explanations": {"壮大": "「子どもの頃、壮大な冒険の物語」の、とても大きくすごいさまを表す語で、文脈に合う。", "平気": "「平気な冒険の物語」は心の平然さを言う語で、物語を修飾すると不自然になる。", "健康": "「健康な冒険の物語」は人や体の状態を言う語で、物語には使えない。", "不器用": "「不器用な冒険の物語」は手際の悪さを言う語で、物語の修飾にはならない。"}, "sentence_index": 6, "correct_answer": "壮大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その男は壮大な性格で、初対面の人ともすぐ打ち解けた。", "explanation": "ここは〈陽気〉の意味。明るく人懐っこい性格を言う語で、壮大は人の性格には使わない。"}, {"text": "その店には壮大な宝石が並んでいた。", "explanation": "ここは〈高価〉の意味。値段が高いことを言う語で、大きさや迫力の壮大とは合わない。"}, {"text": "その会社は壮大な包装をして、ゴミが増えた。", "explanation": "ここは〈過剰〉の意味。必要以上に多いことを言う語で、壮大は包装の程度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51563, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜空いっぱいに広がる壮大の銀河を見上げた。", "corrected_sentence": "夜空いっぱいに広がる壮大な銀河を見上げた。", "error_description": "名詞を修飾するときは「壮大な」。「壮大の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "壮大", "is_correct": true, "explanation": "「な」の前に置く語幹で、「壮大な自然」の形に合う。"}, {"text": "壮大だ", "is_correct": false, "explanation": "終止形。「な」の前には置けないので、「自然」を修飾できない。"}, {"text": "壮大に", "is_correct": false, "explanation": "連用形。名詞を直接修飾できないので、「自然」の前には入らない。"}, {"text": "壮大で", "is_correct": false, "explanation": "連用形（で）。名詞の直前には置けないので、この位置では不自然になる。"}], "correct_form": "壮大", "base_form": "壮大だ", "form_label": "連体形の語幹", "sentence_index": 1, "explanations": {"壮大": "「な」の前に置く語幹で、「壮大な自然」の形に合う。", "壮大だ": "終止形。「な」の前には置けないので、「自然」を修飾できない。", "壮大に": "連用形。名詞を直接修飾できないので、「自然」の前には入らない。", "壮大で": "連用形（で）。名詞の直前には置けないので、この位置では不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51563, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その寺は壮大くて、見る人を圧倒する。", "corrected_sentence": "その寺は壮大で、見る人を圧倒する。", "error_description": "「壮大で」が正しい連用形（で）。「壮大くて」は形容詞の活用で誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "壮大", "is_correct": true, "explanation": "「壮大な計画だが」の「な」の前に置く語幹で、名詞を修飾する形に合う。"}, {"text": "壮大さ", "is_correct": false, "explanation": "名詞化した形。「な」の前には置けないので、「計画」を修飾できない。"}, {"text": "壮大すぎ", "is_correct": false, "explanation": "程度を表す形。「すぎ」の後に「な」は続かないので、ここでは合わない。"}, {"text": "壮大化", "is_correct": false, "explanation": "動詞化の接尾語を付けた形。「な」の前には置けず、「計画」を修飾できない。"}], "correct_form": "壮大", "base_form": "壮大だ", "form_label": "連体形の語幹", "sentence_index": 7, "explanations": {"壮大": "「壮大な計画だが」の「な」の前に置く語幹で、名詞を修飾する形に合う。", "壮大さ": "名詞化した形。「な」の前には置けないので、「計画」を修飾できない。", "壮大すぎ": "程度を表す形。「すぎ」の後に「な」は続かないので、ここでは合わない。", "壮大化": "動詞化の接尾語を付けた形。「な」の前には置けず、「計画」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51564, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "矮小", "is_correct": true, "explanation": "「壮大」の対義語。規模が小さくちっぽけな様子で、規模が大きく立派な意味と対になる。"}, {"text": "平穏", "is_correct": false, "explanation": "波風のない穏やかな状態で、規模の大小とは関係しないので対義語にならない。"}, {"text": "軽快", "is_correct": false, "explanation": "身軽で弾むような動きを言う語で、規模の大きさとは対にならない。"}, {"text": "繊細", "is_correct": false, "explanation": "細やかで感じやすい様子を言う語で、規模の大小とは関係しない。"}], "correct_answer": "矮小", "explanations": {"矮小": "「壮大」の対義語。規模が小さくちっぽけな様子で、規模が大きく立派な意味と対になる。", "平穏": "波風のない穏やかな状態で、規模の大小とは関係しないので対義語にならない。", "軽快": "身軽で弾むような動きを言う語で、規模の大きさとは対にならない。", "繊細": "細やかで感じやすい様子を言う語で、規模の大小とは関係しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
