INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51564, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "規模が大きく、立派で力強い様子。", "primary_collocate": null, "pronunciation": "そうだい", "ipa": "soːdai", "syllable_count": 4, "sentences": [{"text": "しかし、農薬を使わずに野菜を育てるという仕事を通じて、彼は自然の厳しさと、土が命を育むという壮大な仕組みを、自らの肌で実感していくことになります。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "しかし、農薬[のうやく]を使[つか]わずに野菜[やさい]を育[そだ]てるという仕事[しごと]を通[つう]じて、彼[かれ]は自然[しぜん]の厳[きび]しさと、土[つち]が命[いのち]を育[はぐく]むという壮大[そうだい]な仕組[しく]みを、自[みずか]らの肌[はだ]で実感[じっかん]していくことになります。", "sentence_source": "mined"}, {"text": "山の上から、壮大な景色が広がっていた。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]から、壮大[そうだい]な景色[けしき]が広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "彼は世界中を旅するという壮大な計画を立てた。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "彼[かれ]は世界中[せかいじゅう]を旅[たび]するという壮大[そうだい]な計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "オーケストラの壮大な演奏に、観客は息をのんだ。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "オーケストラの壮大[そうだい]な演奏[えんそう]に、観客[かんきゃく]は息[いき]をのんだ。", "sentence_source": "generated"}, {"text": "壮大なスケールの物語で、読み終えるまで三日かかった。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "壮大[そうだい]なスケールの物語[ものがたり]で、読[よ]み終[お]えるまで三日[みっか]かかった。", "sentence_source": "generated"}, {"text": "その寺は壮大な建物で、見る人を圧倒する。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "その寺[てら]は壮大[そうだい]な建物[たてもの]で、見[み]る人[ひと]を圧倒[あっとう]する。", "sentence_source": "generated"}, {"text": "宇宙の壮大な歴史を、図を使って学んだ。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]の壮大[そうだい]な歴史[れきし]を、図[ず]を使[つか]って学[まな]んだ。", "sentence_source": "generated"}, {"text": "滝の壮大な迫力に、思わず声が出た。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "滝[たき]の壮大[そうだい]な迫力[はくりょく]に、思[おも]わず声[こえ]が出[で]た。", "sentence_source": "generated"}, {"text": "壮大な夢を持つ若者を、町の人たちが応援した。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "壮大[そうだい]な夢[ゆめ]を持[も]つ若者[わかもの]を、町[まち]の人[ひと]たちが応援[おうえん]した。", "sentence_source": "generated"}, {"text": "映画は壮大な音楽とともに幕を閉じた。", "target_word": "壮大", "complexity_tier": "T3", "furigana": "映画[えいが]は壮大[そうだい]な音楽[おんがく]とともに幕[まく]を閉[と]じた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "壮大だ", "label": "終止形"}, {"form": "壮大な", "label": "連体形"}, {"form": "壮大に", "label": "連用形"}, {"form": "壮大で", "label": "連用形(で)"}], "register": "neutral", "sense_fingerprint": "規模が大きく立派で力強いさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7d6c3d-f83b-4e4e-9225-ca1e02731215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51564, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "壮大", "is_correct": true, "explanation": "「土が命を育むという壮大な仕組み」の規模の大きさを表す語で、文脈に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気な仕組み」は人の明るい性質を言う語で、仕組みには使えないので文に入らない。"}, {"text": "元気", "is_correct": false, "explanation": "「元気な仕組み」は人の活力を言う語で、仕組みを修飾すると不自然で文が通らない。"}, {"text": "平気", "is_correct": false, "explanation": "「平気な仕組み」は心の平然さを表す語で、仕組みには使えないので文に入らない。"}], "explanations": {"壮大": "「土が命を育むという壮大な仕組み」の規模の大きさを表す語で、文脈に合う。", "陽気": "「陽気な仕組み」は人の明るい性質を言う語で、仕組みには使えないので文に入らない。", "元気": "「元気な仕組み」は人の活力を言う語で、仕組みを修飾すると不自然で文が通らない。", "平気": "「平気な仕組み」は心の平然さを表す語で、仕組みには使えないので文に入らない。"}, "sentence_index": 0, "correct_answer": "壮大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この時計は壮大な精度で時を刻む。", "explanation": "ここは〈精密〉の意味。精度の細かさは「精密」で言い、規模の大きさを表す壮大とは合わない。"}, {"text": "祖母は壮大な暮らしを続け、ほとんど物を買わない。", "explanation": "ここは〈質素〉の意味。飾らず簡素なさまを言う語で、規模が大きく立派な壮大とは反対になる。"}, {"text": "彼は、壮大な慎重さで一つずつ確かめた。", "explanation": "ここは〈慎重〉の意味。注意深く行う態度を言う語で、規模や立派さを表す壮大は態度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51564, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "壮大", "is_correct": true, "explanation": "「宇宙の壮大な歴史」の規模の大きさを表す語で、文脈に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気な歴史」は人の明るい性質を言う語で、歴史には使えないので文に入らない。"}, {"text": "器用", "is_correct": false, "explanation": "「器用な歴史」は手先の巧みさを言う語で、歴史を修飾すると不自然になる。"}, {"text": "健気", "is_correct": false, "explanation": "「健気な歴史」は人のひたむきさを言う語で、歴史には使えない。"}], "explanations": {"壮大": "「宇宙の壮大な歴史」の規模の大きさを表す語で、文脈に合う。", "陽気": "「陽気な歴史」は人の明るい性質を言う語で、歴史には使えないので文に入らない。", "器用": "「器用な歴史」は手先の巧みさを言う語で、歴史を修飾すると不自然になる。", "健気": "「健気な歴史」は人のひたむきさを言う語で、歴史には使えない。"}, "sentence_index": 6, "correct_answer": "壮大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は壮大な足取りで、階段を駆け上がった。", "explanation": "ここは〈軽快〉の意味。身軽で弾むような動きに使う語で、規模や力強さを言う壮大とは合わない。"}, {"text": "その少女は壮大な指先で、細かい刺繍を仕上げた。", "explanation": "ここは〈器用〉の意味。手先の巧みさを言う語で、規模や力強さを表す壮大とは合わない。"}, {"text": "彼は壮大な感性で、季節の変化に気づく。", "explanation": "ここは〈繊細〉の意味。感覚が細やかなことを言う語で、規模の大きさを表す壮大とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51564, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その会社は壮大の計画を立てた。", "corrected_sentence": "その会社は壮大な計画を立てた。", "error_description": "形状詞「壮大」は名詞を修飾するとき「壮大な」になる。「壮大の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "壮大", "is_correct": true, "explanation": "「な」の前に置く語幹で、「壮大な景色」の形に合う。"}, {"text": "壮大だ", "is_correct": false, "explanation": "終止形。「な」の前には置けないので、「景色」を修飾できない。"}, {"text": "壮大に", "is_correct": false, "explanation": "連用形。名詞を直接修飾できないので、「景色」の前には入らない。"}, {"text": "壮大で", "is_correct": false, "explanation": "連用形（で）。名詞の直前には置けないので、この位置では不自然になる。"}], "correct_form": "壮大", "base_form": "壮大だ", "form_label": "連体形の語幹", "sentence_index": 1, "explanations": {"壮大": "「な」の前に置く語幹で、「壮大な景色」の形に合う。", "壮大だ": "終止形。「な」の前には置けないので、「景色」を修飾できない。", "壮大に": "連用形。名詞を直接修飾できないので、「景色」の前には入らない。", "壮大で": "連用形（で）。名詞の直前には置けないので、この位置では不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51564, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その遺跡はとても壮大くて、見る人を圧倒する。", "corrected_sentence": "その遺跡はとても壮大で、見る人を圧倒する。", "error_description": "形状詞「壮大」を続けるときは「壮大で」。「壮大くて」は形容詞の活用で誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "壮大", "is_correct": true, "explanation": "「滝の壮大な迫力」の「な」の前に置く語幹で、名詞を修飾する形に合う。"}, {"text": "壮大だった", "is_correct": false, "explanation": "過去の形。名詞「迫力」の前に「な」を置く形にはならず、ここでは合わない。"}, {"text": "壮大ではない", "is_correct": false, "explanation": "否定の形。「壮大ではない迫力」とは言えず、名詞を修飾できない。"}, {"text": "壮大である", "is_correct": false, "explanation": "断定の形。「な」の前には置けず、「迫力」を修飾できない。"}], "correct_form": "壮大", "base_form": "壮大だ", "form_label": "連体形の語幹", "sentence_index": 7, "explanations": {"壮大": "「滝の壮大な迫力」の「な」の前に置く語幹で、名詞を修飾する形に合う。", "壮大だった": "過去の形。名詞「迫力」の前に「な」を置く形にはならず、ここでは合わない。", "壮大ではない": "否定の形。「壮大ではない迫力」とは言えず、名詞を修飾できない。", "壮大である": "断定の形。「な」の前には置けず、「迫力」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51565, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「寒さを実感した」で、感じる対象を示す正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「寒さに実感した」は対象を示せず、不自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "「寒さが実感した」では寒さが感じる側になり、感じている人が文に現れず合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す助詞なので、感じ取る対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "「寒さを実感した」で、感じる対象を示す正しい助詞。", "に": "「寒さに実感した」は対象を示せず、不自然な文になる。", "が": "「寒さが実感した」では寒さが感じる側になり、感じている人が文に現れず合わない。", "へ": "「へ」は方向を表す助詞なので、感じ取る対象には使えない。"}, "error_tags": {"に": "対象", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51565, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51565, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "じぶんのからだで、ほんとうにそうだとわかること。", "primary_collocate": null, "pronunciation": "じっかん", "ipa": "dʑikkaɴ", "syllable_count": 4, "sentences": [{"text": "山に登って、空気がうすいことを実感した。", "target_word": "実感", "complexity_tier": "T3", "furigana": "山[やま]に登[のぼ]って、空気[くうき]がうすいことを実感[じっかん]した。", "sentence_source": "generated"}, {"text": "冬の朝、外に出て、寒さを実感した。", "target_word": "実感", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]、外[そと]に出[で]て、寒[さむ]さを実感[じっかん]した。", "sentence_source": "generated"}, {"text": "走ってみて、足が強くなったことを実感できた。", "target_word": "実感", "complexity_tier": "T3", "furigana": "走[はし]ってみて、足[あし]が強[つよ]くなったことを実感[じっかん]できた。", "sentence_source": "generated"}, {"text": "温泉に入ると、疲れがとれていく実感があった。", "target_word": "実感", "complexity_tier": "T3", "furigana": "温泉[おんせん]に入[はい]ると、疲[つか]れがとれていく実感[じっかん]があった。", "sentence_source": "generated"}, {"text": "泳いだあと、体が軽くなった実感がある。", "target_word": "実感", "complexity_tier": "T3", "furigana": "泳[およ]いだあと、体[からだ]が軽[かる]くなった実感[じっかん]がある。", "sentence_source": "generated"}, {"text": "長い時間歩いて、地図で見るより遠いと実感した。", "target_word": "実感", "complexity_tier": "T3", "furigana": "長[なが]い時間[じかん]歩[ある]いて、地図[ちず]で見[み]るより遠[とお]いと実感[じっかん]した。", "sentence_source": "generated"}, {"text": "重い荷物を持ってみて、父の力の強さを実感した。", "target_word": "実感", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を持[も]ってみて、父[ちち]の力[ちから]の強[つよ]さを実感[じっかん]した。", "sentence_source": "generated"}, {"text": "熱いお茶を飲んで、体があたたまるのを実感した。", "target_word": "実感", "complexity_tier": "T3", "furigana": "熱[あつ]いお茶[ちゃ]を飲[の]んで、体[からだ]があたたまるのを実感[じっかん]した。", "sentence_source": "generated"}, {"text": "薬を飲んでも、すぐに治った実感はなかった。", "target_word": "実感", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んでも、すぐに治[なお]った実感[じっかん]はなかった。", "sentence_source": "generated"}, {"text": "砂浜をはだしで歩き、夏が来たことを実感した。", "target_word": "実感", "complexity_tier": "T3", "furigana": "砂浜[すなはま]をはだしで歩[ある]き、夏[なつ]が来[き]たことを実感[じっかん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実感する", "label": "辞書形"}, {"form": "実感した", "label": "過去形"}, {"form": "実感して", "label": "て形"}, {"form": "実感しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "自分の体で感じて、本当にそうだとわかること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: あたたまる (Zipf 2.17)']::text[], 'cb7d6c3d-f83b-4e4e-9225-ca1e02731215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51565, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実感", "is_correct": true, "explanation": "「空気がうすいことを実感した」の空欄。自分の体で感じて、確かにそうだと分かったという意味に合う。"}, {"text": "遠慮", "is_correct": false, "explanation": "「空気がうすいことを遠慮した」は意味が通らず、空欄に合わない。"}, {"text": "侮辱", "is_correct": false, "explanation": "「空気がうすいことを侮辱した」は文の内容と結びつかず、意味が通らない。"}, {"text": "反発", "is_correct": false, "explanation": "「反発」は「〜に反発する」の形で使うため、「ことを反発した」は成り立たない。"}], "explanations": {"実感": "「空気がうすいことを実感した」の空欄。自分の体で感じて、確かにそうだと分かったという意味に合う。", "遠慮": "「空気がうすいことを遠慮した」は意味が通らず、空欄に合わない。", "侮辱": "「空気がうすいことを侮辱した」は文の内容と結びつかず、意味が通らない。", "反発": "「反発」は「〜に反発する」の形で使うため、「ことを反発した」は成り立たない。"}, "sentence_index": 0, "correct_answer": "実感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この数式の仕組みを、説明を聞いて実感した。", "explanation": "ここは〈理解〉の意味。実感は自分の体で感じることで、頭で理解した内容には使わないので合わない。"}, {"text": "明日は寒くなると、今から実感している。", "explanation": "ここは〈予想〉の意味。体で感じた確かさを表す実感は、まだ起きていない未来には使えないので合わない。"}, {"text": "一度も登らずに、山頂の景色を実感した。", "explanation": "ここは〈推測〉の意味。実感は体で実際に感じたことに使うので、登っていない山頂の景色を推し量るだけでは実感とは言えず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51565, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実感", "is_correct": true, "explanation": "「父の力の強さを実感した」の空欄。重い荷物を持って体で確かに感じたという意味に合う。"}, {"text": "宣言", "is_correct": false, "explanation": "「父の力の強さを宣言した」は意味が通らず、空欄に合わない。"}, {"text": "延期", "is_correct": false, "explanation": "「父の力の強さを延期した」は文の内容と結びつかず、成り立たない。"}, {"text": "分担", "is_correct": false, "explanation": "「父の力の強さを分担した」は、体で感じ取る文脈に合わない。"}], "explanations": {"実感": "「父の力の強さを実感した」の空欄。重い荷物を持って体で確かに感じたという意味に合う。", "宣言": "「父の力の強さを宣言した」は意味が通らず、空欄に合わない。", "延期": "「父の力の強さを延期した」は文の内容と結びつかず、成り立たない。", "分担": "「父の力の強さを分担した」は、体で感じ取る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "実感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "まだ見たことのない海の冷たさを、想像だけで実感した。", "explanation": "ここは〈想像〉の意味。実感は実際に体で感じることなので、想像だけで実感したと言うのは矛盾して合わない。"}, {"text": "看板を見て、近道を実感した。", "explanation": "ここは〈発見〉の意味。見つけたことは発見と言い、実感は自分の体で確かに感じたことに使うので合わない。"}, {"text": "お会計の合計を、電卓で実感した。", "explanation": "ここは〈確認〉の意味。計算して確かめることは確認と言い、実感は自分の体で感じたことに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51565, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝の散歩で、ひんやりした空気に実感した。", "corrected_sentence": "朝の散歩で、ひんやりした空気を実感した。", "error_description": "誤りは「実感」の対象を示す助詞。「実感した」は「空気を実感した」と「を」で対象を示すのが正しく、「に」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51565, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "プールで泳いだら、体がほぐれた実感がなった。", "corrected_sentence": "プールで泳いだら、体がほぐれた実感があった。", "error_description": "誤りは「実感」と結びつく動詞。「実感がある」が正しく、「実感がなった」は組み合わせとして成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
