INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51566, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際に経験して、確かにそうだと感じること。", "primary_collocate": null, "pronunciation": "じっかん", "ipa": "dʑikkaɴ", "syllable_count": 4, "sentences": [{"text": "しかし、農薬を使わずに野菜を育てるという仕事を通じて、彼は自然の厳しさと、土が命を育むという壮大な仕組みを、自らの肌で実感していくことになります。", "target_word": "実感", "complexity_tier": "T4", "furigana": "しかし、農薬[のうやく]を使[つか]わずに野菜[やさい]を育[そだ]てるという仕事[しごと]を通[つう]じて、彼[かれ]は自然[しぜん]の厳[きび]しさと、土[つち]が命[いのち]を育[はぐく]むという壮大[そうだい]な仕組[しく]みを、自[みずか]らの肌[はだ]で実感[じっかん]していくことになります。", "sentence_source": "mined"}, {"text": "初めて給料をもらって、働くことの大変さを実感した。", "target_word": "実感", "complexity_tier": "T3", "furigana": "初[はじ]めて給料[きゅうりょう]をもらって、働[はたら]くことの大変[たいへん]さを実感[じっかん]した。", "sentence_source": "generated"}, {"text": "合格したと聞いても、まだ実感がわかない。", "target_word": "実感", "complexity_tier": "T3", "furigana": "合格[ごうかく]したと聞[き]いても、まだ実感[じっかん]がわかない。", "sentence_source": "generated"}, {"text": "一人暮らしを始めて、親のありがたさを実感しています。", "target_word": "実感", "complexity_tier": "T3", "furigana": "一人暮[ひとりぐ]らしを始[はじ]めて、親[おや]のありがたさを実感[じっかん]しています。", "sentence_source": "generated"}, {"text": "毎日走り続けたので、体力がついたことを実感できた。", "target_word": "実感", "complexity_tier": "T3", "furigana": "毎日[まいにち]走[はし]り続[つづ]けたので、体力[たいりょく]がついたことを実感[じっかん]できた。", "sentence_source": "generated"}, {"text": "海外に住んでみると、日本の食べ物のおいしさを実感する。", "target_word": "実感", "complexity_tier": "T3", "furigana": "海外[かいがい]に住[す]んでみると、日本[にほん]の食[た]べ物[もの]のおいしさを実感[じっかん]する。", "sentence_source": "generated"}, {"text": "子どもが生まれたが、父親になった実感はまだない。", "target_word": "実感", "complexity_tier": "T3", "furigana": "子[こ]どもが生[う]まれたが、父親[ちちおや]になった実感[じっかん]はまだない。", "sentence_source": "generated"}, {"text": "数字で見るだけでは実感しにくいが、実際に現地へ行けばよくわかる。", "target_word": "実感", "complexity_tier": "T3", "furigana": "数字[すうじ]で見[み]るだけでは実感[じっかん]しにくいが、実際[じっさい]に現地[げんち]へ行[い]けばよくわかる。", "sentence_source": "generated"}, {"text": "駅前の店が次々に閉まり、町の人口が減っていると実感する。", "target_word": "実感", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の店[みせ]が次々[つぎつぎ]に閉[し]まり、町[まち]の人口[じんこう]が減[へ]っていると実感[じっかん]する。", "sentence_source": "generated"}, {"text": "新しい自転車に乗ってみて、前のものとの違いを実感した。", "target_word": "実感", "complexity_tier": "T3", "furigana": "新[あたら]しい自転車[じてんしゃ]に乗[の]ってみて、前[まえ]のものとの違[ちが]いを実感[じっかん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実感する", "label": "辞書形"}, {"form": "実感した", "label": "過去形"}, {"form": "実感して", "label": "て形"}, {"form": "実感しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "実際に経験して、本当にそうだと確かに感じること。頭の理解ではなく経験にもとづく感覚。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7d6c3d-f83b-4e4e-9225-ca1e02731215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51566, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実感", "is_correct": true, "explanation": "「自らの肌で実感していく」の空欄。実際に経験して確かに感じるという意味で文脈に合う。"}, {"text": "誤解", "is_correct": false, "explanation": "「自らの肌で誤解していく」は体で感じ取る文脈と合わず、意味が通らない。"}, {"text": "遠慮", "is_correct": false, "explanation": "「自らの肌で遠慮していく」は、自然の厳しさを体で知るという文脈に合わない。"}, {"text": "忘却", "is_correct": false, "explanation": "「自らの肌で忘却していく」は、体で仕組みを感じ取る文の流れと逆になり、合わない。"}], "explanations": {"実感": "「自らの肌で実感していく」の空欄。実際に経験して確かに感じるという意味で文脈に合う。", "誤解": "「自らの肌で誤解していく」は体で感じ取る文脈と合わず、意味が通らない。", "遠慮": "「自らの肌で遠慮していく」は、自然の厳しさを体で知るという文脈に合わない。", "忘却": "「自らの肌で忘却していく」は、体で仕組みを感じ取る文の流れと逆になり、合わない。"}, "sentence_index": 0, "correct_answer": "実感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この定理の証明を、一晩で実感した。", "explanation": "ここは〈理解〉の意味。実感は実際に経験して確かに感じることで、証明の内容は理解するものなので合わない。"}, {"text": "明日は雨になると、もう実感している。", "explanation": "ここは〈予想〉の意味。実感は既に経験して感じることで、まだ起きていない未来の出来事には使えないので合わない。"}, {"text": "生まれる前の出来事を、実感していた。", "explanation": "ここは〈想像〉の意味。実感は自分が実際に経験して確かに感じることで、生まれる前の出来事は経験できないので、想像で思い描くことには使えず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51566, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実感", "is_correct": true, "explanation": "「父親になった実感はまだない」の空欄。父親になったことを確かに感じられていない、という意味に合う。"}, {"text": "寄付", "is_correct": false, "explanation": "「父親になった寄付はまだない」は意味が通らず、空欄に合わない。"}, {"text": "失恋", "is_correct": false, "explanation": "「父親になった失恋」は文の内容と結びつかず、空欄に合わない。"}, {"text": "雑談", "is_correct": false, "explanation": "「父親になった雑談」は意味が通らず、文の流れに合わない。"}], "explanations": {"実感": "「父親になった実感はまだない」の空欄。父親になったことを確かに感じられていない、という意味に合う。", "寄付": "「父親になった寄付はまだない」は意味が通らず、空欄に合わない。", "失恋": "「父親になった失恋」は文の内容と結びつかず、空欄に合わない。", "雑談": "「父親になった雑談」は意味が通らず、文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "実感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地図を広げて、新しい道を実感した。", "explanation": "ここは〈発見〉の意味。初めて見つけたことは発見と言い、実感は自分が実際に経験して確かに感じたことに使うので合わない。"}, {"text": "事故の原因を、目撃者の話だけで実感した。", "explanation": "ここは〈推測〉の意味。実感は自分の経験で確かに感じることで、人の話から推し量ったことには使わないので合わない。"}, {"text": "お釣りの金額を、暗算で実感した。", "explanation": "ここは〈確認〉の意味。計算して確かめることは確認と言い、実感は自分の経験で確かに感じたことに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51566, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "引っ越したが、まだ新しい町に住んでいる実感をない。", "corrected_sentence": "引っ越したが、まだ新しい町に住んでいる実感がない。", "error_description": "誤りは「実感」に続く助詞。「実感がない」の「が」を「を」にしている。「実感」は「が」で存在を表すので、「を」は不可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51566, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試験の結果を聞いたが、まだ実感がわいない。", "corrected_sentence": "試験の結果を聞いたが、まだ実感がわかない。", "error_description": "誤りは「わく」の活用。否定形は「わかない」が正しく、「わいない」は活用として誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51567, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「肌にさわる」で、さわる対象を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「肌がさわる」では肌が主語になり、さわる人と対象が成り立たず合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、接触の対象を示すには使えない。"}, {"text": "の", "is_correct": false, "explanation": "「肌のさわる」は名詞修飾になり、動詞の対象を示せないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「肌にさわる」で、さわる対象を示す正しい助詞。", "が": "「肌がさわる」では肌が主語になり、さわる人と対象が成り立たず合わない。", "へ": "「へ」は方向を表すので、接触の対象を示すには使えない。", "の": "「肌のさわる」は名詞修飾になり、動詞の対象を示せないので合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "名詞修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51567, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「肌が弱い」で、弱いのは肌なので主語を示す「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「肌を弱い」は目的語になり、状態を表す形容詞と合わないので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、肌の状態を表す文には使えない。"}, {"text": "で", "is_correct": false, "explanation": "「肌で弱い」は手段を示す「で」になり、状態の主語にならないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「肌が弱い」で、弱いのは肌なので主語を示す「が」が正しい。", "を": "「肌を弱い」は目的語になり、状態を表す形容詞と合わないので不自然。", "へ": "「へ」は方向を示すので、肌の状態を表す文には使えない。", "で": "「肌で弱い」は手段を示す「で」になり、状態の主語にならないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51567, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人の体の外側をおおっているもの。", "primary_collocate": null, "pronunciation": "はだ", "ipa": "hada", "syllable_count": 2, "sentences": [{"text": "夏になると、肌が日に焼けて黒くなる。", "target_word": "肌", "complexity_tier": "T3", "furigana": "夏[なつ]になると、肌[はだ]が日[ひ]に焼[や]けて黒[くろ]くなる。", "sentence_source": "generated"}, {"text": "手でそっと肌にさわると、あたたかかった。", "target_word": "肌", "complexity_tier": "T3", "furigana": "手[て]でそっと肌[はだ]にさわると、あたたかかった。", "sentence_source": "generated"}, {"text": "寒い日は、肌を出さないように長い服を着る。", "target_word": "肌", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、肌[はだ]を出[だ]さないように長[なが]い服[ふく]を着[き]る。", "sentence_source": "generated"}, {"text": "毎晩、顔の肌にクリームをつけてから寝る。", "target_word": "肌", "complexity_tier": "T3", "furigana": "毎晩[まいばん]、顔[かお]の肌[はだ]にクリームをつけてから寝[ね]る。", "sentence_source": "generated"}, {"text": "かゆくて肌をかいたら、跡が残ってしまった。", "target_word": "肌", "complexity_tier": "T3", "furigana": "かゆくて肌[はだ]をかいたら、跡[あと]が残[のこ]ってしまった。", "sentence_source": "generated"}, {"text": "蚊にさされた肌が、ぷくっとふくれている。", "target_word": "肌", "complexity_tier": "T3", "furigana": "蚊[か]にさされた肌[はだ]が、ぷくっとふくれている。", "sentence_source": "generated"}, {"text": "海で遊んだので、肌がひりひりして痛い。", "target_word": "肌", "complexity_tier": "T3", "furigana": "海[うみ]で遊[あそ]んだので、肌[はだ]がひりひりして痛[いた]い。", "sentence_source": "generated"}, {"text": "肌が弱いので、強い洗剤は使えない。", "target_word": "肌", "complexity_tier": "T3", "furigana": "肌[はだ]が弱[よわ]いので、強[つよ]い洗剤[せんざい]は使[つか]えない。", "sentence_source": "generated"}, {"text": "兄は肌が白いので、夏は帽子が欠かせない。", "target_word": "肌", "complexity_tier": "T3", "furigana": "兄[あに]は肌[はだ]が白[しろ]いので、夏[なつ]は帽子[ぼうし]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "雨にぬれて、肌にシャツがはりついた。", "target_word": "肌", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれて、肌[はだ]にシャツがはりついた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "肌", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人の体の外側をおおっている皮ふ。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: あたたかかっ (Zipf 1.27)','sentence 6 above tier T2: contains vocabulary far above tier T2: ひりひり (Zipf 2.32)','sentence 9 above tier T2: contains vocabulary far above tier T2: はりつい (Zipf 2.16)']::text[], 'cb7d6c3d-f83b-4e4e-9225-ca1e02731215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51567, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肌", "is_correct": true, "explanation": "「夏になると、肌が日に焼けて黒くなる」の空欄。体の表面が日に焼けるという意味に合う。"}, {"text": "胃", "is_correct": false, "explanation": "胃は体の内側の器官で、日に焼けて黒くなるものではないので文に合わない。"}, {"text": "腸", "is_correct": false, "explanation": "腸は体の内側にあり日に焼けることはないので、文の内容に合わない。"}, {"text": "肺", "is_correct": false, "explanation": "肺は体の内側にあり、日焼けの対象にならないので文に合わない。"}], "explanations": {"肌": "「夏になると、肌が日に焼けて黒くなる」の空欄。体の表面が日に焼けるという意味に合う。", "胃": "胃は体の内側の器官で、日に焼けて黒くなるものではないので文に合わない。", "腸": "腸は体の内側にあり日に焼けることはないので、文の内容に合わない。", "肺": "肺は体の内側にあり、日焼けの対象にならないので文に合わない。"}, "sentence_index": 0, "correct_answer": "肌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "りんごの肌をむいて、食べた。", "explanation": "ここは〈皮〉の意味。りんごの外側は皮と言い、人の体の表面をいう肌は使わないので合わない。"}, {"text": "肌の中で腸がゆっくり動いている。", "explanation": "ここは〈表面〉の意味。肌は体の外側を指すので、体の内側の器官には使えず合わない。"}, {"text": "芝生の肌がやわらかい。", "explanation": "ここは〈地表〉の意味。草地の表面は地表と言い、人の体の外側をおおう肌は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51567, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肌", "is_correct": true, "explanation": "「海で遊んだので、肌がひりひりして痛い」の空欄。日焼けなどで皮ふがひりひり痛む意味に合う。"}, {"text": "肝臓", "is_correct": false, "explanation": "肝臓は体の内側の器官で、表面がひりひりと痛むという文に合わない。"}, {"text": "腎臓", "is_correct": false, "explanation": "腎臓は体の内側にあり、ひりひり痛む場所として文の内容に合わない。"}, {"text": "膵臓", "is_correct": false, "explanation": "膵臓は体の内側の器官で、日焼けのように表面がひりつく文には合わない。"}], "explanations": {"肌": "「海で遊んだので、肌がひりひりして痛い」の空欄。日焼けなどで皮ふがひりひり痛む意味に合う。", "肝臓": "肝臓は体の内側の器官で、表面がひりひりと痛むという文に合わない。", "腎臓": "腎臓は体の内側にあり、ひりひり痛む場所として文の内容に合わない。", "膵臓": "膵臓は体の内側の器官で、日焼けのように表面がひりつく文には合わない。"}, "sentence_index": 6, "correct_answer": "肌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "卵の肌が、ひびで割れてしまった。", "explanation": "ここは〈殻〉の意味。卵の外側は殻と言い、人の体の表面をいう肌は使わないので合わない。"}, {"text": "伸びすぎた肌を、ハサミで切った。", "explanation": "ここは〈爪〉の意味。ハサミで切るのは爪で、皮ふの肌を切ることはないので合わない。"}, {"text": "鳥が肌を広げて飛んだ。", "explanation": "ここは〈翼〉の意味。鳥が広げて飛ぶのは翼で、皮ふの肌は広げないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51567, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "肌を弱い人は、日焼け止めを選ぶとよい。", "corrected_sentence": "肌の弱い人は、日焼け止めを選ぶとよい。", "error_description": "誤りは「肌」に続く助詞。「肌の弱い人」と「の」で修飾するのが正しく、「を」は形容詞「弱い」と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51567, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "真夏の海辺で、肌が焼けなくように日傘をさした。", "corrected_sentence": "真夏の海辺で、肌が焼けないように日傘をさした。", "error_description": "誤りは「焼ける」の活用。「〜ないように」が正しく、「焼けなくように」は打ち消しの形として誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51568, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51568, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「肌が温まって赤くなった」で、温まる主体は肌なので主語を示す「が」が正しい。"}, {"text": "と", "is_correct": false, "explanation": "「肌と温まって」は並べる相手を示す「と」になり、肌が温まるという主語の関係が成り立たないので不自然。"}, {"text": "の", "is_correct": false, "explanation": "「肌の温まって」は名詞に続く「の」になり、動詞「温まる」の主語にならず、文の述語が立たないので不自然。"}, {"text": "より", "is_correct": false, "explanation": "「肌より温まって」は比べる相手を示す「より」になり、肌が温まるという変化の主語を表せないので不自然。"}], "correct_answer": "が", "explanations": {"が": "「肌が温まって赤くなった」で、温まる主体は肌なので主語を示す「が」が正しい。", "と": "「肌と温まって」は並べる相手を示す「と」になり、肌が温まるという主語の関係が成り立たないので不自然。", "の": "「肌の温まって」は名詞に続く「の」になり、動詞「温まる」の主語にならず、文の述語が立たないので不自然。", "より": "「肌より温まって」は比べる相手を示す「より」になり、肌が温まるという変化の主語を表せないので不自然。"}, "error_tags": {"と": "並列", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51568, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人や動物の体の表面を覆っている組織。", "primary_collocate": null, "pronunciation": "はだ", "ipa": "hada", "syllable_count": 2, "sentences": [{"text": "しかし、農薬を使わずに野菜を育てるという仕事を通じて、彼は自然の厳しさと、土が命を育むという壮大な仕組みを、自らの肌で実感していくことになります。", "target_word": "肌", "complexity_tier": "T4", "furigana": "しかし、農薬[のうやく]を使[つか]わずに野菜[やさい]を育[そだ]てるという仕事[しごと]を通[つう]じて、彼[かれ]は自然[しぜん]の厳[きび]しさと、土[つち]が命[いのち]を育[はぐく]むという壮大[そうだい]な仕組[しく]みを、自[みずか]らの肌[はだ]で実感[じっかん]していくことになります。", "sentence_source": "mined"}, {"text": "冬は空気が乾燥するので、肌がかさかさになる。", "target_word": "肌", "complexity_tier": "T3", "furigana": "冬[ふゆ]は空気[くうき]が乾燥[かんそう]するので、肌[はだ]がかさかさになる。", "sentence_source": "generated"}, {"text": "日焼け止めを塗らないと、強い日差しで肌が赤くなる。", "target_word": "肌", "complexity_tier": "T3", "furigana": "日焼[ひや]け止[ど]めを塗[ぬ]らないと、強[つよ]い日差[ひざ]しで肌[はだ]が赤[あか]くなる。", "sentence_source": "generated"}, {"text": "赤ちゃんの肌はやわらかくて、とても敏感だ。", "target_word": "肌", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの肌[はだ]はやわらかくて、とても敏感[びんかん]だ。", "sentence_source": "generated"}, {"text": "この石けんは肌にやさしいので、子どもにも使えます。", "target_word": "肌", "complexity_tier": "T3", "furigana": "この石[せっ]けんは肌[はだ]にやさしいので、子[こ]どもにも使[つか]えます。", "sentence_source": "generated"}, {"text": "夜ふかしが続いたせいで、肌の調子が悪い。", "target_word": "肌", "complexity_tier": "T3", "furigana": "夜[よる]ふかしが続[つづ]いたせいで、肌[はだ]の調子[ちょうし]が悪[わる]い。", "sentence_source": "generated"}, {"text": "ゾウの肌は厚くて、しわが多い。", "target_word": "肌", "complexity_tier": "T3", "furigana": "ゾウの肌[はだ]は厚[あつ]くて、しわが多[おお]い。", "sentence_source": "generated"}, {"text": "風呂上がりに、肌が温まってほんのり赤くなった。", "target_word": "肌", "complexity_tier": "T3", "furigana": "風呂上[ふろあ]がりに、肌[はだ]が温[あたた]まってほんのり赤[あか]くなった。", "sentence_source": "generated"}, {"text": "彼女は色が白く、肌がきれいだと言われる。", "target_word": "肌", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は色[いろ]が白[しろ]く、肌[はだ]がきれいだと言[い]われる。", "sentence_source": "generated"}, {"text": "寒い風が肌を刺して、思わず上着を着た。", "target_word": "肌", "complexity_tier": "T3", "furigana": "寒[さむ]い風[かぜ]が肌[はだ]を刺[さ]して、思[おも]わず上着[うわぎ]を着[き]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "肌", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人や動物の体の表面をおおう皮ふ。その状態や手ざわりもいう。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: かさかさ (Zipf 1.95)']::text[], 'cb7d6c3d-f83b-4e4e-9225-ca1e02731215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51568, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肌", "is_correct": true, "explanation": "「自らの肌で実感していく」の空欄。体の表面で直接感じるという意味に合う。"}, {"text": "爪", "is_correct": false, "explanation": "「自らの爪で実感していく」は、感じ取る器官として不自然で文が成り立たない。"}, {"text": "額", "is_correct": false, "explanation": "「自らの額で実感していく」は、体で感じる文脈として不自然で合わない。"}, {"text": "瞼", "is_correct": false, "explanation": "「自らの瞼で実感していく」は、自然の厳しさを感じ取る文脈に合わない。"}], "explanations": {"肌": "「自らの肌で実感していく」の空欄。体の表面で直接感じるという意味に合う。", "爪": "「自らの爪で実感していく」は、感じ取る器官として不自然で文が成り立たない。", "額": "「自らの額で実感していく」は、体で感じる文脈として不自然で合わない。", "瞼": "「自らの瞼で実感していく」は、自然の厳しさを感じ取る文脈に合わない。"}, "sentence_index": 0, "correct_answer": "肌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ゆで卵の肌をむいて、食べた。", "explanation": "ここは〈殻〉の意味。卵の外側は殻と言い、人や動物の皮ふをいう肌は使わないので合わない。"}, {"text": "肌の中で胃がゆっくり動いている。", "explanation": "ここは〈表面〉の意味。肌は体の外側の皮ふを指すので、体の内側の器官には使えず合わない。"}, {"text": "ツバメの肌を広げて飛んだ。", "explanation": "ここは〈翼〉の意味。ツバメが広げて飛ぶのは翼で、皮ふの肌は広げないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51568, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肌", "is_correct": true, "explanation": "「ゾウの肌は厚くて、しわが多い」の空欄。ゾウの皮ふの状態を表すので文に合う。"}, {"text": "眉", "is_correct": false, "explanation": "「ゾウの眉は厚くて、しわが多い」は、ゾウに眉を当てる文脈として合わない。"}, {"text": "髪", "is_correct": false, "explanation": "ゾウには髪がなく、「厚くて、しわが多い」という皮ふの様子を表す文に合わない。"}, {"text": "唾", "is_correct": false, "explanation": "唾は体の表面を覆うものではないので、「厚くてしわが多い」という様子に合わない。"}], "explanations": {"肌": "「ゾウの肌は厚くて、しわが多い」の空欄。ゾウの皮ふの状態を表すので文に合う。", "眉": "「ゾウの眉は厚くて、しわが多い」は、ゾウに眉を当てる文脈として合わない。", "髪": "ゾウには髪がなく、「厚くて、しわが多い」という皮ふの様子を表す文に合わない。", "唾": "唾は体の表面を覆うものではないので、「厚くてしわが多い」という様子に合わない。"}, "sentence_index": 6, "correct_answer": "肌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の肌が肩まで伸びた。", "explanation": "ここは〈髪〉の意味。肩まで伸びるのは髪で、体の表面をおおう肌は伸びないので合わない。"}, {"text": "ぶどうの肌をむいて食べた。", "explanation": "ここは〈皮〉の意味。果物の外側は皮と言い、人や動物の皮ふをいう肌は使わないので合わない。"}, {"text": "伸びすぎた肌を、ハサミで切って整えた。", "explanation": "ここは〈爪〉の意味。ハサミで切って整えるのは爪で、皮ふの肌は切らないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51568, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬の朝は、冷たい風が肌が刺す。", "corrected_sentence": "冬の朝は、冷たい風が肌を刺す。", "error_description": "誤りは「肌」に続く助詞。「刺す」は目的語を「を」で示す他動詞なので、「肌を刺す」が正しく、「肌が刺す」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51568, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暑い夏の日、肌が赤いなった。", "corrected_sentence": "暑い夏の日、肌が赤くなった。", "error_description": "誤りは「赤くなる」の形。形容詞の連用形「赤く」＋「なる」が正しく、「赤いなった」は活用の形として誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51571, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『買う』の目的語を示す『を』が入る。"}, {"text": "が", "is_correct": false, "explanation": "『買って』の主語は『私』で、『食肉』は買う対象なので『が』は合わない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は相手や到達点を表すが、『買う』の対象には使わない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は共同の相手や引用を表し、『買う』の対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "『買う』の目的語を示す『を』が入る。", "が": "『買って』の主語は『私』で、『食肉』は買う対象なので『が』は合わない。", "に": "『に』は相手や到達点を表すが、『買う』の対象には使わない。", "と": "『と』は共同の相手や引用を表し、『買う』の対象には合わない。"}, "error_tags": {"が": "主語", "に": "相手・到達点", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
