INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51571, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べるための肉", "primary_collocate": null, "pronunciation": "しょくにく", "ipa": "ɕokɯɲikɯ", "syllable_count": 4, "sentences": [{"text": "食肉は、牛や豚や鶏の肉のことです。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "食肉[しょくにく]は、牛[うし]や豚[ぶた]や鶏[にわとり]の肉[にく]のことです。", "sentence_source": "generated"}, {"text": "スーパーで食肉を買って、夕食にカレーを作りました。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "スーパーで食肉[しょくにく]を買[か]って、夕食[ゆうしょく]にカレーを作[つく]りました。", "sentence_source": "generated"}, {"text": "食肉は冷たくしておかないと、悪くなります。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "食肉[しょくにく]は冷[つめ]たくしておかないと、悪[わる]くなります。", "sentence_source": "generated"}, {"text": "兄は食肉を使わない料理が好きで、野菜ばかり食べています。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "兄[あに]は食肉[しょくにく]を使[つか]わない料理[りょうり]が好[す]きで、野菜[やさい]ばかり食[た]べています。", "sentence_source": "generated"}, {"text": "この店の食肉は、近くの農家から届いたものです。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "この店[みせ]の食肉[しょくにく]は、近[ちか]くの農家[のうか]から届[とど]いたものです。", "sentence_source": "generated"}, {"text": "ステーキに使う食肉は、厚く切ったほうがおいしいです。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "ステーキに使[つか]う食肉[しょくにく]は、厚[あつ]く切[き]ったほうがおいしいです。", "sentence_source": "generated"}, {"text": "食肉の値段は、季節によって少し変わります。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "食肉[しょくにく]の値段[ねだん]は、季節[きせつ]によって少[すこ]し変[か]わります。", "sentence_source": "generated"}, {"text": "魚や野菜と違って、食肉は焼くと香ばしい匂いがします。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "魚[さかな]や野菜[やさい]と違[ちが]って、食肉[しょくにく]は焼[や]くと香[こう]ばしい匂[にお]いがします。", "sentence_source": "generated"}, {"text": "母は食肉に塩をふってから、フライパンで焼きます。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "母[はは]は食肉[しょくにく]に塩[しお]をふってから、フライパンで焼[や]きます。", "sentence_source": "generated"}, {"text": "パーティーのために、食肉を三キロも買いました。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "パーティーのために、食肉[しょくにく]を三[さん]キロも買[か]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食肉", "label": "基本形"}], "register": "中立（ですます体）", "sense_fingerprint": "食べ物として売られ、料理に使う牛・豚・鶏などの肉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51571, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食肉", "is_correct": true, "explanation": "『〜の肉のことです』と説明できる語で、牛・豚・鶏の肉を指すので文が成り立つ。"}, {"text": "野菜", "is_correct": false, "explanation": "野菜は植物なので、牛・豚・鶏の肉の意味にはならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、肉の種類を表す語ではないので合わない。"}, {"text": "肥料", "is_correct": false, "explanation": "肥料は作物を育てる材料で、肉を指さないので合わない。"}], "explanations": {"食肉": "『〜の肉のことです』と説明できる語で、牛・豚・鶏の肉を指すので文が成り立つ。", "野菜": "野菜は植物なので、牛・豚・鶏の肉の意味にはならない。", "冷蔵庫": "冷蔵庫は家電で、肉の種類を表す語ではないので合わない。", "肥料": "肥料は作物を育てる材料で、肉を指さないので合わない。"}, "sentence_index": 0, "correct_answer": "食肉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "マグロは食肉として、冷凍して海外へ輸出されている。", "explanation": "ここは〈魚肉〉の意味。食肉は家畜や鳥類の肉を指し、魚は含まないので〈魚肉〉を使う。"}, {"text": "ネコやイヌは食肉に分類される。", "explanation": "ここは〈食肉目〉の意味。食肉は食用の肉で、動物の分類には使わないので〈食肉目〉と言う。"}, {"text": "ライオンは食肉で、シマウマを狩って食べる。", "explanation": "ここは〈肉食〉の意味。動物が肉を主に食べることは〈肉食〉と言い、食用の肉を指す食肉とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51571, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食肉", "is_correct": true, "explanation": "『食肉の値段』は食用の肉の値段という意味になり、文として成り立つ。"}, {"text": "天気", "is_correct": false, "explanation": "天気には値段がないので、『天気の値段』は成り立たない。"}, {"text": "教室", "is_correct": false, "explanation": "教室には値段がないので、『教室の値段』は成り立たない。"}, {"text": "月", "is_correct": false, "explanation": "月には値段がないので、『月の値段』は成り立たない。"}], "explanations": {"食肉": "『食肉の値段』は食用の肉の値段という意味になり、文として成り立つ。", "天気": "天気には値段がないので、『天気の値段』は成り立たない。", "教室": "教室には値段がないので、『教室の値段』は成り立たない。", "月": "月には値段がないので、『月の値段』は成り立たない。"}, "sentence_index": 6, "correct_answer": "食肉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このメロンは食肉が厚くて、とても甘い。", "explanation": "ここは〈果肉〉の意味。食肉は家畜や鳥の肉を指し、果物の果肉には使わない。"}, {"text": "この牧場では、食肉を毎朝育てている。", "explanation": "ここは〈畜産〉の意味。食肉は肉そのものなので、育てる仕事や対象には使わない。"}, {"text": "ステーキを切ると、食肉が皿にたくさん流れ出た。", "explanation": "ここは〈肉汁〉の意味。焼いた肉から出る汁は肉汁で、食肉は肉そのものを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51571, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "買ってきた食肉が、すぐに冷蔵庫へ入れました。", "corrected_sentence": "買ってきた食肉を、すぐに冷蔵庫へ入れました。", "error_description": "『入れる』は目的語に『を』を取るので、『食肉』には『を』が正しい。『が』は主語を示すので、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51571, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "食肉を薄く切っで、フライパンで炒めます。", "corrected_sentence": "食肉を薄く切って、フライパンで炒めます。", "error_description": "『切る』のて形は『切って』。『切っで』は濁音化の誤りで、正しい活用は『切って』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51572, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『食肉』は『売られています』の主語にあたるので、主語を示す『が』が入る。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すが、『売られています』は受身で目的語を取らないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は受身の相手や場所を表すが、ここでは『食肉』が主語なので入らない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表すので、『食肉』を主語にする文には入らない。"}], "correct_answer": "が", "explanations": {"が": "『食肉』は『売られています』の主語にあたるので、主語を示す『が』が入る。", "を": "『を』は目的語を示すが、『売られています』は受身で目的語を取らないので合わない。", "に": "『に』は受身の相手や場所を表すが、ここでは『食肉』が主語なので入らない。", "へ": "『へ』は方向を表すので、『食肉』を主語にする文には入らない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51572, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51572, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食用としての肉。特に、家畜や鳥類の肉を指す。", "primary_collocate": null, "pronunciation": "しょくにく", "ipa": "ɕokɯɲikɯ", "syllable_count": 4, "sentences": [{"text": "ブロイラーは、食肉を得るために改良された鶏の品種です。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "ブロイラーは、食肉[しょくにく]を得[え]るために改良[かいりょう]された鶏[にわとり]の品種[ひんしゅ]です。", "sentence_source": "mined"}, {"text": "日本では、牛や豚、鶏などの食肉が毎日スーパーで売られています。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "日本[にほん]では、牛[うし]や豚[ぶた]、鶏[にわとり]などの食肉[しょくにく]が毎日[まいにち]スーパーで売[う]られています。", "sentence_source": "generated"}, {"text": "食肉は、衛生的に処理されてから店に運ばれます。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "食肉[しょくにく]は、衛生的[えいせいてき]に処理[しょり]されてから店[みせ]に運[はこ]ばれます。", "sentence_source": "generated"}, {"text": "この国は食肉の輸入が多く、外国の牧場から大量に肉が届きます。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "この国[くに]は食肉[しょくにく]の輸入[ゆにゅう]が多[おお]く、外国[がいこく]の牧場[ぼくじょう]から大量[たいりょう]に肉[にく]が届[とど]きます。", "sentence_source": "generated"}, {"text": "魚は食べ物ですが、一般に食肉とは呼ばれません。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "魚[さかな]は食[た]べ物[もの]ですが、一般[いっぱん]に食肉[しょくにく]とは呼[よ]ばれません。", "sentence_source": "generated"}, {"text": "食肉の値段が上がったため、今月は買う量を減らしました。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "食肉[しょくにく]の値段[ねだん]が上[あ]がったため、今月[こんげつ]は買[か]う量[りょう]を減[へ]らしました。", "sentence_source": "generated"}, {"text": "牧場では、食肉にするために牛を二年ほど大切に育てます。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "牧場[ぼくじょう]では、食肉[しょくにく]にするために牛[うし]を二年[にねん]ほど大切[たいせつ]に育[そだ]てます。", "sentence_source": "generated"}, {"text": "食肉は冷蔵庫で保存しないと、すぐに傷んでしまいます。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "食肉[しょくにく]は冷蔵庫[れいぞうこ]で保存[ほぞん]しないと、すぐに傷[いた]んでしまいます。", "sentence_source": "generated"}, {"text": "豚肉も鶏肉も、代表的な食肉として世界中で食べられています。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "豚肉[ぶたにく]も鶏肉[とりにく]も、代表的[だいひょうてき]な食肉[しょくにく]として世界中[せかいじゅう]で食[た]べられています。", "sentence_source": "generated"}, {"text": "野菜中心の食事にして、食肉をあまり食べない人もいます。", "target_word": "食肉", "complexity_tier": "T3", "furigana": "野菜[やさい]中心[ちゅうしん]の食事[しょくじ]にして、食肉[しょくにく]をあまり食[た]べない人[ひと]もいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食肉", "label": "基本形"}], "register": "中立（やや書き言葉）", "sense_fingerprint": "食用にする家畜や鳥類の肉（牛・豚・鶏など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51572, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食肉", "is_correct": true, "explanation": "「食用の肉を得る目的で改良された鶏」となり、空欄に食用の肉を指す語が入って文が成り立つ。"}, {"text": "乳製品", "is_correct": false, "explanation": "乳製品は乳から作る食品で、鶏からは得られないので「得るために改良された」と合わない。"}, {"text": "飼料", "is_correct": false, "explanation": "飼料は鶏に与える餌で、鶏を改良して得る対象にはならないので合わない。"}, {"text": "羊毛", "is_correct": false, "explanation": "羊毛は羊から採る繊維で、鶏から得るものではないので合わない。"}], "explanations": {"食肉": "「食用の肉を得る目的で改良された鶏」となり、空欄に食用の肉を指す語が入って文が成り立つ。", "乳製品": "乳製品は乳から作る食品で、鶏からは得られないので「得るために改良された」と合わない。", "飼料": "飼料は鶏に与える餌で、鶏を改良して得る対象にはならないので合わない。", "羊毛": "羊毛は羊から採る繊維で、鶏から得るものではないので合わない。"}, "sentence_index": 0, "correct_answer": "食肉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "マグロは食肉として、冷凍して海外へ輸出されている。", "explanation": "ここは〈魚肉〉の意味。食肉は牛・豚・鶏など家畜や鳥類の肉を指し、魚は含まないので〈魚肉〉を使う。"}, {"text": "ネコやイヌは食肉に分類される。", "explanation": "ここは〈食肉目〉の意味。食肉は食用の肉で、動物の分類には使わないので〈食肉目〉と言う。"}, {"text": "このメロンは食肉が厚くて、とても甘い。", "explanation": "ここは〈果肉〉の意味。食肉は家畜や鳥の肉を指し、果物の果肉には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51572, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食肉", "is_correct": true, "explanation": "『食肉にするために牛を育てる』は、食用の肉にするために育てるという意味で成り立つ。"}, {"text": "穀物", "is_correct": false, "explanation": "牛を穀物にするという意味になり、牛は穀物にならないので合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "牛を野菜にするという文は成り立たないので合わない。"}, {"text": "卵", "is_correct": false, "explanation": "牛は卵を産まないので、卵にするために育てるとは合わない。"}], "explanations": {"食肉": "『食肉にするために牛を育てる』は、食用の肉にするために育てるという意味で成り立つ。", "穀物": "牛を穀物にするという意味になり、牛は穀物にならないので合わない。", "野菜": "牛を野菜にするという文は成り立たないので合わない。", "卵": "牛は卵を産まないので、卵にするために育てるとは合わない。"}, "sentence_index": 6, "correct_answer": "食肉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この動物は食肉で、草や葉はほとんど食べない。", "explanation": "ここは〈肉食〉の意味。動物の食べ方は〈肉食〉と言い、食肉は食用の肉を指すので合わない。"}, {"text": "この農場では、食肉を毎朝育てている。", "explanation": "ここは〈畜産〉の意味。食肉は肉そのものなので、育てる仕事や対象には使わない。"}, {"text": "ステーキを切ると、食肉が皿にたくさん流れ出た。", "explanation": "ここは〈肉汁〉の意味。焼いた肉から出る汁は肉汁で、食肉は肉そのものを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51572, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "スーパーでは、食肉で冷蔵ケースに並べています。", "corrected_sentence": "スーパーでは、食肉を冷蔵ケースに並べています。", "error_description": "『食肉』に続く助詞が誤り。『並べる』は目的語に『を』を取るので、『で』（場所・手段）は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51572, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店では、食肉を冷凍すて保存しています。", "corrected_sentence": "店では、食肉を冷凍して保存しています。", "error_description": "『冷凍する』のて形は『冷凍して』。『冷凍すて』は誤った活用で、正しくは『冷凍して』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
