INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51573, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "体の重さのことです。", "primary_collocate": null, "pronunciation": "たいじゅう", "ipa": "taidʑɯː", "syllable_count": 4, "sentences": [{"text": "私の体重は五十キロです。", "target_word": "体重", "complexity_tier": "T3", "furigana": "私[わたし]の体重[たいじゅう]は五十[ごじゅう]キロです。", "sentence_source": "generated"}, {"text": "体重が増えたので、毎日歩くことにしました。", "target_word": "体重", "complexity_tier": "T3", "furigana": "体重[たいじゅう]が増[ふ]えたので、毎日[まいにち]歩[ある]くことにしました。", "sentence_source": "generated"}, {"text": "病院で身長と体重をはかりました。", "target_word": "体重", "complexity_tier": "T3", "furigana": "病院[びょういん]で身長[しんちょう]と体重[たいじゅう]をはかりました。", "sentence_source": "generated"}, {"text": "弟は体重が軽いので、風が強い日は飛ばされそうです。", "target_word": "体重", "complexity_tier": "T3", "furigana": "弟[おとうと]は体重[たいじゅう]が軽[かる]いので、風[かぜ]が強[つよ]い日[ひ]は飛[と]ばされそうです。", "sentence_source": "generated"}, {"text": "体重を減らすために、夜はご飯を少なくしています。", "target_word": "体重", "complexity_tier": "T3", "furigana": "体重[たいじゅう]を減[へ]らすために、夜[よる]はご飯[はん]を少[すく]なくしています。", "sentence_source": "generated"}, {"text": "猫の体重は、四キロぐらいがちょうどいいです。", "target_word": "体重", "complexity_tier": "T3", "furigana": "猫[ねこ]の体重[たいじゅう]は、四[よん]キロぐらいがちょうどいいです。", "sentence_source": "generated"}, {"text": "健康診断の前の日は、体重を気にして食事を減らしました。", "target_word": "体重", "complexity_tier": "T3", "furigana": "健康[けんこう]診断[しんだん]の前[まえ]の日[ひ]は、体重[たいじゅう]を気[き]にして食事[しょくじ]を減[へ]らしました。", "sentence_source": "generated"}, {"text": "兄は体重が重いので、自転車のタイヤがすぐに減ります。", "target_word": "体重", "complexity_tier": "T3", "furigana": "兄[あに]は体重[たいじゅう]が重[おも]いので、自転車[じてんしゃ]のタイヤがすぐに減[へ]ります。", "sentence_source": "generated"}, {"text": "父は体重を毎週ノートに記録しています。", "target_word": "体重", "complexity_tier": "T3", "furigana": "父[ちち]は体重[たいじゅう]を毎週[まいしゅう]ノートに記録[きろく]しています。", "sentence_source": "generated"}, {"text": "子どもの体重が増えてきて、だっこするのが大変になりました。", "target_word": "体重", "complexity_tier": "T3", "furigana": "子[こ]どもの体重[たいじゅう]が増[ふ]えてきて、だっこするのが大変[たいへん]になりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体重", "label": "基本形"}], "register": "中立（ですます体）", "sense_fingerprint": "人や動物の体の重さ（キロで表す）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51573, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": true, "explanation": "『私の体重は五十キロです』は体の重さを表し、キロで量る語として成り立つ。"}, {"text": "体温", "is_correct": false, "explanation": "体温は温度なので、キロの数値で表す『私の体温は五十キロ』は成り立たない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は生きた年数なので、キロの数値で表す『私の年齢は五十キロ』は成り立たない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は生きる期間なので、キロの数値で表す『私の寿命は五十キロ』は成り立たない。"}], "explanations": {"体重": "『私の体重は五十キロです』は体の重さを表し、キロで量る語として成り立つ。", "体温": "体温は温度なので、キロの数値で表す『私の体温は五十キロ』は成り立たない。", "年齢": "年齢は生きた年数なので、キロの数値で表す『私の年齢は五十キロ』は成り立たない。", "寿命": "寿命は生きる期間なので、キロの数値で表す『私の寿命は五十キロ』は成り立たない。"}, "sentence_index": 0, "correct_answer": "体重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟は体重が高いので、ドアを頭でくぐれない。", "explanation": "ここは〈身長〉の意味。体重は重さなので『高い』とは言わず、背の高さは身長で表すので〈身長〉を使う。"}, {"text": "弟は体重が強いので、毎日長く走れる。", "explanation": "ここは〈体力〉の意味。体重は重さで、強さや走る能力は表さないので〈体力〉を使う。"}, {"text": "弟は体重が若いので、まだ小学生だ。", "explanation": "ここは〈年齢〉の意味。体重は重さで、若さや年の数は表さないので〈年齢〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51573, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": true, "explanation": "『体重を気にして食事を減らした』は体の重さを気にしたという意味で、文が成り立つ。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題を気にして食事を減らすという文は成り立たないので合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨を気にして食事を減らすという文は成り立たないので合わない。"}, {"text": "天井", "is_correct": false, "explanation": "天井を気にして食事を減らすという文は成り立たないので合わない。"}], "explanations": {"体重": "『体重を気にして食事を減らした』は体の重さを気にしたという意味で、文が成り立つ。", "宿題": "宿題を気にして食事を減らすという文は成り立たないので合わない。", "雨": "雨を気にして食事を減らすという文は成り立たないので合わない。", "天井": "天井を気にして食事を減らすという文は成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "体重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもの体重が細長くなって、だっこするのが大変になりました。", "explanation": "ここは〈体格〉の意味。体重は重さを表すので、体の細長さや形（体格）は表さないので合わない。"}, {"text": "子どもの体重が広くなって、ベッドに入らなくなりました。", "explanation": "ここは〈体積〉の意味。体重は重さなので、広さ（体積）は表さないので合わない。"}, {"text": "子どもの体重が長く寝るようになって、だっこが大変です。", "explanation": "ここは〈睡眠〉の意味。体重は重さで、寝る時間は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51573, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "病院で、体重が測ってもらいました。", "corrected_sentence": "病院で、体重を測ってもらいました。", "error_description": "『測る』は目的語に『を』を取る。『が』は主語を示すので、ここは『を』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51573, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "体重で量ったら、数字を紙に書きます。", "corrected_sentence": "体重を量ったら、数字を紙に書きます。", "error_description": "『量る』は目的語に『を』を取る。『で』は手段を示すので、ここは『を』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
