INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51574, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "人や動物の体全体の重さのこと。", "primary_collocate": null, "pronunciation": "たいじゅう", "ipa": "taidʑɯː", "syllable_count": 4, "sentences": [{"text": "彼らは驚くべきスピードで成長し、わずか数週間で出荷可能な体重になります。", "target_word": "体重", "complexity_tier": "T3", "furigana": "彼[かれ]らは驚[おどろ]くべきスピードで成長[せいちょう]し、わずか数週間[すうしゅうかん]で出荷[しゅっか]可能[かのう]な体重[たいじゅう]になります。", "sentence_source": "mined"}, {"text": "毎朝、起きてすぐに体重を量るのが私の習慣です。", "target_word": "体重", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、起[お]きてすぐに体重[たいじゅう]を量[はか]るのが私[わたし]の習慣[しゅうかん]です。", "sentence_source": "generated"}, {"text": "運動を始めてから、体重が三キロ減りました。", "target_word": "体重", "complexity_tier": "T3", "furigana": "運動[うんどう]を始[はじ]めてから、体重[たいじゅう]が三[さん]キロ減[へ]りました。", "sentence_source": "generated"}, {"text": "赤ちゃんの体重は、生まれてから半年で約二倍になります。", "target_word": "体重", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの体重[たいじゅう]は、生[う]まれてから半年[はんとし]で約[やく]二倍[にばい]になります。", "sentence_source": "generated"}, {"text": "ボクシングでは、試合の前に選手の体重を正式に計ります。", "target_word": "体重", "complexity_tier": "T3", "furigana": "ボクシングでは、試合[しあい]の前[まえ]に選手[せんしゅ]の体重[たいじゅう]を正式[せいしき]に計[はか]ります。", "sentence_source": "generated"}, {"text": "体重が重すぎると、膝に負担がかかって痛くなることがあります。", "target_word": "体重", "complexity_tier": "T3", "furigana": "体重[たいじゅう]が重[おも]すぎると、膝[ひざ]に負担[ふたん]がかかって痛[いた]くなることがあります。", "sentence_source": "generated"}, {"text": "犬の体重に合わせて、毎日のえさの量を決めています。", "target_word": "体重", "complexity_tier": "T3", "furigana": "犬[いぬ]の体重[たいじゅう]に合[あ]わせて、毎日[まいにち]のえさの量[りょう]を決[き]めています。", "sentence_source": "generated"}, {"text": "医者に、年齢と身長に合った体重を保つように言われました。", "target_word": "体重", "complexity_tier": "T3", "furigana": "医者[いしゃ]に、年齢[ねんれい]と身長[しんちょう]に合[あ]った体重[たいじゅう]を保[たも]つように言[い]われました。", "sentence_source": "generated"}, {"text": "冬休みに食べすぎて、体重が増えてしまいました。", "target_word": "体重", "complexity_tier": "T3", "furigana": "冬休[ふゆやす]みに食[た]べすぎて、体重[たいじゅう]が増[ふ]えてしまいました。", "sentence_source": "generated"}, {"text": "ゾウは体重が五トン以上にもなる大きな動物です。", "target_word": "体重", "complexity_tier": "T3", "furigana": "ゾウは体重[たいじゅう]が五[ご]トン以上[いじょう]にもなる大[おお]きな動物[どうぶつ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体重", "label": "基本形"}], "register": "中立", "sense_fingerprint": "人や動物の体全体の重さ（キロなどで量る）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51574, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": true, "explanation": "『出荷可能な体重』は出荷の基準となる重さという意味で、文が成り立つ。"}, {"text": "体温", "is_correct": false, "explanation": "体温は出荷の基準になる数値ではなく、『出荷可能な体温』とは言わないので合わない。"}, {"text": "病気", "is_correct": false, "explanation": "病気は状態を表す語で、出荷可能な程度の数値にはならないので合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は生きる期間を表す語で、出荷の基準にはならないので合わない。"}], "explanations": {"体重": "『出荷可能な体重』は出荷の基準となる重さという意味で、文が成り立つ。", "体温": "体温は出荷の基準になる数値ではなく、『出荷可能な体温』とは言わないので合わない。", "病気": "病気は状態を表す語で、出荷可能な程度の数値にはならないので合わない。", "寿命": "寿命は生きる期間を表す語で、出荷の基準にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "体重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "赤ちゃんの体重は、生まれてから半年で約十センチ伸びました。", "explanation": "ここは〈身長〉の意味。体重は重さ（キロ）で表し、長さ（センチ）では表さないので〈身長〉を使う。"}, {"text": "赤ちゃんの体重は、生まれてから半年でずいぶん丈夫になった。", "explanation": "ここは〈体力〉の意味。体重は体の重さなので、丈夫さや体の強さは〈体力〉で表し、体重とは合わない。"}, {"text": "赤ちゃんの体重は、生まれてから半年で三十八度まで上がった。", "explanation": "ここは〈体温〉の意味。体重は重さで、温度（度）では表さないので〈体温〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51574, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": true, "explanation": "『犬の体重に合わせて』は犬の重さを基準にするという意味で、文が成り立つ。"}, {"text": "毛色", "is_correct": false, "explanation": "毛色はえさの量の基準にならず、『毛色に合わせて』とは言わないので合わない。"}, {"text": "寝床", "is_correct": false, "explanation": "寝床はえさの量を決める基準にならないので合わない。"}, {"text": "名前", "is_correct": false, "explanation": "名前はえさの量を決める基準にならず、『名前に合わせて』とは言えない。"}], "explanations": {"体重": "『犬の体重に合わせて』は犬の重さを基準にするという意味で、文が成り立つ。", "毛色": "毛色はえさの量の基準にならず、『毛色に合わせて』とは言わないので合わない。", "寝床": "寝床はえさの量を決める基準にならないので合わない。", "名前": "名前はえさの量を決める基準にならず、『名前に合わせて』とは言えない。"}, "sentence_index": 6, "correct_answer": "体重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ゾウは体重が逞しくて、鼻で木を倒すほどだ。", "explanation": "ここは〈体格〉の意味。体重は重さを表すので、体つきのがっしりした様子は〈体格〉で言い、体重とは合わない。"}, {"text": "ゾウは体重が立方メートル以上にもなる大きな動物です。", "explanation": "ここは〈体積〉の意味。立方メートルは体積の単位で、体重はキロやトンで表すので合わない。"}, {"text": "ゾウは体重が五十歳で、まだ若い大きな動物です。", "explanation": "ここは〈年齢〉の意味。体重は重さで、生きた年数（年齢）は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51574, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "病院で、赤ちゃんの体重が量ってもらいました。", "corrected_sentence": "病院で、赤ちゃんの体重を量ってもらいました。", "error_description": "『量る』は目的語に『を』を取る。『が』は主語を示すので、ここは『を』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51574, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "体重を毎週量るて、ノートに書いています。", "corrected_sentence": "体重を毎週量って、ノートに書いています。", "error_description": "『量る』のて形は『量って』。『量るて』は誤った活用で、正しくは『量って』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51576, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51576, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ないで」の「で」。「驚かないでください」と依頼を表し、文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。依頼の文に続けると文が崩れる。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す「が」。「驚かないがください」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "対象や帰着点を表す「に」。「驚かないにください」は文が崩れる。"}], "correct_answer": "で", "explanations": {"で": "「ないで」の「で」。「驚かないでください」と依頼を表し、文が成り立つ。", "を": "目的語を表す「を」。依頼の文に続けると文が崩れる。", "が": "主語を表す「が」。「驚かないがください」は成り立たない。", "に": "対象や帰着点を表す「に」。「驚かないにください」は文が崩れる。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "相手・帰着点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51576, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "予想していなかったことに出会って、心が大きく動く。", "primary_collocate": null, "pronunciation": "おどろく", "ipa": "odoɾokɯ", "syllable_count": 4, "sentences": [{"text": "彼らは驚くべきスピードで成長し、わずか数週間で出荷可能な体重になります。", "target_word": "驚く", "complexity_tier": "T4", "furigana": "彼(かれ)らは驚(おどろ)くべきスピードで成長(せいちょう)し、わずか数週間(すうしゅうかん)で出荷可能(しゅっかかのう)な体重(たいじゅう)になります。", "sentence_source": "mined"}, {"text": "突然の大きな音に、犬も人もみんな驚いた。", "target_word": "驚いた", "complexity_tier": "T2", "furigana": "突然(とつぜん)の大(おお)きな音(おと)に、犬(いぬ)も人(ひと)もみんな驚(おどろ)いた。", "sentence_source": "generated"}, {"text": "試験の結果を見て、あまりに点数が高いので自分でも驚いた。", "target_word": "驚いた", "complexity_tier": "T3", "furigana": "試験(しけん)の結果(けっか)を見(み)て、あまりに点数(てんすう)が高(たか)いので自分(じぶん)でも驚(おどろ)いた。", "sentence_source": "generated"}, {"text": "彼が十年ぶりに帰ってきたと聞いて、家族は驚いた。", "target_word": "驚いた", "complexity_tier": "T3", "furigana": "彼(かれ)が十年(じゅうねん)ぶりに帰(かえ)ってきたと聞(き)いて、家族(かぞく)は驚(おどろ)いた。", "sentence_source": "generated"}, {"text": "子どもが一人で料理を作ったと知り、先生は驚いて目を丸くした。", "target_word": "驚いて", "complexity_tier": "T3", "furigana": "子(こ)どもが一人(ひとり)で料理(りょうり)を作(つく)ったと知(し)り、先生(せんせい)は驚(おどろ)いて目(め)を丸(まる)くした。", "sentence_source": "generated"}, {"text": "久しぶりに訪れた町の変わりように驚く人は多い。", "target_word": "驚く", "complexity_tier": "T3", "furigana": "久(ひさ)しぶりに訪(おとず)れた町(まち)の変(か)わりに驚(おどろ)く人(ひと)は多(おお)い。", "sentence_source": "generated"}, {"text": "彼女の歌のうまさに、会場の誰もが驚いた。", "target_word": "驚いた", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の歌(うた)のうまさに、会場(かいじょう)の誰(だれ)もが驚(おどろ)いた。", "sentence_source": "generated"}, {"text": "値段を聞いても驚かないでください。実は無料なんです。", "target_word": "驚かない", "complexity_tier": "T3", "furigana": "値段(ねだん)を聞(き)いても驚(おどろ)かないでください。実(じつ)は無料(むりょう)なんです。", "sentence_source": "generated"}, {"text": "朝起きたら雪が積もっていて、驚きました。", "target_word": "驚きました", "complexity_tier": "T2", "furigana": "朝(あさ)起(お)きたら雪(ゆき)が積(つ)もっていて、驚(おどろ)きました。", "sentence_source": "generated"}, {"text": "彼の突然の引退発表には、ファンだけでなく関係者も驚いた。", "target_word": "驚いた", "complexity_tier": "T4", "furigana": "彼(かれ)の突然(とつぜん)の引退発表(いんたいはっぴょう)には、ファンだけでなく関係者(かんけいしゃ)も驚(おどろ)いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "驚く", "label": "基本形"}, {"form": "驚かない", "label": "否定形"}, {"form": "驚いた", "label": "過去形"}, {"form": "驚いて", "label": "て形"}, {"form": "驚けば", "label": "仮定形"}, {"form": "驚こう", "label": "意志形"}, {"form": "驚きました", "label": "丁寧過去形"}], "register": "neutral", "sense_fingerprint": "予想外の出来事に出会って心が大きく動く意味の動詞(おどろく)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08e7e9f6-0f05-455b-afc5-ee87762d7379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51576, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "驚く", "is_correct": true, "explanation": "基本形で、「驚くべきスピード」と程度の大きさを表す連体修飾として文に合う。"}, {"text": "怒る", "is_correct": false, "explanation": "怒りの感情を表す。「怒るべきスピード」では成長の速さを表せず、文が成り立たない。"}, {"text": "泣く", "is_correct": false, "explanation": "泣く行為で、成長の速さの描写に使えない。「泣くべきスピード」は意味をなさない。"}, {"text": "笑う", "is_correct": false, "explanation": "笑う行為で、成長の速さを表せない。「笑うべきスピード」は文の描写に合わない。"}], "explanations": {"驚く": "基本形で、「驚くべきスピード」と程度の大きさを表す連体修飾として文に合う。", "怒る": "怒りの感情を表す。「怒るべきスピード」では成長の速さを表せず、文が成り立たない。", "泣く": "泣く行為で、成長の速さの描写に使えない。「泣くべきスピード」は意味をなさない。", "笑う": "笑う行為で、成長の速さを表せない。「笑うべきスピード」は文の描写に合わない。"}, "sentence_index": 0, "correct_answer": "驚く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒さで、手が驚いた。", "explanation": "ここは〈震える〉の場面。体が細かく揺れる動きには震えるを使い、心の動きを表す驚くは合わない。"}, {"text": "疲れて、すぐに驚いた。", "explanation": "ここは〈眠る〉の場面。眠りに落ちる意味で、心が動く驚くは合わないので、この言葉はこうは使わない。"}, {"text": "春になると、庭の花が驚いた。", "explanation": "ここは〈咲く〉の場面。花が開く変化には咲くを使い、驚くは人の心の反応なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51576, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驚いた", "is_correct": true, "explanation": "過去形。歌のうまさに会場の人々が受けた驚きを、過去の出来事として述べる。"}, {"text": "困った", "is_correct": false, "explanation": "困る感情で、歌のうまさへの反応としては文に合わない。"}, {"text": "悲しんだ", "is_correct": false, "explanation": "悲しむ感情で、歌のうまさへの反応として成り立たない。"}, {"text": "恥じた", "is_correct": false, "explanation": "自分の行いへの感情を表し、会場の人々の反応には当てはまらない。"}], "explanations": {"驚いた": "過去形。歌のうまさに会場の人々が受けた驚きを、過去の出来事として述べる。", "困った": "困る感情で、歌のうまさへの反応としては文に合わない。", "悲しんだ": "悲しむ感情で、歌のうまさへの反応として成り立たない。", "恥じた": "自分の行いへの感情を表し、会場の人々の反応には当てはまらない。"}, "sentence_index": 6, "correct_answer": "驚いた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬の朝、池が驚いた。", "explanation": "ここは〈凍る〉の場面。水が固まる変化には凍るを使い、心の動きを表す驚くは合わない。"}, {"text": "強い風で、木が驚いた。", "explanation": "ここは〈倒れる〉の場面。物が倒れる変化には倒れるを使い、驚くは人の心の反応なので合わない。"}, {"text": "夜空に、星が驚いた。", "explanation": "ここは〈光る〉の場面。星が光る様子には光るを使い、驚くは文の描写に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51576, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもは大きな音に驚くて、泣き出した。", "corrected_sentence": "子どもは大きな音に驚いて、泣き出した。", "error_description": "誤りは「驚くて」。「驚く」のて形は音便で「驚いて」になるので、「く」を「い」に変える。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "驚いた", "is_correct": true, "explanation": "過去形。大きな音への反応を過去の出来事として述べ、文を終えられる。"}, {"text": "驚いて", "is_correct": false, "explanation": "て形。文の途中で続ける形で、文末に置くと文が終わらない。"}, {"text": "驚けば", "is_correct": false, "explanation": "仮定形。条件を表すため、過去の反応を述べる文末には合わない。"}, {"text": "驚こう", "is_correct": false, "explanation": "意志・推量の形で、過去の出来事の描写に合わない。"}], "correct_form": "驚いた", "base_form": "驚く", "form_label": "過去形", "sentence_index": 1, "explanations": {"驚いた": "過去形。大きな音への反応を過去の出来事として述べ、文を終えられる。", "驚いて": "て形。文の途中で続ける形で、文末に置くと文が終わらない。", "驚けば": "仮定形。条件を表すため、過去の反応を述べる文末には合わない。", "驚こう": "意志・推量の形で、過去の出来事の描写に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51576, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試合の結果を聞いても驚きないでください。実は逆転勝ちなんです。", "corrected_sentence": "試合の結果を聞いても驚かないでください。実は逆転勝ちなんです。", "error_description": "誤りは「驚きない」。「驚く」の否定形は語幹「驚か」に「ない」を付けた「驚かない」なので、「き」を「か」に直す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "驚かない", "is_correct": true, "explanation": "否定形。「驚かないでください」と、驚かないよう求める依頼の文に合う。"}, {"text": "驚く", "is_correct": false, "explanation": "基本形。「驚くでください」とは続かず、依頼の文にならない。"}, {"text": "驚いた", "is_correct": false, "explanation": "過去形。「驚いたでください」は成り立たず、依頼の文に合わない。"}, {"text": "驚きました", "is_correct": false, "explanation": "丁寧な過去形。「驚きましたでください」と続かず、依頼の文に合わない。"}], "correct_form": "驚かない", "base_form": "驚く", "form_label": "否定形", "sentence_index": 7, "explanations": {"驚かない": "否定形。「驚かないでください」と、驚かないよう求める依頼の文に合う。", "驚く": "基本形。「驚くでください」とは続かず、依頼の文にならない。", "驚いた": "過去形。「驚いたでください」は成り立たず、依頼の文に合わない。", "驚きました": "丁寧な過去形。「驚きましたでください」と続かず、依頼の文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51577, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51577, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「つながる」は「に」で結果の対象を示す。「生育につながる」の形になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表す。「生育がつながる」は主語の使い方として合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表すが、「つながる」は目的語を取らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表す。「生育でつながる」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「つながる」は「に」で結果の対象を示す。「生育につながる」の形になる。", "が": "「が」は主語を表す。「生育がつながる」は主語の使い方として合わない。", "を": "「を」は目的語を表すが、「つながる」は目的語を取らないので合わない。", "で": "「で」は手段や場所を表す。「生育でつながる」は意味が通らない。"}, "error_tags": {"が": "主語の格。つながるは主語に生育を取らない", "を": "目的語の格。つながるは目的語を取らない", "で": "手段・場所の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51577, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "生き物が育つこと。", "primary_collocate": null, "pronunciation": "せいいく", "ipa": "seːikɯ", "syllable_count": 4, "sentences": [{"text": "池の水が汚れると、魚の生育が悪くなります。", "target_word": "生育", "complexity_tier": "T3", "furigana": "池[いけ]の水[みず]が汚[よご]れると、魚[さかな]の生育[せいいく]が悪[わる]くなります。", "sentence_source": "generated"}, {"text": "子牛の生育は順調で、体重も増えてきた。", "target_word": "生育", "complexity_tier": "T3", "furigana": "子牛[こうし]の生育[せいいく]は順調[じゅんちょう]で、体重[たいじゅう]も増[ふ]えてきた。", "sentence_source": "generated"}, {"text": "この水槽は温度が一定なので、メダカの生育に向いている。", "target_word": "生育", "complexity_tier": "T3", "furigana": "この水槽[すいそう]は温度[おんど]が一定[いってい]なので、メダカの生育[せいいく]に向[む]いている。", "sentence_source": "generated"}, {"text": "森では光が届かない場所だと、若木の生育が止まってしまう。", "target_word": "生育", "complexity_tier": "T3", "furigana": "森[もり]では光[ひかり]が届[とど]かない場所[ばしょ]だと、若木[わかぎ]の生育[せいいく]が止[と]まってしまう。", "sentence_source": "generated"}, {"text": "海がきれいなら、貝の生育もよくなる。", "target_word": "生育", "complexity_tier": "T3", "furigana": "海[うみ]がきれいなら、貝[かい]の生育[せいいく]もよくなる。", "sentence_source": "generated"}, {"text": "研究者は、ミツバチの生育を長い間観察している。", "target_word": "生育", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、ミツバチの生育[せいいく]を長[なが]い間[あいだ]観察[かんさつ]している。", "sentence_source": "generated"}, {"text": "栄養が足りないと、稚魚の生育が遅れることがある。", "target_word": "生育", "complexity_tier": "T3", "furigana": "栄養[えいよう]が足[た]りないと、稚魚[ちぎょ]の生育[せいいく]が遅[おく]れることがある。", "sentence_source": "generated"}, {"text": "川の環境を守ることは、サケの生育につながります。", "target_word": "生育", "complexity_tier": "T3", "furigana": "川[かわ]の環境[かんきょう]を守[まも]ることは、サケの生育[せいいく]につながります。", "sentence_source": "generated"}, {"text": "暑すぎる夏は、野菜だけでなく牛の生育にも悪い影響を与える。", "target_word": "生育", "complexity_tier": "T3", "furigana": "暑[あつ]すぎる夏[なつ]は、野菜[やさい]だけでなく牛[うし]の生育[せいいく]にも悪[わる]い影響[えいきょう]を与[あた]える。", "sentence_source": "generated"}, {"text": "この藻は水温が高いほど、生育が盛んになります。", "target_word": "生育", "complexity_tier": "T3", "furigana": "この藻[も]は水温[すいおん]が高[たか]いほど、生育[せいいく]が盛[さか]んになります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生育する", "label": "する動詞・辞書形"}, {"form": "生育した", "label": "過去形"}, {"form": "生育しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "動物・魚・植物など生き物全般が育つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51577, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "魚が育つ様子を表し、水が汚れて影響が出る文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、魚について言うことはできない。"}, {"text": "解散", "is_correct": false, "explanation": "団体などが散ることを表す。魚の状態を言う文脈には合わない。"}, {"text": "返品", "is_correct": false, "explanation": "買った品物を返すことを表す。魚の状態には使わない。"}], "explanations": {"生育": "魚が育つ様子を表し、水が汚れて影響が出る文脈に合う。", "天気": "空模様を表す語で、魚について言うことはできない。", "解散": "団体などが散ることを表す。魚の状態を言う文脈には合わない。", "返品": "買った品物を返すことを表す。魚の状態には使わない。"}, "sentence_index": 0, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この池では毎年、メダカが一度に百匹も生育する。", "explanation": "ここは〈繁殖〉の意味。生育は育つことで、数が増えることは指さないので合わない。"}, {"text": "彼は会社の業績を生育させるため、夜遅くまで働いた。", "explanation": "ここは〈業績を伸ばす〉の意味。生育は生き物が育つことなので、会社の業績には使わない。"}, {"text": "先生は学級通信を生育して、毎週配っている。", "explanation": "ここは〈作成〉の意味。生育は生き物の成長を言うので、紙の文書には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51577, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "「生育が遅れる」は稚魚の育つ速さが落ちることを表し、文脈に合う。"}, {"text": "改築", "is_correct": false, "explanation": "建物を作り直すことを表す。稚魚には使えないので合わない。"}, {"text": "謝罪", "is_correct": false, "explanation": "相手にわびることを表す。稚魚の状態には使わない。"}, {"text": "解約", "is_correct": false, "explanation": "契約をやめることを表す。稚魚には使わないので合わない。"}], "explanations": {"生育": "「生育が遅れる」は稚魚の育つ速さが落ちることを表し、文脈に合う。", "改築": "建物を作り直すことを表す。稚魚には使えないので合わない。", "謝罪": "相手にわびることを表す。稚魚の状態には使わない。", "解約": "契約をやめることを表す。稚魚には使わないので合わない。"}, "sentence_index": 6, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その映像会社は新作のアニメを生育している。", "explanation": "ここは〈製作〉の意味。生育は生き物の成長を言うので、映像作品には使わない。"}, {"text": "この町は人口が生育して、住民が増えた。", "explanation": "ここは〈増える〉の意味。生育は育つことで、人口の増加は指さないので合わない。"}, {"text": "彼は新しい曲を生育して、コンサートで披露した。", "explanation": "ここは〈作曲〉の意味。生育は生き物の成長に使うので、音楽を作る行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51577, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水温が高すぎると、稚魚の生育を止まる。", "corrected_sentence": "水温が高すぎると、稚魚の生育が止まる。", "error_description": "「止まる」は自動詞で、主語の「生育」に「が」を付ける。「生育を止まる」は誤りで、正しくは「生育が止まる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51577, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏は水温が高いと、稚魚の生育を進む。", "corrected_sentence": "夏は水温が高いと、稚魚の生育が進む。", "error_description": "「進む」は自動詞で、主語の「生育」に「が」を付ける。「生育を進む」は誤りで、正しくは「生育が進む」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
