INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51578, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「生育に大きな問題は見られない」の「に」は、問題の対象を示す形で、生育を対象として示す。"}, {"text": "を", "is_correct": false, "explanation": "「見られる」に「を」は付かず、「生育を大きな問題は」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示す。「生育から大きな問題は見られない」では起点にならず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示す。「生育より大きな問題は見られない」では比較の対象が合わず、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「生育に大きな問題は見られない」の「に」は、問題の対象を示す形で、生育を対象として示す。", "を": "「見られる」に「を」は付かず、「生育を大きな問題は」は成り立たない。", "から": "「から」は起点や理由を示す。「生育から大きな問題は見られない」では起点にならず、意味が通らない。", "より": "「より」は比較の基準を示す。「生育より大きな問題は見られない」では比較の対象が合わず、意味が通らない。"}, "error_tags": {"を": "目的語。見られるは目的語を取らない", "から": "起点・理由の格", "より": "比較の基準"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51578, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "生物が育ち、成長すること。特に、植物が育つことをいう。", "primary_collocate": null, "pronunciation": "せいいく", "ipa": "seːikɯ", "syllable_count": 4, "sentences": [{"text": "これは、作物の生育状況を細かく把握し、必要な水や肥料を的確に与える仕組みです。", "target_word": "生育", "complexity_tier": "T3", "furigana": "これは、作物[さくもつ]の生育[せいいく]状況[じょうきょう]を細[こま]かく把握[はあく]し、必要[ひつよう]な水[みず]や肥料[ひりょう]を的確[てきかく]に与[あた]える仕組[しく]みです。", "sentence_source": "mined"}, {"text": "今年は雨が少なく、トマトの生育が例年より遅れています。", "target_word": "生育", "complexity_tier": "T3", "furigana": "今年[ことし]は雨[あめ]が少[すく]なく、トマトの生育[せいいく]が例年[れいねん]より遅[おく]れています。", "sentence_source": "generated"}, {"text": "日当たりが悪いと、野菜の生育に影響が出ます。", "target_word": "生育", "complexity_tier": "T3", "furigana": "日当[ひあ]たりが悪[わる]いと、野菜[やさい]の生育[せいいく]に影響[えいきょう]が出[で]ます。", "sentence_source": "generated"}, {"text": "気温が低かったため、稲の生育は思うように進まなかった。", "target_word": "生育", "complexity_tier": "T3", "furigana": "気温[きおん]が低[ひく]かったため、稲[いね]の生育[せいいく]は思[おも]うように進[すす]まなかった。", "sentence_source": "generated"}, {"text": "この肥料は根の生育を助けるので、春先によく使われます。", "target_word": "生育", "complexity_tier": "T3", "furigana": "この肥料[ひりょう]は根[ね]の生育[せいいく]を助[たす]けるので、春先[はるさき]によく使[つか]われます。", "sentence_source": "generated"}, {"text": "農家の人は毎朝畑を回り、苗の生育を確かめている。", "target_word": "生育", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は毎朝[まいあさ]畑[はたけ]を回[まわ]り、苗[なえ]の生育[せいいく]を確[たし]かめている。", "sentence_source": "generated"}, {"text": "生育が早い品種を選べば、短い期間で収穫できます。", "target_word": "生育", "complexity_tier": "T3", "furigana": "生育[せいいく]が早[はや]い品種[ひんしゅ]を選[えら]べば、短[みじか]い期間[きかん]で収穫[しゅうかく]できます。", "sentence_source": "generated"}, {"text": "台風のあとも、ぶどうの生育に大きな問題は見られませんでした。", "target_word": "生育", "complexity_tier": "T3", "furigana": "台風[たいふう]のあとも、ぶどうの生育[せいいく]に大[おお]きな問題[もんだい]は見[み]られませんでした。", "sentence_source": "generated"}, {"text": "土の質を変えただけで、花の生育がずいぶんよくなった。", "target_word": "生育", "complexity_tier": "T3", "furigana": "土[つち]の質[しつ]を変[か]えただけで、花[はな]の生育[せいいく]がずいぶんよくなった。", "sentence_source": "generated"}, {"text": "温室では温度を管理して、苗の生育を安定させている。", "target_word": "生育", "complexity_tier": "T3", "furigana": "温室[おんしつ]では温度[おんど]を管理[かんり]して、苗[なえ]の生育[せいいく]を安定[あんてい]させている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生育する", "label": "する動詞・辞書形"}, {"form": "生育した", "label": "過去形"}, {"form": "生育しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "植物が育つこと(農業・栽培の文脈)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51578, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "作物が育つ様子を表し、水や肥料で管理する文脈に合う。"}, {"text": "生活", "is_correct": false, "explanation": "暮らしや生き方を指すので、作物の状況には合わない。"}, {"text": "養殖", "is_correct": false, "explanation": "魚などを人が育てて増やす意味で、作物には使わない。"}, {"text": "消滅", "is_correct": false, "explanation": "なくなることを表す。水や肥料を与えて管理する文脈とは合わない。"}], "explanations": {"生育": "作物が育つ様子を表し、水や肥料で管理する文脈に合う。", "生活": "暮らしや生き方を指すので、作物の状況には合わない。", "養殖": "魚などを人が育てて増やす意味で、作物には使わない。", "消滅": "なくなることを表す。水や肥料を与えて管理する文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妻は来月、双子を生育する予定だ。", "explanation": "ここは〈出産〉ではなく人の子を育てる文脈。生育は植物の成長に限るので、人には使わない。"}, {"text": "工場では毎日、部品を生育している。", "explanation": "ここは〈製造〉の意味。生育は生き物の成長に使う語で、機械で作る部品には合わない。"}, {"text": "彼女は数学の生育が学年でトップだ。", "explanation": "ここは〈成績〉の意味。生育は育つことなので、学業の評価には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51578, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "「生育が早い」は植物の育つ速さを表し、品種の性質を説明する。"}, {"text": "消費", "is_correct": false, "explanation": "使って減らすことを表す。品種の性質の説明には合わない。"}, {"text": "解散", "is_correct": false, "explanation": "団体などが散ることを表す。品種には使わない。"}, {"text": "返品", "is_correct": false, "explanation": "買った品物を返すことを表す。品種の話には合わない。"}], "explanations": {"生育": "「生育が早い」は植物の育つ速さを表し、品種の性質を説明する。", "消費": "使って減らすことを表す。品種の性質の説明には合わない。", "解散": "団体などが散ることを表す。品種には使わない。", "返品": "買った品物を返すことを表す。品種の話には合わない。"}, "sentence_index": 6, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しいアプリを生育して、来月リリースする。", "explanation": "ここは〈開発〉の意味。生育は生き物の成長に使うので、ソフトウェアには合わない。"}, {"text": "この会社は余った資金を生育させて、利益を増やした。", "explanation": "ここは〈運用〉の意味。生育は生き物が育つことなので、お金を増やす話には使わない。"}, {"text": "この鉱山では、石油を生育している。", "explanation": "ここは〈採掘〉の意味。生育は育つことで、地下から掘り出す資源には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51578, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が多かったので、トマトの生育を遅れた。", "corrected_sentence": "雨が多かったので、トマトの生育が遅れた。", "error_description": "「遅れる」は自動詞で、主語の「生育」に「が」を付ける。「生育を遅れた」は誤りで、正しくは「生育が遅れた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51578, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の雨が続いて、ぶどうの生育に進まなかった。", "corrected_sentence": "夏の雨が続いて、ぶどうの生育が進まなかった。", "error_description": "「進む」は主語に「が」を取る。「生育に進まなかった」は誤りで、正しくは「生育が進まなかった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
