INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51579, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "やくに たたない こと。", "primary_collocate": null, "pronunciation": "むだ", "ipa": "mɯda", "syllable_count": 2, "sentences": [{"text": "壊れた傘を持っていても無駄です。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "壊[こわ]れた傘[かさ]を持[も]っていても無駄[むだ]です。", "sentence_source": "generated"}, {"text": "練習しないで試合に出ても無駄だ。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "練習[れんしゅう]しないで試合[しあい]に出[で]ても無駄[むだ]だ。", "sentence_source": "generated"}, {"text": "紙をたくさん使うのは無駄だと思う。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "紙[かみ]をたくさん使[つか]うのは無駄[むだ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "無駄なものは買わないようにしている。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "無駄[むだ]なものは買[か]わないようにしている。", "sentence_source": "generated"}, {"text": "忘れ物を取りに戻ったが、店は閉まっていて無駄だった。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "忘[わす]れ物[もの]を取[と]りに戻[もど]ったが、店[みせ]は閉[し]まっていて無駄[むだ]だった。", "sentence_source": "generated"}, {"text": "水を出しっぱなしにするのは無駄ですよ。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "水[みず]を出[だ]しっぱなしにするのは無駄[むだ]ですよ。", "sentence_source": "generated"}, {"text": "彼に頼んでも無駄だよ、今日は忙しいから。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "彼[かれ]に頼[たの]んでも無駄[むだ]だよ、今日[きょう]は忙[いそが]しいから。", "sentence_source": "generated"}, {"text": "この部屋には無駄な物が一つもない。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "この部屋[へや]には無駄[むだ]な物[もの]が一[ひと]つもない。", "sentence_source": "generated"}, {"text": "急いで走ったのに、電車はもう出たあとで無駄になった。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "急[いそ]いで走[はし]ったのに、電車[でんしゃ]はもう出[で]たあとで無駄[むだ]になった。", "sentence_source": "generated"}, {"text": "地図を見ずに歩くと、時間を無駄にしてしまう。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ずに歩[ある]くと、時間[じかん]を無駄[むだ]にしてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無駄だ", "label": "断定形"}, {"form": "無駄な", "label": "連体形"}, {"form": "無駄に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "役に立たないこと(日常の簡単な用法)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51579, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無駄", "is_correct": true, "explanation": "役に立たないことを表し、壊れた傘を持っていても意味がないという文に合う。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙や荷物を届ける仕組みを表す。文の述語として成り立たない。"}, {"text": "景色", "is_correct": false, "explanation": "眺めのことを表す。役に立つかどうかの文脈には合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠くなる感覚を表す。傘を持つ文脈には合わない。"}], "explanations": {"無駄": "役に立たないことを表し、壊れた傘を持っていても意味がないという文に合う。", "郵便": "手紙や荷物を届ける仕組みを表す。文の述語として成り立たない。", "景色": "眺めのことを表す。役に立つかどうかの文脈には合わない。", "眠気": "眠くなる感覚を表す。傘を持つ文脈には合わない。"}, "sentence_index": 0, "correct_answer": "無駄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は無駄を凝らして、おいしい料理を作った。", "explanation": "ここは〈工夫〉の意味。無駄は役に立たないことで、「工夫を凝らす」の代わりには使わないので合わない。"}, {"text": "その映画は無駄が強く、長く記憶に残った。", "explanation": "ここは〈印象〉の意味。無駄は役に立たないことで、感じの強さは指さないので合わない。"}, {"text": "友達と相談して、週末の無駄を立てた。", "explanation": "ここは〈計画〉の意味。無駄は役に立たないことで、予定を組むことには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51579, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無駄", "is_correct": true, "explanation": "役に立たないことを表し、頼んでも意味がないという文脈に合う。"}, {"text": "辞書", "is_correct": false, "explanation": "言葉を調べる本を表す。頼んでも意味がない、という述語としては成り立たない。"}, {"text": "食卓", "is_correct": false, "explanation": "食事をする台を表す。文の述語として成り立たない。"}, {"text": "花束", "is_correct": false, "explanation": "花をまとめたものを表す。頼む行為の結果を述べる文には合わない。"}], "explanations": {"無駄": "役に立たないことを表し、頼んでも意味がないという文脈に合う。", "辞書": "言葉を調べる本を表す。頼んでも意味がない、という述語としては成り立たない。", "食卓": "食事をする台を表す。文の述語として成り立たない。", "花束": "花をまとめたものを表す。頼む行為の結果を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "無駄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "観客が無駄を送り、会場は大いに盛り上がった。", "explanation": "ここは〈拍手〉の意味。無駄は役に立たないことで、「拍手を送る」の代わりには使わないので合わない。"}, {"text": "この曲は無駄がきれいで、聴いていて心地よい。", "explanation": "ここは〈旋律〉の意味。無駄は役に立たないことで、音の美しさには使わないので合わない。"}, {"text": "彼は無駄を出して、先生に話しかけた。", "explanation": "ここは〈勇気〉の意味。「勇気を出す」と言い、無駄を出すとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51579, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この紙を使うのは無駄と思う。", "corrected_sentence": "この紙を使うのは無駄だと思う。", "error_description": "「無駄」は形容動詞なので、「と思う」の前には「だと」が必要。「無駄と思う」は誤りで、正しくは「無駄だと思う」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51579, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この机には無駄の物が一つもない。", "corrected_sentence": "この机には無駄な物が一つもない。", "error_description": "「無駄」は形容動詞で、名詞の前では「無駄な」になる。「無駄の物」は誤りで、正しくは「無駄な物」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
