INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51580, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "役に立たないこと。効果や益がないこと。", "primary_collocate": null, "pronunciation": "むだ", "ipa": "mɯda", "syllable_count": 2, "sentences": [{"text": "これにより、ムダを省きながら収量の「最適化」を図ることができます。", "target_word": "ムダ", "complexity_tier": "T3", "furigana": "これにより、ムダを省[はぶ]きながら収量[しゅうりょう]の「最適化[さいてきか]」を図[はか]ることができます。", "sentence_source": "mined"}, {"text": "電気をつけたまま寝ると、電気代の無駄になります。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "電気[でんき]をつけたまま寝[ね]ると、電気代[でんきだい]の無駄[むだ]になります。", "sentence_source": "generated"}, {"text": "話し合いもせずに決めたので、これまでの努力が無駄になった。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いもせずに決[き]めたので、これまでの努力[どりょく]が無駄[むだ]になった。", "sentence_source": "generated"}, {"text": "雨の日に出かけても無駄だと思い、家で本を読んだ。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]に出[で]かけても無駄[むだ]だと思[おも]い、家[いえ]で本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "彼は無駄な動きが少なく、仕事が早い。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "彼[かれ]は無駄[むだ]な動[うご]きが少[すく]なく、仕事[しごと]が早[はや]い。", "sentence_source": "generated"}, {"text": "何度言っても無駄なので、もう注意するのをやめた。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "何度[なんど]言[い]っても無駄[むだ]なので、もう注意[ちゅうい]するのをやめた。", "sentence_source": "generated"}, {"text": "食べ残しを減らして、食材の無駄を防ぎましょう。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "食[た]べ残[のこ]しを減[へ]らして、食材[しょくざい]の無駄[むだ]を防[ふせ]ぎましょう。", "sentence_source": "generated"}, {"text": "時間を無駄にしないために、前の日に準備しておく。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "時間[じかん]を無駄[むだ]にしないために、前[まえ]の日[ひ]に準備[じゅんび]しておく。", "sentence_source": "generated"}, {"text": "高い辞書を買ったのに一度も開かず、お金が無駄になってしまった。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "高[たか]い辞書[じしょ]を買[か]ったのに一度[いちど]も開[ひら]かず、お金[かね]が無駄[むだ]になってしまった。", "sentence_source": "generated"}, {"text": "会議が長いばかりで結論も出ない、無駄な時間だった。", "target_word": "無駄", "complexity_tier": "T3", "furigana": "会議[かいぎ]が長[なが]いばかりで結論[けつろん]も出[で]ない、無駄[むだ]な時間[じかん]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無駄だ", "label": "断定形"}, {"form": "無駄な", "label": "連体形"}, {"form": "無駄に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "効果・益がなく役に立たないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51580, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ムダ", "is_correct": true, "explanation": "「省く」の目的語として、無駄な部分を減らす文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、省くものとしては成り立たない。"}, {"text": "辞書", "is_correct": false, "explanation": "言葉を調べる本。省く対象として文が成り立たない。"}, {"text": "風景", "is_correct": false, "explanation": "景色を表す語。収量の最適化の文脈では省けるものにならない。"}], "explanations": {"ムダ": "「省く」の目的語として、無駄な部分を減らす文脈に合う。", "天気": "空模様を表す語で、省くものとしては成り立たない。", "辞書": "言葉を調べる本。省く対象として文が成り立たない。", "風景": "景色を表す語。収量の最適化の文脈では省けるものにならない。"}, "sentence_index": 0, "correct_answer": "ムダ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この機械は無駄が高く、一時間に多くの部品を作れる。", "explanation": "ここは〈効率〉の意味。無駄は役に立たないことで、能率の高さを表す語ではないので合わない。"}, {"text": "彼は無駄の才能があり、何でも短時間で仕上げる。", "explanation": "ここは〈才能〉の意味。無駄は役に立たないことで、人の能力の高さには使わないので合わない。"}, {"text": "彼は無駄をかけて、先輩の仕事を手伝った。", "explanation": "ここは〈手間〉の意味。「手間をかける」と言い、無駄を使ってかける形は言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51580, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無駄", "is_correct": true, "explanation": "食材の無駄を防ぐという文脈に合い、食べ残しを減らす話題と一致する。"}, {"text": "眠気", "is_correct": false, "explanation": "眠くなる感覚を表す。食材を防ぐ対象にはならない。"}, {"text": "写真", "is_correct": false, "explanation": "映像を記録したものを表す。食材の防止の対象としては成り立たない。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を知る道具を表す。食材を防ぐという文脈には合わない。"}], "explanations": {"無駄": "食材の無駄を防ぐという文脈に合い、食べ残しを減らす話題と一致する。", "眠気": "眠くなる感覚を表す。食材を防ぐ対象にはならない。", "写真": "映像を記録したものを表す。食材の防止の対象としては成り立たない。", "時計": "時刻を知る道具を表す。食材を防ぐという文脈には合わない。"}, "sentence_index": 6, "correct_answer": "無駄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷蔵庫の無駄を使って、夕飯を作った。", "explanation": "ここは〈残り物〉の意味。無駄は役に立たないことで、余った材料そのものは指さないので合わない。"}, {"text": "観客は選手に無駄を送り、大歓声が響いた。", "explanation": "ここは〈声援〉の意味。無駄は役に立たないことで、励ましの言葉や応援には使わないので合わない。"}, {"text": "このスープは無駄が深く、とても美味しい。", "explanation": "ここは〈味〉の意味。「味が深い」と言い、無駄は味の評価には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51580, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "あの旅行は無駄を終わった。", "corrected_sentence": "あの旅行は無駄に終わった。", "error_description": "「終わる」は自動詞で、「無駄に終わる」の形を取る。「無駄を終わった」は誤りで、正しくは「無駄に終わった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51580, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その時間は無駄の会議だった。", "corrected_sentence": "その時間は無駄な会議だった。", "error_description": "「無駄」は形容動詞で、名詞の前では「無駄な」になる。「無駄の会議」は誤りで、正しくは「無駄な会議」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
