INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51581, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "まちがいがないこと。", "primary_collocate": null, "pronunciation": "てきかく", "ipa": "tekikakɯ", "syllable_count": 4, "sentences": [{"text": "彼の答えは的確で、間違いが一つもなかった。", "target_word": "的確", "complexity_tier": "T3", "furigana": "彼[かれ]の答[こた]えは的確[てきかく]で、間違[まちが]いが一[ひと]つもなかった。", "sentence_source": "generated"}, {"text": "先生は私の質問に的確に答えてくれた。", "target_word": "的確", "complexity_tier": "T3", "furigana": "先生[せんせい]は私[わたし]の質問[しつもん]に的確[てきかく]に答[こた]えてくれた。", "sentence_source": "generated"}, {"text": "的確な指示のおかげで、作業は早く終わった。", "target_word": "的確", "complexity_tier": "T3", "furigana": "的確[てきかく]な指示[しじ]のおかげで、作業[さぎょう]は早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "この説明は短いが、とても的確です。", "target_word": "的確", "complexity_tier": "T3", "furigana": "この説明[せつめい]は短[みじか]いが、とても的確[てきかく]です。", "sentence_source": "generated"}, {"text": "彼のアドバイスは的確で、迷っていた進路がはっきりした。", "target_word": "的確", "complexity_tier": "T3", "furigana": "彼[かれ]のアドバイスは的確[てきかく]で、迷[まよ]っていた進路[しんろ]がはっきりした。", "sentence_source": "generated"}, {"text": "彼女はいつも的確に問題を見つける。", "target_word": "的確", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はいつも的確[てきかく]に問題[もんだい]を見[み]つける。", "sentence_source": "generated"}, {"text": "的確な判断をするために、情報をよく集める。", "target_word": "的確", "complexity_tier": "T3", "furigana": "的確[てきかく]な判断[はんだん]をするために、情報[じょうほう]をよく集[あつ]める。", "sentence_source": "generated"}, {"text": "店員が的確に場所を教えてくれたので、すぐ見つかった。", "target_word": "的確", "complexity_tier": "T3", "furigana": "店員[てんいん]が的確[てきかく]に場所[ばしょ]を教[おし]えてくれたので、すぐ見[み]つかった。", "sentence_source": "generated"}, {"text": "的確なたとえを使うと、話がわかりやすくなる。", "target_word": "的確", "complexity_tier": "T3", "furigana": "的確[てきかく]なたとえを使[つか]うと、話[はなし]がわかりやすくなる。", "sentence_source": "generated"}, {"text": "医者の的確な治療で、熱はすぐに下がった。", "target_word": "的確", "complexity_tier": "T3", "furigana": "医者[いしゃ]の的確[てきかく]な治療[ちりょう]で、熱[ねつ]はすぐに下[さ]がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "的確だ", "label": "断定形"}, {"form": "的確な", "label": "連体形"}, {"form": "的確に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "まちがいがなく正しいこと(日常の簡単な用法)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51581, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "的確", "is_correct": true, "explanation": "正解。「答えは的確で」は、答えにまちがいがないという意味で、文脈に合う。"}, {"text": "頑丈", "is_correct": false, "explanation": "「頑丈」は物の堅さを表すので、答えの正しさを述べる文には合わない。"}, {"text": "豪華", "is_correct": false, "explanation": "「豪華」は華やかさを表すので、答えがまちがいないかどうかとは関係がない。"}, {"text": "静粛", "is_correct": false, "explanation": "「静粛」は場が静かなさまを表すので、答えの性質には使えない。"}], "explanations": {"的確": "正解。「答えは的確で」は、答えにまちがいがないという意味で、文脈に合う。", "頑丈": "「頑丈」は物の堅さを表すので、答えの正しさを述べる文には合わない。", "豪華": "「豪華」は華やかさを表すので、答えがまちがいないかどうかとは関係がない。", "静粛": "「静粛」は場が静かなさまを表すので、答えの性質には使えない。"}, "sentence_index": 0, "correct_answer": "的確"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は的確に素早く仕事を終えた。", "explanation": "ここは〈迅速〉（すばやさ）の意味。速さは〈素早い〉や〈迅速〉で言い、〈的確〉（まちがいがない）とは合わない。"}, {"text": "この薬を飲めば、的確に治ると言われた。", "explanation": "ここは〈確実〉の意味。治癒の確かさは〈確実〉で表し、〈的確〉は合わない。"}, {"text": "先輩には的確な礼儀を尽くすようにしている。", "explanation": "ここは〈礼儀〉（作法）の意味。礼儀正しさは〈礼儀〉で言い、〈的確〉（まちがいがない）とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51581, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "的確", "is_correct": true, "explanation": "正解。「的確な判断をする」は、状況に合った正しい判断をするという意味で、文脈に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気」は人の性格や雰囲気を表すので、「陽気な判断」は成り立たない。"}, {"text": "饒舌", "is_correct": false, "explanation": "「饒舌」は話し方が多弁なさまを表すので、判断を修飾する語としては合わない。"}, {"text": "従順", "is_correct": false, "explanation": "「従順」は指示に素直に従う態度を表すので、判断の性質を述べる文には合わない。"}], "explanations": {"的確": "正解。「的確な判断をする」は、状況に合った正しい判断をするという意味で、文脈に合う。", "陽気": "「陽気」は人の性格や雰囲気を表すので、「陽気な判断」は成り立たない。", "饒舌": "「饒舌」は話し方が多弁なさまを表すので、判断を修飾する語としては合わない。", "従順": "「従順」は指示に素直に従う態度を表すので、判断の性質を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "的確"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は資格に的確で、試験にすぐ受かった。", "explanation": "ここは〈適格〉（資格を満たす）の意味。資格の要件を満たすことは〈適格〉で言い、〈的確〉とは合わない。"}, {"text": "その主張は的確な権利に基づいている。", "explanation": "ここは〈正当〉の意味。権利が道理にかなう場合は〈正当〉で言い、〈的確〉（状況に合う）は合わない。"}, {"text": "彼は的確なぜいたくで、高い服ばかり買う。", "explanation": "ここは〈贅沢〉（ぜいたくさ）の意味。ぜいたくさは〈贅沢〉で言い、〈的確〉（まちがいがない）とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51581, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その計算は的確に、結果に間違いがなかった。", "corrected_sentence": "その計算は的確で、結果に間違いがなかった。", "error_description": "形容動詞の述語には「で」が必要。「的確に」は動詞を修飾する形なので、ここでは述語として使えない。正しくは「的確で」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "的確に", "is_correct": true, "explanation": "連用形。動詞「答えてくれた」を修飾する副詞の形で、「に」を付けた形が使われる。"}, {"text": "的確だ", "is_correct": false, "explanation": "断定形。言い切りの形で、「答えてくれた」の前に置くと文が成り立たないので合わない。"}, {"text": "的確な", "is_correct": false, "explanation": "連体形。名詞の前に付く形で、動詞「答えてくれた」は修飾できないので合わない。"}, {"text": "的確で", "is_correct": false, "explanation": "中止形。文をつなぐ形で、動詞「答えてくれた」を修飾する位置には入らないので合わない。"}], "correct_form": "的確に", "base_form": "的確だ", "form_label": "連用形", "sentence_index": 1, "explanations": {"的確に": "連用形。動詞「答えてくれた」を修飾する副詞の形で、「に」を付けた形が使われる。", "的確だ": "断定形。言い切りの形で、「答えてくれた」の前に置くと文が成り立たないので合わない。", "的確な": "連体形。名詞の前に付く形で、動詞「答えてくれた」は修飾できないので合わない。", "的確で": "中止形。文をつなぐ形で、動詞「答えてくれた」を修飾する位置には入らないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51581, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "的確だ判断に基づいて、作業の手順を決めた。", "corrected_sentence": "的確な判断に基づいて、作業の手順を決めた。", "error_description": "名詞を修飾するには「な」が必要。「だ」は述語の形なので、名詞「判断」の前には置けない。正しくは「的確な判断」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "的確に", "is_correct": true, "explanation": "連用形。動詞「教えてくれた」を修飾する副詞の形で、「に」を付けた形が使われる。"}, {"text": "的確でない", "is_correct": false, "explanation": "否定形。正確さを否定する意味になり、副詞の位置には入らないので合わない。"}, {"text": "的確だろう", "is_correct": false, "explanation": "推量の形。名詞「場所」の前には置けず、文が成り立たないので合わない。"}, {"text": "的確ならば", "is_correct": false, "explanation": "条件の形。文末に続く形で、名詞「場所」を修飾できないので合わない。"}], "correct_form": "的確に", "base_form": "的確だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"的確に": "連用形。動詞「教えてくれた」を修飾する副詞の形で、「に」を付けた形が使われる。", "的確でない": "否定形。正確さを否定する意味になり、副詞の位置には入らないので合わない。", "的確だろう": "推量の形。名詞「場所」の前には置けず、文が成り立たないので合わない。", "的確ならば": "条件の形。文末に続く形で、名詞「場所」を修飾できないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
