INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51582, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事の状況や内容にぴったり合っていて、間違いのないさま。", "primary_collocate": null, "pronunciation": "てきかく", "ipa": "tekikakɯ", "syllable_count": 4, "sentences": [{"text": "これは、作物の生育状況を細かく把握し、必要な水や肥料を的確に与える仕組みです。", "target_word": "的確", "complexity_tier": "T3", "furigana": "これは、作物[さくもつ]の生育[せいいく]状況[じょうきょう]を細[こま]かく把握[はあく]し、必要[ひつよう]な水[みず]や肥料[ひりょう]を的確[てきかく]に与[あた]える仕組[しく]みです。", "sentence_source": "mined"}, {"text": "医者は症状を聞いて、的確な診断を下した。", "target_word": "的確", "complexity_tier": "T3", "furigana": "医者[いしゃ]は症状[しょうじょう]を聞[き]いて、的確[てきかく]な診断[しんだん]を下[くだ]した。", "sentence_source": "generated"}, {"text": "彼女の説明は短いが的確で、だれにでもよくわかる。", "target_word": "的確", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の説明[せつめい]は短[みじか]いが的確[てきかく]で、だれにでもよくわかる。", "sentence_source": "generated"}, {"text": "試合中、監督は的確に指示を出して流れを変えた。", "target_word": "的確", "complexity_tier": "T3", "furigana": "試合中[しあいちゅう]、監督[かんとく]は的確[てきかく]に指示[しじ]を出[だ]して流[なが]れを変[か]えた。", "sentence_source": "generated"}, {"text": "質問に的確に答えるには、まず内容を正しく理解する必要がある。", "target_word": "的確", "complexity_tier": "T3", "furigana": "質問[しつもん]に的確[てきかく]に答[こた]えるには、まず内容[ないよう]を正[ただ]しく理解[りかい]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "先生の的確なアドバイスのおかげで、作文が上手になった。", "target_word": "的確", "complexity_tier": "T3", "furigana": "先生[せんせい]の的確[てきかく]なアドバイスのおかげで、作文[さくぶん]が上手[じょうず]になった。", "sentence_source": "generated"}, {"text": "状況を的確に判断できる人は、困ったときにも落ち着いている。", "target_word": "的確", "complexity_tier": "T3", "furigana": "状況[じょうきょう]を的確[てきかく]に判断[はんだん]できる人[ひと]は、困[こま]ったときにも落[お]ち着[つ]いている。", "sentence_source": "generated"}, {"text": "会議では、問題点を的確に整理して、報告書にまとめた。", "target_word": "的確", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、問題点[もんだいてん]を的確[てきかく]に整理[せいり]して、報告書[ほうこくしょ]にまとめた。", "sentence_source": "generated"}, {"text": "道の説明が的確だったので、初めての町でも迷わなかった。", "target_word": "的確", "complexity_tier": "T3", "furigana": "道[みち]の説明[せつめい]が的確[てきかく]だったので、初[はじ]めての町[まち]でも迷[まよ]わなかった。", "sentence_source": "generated"}, {"text": "記者は事故の原因を的確にまとめて、記事に書いた。", "target_word": "的確", "complexity_tier": "T3", "furigana": "記者[きしゃ]は事故[じこ]の原因[げんいん]を的確[てきかく]にまとめて、記事[きじ]に書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "的確だ", "label": "断定形"}, {"form": "的確な", "label": "連体形"}, {"form": "的確に", "label": "連用形"}], "register": "formal", "sense_fingerprint": "状況や内容にぴったり合っていて間違いがないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51582, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "的確", "is_correct": true, "explanation": "正解。「的確に与える」は、状況に合わせて水や肥料を間違いなく与えるという意味で、文脈に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気」は人の性格や雰囲気を表す語なので、「陽気に与える」は成り立たない。"}, {"text": "饒舌", "is_correct": false, "explanation": "「饒舌」は話し方が多弁なさまを表すので、水や肥料を与える動作には使えない。"}, {"text": "静粛", "is_correct": false, "explanation": "「静粛」は場が静かなさまを表すので、物を与える動作を修飾できない。"}], "explanations": {"的確": "正解。「的確に与える」は、状況に合わせて水や肥料を間違いなく与えるという意味で、文脈に合う。", "陽気": "「陽気」は人の性格や雰囲気を表す語なので、「陽気に与える」は成り立たない。", "饒舌": "「饒舌」は話し方が多弁なさまを表すので、水や肥料を与える動作には使えない。", "静粛": "「静粛」は場が静かなさまを表すので、物を与える動作を修飾できない。"}, "sentence_index": 0, "correct_answer": "的確"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "救急隊は、通報を受けて的確にすぐ現場へ駆けつけた。", "explanation": "ここは〈迅速〉（すばやさ）の意味。速さは〈すぐ〉や〈迅速〉で言い、〈的確〉（状況に合う）とは合わない。"}, {"text": "この時計は的確で、一秒も狂わない。", "explanation": "ここは〈正確〉の意味。機械の精度は〈正確〉で言い、〈的確〉は状況への合い方を表すので合わない。"}, {"text": "この方法を使えば、的確に成功するはずだ。", "explanation": "ここは〈確実〉の意味。〈的確〉は状況に合っていることであり、成功の確かさは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51582, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "的確", "is_correct": true, "explanation": "正解。「状況を的確に判断できる」は、状況を正しく見極めて判断できるという意味で、文脈に合う。"}, {"text": "従順", "is_correct": false, "explanation": "「従順」は人が指示に素直に従う態度を表すので、判断の仕方を修飾できない。"}, {"text": "温厚", "is_correct": false, "explanation": "「温厚」は人柄がおだやかなことを表すので、判断の仕方には使えない。"}, {"text": "粗末", "is_correct": false, "explanation": "「粗末」は質が低いさまを表すので、判断を修飾する語としては成り立たない。"}], "explanations": {"的確": "正解。「状況を的確に判断できる」は、状況を正しく見極めて判断できるという意味で、文脈に合う。", "従順": "「従順」は人が指示に素直に従う態度を表すので、判断の仕方を修飾できない。", "温厚": "「温厚」は人柄がおだやかなことを表すので、判断の仕方には使えない。", "粗末": "「粗末」は質が低いさまを表すので、判断を修飾する語としては成り立たない。"}, "sentence_index": 6, "correct_answer": "的確"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は的確な権利を主張した。", "explanation": "ここは〈正当〉（道理にかなう）の意味。権利の正しさは〈正当〉で言い、〈的確〉（状況に合う）とは合わない。"}, {"text": "審判は的確に一方のチームへ肩入れして、判定を決めた。", "explanation": "ここは〈公正〉（偏らないこと）の意味。判定の公平さは〈公正〉で言い、〈的確〉（状況に合う）を偏った肩入れには当てはめられない。"}, {"text": "職人は部品の寸法を的確に測って、ミリ単位の差を見つけた。", "explanation": "ここは〈精密〉（細部まで精度が高いこと）の意味。細かい計測の精度は〈精密〉で言い、〈的確〉（状況に合う）とは区別される。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51582, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は的確の判断で、チームを勝利に導いた。", "corrected_sentence": "彼は的確な判断で、チームを勝利に導いた。", "error_description": "「的確」は形容動詞なので、名詞を修飾するには「な」が必要。「的確の判断」は誤りで、正しくは「的確な判断」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "的確な", "is_correct": true, "explanation": "連体形。名詞「診断」を修飾する形で、「な」を付けた形が使われる。"}, {"text": "的確だ", "is_correct": false, "explanation": "断定形。言い切りの形で、名詞「診断」の前には置けないので合わない。"}, {"text": "的確ならば", "is_correct": false, "explanation": "条件の形。名詞「診断」の前には置けず、文として成り立たないので合わない。"}, {"text": "的確で", "is_correct": false, "explanation": "中止形。文を続けるときの形で、名詞「診断」の前には置けないので合わない。"}], "correct_form": "的確な", "base_form": "的確だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"的確な": "連体形。名詞「診断」を修飾する形で、「な」を付けた形が使われる。", "的確だ": "断定形。言い切りの形で、名詞「診断」の前には置けないので合わない。", "的確ならば": "条件の形。名詞「診断」の前には置けず、文として成り立たないので合わない。", "的確で": "中止形。文を続けるときの形で、名詞「診断」の前には置けないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51582, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は的確と状況を見極めて、行動を決める。", "corrected_sentence": "彼女は的確に状況を見極めて、行動を決める。", "error_description": "「的確」は副詞として動詞「見極める」を修飾するので、格助詞「と」ではなく「に」を続ける。「的確と」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "的確に", "is_correct": true, "explanation": "連用形。動詞「整理して」を修飾する副詞の形で、「に」を付けた形が使われる。"}, {"text": "的確でない", "is_correct": false, "explanation": "否定形。「整理して」の前に入ると否定の意味になり、文の内容が反転するので合わない。"}, {"text": "的確だった", "is_correct": false, "explanation": "過去の断定形。動詞「整理して」の前には入らず、文の流れが合わない。"}, {"text": "的確であった", "is_correct": false, "explanation": "過去の書き言葉の断定形。動詞を修飾する位置には入らないので合わない。"}], "correct_form": "的確に", "base_form": "的確だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"的確に": "連用形。動詞「整理して」を修飾する副詞の形で、「に」を付けた形が使われる。", "的確でない": "否定形。「整理して」の前に入ると否定の意味になり、文の内容が反転するので合わない。", "的確だった": "過去の断定形。動詞「整理して」の前には入らず、文の流れが合わない。", "的確であった": "過去の書き言葉の断定形。動詞を修飾する位置には入らないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51583, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "条件の「と」。「省くと」で〈省けば〉の意味の条件を作る。"}, {"text": "に", "is_correct": false, "explanation": "「省くに」は動詞に直接続かず、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」は、「省くで」の形で動詞の条件を作れない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は「省くを」となり、動詞の後に続けられない。"}], "correct_answer": "と", "explanations": {"と": "条件の「と」。「省くと」で〈省けば〉の意味の条件を作る。", "に": "「省くに」は動詞に直接続かず、文として成り立たない。", "で": "手段・場所の「で」は、「省くで」の形で動詞の条件を作れない。", "を": "目的語の「を」は「省くを」となり、動詞の後に続けられない。"}, "error_tags": {"に": "接続不可", "で": "手段・場所", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51583, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「省こうと」の「と」。〈省こうとする〉の意図を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」だが、「省こうが」は文法的に成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」だが、「省こうから」は続かず、意図を表せない。"}, {"text": "の", "is_correct": false, "explanation": "名詞修飾の「の」だが、「省こうの」は名詞を修飾できず、成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「省こうと」の「と」。〈省こうとする〉の意図を表す。", "が": "主語を示す「が」だが、「省こうが」は文法的に成り立たない。", "から": "起点の「から」だが、「省こうから」は続かず、意図を表せない。", "の": "名詞修飾の「の」だが、「省こうの」は名詞を修飾できず、成り立たない。"}, "error_tags": {"が": "主語", "から": "起点", "の": "名詞修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51583, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いらないものをなくすこと。", "primary_collocate": null, "pronunciation": "はぶく", "ipa": "habɯkɯ", "syllable_count": 3, "sentences": [{"text": "飾りを省いたシンプルな服が、今年は人気です。", "target_word": "省いた", "complexity_tier": "T3", "furigana": "飾[かざ]りを省[はぶ]いたシンプルな服[ふく]が、今年[ことし]は人気[にんき]です。", "sentence_source": "generated"}, {"text": "余計な言葉を省くと、文章はずっと読みやすくなる。", "target_word": "省く", "complexity_tier": "T3", "furigana": "余計[よけい]な言葉[ことば]を省[はぶ]くと、文章[ぶんしょう]はずっと読[よ]みやすくなる。", "sentence_source": "generated"}, {"text": "不要な手続きを省いたので、申し込みが簡単になった。", "target_word": "省いた", "complexity_tier": "T3", "furigana": "不要[ふよう]な手続[てつづ]きを省[はぶ]いたので、申[もう]し込[こ]みが簡単[かんたん]になった。", "sentence_source": "generated"}, {"text": "無駄な動きを省いて、作業を速く終わらせた。", "target_word": "省いて", "complexity_tier": "T3", "furigana": "無駄[むだ]な動[うご]きを省[はぶ]いて、作業[さぎょう]を速[はや]く終[お]わらせた。", "sentence_source": "generated"}, {"text": "余計な装飾を省けば、資料はもっと見やすくなります。", "target_word": "省けば", "complexity_tier": "T3", "furigana": "余計[よけい]な装飾[そうしょく]を省[はぶ]けば、資料[しりょう]はもっと見[み]やすくなります。", "sentence_source": "generated"}, {"text": "彼は長い挨拶を省いて、すぐに本題に入った。", "target_word": "省いて", "complexity_tier": "T3", "furigana": "彼[かれ]は長[なが]い挨拶[あいさつ]を省[はぶ]いて、すぐに本題[ほんだい]に入[はい]った。", "sentence_source": "generated"}, {"text": "不要な機能を省いた分、この機械は軽くて安い。", "target_word": "省いた", "complexity_tier": "T3", "furigana": "不要[ふよう]な機能[きのう]を省[はぶ]いた分[ぶん]、この機械[きかい]は軽[かる]くて安[やす]い。", "sentence_source": "generated"}, {"text": "むだな出費を省こうと、家計簿をつけ始めた。", "target_word": "省こう", "complexity_tier": "T3", "furigana": "むだな出費[しゅっぴ]を省[はぶ]こうと、家計簿[かけいぼ]をつけ始[はじ]めた。", "sentence_source": "generated"}, {"text": "書類から古い情報を省いて、新しく作り直す。", "target_word": "省いて", "complexity_tier": "T3", "furigana": "書類[しょるい]から古[ふる]い情報[じょうほう]を省[はぶ]いて、新[あたら]しく作[つく]り直[なお]す。", "sentence_source": "generated"}, {"text": "形式的な手続きを省くことで、時間を節約できる。", "target_word": "省く", "complexity_tier": "T3", "furigana": "形式的[けいしきてき]な手続[てつづ]きを省[はぶ]くことで、時間[じかん]を節約[せつやく]できる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "省く", "label": "辞書形"}, {"form": "省き", "label": "連用形"}, {"form": "省いた", "label": "過去形"}, {"form": "省いて", "label": "て形"}, {"form": "省かない", "label": "否定形"}, {"form": "省けば", "label": "仮定形"}], "register": "標準（中立）", "sense_fingerprint": "余計なものを取り除いてなくす、省く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33db208a-4ad2-4e69-a0ee-68818b305fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51583, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "省いた", "is_correct": true, "explanation": "連体形「省いた」で「服」を修飾し、飾りを取り除いた服を表す。"}, {"text": "省き", "is_correct": false, "explanation": "連用形は名詞を修飾できず、「飾りを省きシンプルな服」は成立しない。"}, {"text": "省か", "is_correct": false, "explanation": "未然形は名詞を修飾できず、文として成り立たない。"}, {"text": "省け", "is_correct": false, "explanation": "命令・仮定の形は名詞を修飾できず、「省けシンプルな服」は成立しない。"}], "explanations": {"省いた": "連体形「省いた」で「服」を修飾し、飾りを取り除いた服を表す。", "省き": "連用形は名詞を修飾できず、「飾りを省きシンプルな服」は成立しない。", "省か": "未然形は名詞を修飾できず、文として成り立たない。", "省け": "命令・仮定の形は名詞を修飾できず、「省けシンプルな服」は成立しない。"}, "sentence_index": 0, "correct_answer": "省いた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は友人の気持ちを省いて、ひとりで話を続けた。", "explanation": "〈省く〉は不要なものを取り除く意味で、気持ちは取り除く対象にならないため合わない。"}, {"text": "祖母は娘の寂しさを省いて、懐かしそうに笑った。", "explanation": "〈省く〉は不要なものを取り除く意味で、寂しさを取り除く対象とはしないので、この文は合わない。"}, {"text": "彼は仲間の苦しみを省いて、そのまま寝てしまった。", "explanation": "〈省く〉に〈恩に報いる〉の意味はなく、恩を取り除く用法としても合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51583, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省いた", "is_correct": true, "explanation": "連体形「省いた」で「分」を修飾し、機能を取り除いた分という意味になる。"}, {"text": "省こう", "is_correct": false, "explanation": "意向形は「省こう分」と名詞を修飾できず、成り立たない。"}, {"text": "省かず", "is_correct": false, "explanation": "ず形は「省かず分」と続かず、文として成り立たない。"}, {"text": "省けば", "is_correct": false, "explanation": "仮定形は「省けば分」と続かず、名詞を修飾できない。"}], "explanations": {"省いた": "連体形「省いた」で「分」を修飾し、機能を取り除いた分という意味になる。", "省こう": "意向形は「省こう分」と名詞を修飾できず、成り立たない。", "省かず": "ず形は「省かず分」と続かず、文として成り立たない。", "省けば": "仮定形は「省けば分」と続かず、名詞を修飾できない。"}, "sentence_index": 6, "correct_answer": "省いた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は怒りを省いて、冷静に話をまとめた。", "explanation": "〈省く〉は不要なものを取り除く意味で、怒りを抑える意味は持たない。"}, {"text": "彼は仲間の笑顔を省いて、黙々と作業を続けた。", "explanation": "〈省く〉は不要なものを取り除く意味で、笑顔を交わす意味はなく、笑顔は取り除く対象にならない。"}, {"text": "彼女は失敗の責任を省いて、みんなに謝った。", "explanation": "〈省く〉は不要なものを取り除く意味で、責任を外す意味は持たず、この文は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51583, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は昼ご飯を省くて、散歩に出かけた。", "corrected_sentence": "祖母は昼ご飯を省いて、散歩に出かけた。", "error_description": "て形は「省いて」。辞書形「省く」に「て」をつけた「省くて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "省く", "is_correct": true, "explanation": "辞書形「省く」＋「と」で条件を表す。「省くと」で〈省けば〉の意味になる。"}, {"text": "省き", "is_correct": false, "explanation": "連用形は「省きと」となり、「と」の前に続かない。"}, {"text": "省か", "is_correct": false, "explanation": "未然形は「省かと」となり、条件の形として成り立たない。"}, {"text": "省け", "is_correct": false, "explanation": "命令・仮定の形は「省けと」となり、条件の「と」に続かない。"}], "correct_form": "省く", "base_form": "省く", "form_label": "辞書形", "sentence_index": 1, "explanations": {"省く": "辞書形「省く」＋「と」で条件を表す。「省くと」で〈省けば〉の意味になる。", "省き": "連用形は「省きと」となり、「と」の前に続かない。", "省か": "未然形は「省かと」となり、条件の形として成り立たない。", "省け": "命令・仮定の形は「省けと」となり、条件の「と」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51583, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "資料から古い情報に省いて、新しく作り直した。", "corrected_sentence": "資料から古い情報を省いて、新しく作り直した。", "error_description": "〈省く〉は「〜を省く」と目的語に「を」を取る。「古い情報に省いて」の「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "省こう", "is_correct": true, "explanation": "意向形「省こう」。「省こうと」で、省こうとする意図を表す。"}, {"text": "省かず", "is_correct": false, "explanation": "ず形は「省かずと」となり、「と」に続けても意図を表せない。"}, {"text": "省けば", "is_correct": false, "explanation": "仮定形は「省けばと」となり、「と」に続かない。"}, {"text": "省いて", "is_correct": false, "explanation": "て形は「省いてと」となり、「と」に続かず、意図の意味も表せない。"}], "correct_form": "省こう", "base_form": "省く", "form_label": "意向形", "sentence_index": 7, "explanations": {"省こう": "意向形「省こう」。「省こうと」で、省こうとする意図を表す。", "省かず": "ず形は「省かずと」となり、「と」に続けても意図を表せない。", "省けば": "仮定形は「省けばと」となり、「と」に続かない。", "省いて": "て形は「省いてと」となり、「と」に続かず、意図の意味も表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
