INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51584, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「省かずに」の「に」。ずに（〜しないで）の形で、省かないまま作る意味を作る。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」だが、「省かずを作る」は文法的に成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」だが、「省かずで作る」は不自然で、「ずに」の形にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」だが、「省かずへ作る」は続かず、文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「省かずに」の「に」。ずに（〜しないで）の形で、省かないまま作る意味を作る。", "を": "目的語の「を」だが、「省かずを作る」は文法的に成り立たない。", "で": "手段の「で」だが、「省かずで作る」は不自然で、「ずに」の形にならない。", "へ": "方向の「へ」だが、「省かずへ作る」は続かず、文として成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51584, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "無駄をなくす、不要なものを取り除く。", "primary_collocate": null, "pronunciation": "はぶく", "ipa": "habɯkɯ", "syllable_count": 3, "sentences": [{"text": "これにより、ムダを省きながら収量の「最適化」を図ることができます。", "target_word": "省き", "complexity_tier": "T3", "furigana": "これにより、ムダを省[はぶ]きながら収量[しゅうりょう]の「最適化[さいてきか]」を図[はか]ることができます。", "sentence_source": "mined"}, {"text": "時間がないので、説明の一部を省いて先に進みます。", "target_word": "省いて", "complexity_tier": "T3", "furigana": "時間[じかん]がないので、説明[せつめい]の一部[いちぶ]を省[はぶ]いて先[さき]に進[すす]みます。", "sentence_source": "generated"}, {"text": "手間を省くために、材料はあらかじめ切っておきます。", "target_word": "省く", "complexity_tier": "T3", "furigana": "手間[てま]を省[はぶ]くために、材料[ざいりょう]はあらかじめ切[き]っておきます。", "sentence_source": "generated"}, {"text": "記事が長すぎたため、細かい数字は省きました。", "target_word": "省き", "complexity_tier": "T3", "furigana": "記事[きじ]が長[なが]すぎたため、細[こま]かい数字[すうじ]は省[はぶ]きました。", "sentence_source": "generated"}, {"text": "無駄な会議を省けば、仕事の時間が増えるはずだ。", "target_word": "省けば", "complexity_tier": "T3", "furigana": "無駄[むだ]な会議[かいぎ]を省[はぶ]けば、仕事[しごと]の時間[じかん]が増[ふ]えるはずだ。", "sentence_source": "generated"}, {"text": "敬称は省いて、名前だけを表に書いてください。", "target_word": "省いて", "complexity_tier": "T3", "furigana": "敬称[けいしょう]は省[はぶ]いて、名前[なまえ]だけを表[ひょう]に書[か]いてください。", "sentence_source": "generated"}, {"text": "工程を省いたせいで、製品の品質が落ちてしまった。", "target_word": "省いた", "complexity_tier": "T3", "furigana": "工程[こうてい]を省[はぶ]いたせいで、製品[せいひん]の品質[ひんしつ]が落[お]ちてしまった。", "sentence_source": "generated"}, {"text": "この料理は手順を省かずに作るのが、おいしさのこつです。", "target_word": "省かず", "complexity_tier": "T3", "furigana": "この料理[りょうり]は手順[てじゅん]を省[はぶ]かずに作[つく]るのが、おいしさのこつです。", "sentence_source": "generated"}, {"text": "重複する項目を省いてから、一覧表を提出しました。", "target_word": "省いて", "complexity_tier": "T3", "furigana": "重複[ちょうふく]する項目[こうもく]を省[はぶ]いてから、一覧表[いちらんひょう]を提出[ていしゅつ]しました。", "sentence_source": "generated"}, {"text": "経費を省こうとして、安い部品を選んだ。", "target_word": "省こう", "complexity_tier": "T3", "furigana": "経費[けいひ]を省[はぶ]こうとして、安[やす]い部品[ぶひん]を選[えら]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "省く", "label": "辞書形"}, {"form": "省き", "label": "連用形"}, {"form": "省いた", "label": "過去形"}, {"form": "省いて", "label": "て形"}, {"form": "省かない", "label": "否定形"}, {"form": "省けば", "label": "仮定形"}], "register": "標準（中立）", "sense_fingerprint": "無駄や不要な部分を取り除いて簡単にする、省く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33db208a-4ad2-4e69-a0ee-68818b305fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51584, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "省き", "is_correct": true, "explanation": "連用形「省き」。「〜ながら」に続けて同時進行を表す。"}, {"text": "省か", "is_correct": false, "explanation": "未然形は「省かながら」となり、「ながら」に続かない。"}, {"text": "省け", "is_correct": false, "explanation": "命令・仮定の形は「省けながら」となり、成り立たない。"}, {"text": "省こう", "is_correct": false, "explanation": "意向形は「省こうながら」となり、「ながら」に続かない。"}], "explanations": {"省き": "連用形「省き」。「〜ながら」に続けて同時進行を表す。", "省か": "未然形は「省かながら」となり、「ながら」に続かない。", "省け": "命令・仮定の形は「省けながら」となり、成り立たない。", "省こう": "意向形は「省こうながら」となり、「ながら」に続かない。"}, "sentence_index": 0, "correct_answer": "省き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は健康を省いて、仕事を優先した。", "explanation": "〈省く〉は不要なものを取り除く意味で、健康は取り除く対象にならないため合わない。"}, {"text": "彼女は子どもの笑顔を省いて、厳しく育てた。", "explanation": "〈省く〉は不要なものを取り除く意味で、子どもの笑顔を取り除く対象とはしないので、この文は合わない。"}, {"text": "祖父は昔の恩を省いて、友人の店を訪ねた。", "explanation": "〈省く〉に〈恩に報いる〉の意味はなく、恩を取り除く用法としても合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51584, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省いた", "is_correct": true, "explanation": "過去形「省いた」。「省いたせいで」で原因を述べ、後の結果につなげる。"}, {"text": "省かず", "is_correct": false, "explanation": "ず形は「省かずせいで」とは続かず、原因を示せない。"}, {"text": "省けない", "is_correct": false, "explanation": "否定の可能形は「省けないせいで」となり、ここでは原因の意味が通らない。"}, {"text": "省いて", "is_correct": false, "explanation": "て形は「省いてせいで」と続かず、文として成立しない。"}], "explanations": {"省いた": "過去形「省いた」。「省いたせいで」で原因を述べ、後の結果につなげる。", "省かず": "ず形は「省かずせいで」とは続かず、原因を示せない。", "省けない": "否定の可能形は「省けないせいで」となり、ここでは原因の意味が通らない。", "省いて": "て形は「省いてせいで」と続かず、文として成立しない。"}, "sentence_index": 6, "correct_answer": "省いた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "相手の気持ちを省いて、言葉を選んだ。", "explanation": "〈省く〉に〈気持ちを思いやる〉の意味はなく、取り除く意味では気持ちは対象にならない。"}, {"text": "彼は友人の悲しみを省いて、冷静に話を進めた。", "explanation": "〈省く〉に〈悲しみに寄り添う〉の意味はなく、悲しみは取り除く対象にならない。"}, {"text": "店主は常連客の顔を省いて、新しい客だけを案内した。", "explanation": "〈省く〉に〈常連客を大切にする〉の意味はなく、人の顔を取り除く用法としても合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51584, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "資料の重複部分を省くて提出した。", "corrected_sentence": "資料の重複部分を省いて提出した。", "error_description": "て形は「省いて」。辞書形「省く」に「て」をつけた「省くて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "省いて", "is_correct": true, "explanation": "て形「省いて」。「省いて先に進む」で手順を省いた後の動作を表す。"}, {"text": "省く", "is_correct": false, "explanation": "辞書形は「省く先に進みます」となり、「先に」の前に続かない。"}, {"text": "省かない", "is_correct": false, "explanation": "否定形は「省かない先に」となり、文として成り立たない。"}, {"text": "省こう", "is_correct": false, "explanation": "意向形「省こう」は「省こう先に」と続かず、文として成り立たない。"}], "correct_form": "省いて", "base_form": "省く", "form_label": "て形", "sentence_index": 1, "explanations": {"省いて": "て形「省いて」。「省いて先に進む」で手順を省いた後の動作を表す。", "省く": "辞書形は「省く先に進みます」となり、「先に」の前に続かない。", "省かない": "否定形は「省かない先に」となり、文として成り立たない。", "省こう": "意向形「省こう」は「省こう先に」と続かず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51584, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "経費を省くようとして、新しい機械を買った。", "corrected_sentence": "経費を省こうとして、新しい機械を買った。", "error_description": "「〜ようとして」には意向形「省こう」が必要。辞書形「省く」に「ようとして」をつけた形は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "省かず", "is_correct": true, "explanation": "ず形「省かず」。「省かずに作る」で、省かないまま作る意味を表す。"}, {"text": "省いた", "is_correct": false, "explanation": "過去形は「省いた作る」となり、「作る」に続かない。"}, {"text": "省ける", "is_correct": false, "explanation": "可能形は「省ける作る」となり、文法的に成り立たない。"}, {"text": "省けない", "is_correct": false, "explanation": "否定の可能形は「省けない作る」となり、文が成立しない。"}], "correct_form": "省かず", "base_form": "省く", "form_label": "ず形", "sentence_index": 7, "explanations": {"省かず": "ず形「省かず」。「省かずに作る」で、省かないまま作る意味を表す。", "省いた": "過去形は「省いた作る」となり、「作る」に続かない。", "省ける": "可能形は「省ける作る」となり、文法的に成り立たない。", "省けない": "否定の可能形は「省けない作る」となり、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51585, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「収量が二倍になった」で、変化の主語を示す「が」が収量に付く。"}, {"text": "を", "is_correct": false, "explanation": "「収量を二倍になった」は目的語になれず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「収量に二倍になった」は帰着の意味になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「収量へ二倍になった」は方向の意味になり、変化の文として不自然。"}], "correct_answer": "が", "explanations": {"が": "「収量が二倍になった」で、変化の主語を示す「が」が収量に付く。", "を": "「収量を二倍になった」は目的語になれず、文が成り立たない。", "に": "「収量に二倍になった」は帰着の意味になり、文が成り立たない。", "へ": "「収量へ二倍になった」は方向の意味になり、変化の文として不自然。"}, "error_tags": {"を": "目的語", "に": "帰着", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51585, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「収量が上がった」で、上がる主体を示す「が」が収量に付く。"}, {"text": "に", "is_correct": false, "explanation": "「収量に上がった」は変化の主体を示せず、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「収量で上がった」は手段の意味になり、不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "「収量から上がった」は起点の意味になり、変化の主体を示せず不自然。"}], "correct_answer": "が", "explanations": {"が": "「収量が上がった」で、上がる主体を示す「が」が収量に付く。", "に": "「収量に上がった」は変化の主体を示せず、文として成り立たない。", "で": "「収量で上がった」は手段の意味になり、不自然になる。", "から": "「収量から上がった」は起点の意味になり、変化の主体を示せず不自然。"}, "error_tags": {"に": "帰着・方向", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51585, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とれる量のこと。", "primary_collocate": null, "pronunciation": "しゅうりょう", "ipa": "ɕɯːɾjoː", "syllable_count": 4, "sentences": [{"text": "今年は雨が多かったので、米の収量が減った。", "target_word": "収量", "complexity_tier": "T3", "furigana": "今年[ことし]は雨[あめ]が多[おお]かったので、米[こめ]の収量[しゅうりょう]が減[へ]った。", "sentence_source": "generated"}, {"text": "肥料を変えたら、トマトの収量が二倍になった。", "target_word": "収量", "complexity_tier": "T3", "furigana": "肥料[ひりょう]を変[か]えたら、トマトの収量[しゅうりょう]が二倍[にばい]になった。", "sentence_source": "generated"}, {"text": "同じ広さの畑でも、土によって収量はちがう。", "target_word": "収量", "complexity_tier": "T3", "furigana": "同[おな]じ広[ひろ]さの畑[はたけ]でも、土[つち]によって収量[しゅうりょう]はちがう。", "sentence_source": "generated"}, {"text": "農家の人は、毎年の収量を細かく記録している。", "target_word": "収量", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は、毎年[まいとし]の収量[しゅうりょう]を細[こま]かく記録[きろく]している。", "sentence_source": "generated"}, {"text": "新しい品種は、収量が多くて病気にも強い。", "target_word": "収量", "complexity_tier": "T3", "furigana": "新[あたら]しい品種[ひんしゅ]は、収量[しゅうりょう]が多[おお]くて病気[びょうき]にも強[つよ]い。", "sentence_source": "generated"}, {"text": "台風のせいで、果物の収量が例年の半分になった。", "target_word": "収量", "complexity_tier": "T3", "furigana": "台風[たいふう]のせいで、果物[くだもの]の収量[しゅうりょう]が例年[れいねん]の半分[はんぶん]になった。", "sentence_source": "generated"}, {"text": "収量を増やすために、水のやり方を工夫した。", "target_word": "収量", "complexity_tier": "T3", "furigana": "収量[しゅうりょう]を増[ふ]やすために、水[みず]のやり方[かた]を工夫[くふう]した。", "sentence_source": "generated"}, {"text": "去年より収量が上がったので、売り上げも伸びた。", "target_word": "収量", "complexity_tier": "T3", "furigana": "去年[きょねん]より収量[しゅうりょう]が上[あ]がったので、売[う]り上[あ]げも伸[の]びた。", "sentence_source": "generated"}, {"text": "畑の面積に対する収量を計算して、成果を比べた。", "target_word": "収量", "complexity_tier": "T3", "furigana": "畑[はたけ]の面積[めんせき]に対[たい]する収量[しゅうりょう]を計算[けいさん]して、成果[せいか]を比[くら]べた。", "sentence_source": "generated"}, {"text": "寒い夏は、麦の収量が下がりやすい。", "target_word": "収量", "complexity_tier": "T3", "furigana": "寒[さむ]い夏[なつ]は、麦[むぎ]の収量[しゅうりょう]が下[さ]がりやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "収量", "label": "基本形"}], "register": "常体（中立）", "sense_fingerprint": "農作物などの収穫でとれる量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aba9d36-096d-4db0-9fb9-3346be598cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51585, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "収量", "is_correct": true, "explanation": "米のとれた量が減るという意味になり、文が成り立つ。"}, {"text": "授業", "is_correct": false, "explanation": "「米の授業が減った」は意味が通らず、文が成り立たない。"}, {"text": "寝具", "is_correct": false, "explanation": "「米の寝具が減った」は収穫の文脈に合わず、文が成り立たない。"}, {"text": "乗用車", "is_correct": false, "explanation": "「米の乗用車が減った」は文の意味が成り立たない。"}], "explanations": {"収量": "米のとれた量が減るという意味になり、文が成り立つ。", "授業": "「米の授業が減った」は意味が通らず、文が成り立たない。", "寝具": "「米の寝具が減った」は収穫の文脈に合わず、文が成り立たない。", "乗用車": "「米の乗用車が減った」は文の意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "収量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は毎年の収量を税務署に報告している。", "explanation": "ここは〈収入〉の意味。収量は農作物などのとれた量で、お金の額には使わないので合わない。"}, {"text": "店は毎日、収量をパソコンで集計している。", "explanation": "ここは〈売上〉の意味。収量は農作物などのとれた量で、店の儲けには使わないので合わない。"}, {"text": "この電池は収量が長い。", "explanation": "ここは〈寿命〉の意味。収量はとれた量なので、製品の使用期間には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51585, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "収量", "is_correct": true, "explanation": "増やす対象としてとれた量を指すので、文が成り立つ。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書を増やすために水のやり方を工夫した」は文脈に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "水のやり方の工夫と結びつかず、文が不自然になる。"}, {"text": "運動会", "is_correct": false, "explanation": "「運動会を増やすために」は意味が通らず、文が成り立たない。"}], "explanations": {"収量": "増やす対象としてとれた量を指すので、文が成り立つ。", "教科書": "「教科書を増やすために水のやり方を工夫した」は文脈に合わない。", "座布団": "水のやり方の工夫と結びつかず、文が不自然になる。", "運動会": "「運動会を増やすために」は意味が通らず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "収量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日の運動で、収量が増えた。", "explanation": "ここは〈運動量〉の意味。収量はとれた量のことで、体の動きの量には使わないので合わない。"}, {"text": "休日は、道路の収量が増える。", "explanation": "ここは〈交通量〉の意味。収量は農作物の量で、道路を通る車の数には使わないので合わない。"}, {"text": "勉強しないと、収量が下がりやすい。", "explanation": "ここは〈学力〉の意味。収量は農作物のとれた量で、人の能力には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51585, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この畑では、今年の収量を去年より多い。", "corrected_sentence": "この畑では、今年の収量が去年より多い。", "error_description": "「多い」は形容詞で、主語の収量に「が」を付ける（誤：を／正：が）。「を」は目的語に付くため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51585, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長雨で、トマトの収量が下げた。", "corrected_sentence": "長雨で、トマトの収量が下がった。", "error_description": "「下がる」は自動詞なので「収量が下がった」が正しい（誤：下げた／正：下がった）。「下げた」は他動詞で、収量を動かす人が必要になるため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51587, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重視", "is_correct": true, "explanation": "〈無視〉の対義語。取り上げて大切に扱うこと。"}, {"text": "報告", "is_correct": false, "explanation": "情報を伝える意味の名詞で、〈無視〉と対になる関係ではない。"}, {"text": "雑談", "is_correct": false, "explanation": "気楽に話すこと。〈無視〉とは対義の関係にない。"}, {"text": "通知", "is_correct": false, "explanation": "知らせること。〈無視〉の反対の意味にはならない。"}], "correct_answer": "重視", "explanations": {"重視": "〈無視〉の対義語。取り上げて大切に扱うこと。", "報告": "情報を伝える意味の名詞で、〈無視〉と対になる関係ではない。", "雑談": "気楽に話すこと。〈無視〉とは対義の関係にない。", "通知": "知らせること。〈無視〉の反対の意味にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51587, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "尊重", "is_correct": true, "explanation": "〈無視〉の対義語。相手や意見を大切に扱うこと。"}, {"text": "談話", "is_correct": false, "explanation": "話をすること。〈無視〉と対になる関係ではない。"}, {"text": "交渉", "is_correct": false, "explanation": "条件を話し合うこと。〈無視〉の反対の意味にはならない。"}, {"text": "面会", "is_correct": false, "explanation": "人と会うこと。〈無視〉とは対義の関係にない。"}], "correct_answer": "尊重", "explanations": {"尊重": "〈無視〉の対義語。相手や意見を大切に扱うこと。", "談話": "話をすること。〈無視〉と対になる関係ではない。", "交渉": "条件を話し合うこと。〈無視〉の反対の意味にはならない。", "面会": "人と会うこと。〈無視〉とは対義の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51587, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "見なかったことにする。", "primary_collocate": null, "pronunciation": "むし", "ipa": "mɯɕi", "syllable_count": 2, "sentences": [{"text": "信号を無視して道を渡るのは危ない。", "target_word": "無視", "complexity_tier": "T3", "furigana": "信号[しんごう]を無視[むし]して道[みち]を渡[わた]るのは危[あぶ]ない。", "sentence_source": "generated"}, {"text": "友だちに声をかけたのに、無視されて悲しかった。", "target_word": "無視", "complexity_tier": "T3", "furigana": "友[とも]だちに声[こえ]をかけたのに、無視[むし]されて悲[かな]しかった。", "sentence_source": "generated"}, {"text": "彼は先生の注意を無視して、話し続けた。", "target_word": "無視", "complexity_tier": "T3", "furigana": "彼[かれ]は先生[せんせい]の注意[ちゅうい]を無視[むし]して、話[はな]し続[つづ]けた。", "sentence_source": "generated"}, {"text": "となりの人に挨拶したが、完全に無視された。", "target_word": "無視", "complexity_tier": "T3", "furigana": "となりの人[ひと]に挨拶[あいさつ]したが、完全[かんぜん]に無視[むし]された。", "sentence_source": "generated"}, {"text": "痛みを無視して走ったので、足が悪くなった。", "target_word": "無視", "complexity_tier": "T3", "furigana": "痛[いた]みを無視[むし]して走[はし]ったので、足[あし]が悪[わる]くなった。", "sentence_source": "generated"}, {"text": "メールを無視されたので、もう一度電話をかけた。", "target_word": "無視", "complexity_tier": "T3", "furigana": "メールを無視[むし]されたので、もう一度[いちど]電話[でんわ]をかけた。", "sentence_source": "generated"}, {"text": "ルールを無視する人が増えて、公園が汚れてしまった。", "target_word": "無視", "complexity_tier": "T3", "furigana": "ルールを無視[むし]する人[ひと]が増[ふ]えて、公園[こうえん]が汚[よご]れてしまった。", "sentence_source": "generated"}, {"text": "彼女の意見は無視できないほど大切だ。", "target_word": "無視", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の意見[いけん]は無視[むし]できないほど大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "警告を無視したせいで、データが全部消えてしまった。", "target_word": "無視", "complexity_tier": "T3", "furigana": "警告[けいこく]を無視[むし]したせいで、データが全部[ぜんぶ]消[き]えてしまった。", "sentence_source": "generated"}, {"text": "弟は私の質問を無視して、ゲームを続けた。", "target_word": "無視", "complexity_tier": "T3", "furigana": "弟[おとうと]は私[わたし]の質問[しつもん]を無視[むし]して、ゲームを続[つづ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無視する", "label": "辞書形"}, {"form": "無視した", "label": "過去形"}, {"form": "無視して", "label": "て形"}, {"form": "無視される", "label": "受身形"}, {"form": "無視しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "あることや人を、気づいていても取り上げず、なかったことのように扱うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8f1722b-8f6a-484b-8e04-67ac74b730cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51587, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無視", "is_correct": true, "explanation": "「信号を無視して」は決まりを守らずに進むという意味になり、ここで合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "「信号を翻訳する」は表示を別の言語に訳す意味になり、道を渡る文脈とつながらない。"}, {"text": "解説", "is_correct": false, "explanation": "「信号を解説する」は説明する意味で、道を渡るという行動と結びつかない。"}, {"text": "購入", "is_correct": false, "explanation": "「信号を購入する」は信号機を買う意味になり、ここでは意味が通らない。"}], "explanations": {"無視": "「信号を無視して」は決まりを守らずに進むという意味になり、ここで合う。", "翻訳": "「信号を翻訳する」は表示を別の言語に訳す意味になり、道を渡る文脈とつながらない。", "解説": "「信号を解説する」は説明する意味で、道を渡るという行動と結びつかない。", "購入": "「信号を購入する」は信号機を買う意味になり、ここでは意味が通らない。"}, "sentence_index": 0, "correct_answer": "無視"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "締め切りに気づかず、うっかり無視してしまった。", "explanation": "ここは〈見落とす〉の意味。〈無視〉は気づいたうえであえて取り上げないことなので、気づかなかった場合には合わない。"}, {"text": "会議で意見を求められたので、あえて無視して発言した。", "explanation": "〈無視〉は取り上げないこと。意見を求められて発言する流れとは両立せず、〈無言〉（黙っていること）と混同している。"}, {"text": "先生に呼ばれたので、すぐに無視して、用件を書き留めた。", "explanation": "〈聞き流す〉（注意せず流すこと）と混同している。〈無視〉は取り上げないことで、用件を書き留める行動とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51587, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無視", "is_correct": true, "explanation": "「ルールを無視する人」は決まりを守らない人という意味になり、ここで合う。"}, {"text": "採点", "is_correct": false, "explanation": "「ルールを採点する」は意味が通らず、文脈に合わない。"}, {"text": "収穫", "is_correct": false, "explanation": "「ルールを収穫する」は意味が通らない。"}, {"text": "撮影", "is_correct": false, "explanation": "「ルールを撮影する」は、ルールを写真にする意味になり、ここでは合わない。"}], "explanations": {"無視": "「ルールを無視する人」は決まりを守らない人という意味になり、ここで合う。", "採点": "「ルールを採点する」は意味が通らず、文脈に合わない。", "収穫": "「ルールを収穫する」は意味が通らない。", "撮影": "「ルールを撮影する」は、ルールを写真にする意味になり、ここでは合わない。"}, "sentence_index": 6, "correct_answer": "無視"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生の親切を無視して、すっかり忘れていた。", "explanation": "〈失念〉（うっかり忘れること）と混同している。〈無視〉は気づいたうえで取り上げないことなので、うっかり忘れた場合には使えない。"}, {"text": "壊れた屋根を無視して、業者に連絡した。", "explanation": "〈相談〉（助言を求めること）と混同している。〈無視〉は取り上げないことなので、業者に連絡して対応する行動とは両立しない。"}, {"text": "先生が話し始めたとき、私はあえて無視して、大きな拍手を送った。", "explanation": "〈歓迎〉（喜んで迎えること）と混同している。〈無視〉は取り上げないことなので、拍手で応じる行動とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51587, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもが赤信号を無視した、走り出した。", "corrected_sentence": "子どもが赤信号を無視して、走り出した。", "error_description": "「無視した」は過去形。後ろに動作が続くときは連用形の「無視して」にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51587, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "マナーに無視する人が増えて、駅が汚れてしまった。", "corrected_sentence": "マナーを無視する人が増えて、駅が汚れてしまった。", "error_description": "「無視する」の目的語を示すのは「を」。「に」にすると、他動詞「無視する」の対象にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
