INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51589, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「操作が難しい」の「が」で、形容詞「難しい」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的格だが、形容詞「難しい」の主語には「が」が使われるため合わない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す格で、「難しく」と続けると意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格で、この文では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「操作が難しい」の「が」で、形容詞「難しい」の主語を示す。", "を": "目的格だが、形容詞「難しい」の主語には「が」が使われるため合わない。", "に": "位置や相手を示す格で、「難しく」と続けると意味が通らない。", "へ": "方向を示す格で、この文では意味が通らない。"}, "error_tags": {"を": "目的格", "に": "位置・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51589, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "機械などを動かすこと。", "primary_collocate": null, "pronunciation": "そうさ", "ipa": "soːsa", "syllable_count": 3, "sentences": [{"text": "この機械の操作は、慣れれば簡単だ。", "target_word": "操作", "complexity_tier": "T3", "furigana": "この機械[きかい]の操作[そうさ]は、慣[な]れれば簡単[かんたん]だ。", "sentence_source": "generated"}, {"text": "説明書を読まずに操作したら、画面が消えてしまった。", "target_word": "操作", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]を読[よ]まずに操作[そうさ]したら、画面[がめん]が消[き]えてしまった。", "sentence_source": "generated"}, {"text": "スマホの操作がわからなくて、孫に教えてもらった。", "target_word": "操作", "complexity_tier": "T3", "furigana": "スマホの操作[そうさ]がわからなくて、孫[まご]に教[おし]えてもらった。", "sentence_source": "generated"}, {"text": "クレーンを操作する仕事には、資格が必要だ。", "target_word": "操作", "complexity_tier": "T3", "furigana": "クレーンを操作[そうさ]する仕事[しごと]には、資格[しかく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "操作を間違えると、機械が急に止まることがある。", "target_word": "操作", "complexity_tier": "T3", "furigana": "操作[そうさ]を間違[まちが]えると、機械[きかい]が急[きゅう]に止[と]まることがある。", "sentence_source": "generated"}, {"text": "子どもでも操作できるように、ボタンを大きくした。", "target_word": "操作", "complexity_tier": "T3", "furigana": "子[こ]どもでも操作[そうさ]できるように、ボタンを大[おお]きくした。", "sentence_source": "generated"}, {"text": "ロボットを遠くから操作して、危険な場所を調べる。", "target_word": "操作", "complexity_tier": "T3", "furigana": "ロボットを遠[とお]くから操作[そうさ]して、危険[きけん]な場所[ばしょ]を調[しら]べる。", "sentence_source": "generated"}, {"text": "新しいゲーム機は操作が難しく、すぐやめてしまった。", "target_word": "操作", "complexity_tier": "T3", "furigana": "新[あたら]しいゲーム機[き]は操作[そうさ]が難[むずか]しく、すぐやめてしまった。", "sentence_source": "generated"}, {"text": "工場では、機械を操作する前に必ず安全を確認する。", "target_word": "操作", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、機械[きかい]を操作[そうさ]する前[まえ]に必[かなら]ず安全[あんぜん]を確認[かくにん]する。", "sentence_source": "generated"}, {"text": "画面を指で操作するタイプのレジが増えている。", "target_word": "操作", "complexity_tier": "T3", "furigana": "画面[がめん]を指[ゆび]で操作[そうさ]するタイプのレジが増[ふ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "操作する", "label": "辞書形"}, {"form": "操作した", "label": "過去形"}, {"form": "操作して", "label": "て形"}, {"form": "操作できる", "label": "可能形"}, {"form": "操作しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "機械や道具を、ボタンなどを使って思いどおりに動かすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8f1722b-8f6a-484b-8e04-67ac74b730cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51589, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "操作", "is_correct": true, "explanation": "「機械の操作は、慣れれば簡単」は機械を動かすことの話になり、ここで合う。"}, {"text": "挨拶", "is_correct": false, "explanation": "「機械の挨拶」は意味が通らず、慣れれば簡単という文脈にも合わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "「機械の翻訳」は意味が通らず、文の内容と結びつかない。"}, {"text": "作曲", "is_correct": false, "explanation": "「機械の作曲」は意味が通らず、慣れれば簡単という文脈にも合わない。"}], "explanations": {"操作": "「機械の操作は、慣れれば簡単」は機械を動かすことの話になり、ここで合う。", "挨拶": "「機械の挨拶」は意味が通らず、慣れれば簡単という文脈にも合わない。", "翻訳": "「機械の翻訳」は意味が通らず、文の内容と結びつかない。", "作曲": "「機械の作曲」は意味が通らず、慣れれば簡単という文脈にも合わない。"}, "sentence_index": 0, "correct_answer": "操作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バイオリンを操作して、美しい音を響かせた。", "explanation": "〈演奏〉と混同している。楽器を弾くことは〈操作〉ではなく〈演奏〉と言う。"}, {"text": "工場では作業を操作して、製品を作った。", "explanation": "〈操作〉は機械を動かすこと。仕事の進行そのものには〈操作〉を使わず、〈進行〉（物事を進めること）と混同している。"}, {"text": "先輩は、後輩の操作を受けて仕事を覚えた。", "explanation": "〈指示〉と混同している。〈操作〉は機械を動かすことで、人からの指示の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51589, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "操作", "is_correct": true, "explanation": "「ロボットを遠くから操作して」は遠隔で機械を動かす意味になり、ここで合う。"}, {"text": "購入", "is_correct": false, "explanation": "「ロボットを遠くから購入して」は意味が通らず、調べるという文脈にも合わない。"}, {"text": "採点", "is_correct": false, "explanation": "「ロボットを遠くから採点して」は意味が通らない。"}, {"text": "収穫", "is_correct": false, "explanation": "「ロボットを遠くから収穫して」は意味が通らない。"}], "explanations": {"操作": "「ロボットを遠くから操作して」は遠隔で機械を動かす意味になり、ここで合う。", "購入": "「ロボットを遠くから購入して」は意味が通らず、調べるという文脈にも合わない。", "採点": "「ロボットを遠くから採点して」は意味が通らない。", "収穫": "「ロボットを遠くから収穫して」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "操作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "料理を操作して、おいしい味を出した。", "explanation": "〈調理〉（食材に手を加えること）と混同している。料理は〈操作〉ではなく〈調理〉と言う。"}, {"text": "彼は本を操作して、一日で読み終えた。", "explanation": "〈操作〉は機械や装置を動かすこと。本を読む行為は〈読書〉であって〈操作〉とは言わない。"}, {"text": "彼は歌を操作して、きれいに歌った。", "explanation": "〈歌う〉と混同している。歌は声を出す行為で、〈操作〉は機械や装置を動かすことに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51589, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このエアコンの操作を、説明書を読めば簡単だ。", "corrected_sentence": "このエアコンの操作は、説明書を読めば簡単だ。", "error_description": "主題の「は」を目的格の「を」にしたため、「簡単だ」の主語がなくなり文が成り立たない。正しくは「操作は」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
