INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51591, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「彼は…人材です」と主題を示す「は」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「彼を仕事ができる人材です」は述語と合わず非文。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、主題の位置には使えない。"}, {"text": "に", "is_correct": false, "explanation": "「彼に仕事ができる人材です」は文として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「彼は…人材です」と主題を示す「は」が入る。", "を": "「彼を仕事ができる人材です」は述語と合わず非文。", "へ": "「へ」は方向を示すので、主題の位置には使えない。", "に": "「彼に仕事ができる人材です」は文として成り立たない。"}, "error_tags": {"を": "object", "へ": "direction", "に": "dative"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
