INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51591, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "仕事で役に立つことができる人。", "primary_collocate": null, "pronunciation": "じんざい", "ipa": "dʑinzai", "syllable_count": 4, "sentences": [{"text": "彼は仕事ができる人材です。", "target_word": "人材", "complexity_tier": "T2", "furigana": "彼[かれ]は仕事[しごと]ができる人材[じんざい]です。", "sentence_source": "generated"}, {"text": "新しい人材が入りました。", "target_word": "人材", "complexity_tier": "T2", "furigana": "新[あたら]しい人材[じんざい]が入[はい]りました。", "sentence_source": "generated"}, {"text": "田中さんは店に必要な人材だ。", "target_word": "人材", "complexity_tier": "T3", "furigana": "田中[たなか]さんは店[みせ]に必要[ひつよう]な人材[じんざい]だ。", "sentence_source": "generated"}, {"text": "若い人材を育てたいと思っています。", "target_word": "人材", "complexity_tier": "T3", "furigana": "若[わか]い人材[じんざい]を育[そだ]てたいと思[おも]っています。", "sentence_source": "generated"}, {"text": "人材を集めるために広告を出した。", "target_word": "人材", "complexity_tier": "T3", "furigana": "人材[じんざい]を集[あつ]めるために広告[こうこく]を出[だ]した。", "sentence_source": "generated"}, {"text": "この仕事には経験のある人材がいい。", "target_word": "人材", "complexity_tier": "T3", "furigana": "この仕事[しごと]には経験[けいけん]のある人材[じんざい]がいい。", "sentence_source": "generated"}, {"text": "人材が足りなくて、みんな忙しい。", "target_word": "人材", "complexity_tier": "T3", "furigana": "人材[じんざい]が足[た]りなくて、みんな忙[いそが]しい。", "sentence_source": "generated"}, {"text": "会社は役に立つ人材を求めている。", "target_word": "人材", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は役[やく]に立[た]つ人材[じんざい]を求[もと]めている。", "sentence_source": "generated"}, {"text": "彼女のような人材は少ない。", "target_word": "人材", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のような人材[じんざい]は少[すく]ない。", "sentence_source": "generated"}, {"text": "人材の力で店は大きくなった。", "target_word": "人材", "complexity_tier": "T3", "furigana": "人材[じんざい]の力[ちから]で店[みせ]は大[おお]きくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人材育成", "label": "派生"}, {"form": "人材不足", "label": "派生"}, {"form": "人材派遣", "label": "派生"}, {"form": "人材確保", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 仕事で役に立つ能力のある人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa10040-79ce-478c-8cf8-7b3b9938243e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51591, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人材", "is_correct": true, "explanation": "じんざい。聞いた語そのもの。"}, {"text": "人災", "is_correct": false, "explanation": "じんさい。「ざ」が「さ」に変わる一拍違いで、別の語。"}, {"text": "心材", "is_correct": false, "explanation": "しんざい。「じ」が「し」に変わる一拍違いで、別の語。"}, {"text": "甚大", "is_correct": false, "explanation": "じんだい。「ざ」が「だ」に変わる一拍違いで、別の語。"}], "explanations": {"人材": "じんざい。聞いた語そのもの。", "人災": "じんさい。「ざ」が「さ」に変わる一拍違いで、別の語。", "心材": "しんざい。「じ」が「し」に変わる一拍違いで、別の語。", "甚大": "じんだい。「ざ」が「だ」に変わる一拍違いで、別の語。"}, "sentence_index": null, "correct_answer": "人材"}, "level_3": {"options": [{"text": "人材", "is_correct": true, "explanation": "仕事ができる人を指す語として自然に合う。"}, {"text": "建物", "is_correct": false, "explanation": "形は合うが、建物は仕事ができる主体ではないので意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節が仕事をすることはないので意味が合わない。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、果物は仕事ができる存在ではないので意味が合わない。"}], "explanations": {"人材": "仕事ができる人を指す語として自然に合う。", "建物": "形は合うが、建物は仕事ができる主体ではないので意味が合わない。", "季節": "形は合うが、季節が仕事をすることはないので意味が合わない。", "果物": "形は合うが、果物は仕事ができる存在ではないので意味が合わない。"}, "sentence_index": 0, "correct_answer": "人材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人材をポケットに入れて持ち歩いている。", "explanation": "「人材」は仕事で役立つ人を指す語で、ポケットに入れる物ではない。"}, {"text": "今日は人材が降っているので、傘を持っていく。", "explanation": "「人材」は天気の現象ではなく、降るものとして使えない。"}, {"text": "この人材は赤くて丸く、とても甘い。", "explanation": "「人材」は果物のような物ではなく、色や味を述べる対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51591, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "人材", "is_correct": true, "explanation": "じんざい。聞いた語そのもの。"}, {"text": "人体", "is_correct": false, "explanation": "じんたい。「ざ」が「た」に変わる一拍違いで、別の語。"}, {"text": "人界", "is_correct": false, "explanation": "じんかい。「ざ」が「か」に変わる一拍違いで、別の語。"}, {"text": "人外", "is_correct": false, "explanation": "じんがい。「ざ」が「が」に変わる一拍違いで、別の語。"}], "explanations": {"人材": "じんざい。聞いた語そのもの。", "人体": "じんたい。「ざ」が「た」に変わる一拍違いで、別の語。", "人界": "じんかい。「ざ」が「か」に変わる一拍違いで、別の語。", "人外": "じんがい。「ざ」が「が」に変わる一拍違いで、別の語。"}, "sentence_index": null, "correct_answer": "人材"}, "level_3": {"options": [{"text": "人材", "is_correct": true, "explanation": "足りないために皆が忙しくなるのは、働く人である。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気が足りないという言い方は意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節が足りないという言い方は意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、地震が足りないという言い方は意味が合わない。"}], "explanations": {"人材": "足りないために皆が忙しくなるのは、働く人である。", "天気": "形は合うが、天気が足りないという言い方は意味が合わない。", "季節": "形は合うが、季節が足りないという言い方は意味が合わない。", "地震": "形は合うが、地震が足りないという言い方は意味が合わない。"}, "sentence_index": 6, "correct_answer": "人材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人材を飲みながら、本を読んだ。", "explanation": "「人材」は飲み物ではなく、飲む対象にならない。"}, {"text": "人材を踏んで、床を掃除した。", "explanation": "「人材」は仕事で役に立つ人を指す語で、踏んで掃除に使う道具ではない。"}, {"text": "部屋の壁に人材を掛けて、時間を確認した。", "explanation": "「人材」は時計のような物ではなく、壁に掛けて時間を見る対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings,