INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51592, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "組織や会社のために必要な能力や知識を持った人。", "primary_collocate": null, "pronunciation": "じんざい", "ipa": "dʑinzai", "syllable_count": 4, "sentences": [{"text": "従来の肉体労働は減少しますが、機械を操作する専門知識を持つ人材の確保が、新たな課題として浮上しているのです。", "target_word": "人材", "complexity_tier": "T6", "furigana": "従来[じゅうらい]の肉体労働[にくたいろうどう]は減少[げんしょう]しますが、機械[きかい]を操作[そうさ]する専門知識[せんもんちしき]を持[も]つ人材[じんざい]の確保[かくほ]が、新[あら]たな課題[かだい]として浮上[ふじょう]しているのです。", "sentence_source": "mined"}, {"text": "会社は新しい人材を探しています。", "target_word": "人材", "complexity_tier": "T2", "furigana": "会社[かいしゃ]は新[あたら]しい人材[じんざい]を探[さが]しています。", "sentence_source": "generated"}, {"text": "この会社は人材が足りません。", "target_word": "人材", "complexity_tier": "T2", "furigana": "この会社[かいしゃ]は人材[じんざい]が足[た]りません。", "sentence_source": "generated"}, {"text": "人材を育てるには時間がかかります。", "target_word": "人材", "complexity_tier": "T3", "furigana": "人材[じんざい]を育[そだ]てるには時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "優秀な人材が集まる会社で働きたい。", "target_word": "人材", "complexity_tier": "T3", "furigana": "優秀[ゆうしゅう]な人材[じんざい]が集[あつ]まる会社[かいしゃ]で働[はたら]きたい。", "sentence_source": "generated"}, {"text": "彼は会社に欠かせない人材だ。", "target_word": "人材", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]に欠[か]かせない人材[じんざい]だ。", "sentence_source": "generated"}, {"text": "人材の育成に力を入れている。", "target_word": "人材", "complexity_tier": "T3", "furigana": "人材[じんざい]の育成[いくせい]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "外国から来た人材が活躍している。", "target_word": "人材", "complexity_tier": "T3", "furigana": "外国[がいこく]から来[き]た人材[じんざい]が活躍[かつやく]している。", "sentence_source": "generated"}, {"text": "専門知識のある人材を採用した。", "target_word": "人材", "complexity_tier": "T3", "furigana": "専門知識[せんもんちしき]のある人材[じんざい]を採用[さいよう]した。", "sentence_source": "generated"}, {"text": "人材が不足しているため、仕事が遅れている。", "target_word": "人材", "complexity_tier": "T3", "furigana": "人材[じんざい]が不足[ふそく]しているため、仕事[しごと]が遅[おく]れている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人材育成", "label": "派生"}, {"form": "人材不足", "label": "派生"}, {"form": "人材派遣", "label": "派生"}, {"form": "人材確保", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 組織に必要な能力や知識を持つ人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa10040-79ce-478c-8cf8-7b3b9938243e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51592, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人材", "is_correct": true, "explanation": "じんざい。聞いた語そのもの。"}, {"text": "人災", "is_correct": false, "explanation": "じんさい。「ざ」が「さ」に変わる一拍違いで、別の語。"}, {"text": "心材", "is_correct": false, "explanation": "しんざい。「じ」が「し」に変わる一拍違いで、別の語。"}, {"text": "甚大", "is_correct": false, "explanation": "じんだい。「ざ」が「だ」に変わる一拍違いで、別の語。"}], "explanations": {"人材": "じんざい。聞いた語そのもの。", "人災": "じんさい。「ざ」が「さ」に変わる一拍違いで、別の語。", "心材": "しんざい。「じ」が「し」に変わる一拍違いで、別の語。", "甚大": "じんだい。「ざ」が「だ」に変わる一拍違いで、別の語。"}, "sentence_index": null, "correct_answer": "人材"}, "level_3": {"options": [{"text": "人材", "is_correct": true, "explanation": "専門知識を持つ人を指し、「確保」とも自然に結びつく。"}, {"text": "建物", "is_correct": false, "explanation": "形は合うが、建物は専門知識を持たないので意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節は専門知識を持たないので意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気は専門知識を持たないので意味が合わない。"}], "explanations": {"人材": "専門知識を持つ人を指し、「確保」とも自然に結びつく。", "建物": "形は合うが、建物は専門知識を持たないので意味が合わない。", "季節": "形は合うが、季節は専門知識を持たないので意味が合わない。", "天気": "形は合うが、天気は専門知識を持たないので意味が合わない。"}, "sentence_index": 0, "correct_answer": "人材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上に人材を置いたまま帰りました。", "explanation": "「人材」は能力のある人を指す語で、机に置く物としては使えない。"}, {"text": "汚れた人材を洗濯機で洗いました。", "explanation": "「人材」は能力や知識を持つ人を指す語で、洗濯できる衣類のような物ではない。"}, {"text": "昨日の人材は晴れで、とても暖かかった。", "explanation": "「人材」は天気を表す語ではなく、天候の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51592, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "人材", "is_correct": true, "explanation": "じんざい。聞いた語そのもの。"}, {"text": "人体", "is_correct": false, "explanation": "じんたい。「ざ」が「た」に変わる一拍違いで、別の語。"}, {"text": "人界", "is_correct": false, "explanation": "じんかい。「ざ」が「か」に変わる一拍違いで、別の語。"}, {"text": "人外", "is_correct": false, "explanation": "じんがい。「ざ」が「が」に変わる一拍違いで、別の語。"}], "explanations": {"人材": "じんざい。聞いた語そのもの。", "人体": "じんたい。「ざ」が「た」に変わる一拍違いで、別の語。", "人界": "じんかい。「ざ」が「か」に変わる一拍違いで、別の語。", "人外": "じんがい。「ざ」が「が」に変わる一拍違いで、別の語。"}, "sentence_index": null, "correct_answer": "人材"}, "level_3": {"options": [{"text": "人材", "is_correct": true, "explanation": "「育成に力を入れる」の対象として、能力のある人が自然に合う。"}, {"text": "道路", "is_correct": false, "explanation": "形は合うが、道路は育成するものではないので意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気は育成できないので意味が合わない。"}, {"text": "建物", "is_correct": false, "explanation": "形は合うが、建物は育成するものではないので意味が合わない。"}], "explanations": {"人材": "「育成に力を入れる」の対象として、能力のある人が自然に合う。", "道路": "形は合うが、道路は育成するものではないので意味が合わない。", "天気": "形は合うが、天気は育成できないので意味が合わない。", "建物": "形は合うが、建物は育成するものではないので意味が合わない。"}, "sentence_index": 6, "correct_answer": "人材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人材を電子レンジで温めてから食べた。", "explanation": "「人材」は食べ物ではなく、温めて食べる対象にはならない。"}, {"text": "駅のホームに人材が落ちていたので、拾って交番に届けた。", "explanation": "「人材」は落とし物のような物ではなく、拾って届ける対象にならない。"}, {"text": "この人材はとても甘くて、お茶によく合う。", "explanation": "「人材」は味のある菓子などではなく、甘いと評せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED