INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51593, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "田んぼや畑がたくさんある、町ではない場所のことです。", "primary_collocate": null, "pronunciation": "のうそん", "ipa": "noːsoɴ", "syllable_count": 4, "sentences": [{"text": "祖父は農村に住んでいます。", "target_word": "農村", "complexity_tier": "T2", "furigana": "祖父[そふ]は農村[のうそん]に住[す]んでいます。", "sentence_source": "generated"}, {"text": "農村には田んぼが広がっています。", "target_word": "農村", "complexity_tier": "T3", "furigana": "農村[のうそん]には田[た]んぼが広[ひろ]がっています。", "sentence_source": "generated"}, {"text": "夏休みに農村へ行きました。", "target_word": "農村", "complexity_tier": "T2", "furigana": "夏休[なつやす]みに農村[のうそん]へ行[い]きました。", "sentence_source": "generated"}, {"text": "農村の朝は早いです。", "target_word": "農村", "complexity_tier": "T2", "furigana": "農村[のうそん]の朝[あさ]は早[はや]いです。", "sentence_source": "generated"}, {"text": "農村の空気はきれいだ。", "target_word": "農村", "complexity_tier": "T3", "furigana": "農村[のうそん]の空気[くうき]はきれいだ。", "sentence_source": "generated"}, {"text": "農村で野菜を作る体験をした。", "target_word": "農村", "complexity_tier": "T3", "furigana": "農村[のうそん]で野菜[やさい]を作[つく]る体験[たいけん]をした。", "sentence_source": "generated"}, {"text": "私の母は農村の出身です。", "target_word": "農村", "complexity_tier": "T2", "furigana": "私[わたし]の母[はは]は農村[のうそん]の出身[しゅっしん]です。", "sentence_source": "generated"}, {"text": "ここは町ではなく、農村だ。", "target_word": "農村", "complexity_tier": "T3", "furigana": "ここは町[まち]ではなく、農村[のうそん]だ。", "sentence_source": "generated"}, {"text": "農村では星がよく見える。", "target_word": "農村", "complexity_tier": "T3", "furigana": "農村[のうそん]では星[ほし]がよく見[み]える。", "sentence_source": "generated"}, {"text": "農村の道を自転車で走った。", "target_word": "農村", "complexity_tier": "T3", "furigana": "農村[のうそん]の道[みち]を自転車[じてんしゃ]で走[はし]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農村部", "label": "派生"}, {"form": "農村地帯", "label": "派生"}, {"form": "農村地域", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 田畑が広がる町ではない場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa10040-79ce-478c-8cf8-7b3b9938243e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51593, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "農村", "is_correct": true, "explanation": "のうそん。聞いた語そのもの。"}, {"text": "農産", "is_correct": false, "explanation": "のうさん。「そ」が「さ」に変わる一拍違いで、別の語。"}, {"text": "濃紺", "is_correct": false, "explanation": "のうこん。「そ」が「こ」に変わる一拍違いで、別の語。"}, {"text": "濃淡", "is_correct": false, "explanation": "のうたん。「そ」が「た」に変わる一拍違いで、別の語。"}], "explanations": {"農村": "のうそん。聞いた語そのもの。", "農産": "のうさん。「そ」が「さ」に変わる一拍違いで、別の語。", "濃紺": "のうこん。「そ」が「こ」に変わる一拍違いで、別の語。", "濃淡": "のうたん。「そ」が「た」に変わる一拍違いで、別の語。"}, "sentence_index": null, "correct_answer": "農村"}, "level_3": {"options": [{"text": "農村", "is_correct": true, "explanation": "祖父が住む場所として、田畑のある地域が自然に合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、人が机に住むことはないので意味が合わない。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが、時間に住むという言い方は意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節に住むという言い方は意味が合わない。"}], "explanations": {"農村": "祖父が住む場所として、田畑のある地域が自然に合う。", "机": "形は合うが、人が机に住むことはないので意味が合わない。", "時間": "形は合うが、時間に住むという言い方は意味が合わない。", "季節": "形は合うが、季節に住むという言い方は意味が合わない。"}, "sentence_index": 0, "correct_answer": "農村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "農村をコップに入れて、水と一緒に飲んだ。", "explanation": "「農村」は田畑のある場所を指す語で、飲み物ではない。"}, {"text": "農村には高層ビルや地下鉄が並び、いつも大都会だ。", "explanation": "「農村」は町ではない田畑の場所で、大都会の意味では使えない。"}, {"text": "農村は昨日、私にメールを送ってくれた。", "explanation": "「農村」は場所を指す語で、メールを送る人ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, genera