INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51594, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "都市以外の、農業を主な産業とする地域。田舎。", "primary_collocate": null, "pronunciation": "のうそん", "ipa": "noːsoɴ", "syllable_count": 4, "sentences": [{"text": "一方で、農村経済全体を見ると、労働需要の質が変化するという社会経済的影響も無視できません。", "target_word": "農村", "complexity_tier": "T6", "furigana": "一方[いっぽう]で、農村経済[のうそんけいざい]全体[ぜんたい]を見[み]ると、労働需要[ろうどうじゅよう]の質[しつ]が変化[へんか]するという社会経済的[しゃかいけいざいてき]影響[えいきょう]も無視[むし]できません。", "sentence_source": "mined"}, {"text": "農村では人口が減っています。", "target_word": "農村", "complexity_tier": "T2", "furigana": "農村[のうそん]では人口[じんこう]が減[へ]っています。", "sentence_source": "generated"}, {"text": "彼は農村で生まれ育った。", "target_word": "農村", "complexity_tier": "T3", "furigana": "彼[かれ]は農村[のうそん]で生[う]まれ育[そだ]った。", "sentence_source": "generated"}, {"text": "農村の高齢化が進んでいる。", "target_word": "農村", "complexity_tier": "T3", "furigana": "農村[のうそん]の高齢化[こうれいか]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "都市から農村へ移り住む人が増えた。", "target_word": "農村", "complexity_tier": "T3", "furigana": "都市[とし]から農村[のうそん]へ移[うつ]り住[す]む人[ひと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "農村には若い働き手が少ない。", "target_word": "農村", "complexity_tier": "T3", "furigana": "農村[のうそん]には若[わか]い働[はたら]き手[て]が少[すく]ない。", "sentence_source": "generated"}, {"text": "政府は農村を支える政策を発表した。", "target_word": "農村", "complexity_tier": "T3", "furigana": "政府[せいふ]は農村[のうそん]を支[ささ]える政策[せいさく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "この農村の主な産業は農業です。", "target_word": "農村", "complexity_tier": "T3", "furigana": "この農村[のうそん]の主[おも]な産業[さんぎょう]は農業[のうぎょう]です。", "sentence_source": "generated"}, {"text": "農村と都市の差が大きくなってきた。", "target_word": "農村", "complexity_tier": "T3", "furigana": "農村[のうそん]と都市[とし]の差[さ]が大[おお]きくなってきた。", "sentence_source": "generated"}, {"text": "農村に住む人々の暮らしを調べた。", "target_word": "農村", "complexity_tier": "T3", "furigana": "農村[のうそん]に住[す]む人々[ひとびと]の暮[く]らしを調[しら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農村部", "label": "派生"}, {"form": "農村地帯", "label": "派生"}, {"form": "農村地域", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 農業が中心の都市以外の地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa10040-79ce-478c-8cf8-7b3b9938243e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51594, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "農村", "is_correct": true, "explanation": "のうそん。聞いた語そのもの。"}, {"text": "農産", "is_correct": false, "explanation": "のうさん。「そ」が「さ」に変わる一拍違いで、別の語。"}, {"text": "濃紺", "is_correct": false, "explanation": "のうこん。「そ」が「こ」に変わる一拍違いで、別の語。"}, {"text": "濃淡", "is_correct": false, "explanation": "のうたん。「そ」が「た」に変わる一拍違いで、別の語。"}], "explanations": {"農村": "のうそん。聞いた語そのもの。", "農産": "のうさん。「そ」が「さ」に変わる一拍違いで、別の語。", "濃紺": "のうこん。「そ」が「こ」に変わる一拍違いで、別の語。", "濃淡": "のうたん。「そ」が「た」に変わる一拍違いで、別の語。"}, "sentence_index": null, "correct_answer": "農村"}, "level_3": {"options": [{"text": "農村", "is_correct": true, "explanation": "「農村経済」は農業中心の地域の経済で、文脈に合う。"}, {"text": "野球", "is_correct": false, "explanation": "形は合うが、野球経済では労働需要の質の変化という文脈に意味が合わない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、地図経済という言い方は意味が合わない。"}, {"text": "台所", "is_correct": false, "explanation": "形は合うが、台所経済では社会経済的影響の文脈に意味が合わない。"}], "explanations": {"農村": "「農村経済」は農業中心の地域の経済で、文脈に合う。", "野球": "形は合うが、野球経済では労働需要の質の変化という文脈に意味が合わない。", "地図": "形は合うが、地図経済という言い方は意味が合わない。", "台所": "形は合うが、台所経済では社会経済的影響の文脈に意味が合わない。"}, "sentence_index": 0, "correct_answer": "農村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "農村には大きな駅とデパートが集まり、日本で最も人口が多い。", "explanation": "「農村」は農業中心の地域で、大都市のような場所には使えない。"}, {"text": "農村を食べると、甘くてとてもおいしい。", "explanation": "「農村」は地域を指す語で、食べ物ではない。"}, {"text": "農村を持って、教室の中に入った。", "explanation": "「農村」は地域を指す語で、手に持てる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51594, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "農村", "is_correct": true, "explanation": "のうそん。聞いた語そのもの。"}, {"text": "納棺", "is_correct": false, "explanation": "のうかん。「そ」が「か」に変わる一拍違いで、別の語。"}, {"text": "納本", "is_correct": false, "explanation": "のうほん。「そ」が「ほ」に変わる一拍違いで、別の語。"}, {"text": "脳天", "is_correct": false, "explanation": "のうてん。「そ」が「て」に変わる一拍違いで、別の語。"}], "explanations": {"農村": "のうそん。聞いた語そのもの。", "納棺": "のうかん。「そ」が「か」に変わる一拍違いで、別の語。", "納本": "のうほん。「そ」が「ほ」に変わる一拍違いで、別の語。", "脳天": "のうてん。「そ」が「て」に変わる一拍違いで、別の語。"}, "sentence_index": null, "correct_answer": "農村"}, "level_3": {"options": [{"text": "農村", "is_correct": true, "explanation": "政府が支える対象として、農業中心の地域が自然に合う。"}, {"text": "雨", "is_correct": false, "explanation": "形は合うが、雨を支える政策では意味が合わない。"}, {"text": "星", "is_correct": false, "explanation": "形は合うが、政府が星を支える政策というのは意味が合わない。"}, {"text": "雲", "is_correct": false, "explanation": "形は合うが、雲を支える政策では意味が合わない。"}], "explanations": {"農村": "政府が支える対象として、農業中心の地域が自然に合う。", "雨": "形は合うが、雨を支える政策では意味が合わない。", "星": "形は合うが、政府が星を支える政策というのは意味が合わない。", "雲": "形は合うが、雲を支える政策では意味が合わない。"}, "sentence_index": 6, "correct_answer": "農村"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "農村を着て、寒い冬の朝に出かけた。", "explanation": "「農村」は地域を指す語で、衣服のように着る物ではない。"}, {"text": "農村が急に鳴り出したので、電話に出た。", "explanation": "「農村」は地域を指す語で、電話のように鳴る物ではない。"}, {"text": "農村に乗って、会社まで十分で着いた。", "explanation": "「農村」は地域を指す語で、電車などの乗り物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51594, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府は農村に支える政策を進めた。", "corrected_sentence": "政府は農村を支える政策を進めた。", "error_description": "「支える」の対象は「農村を」であり、「農村に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51594, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多くの人が農村で出身だと言った。", "corrected_sentence": "多くの人が農村の出身だと言った。", "error_description": "「出身」につなぐ場所は「農村の出身」と「の」で結ぶのが正しく、「農村で出身」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51595, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "問題が浮上した、と主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「浮上」は目的語を取らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「問題と浮上した」では意味が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「問題へ」は方向を示し、主語にならない。"}], "correct_answer": "が", "explanations": {"が": "問題が浮上した、と主語を示す。", "を": "「浮上」は目的語を取らないので合わない。", "と": "「問題と浮上した」では意味が成り立たない。", "へ": "「問題へ」は方向を示し、主語にならない。"}, "error_tags": {"を": "object_marker", "と": "comitative", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隠蔽", "is_correct": true, "explanation": "見えるようになる浮上と反対に、隠して見えなくする。"}, {"text": "発覚", "is_correct": false, "explanation": "隠れていたことが分かる意味で、類義に近い。"}, {"text": "露見", "is_correct": false, "explanation": "隠れていたことが現れる意味で、類義に近い。"}, {"text": "表面化", "is_correct": false, "explanation": "表に出る意味で、反対ではない。"}], "correct_answer": "隠蔽", "explanations": {"隠蔽": "見えるようになる浮上と反対に、隠して見えなくする。", "発覚": "隠れていたことが分かる意味で、類義に近い。", "露見": "隠れていたことが現れる意味で、類義に近い。", "表面化": "表に出る意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51595, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "失敗が浮上する、と主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「浮上」は目的語を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「失敗へ」は方向を示し、主語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「失敗より」は比較で、浮上の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "失敗が浮上する、と主語を示す。", "を": "「浮上」は目的語を取らないので合わない。", "へ": "「失敗へ」は方向を示し、主語にならない。", "より": "「失敗より」は比較で、浮上の主語にならない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "より": "comparison"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "埋没", "is_correct": true, "explanation": "見えるようになる浮上と反対に、埋もれて見えなくなる。"}, {"text": "出現", "is_correct": false, "explanation": "現れる意味で、反対ではない。"}, {"text": "判明", "is_correct": false, "explanation": "明らかになる意味で、類義に近い。"}, {"text": "発生", "is_correct": false, "explanation": "起こる意味で、反対ではない。"}], "correct_answer": "埋没", "explanations": {"埋没": "見えるようになる浮上と反対に、埋もれて見えなくなる。", "出現": "現れる意味で、反対ではない。", "判明": "明らかになる意味で、類義に近い。", "発生": "起こる意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51595, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "かくれていたことが、見えるようになること。", "primary_collocate": null, "pronunciation": "ふじょう", "ipa": "ɸudʑoː", "syllable_count": 3, "sentences": [{"text": "古い手紙から、新しい事実が浮上した。", "target_word": "浮上した", "complexity_tier": "T3", "furigana": "古[ふる]い手紙[てがみ]から、新[あたら]しい事実[じじつ]が浮上[ふじょう]した。", "sentence_source": "generated"}, {"text": "かくれていた問題が浮上した。", "target_word": "浮上した", "complexity_tier": "T3", "furigana": "かくれていた問題[もんだい]が浮上[ふじょう]した。", "sentence_source": "generated"}, {"text": "話し合いの中で、本当の理由が浮上してきた。", "target_word": "浮上してきた", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いの中[なか]で、本当[ほんとう]の理由[りゆう]が浮上[ふじょう]してきた。", "sentence_source": "generated"}, {"text": "調べると、うその話が浮上しました。", "target_word": "浮上しました", "complexity_tier": "T3", "furigana": "調[しら]べると、うその話[はなし]が浮上[ふじょう]しました。", "sentence_source": "generated"}, {"text": "事件の新しい事実が浮上している。", "target_word": "浮上している", "complexity_tier": "T3", "furigana": "事件[じけん]の新[あたら]しい事実[じじつ]が浮上[ふじょう]している。", "sentence_source": "generated"}, {"text": "彼の名前が急に浮上した。", "target_word": "浮上した", "complexity_tier": "T3", "furigana": "彼[かれ]の名前[なまえ]が急[きゅう]に浮上[ふじょう]した。", "sentence_source": "generated"}, {"text": "よく調べれば、事故の原因が浮上するだろう。", "target_word": "浮上する", "complexity_tier": "T3", "furigana": "よく調[しら]べれば、事故[じこ]の原因[げんいん]が浮上[ふじょう]するだろう。", "sentence_source": "generated"}, {"text": "昔の失敗がまた浮上するとは思わなかった。", "target_word": "浮上する", "complexity_tier": "T4", "furigana": "昔[むかし]の失敗[しっぱい]がまた浮上[ふじょう]するとは思[おも]わなかった。", "sentence_source": "generated"}, {"text": "かくれた不満が浮上してきた。", "target_word": "浮上してきた", "complexity_tier": "T3", "furigana": "かくれた不満[ふまん]が浮上[ふじょう]してきた。", "sentence_source": "generated"}, {"text": "浮上したうわさについて、先生に聞いた。", "target_word": "浮上した", "complexity_tier": "T3", "furigana": "浮上[ふじょう]したうわさについて、先生[せんせい]に聞[き]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浮上する", "label": "活用"}, {"form": "浮上した", "label": "活用"}, {"form": "浮上している", "label": "活用"}, {"form": "浮上させる", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | かくれていたものが見えてくること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa10040-79ce-478c-8cf8-7b3b9938243e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51595, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "浮上", "is_correct": true, "explanation": "ふじょう。見出し語そのもの。"}, {"text": "負傷", "is_correct": false, "explanation": "ふしょう。「じょ」が「しょ」に変わる別の語。"}, {"text": "無情", "is_correct": false, "explanation": "むじょう。「ふ」が「む」に変わる別の語。"}, {"text": "不要", "is_correct": false, "explanation": "ふよう。「じょ」が「よ」に変わる別の語。"}, {"text": "不幸", "is_correct": false, "explanation": "ふこう。「じょ」が「こ」に変わる別の語。"}], "explanations": {"浮上": "ふじょう。見出し語そのもの。", "負傷": "ふしょう。「じょ」が「しょ」に変わる別の語。", "無情": "むじょう。「ふ」が「む」に変わる別の語。", "不要": "ふよう。「じょ」が「よ」に変わる別の語。", "不幸": "ふこう。「じょ」が「こ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "浮上"}, "level_3": {"options": [{"text": "浮上した", "is_correct": true, "explanation": "手紙からかくれていた事実が見えてきた意味で合う。"}, {"text": "卒業した", "is_correct": false, "explanation": "形は合うが、事実が卒業するのは意味が合わない。"}, {"text": "開店した", "is_correct": false, "explanation": "形は合うが、事実が開店するのは意味が合わない。"}, {"text": "計算した", "is_correct": false, "explanation": "形は合うが、事実が計算するのは意味が合わない。"}], "explanations": {"浮上した": "手紙からかくれていた事実が見えてきた意味で合う。", "卒業した": "形は合うが、事実が卒業するのは意味が合わない。", "開店した": "形は合うが、事実が開店するのは意味が合わない。", "計算した": "形は合うが、事実が計算するのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "浮上した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は新しい事実を黒板に浮上した。", "explanation": "「浮上」は他動詞ではなく、「事実を浮上する」とは使えない。"}, {"text": "子どもが朝早く布団から浮上して顔を洗った。", "explanation": "「浮上」は人が起きる意味には使えない。"}, {"text": "机の上のノートが三冊浮上している。", "explanation": "「浮上」は物が置いてある状態には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
