INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51596, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "確保が浮上する、と主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「浮上」は目的語を取らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「確保と」では述語につながらず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「確保へ」は方向を示し、浮上の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "確保が浮上する、と主語を示す。", "を": "「浮上」は目的語を取らないので合わない。", "と": "「確保と」では述語につながらず文が成り立たない。", "へ": "「確保へ」は方向を示し、浮上の主語にならない。"}, "error_tags": {"を": "object_marker", "と": "comitative", "へ": "direction"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "埋没", "is_correct": true, "explanation": "表に出る浮上と反対に、隠れて見えなくなる。"}, {"text": "表面化", "is_correct": false, "explanation": "浮上と近い意味で、反対ではない。"}, {"text": "発覚", "is_correct": false, "explanation": "隠れていたことが表に出る意味で、類義に近い。"}, {"text": "出現", "is_correct": false, "explanation": "現れる意味で、反対ではない。"}], "correct_answer": "埋没", "explanations": {"埋没": "表に出る浮上と反対に、隠れて見えなくなる。", "表面化": "浮上と近い意味で、反対ではない。", "発覚": "隠れていたことが表に出る意味で、類義に近い。", "出現": "現れる意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51596, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "問題が浮上する、と主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「浮上」は目的語を取らないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「問題より浮上する」では主語がなく文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「問題へ」は方向を示し、主語にならない。"}], "correct_answer": "が", "explanations": {"が": "問題が浮上する、と主語を示す。", "を": "「浮上」は目的語を取らないので合わない。", "より": "「問題より浮上する」では主語がなく文が成り立たない。", "へ": "「問題へ」は方向を示し、主語にならない。"}, "error_tags": {"を": "object_marker", "より": "comparison", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "潜伏", "is_correct": true, "explanation": "表に出る浮上と反対に、隠れて表に出ない。"}, {"text": "顕在化", "is_correct": false, "explanation": "表に現れる意味で、浮上に近い。"}, {"text": "露呈", "is_correct": false, "explanation": "隠れていたことが現れる意味で、類義に近い。"}, {"text": "発生", "is_correct": false, "explanation": "起こる意味で、反対ではない。"}], "correct_answer": "潜伏", "explanations": {"潜伏": "表に出る浮上と反対に、隠れて表に出ない。", "顕在化": "表に現れる意味で、浮上に近い。", "露呈": "隠れていたことが現れる意味で、類義に近い。", "発生": "起こる意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51596, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "問題や課題が新たに表面化すること。水面に浮かび上がるように、目に見える形になること。", "primary_collocate": null, "pronunciation": "ふじょう", "ipa": "ɸudʑoː", "syllable_count": 3, "sentences": [{"text": "従来の肉体労働は減少しますが、機械を操作する専門知識を持つ人材の確保が、新たな課題として浮上しているのです。", "target_word": "浮上している", "complexity_tier": "T6", "furigana": "従来[じゅうらい]の肉体労働[にくたいろうどう]は減少[げんしょう]しますが、機械[きかい]を操作[そうさ]する専門知識[せんもんちしき]を持[も]つ人材[じんざい]の確保[かくほ]が、新[あら]たな課題[かだい]として浮上[ふじょう]しているのです。", "sentence_source": "mined"}, {"text": "新しい問題が浮上した。", "target_word": "浮上した", "complexity_tier": "T3", "furigana": "新[あたら]しい問題[もんだい]が浮上[ふじょう]した。", "sentence_source": "generated"}, {"text": "計画に大きな問題が浮上しました。", "target_word": "浮上しました", "complexity_tier": "T2", "furigana": "計画[けいかく]に大[おお]きな問題[もんだい]が浮上[ふじょう]しました。", "sentence_source": "generated"}, {"text": "会議で新しい課題が浮上している。", "target_word": "浮上している", "complexity_tier": "T3", "furigana": "会議[かいぎ]で新[あたら]しい課題[かだい]が浮上[ふじょう]している。", "sentence_source": "generated"}, {"text": "予算が足りないという問題が浮上した。", "target_word": "浮上した", "complexity_tier": "T3", "furigana": "予算[よさん]が足[た]りないという問題[もんだい]が浮上[ふじょう]した。", "sentence_source": "generated"}, {"text": "浮上した問題をすぐに解決したい。", "target_word": "浮上した", "complexity_tier": "T3", "furigana": "浮上[ふじょう]した問題[もんだい]をすぐに解決[かいけつ]したい。", "sentence_source": "generated"}, {"text": "調査の結果、別の原因が浮上してきた。", "target_word": "浮上してきた", "complexity_tier": "T3", "furigana": "調査[ちょうさ]の結果[けっか]、別[べつ]の原因[げんいん]が浮上[ふじょう]してきた。", "sentence_source": "generated"}, {"text": "問題が浮上すると、会議が長くなる。", "target_word": "浮上する", "complexity_tier": "T4", "furigana": "問題[もんだい]が浮上[ふじょう]すると、会議[かいぎ]が長[なが]くなる。", "sentence_source": "generated"}, {"text": "新しい課題の浮上で、計画が遅れた。", "target_word": "浮上", "complexity_tier": "T3", "furigana": "新[あたら]しい課題[かだい]の浮上[ふじょう]で、計画[けいかく]が遅[おく]れた。", "sentence_source": "generated"}, {"text": "調べると、思わぬ事実が浮上することもある。", "target_word": "浮上する", "complexity_tier": "T4", "furigana": "調[しら]べると、思[おも]わぬ事実[じじつ]が浮上[ふじょう]することもある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浮上する", "label": "活用"}, {"form": "浮上した", "label": "活用"}, {"form": "浮上している", "label": "活用"}, {"form": "浮上させる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 問題や課題が新たに表面化すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa10040-79ce-478c-8cf8-7b3b9938243e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51596, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "浮上", "is_correct": true, "explanation": "ふじょう。見出し語そのもの。"}, {"text": "負傷", "is_correct": false, "explanation": "ふしょう。「じょ」が「しょ」に変わる別の語。"}, {"text": "無情", "is_correct": false, "explanation": "むじょう。「ふ」が「む」に変わる別の語。"}, {"text": "不要", "is_correct": false, "explanation": "ふよう。「じょ」が「よ」に変わる別の語。"}, {"text": "不幸", "is_correct": false, "explanation": "ふこう。「じょ」が「こ」に変わる別の語。"}], "explanations": {"浮上": "ふじょう。見出し語そのもの。", "負傷": "ふしょう。「じょ」が「しょ」に変わる別の語。", "無情": "むじょう。「ふ」が「む」に変わる別の語。", "不要": "ふよう。「じょ」が「よ」に変わる別の語。", "不幸": "ふこう。「じょ」が「こ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "浮上"}, "level_3": {"options": [{"text": "浮上している", "is_correct": true, "explanation": "課題が新たに表面化している意味で文に合う。"}, {"text": "消滅している", "is_correct": false, "explanation": "形は合うが、「新たな課題として」と意味が合わない。"}, {"text": "完了している", "is_correct": false, "explanation": "形は合うが、課題として現れる意味にならない。"}, {"text": "下降している", "is_correct": false, "explanation": "形は合うが、確保が課題として下降するのは意味が合わない。"}], "explanations": {"浮上している": "課題が新たに表面化している意味で文に合う。", "消滅している": "形は合うが、「新たな課題として」と意味が合わない。", "完了している": "形は合うが、課題として現れる意味にならない。", "下降している": "形は合うが、確保が課題として下降するのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "浮上している"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は新しい問題を黒板に浮上した。", "explanation": "「浮上」は自動的に表面化することで、「～を浮上する」と他動詞のようには使えない。"}, {"text": "彼は毎朝六時に浮上して、駅へ向かう。", "explanation": "「浮上」は問題が表に出ることで、人が起きる意味には使えない。"}, {"text": "机の上に鍵が浮上している。", "explanation": "「浮上」は物が置いてある状態には使えない。問題や課題が表に出る意味のみ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51596, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "浮上", "is_correct": true, "explanation": "ふじょう。見出し語そのもの。"}, {"text": "不動", "is_correct": false, "explanation": "ふどう。「じょ」が「ど」に変わる別の語。"}, {"text": "符号", "is_correct": false, "explanation": "ふごう。「じょ」が「ご」に変わる別の語。"}, {"text": "不評", "is_correct": false, "explanation": "ふひょう。「じょ」が「ひょ」に変わる別の語。"}, {"text": "不調", "is_correct": false, "explanation": "ふちょう。「じょ」が「ちょ」に変わる別の語。"}], "explanations": {"浮上": "ふじょう。見出し語そのもの。", "不動": "ふどう。「じょ」が「ど」に変わる別の語。", "符号": "ふごう。「じょ」が「ご」に変わる別の語。", "不評": "ふひょう。「じょ」が「ひょ」に変わる別の語。", "不調": "ふちょう。「じょ」が「ちょ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "浮上"}, "level_3": {"options": [{"text": "浮上してきた", "is_correct": true, "explanation": "別の原因が表に出てきた意味で合う。"}, {"text": "完成してきた", "is_correct": false, "explanation": "形は合うが、原因が完成するのは意味が合わない。"}, {"text": "下降してきた", "is_correct": false, "explanation": "形は合うが、原因が下降するのは意味が合わない。"}, {"text": "出発してきた", "is_correct": false, "explanation": "形は合うが、原因が出発するのは意味が合わない。"}], "explanations": {"浮上してきた": "別の原因が表に出てきた意味で合う。", "完成してきた": "形は合うが、原因が完成するのは意味が合わない。", "下降してきた": "形は合うが、原因が下降するのは意味が合わない。", "出発してきた": "形は合うが、原因が出発するのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "浮上してきた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は新しい事実を浮上して家族に知らせた。", "explanation": "「浮上」は他動詞として「事実を浮上する」とは使えない。"}, {"text": "疲れたので、早く布団に浮上して寝た。", "explanation": "「浮上」は人が布団に入る意味にはならない。"}, {"text": "冷蔵庫の中の牛乳が浮上して古くなった。", "explanation": "「浮上」は問題などが表に出る意味で、物の状態変化には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51596, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい課題を会議で浮上した。", "corrected_sentence": "新しい課題が会議で浮上した。", "error_description": "「浮上」は自動詞的な語なので、「課題を」ではなく「課題が」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51596, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "検査で別の病気に浮上した。", "corrected_sentence": "検査で別の病気が浮上した。", "error_description": "浮上するものを示す助詞は「に」ではなく「が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51601, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ドアに貼った」の着点を示す格助詞。貼る先を表す。"}, {"text": "が", "is_correct": false, "explanation": "「ドアが貼った」はドアを主語にしてしまい、文の意味が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「ドアで貼った」は手段の意味になり、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「ドアを、大きな絵を貼った」は目的語が二つ重なり、不自然。"}], "correct_answer": "に", "explanations": {"に": "「ドアに貼った」の着点を示す格助詞。貼る先を表す。", "が": "「ドアが貼った」はドアを主語にしてしまい、文の意味が合わない。", "で": "「ドアで貼った」は手段の意味になり、不自然。", "を": "「を」は目的語。「ドアを、大きな絵を貼った」は目的語が二つ重なり、不自然。"}, "error_tags": {"が": "主格", "で": "場所・手段", "を": "対格（重複）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51601, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ドアを開けて」の目的語を示す格助詞。"}, {"text": "の", "is_correct": false, "explanation": "「ドアの開けて」は成立せず、目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「ドアへ開けて」は方向を示すことになり、不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の意味になり、「ドアより開けて」は文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "「ドアを開けて」の目的語を示す格助詞。", "の": "「ドアの開けて」は成立せず、目的語にならない。", "へ": "「ドアへ開けて」は方向を示すことになり、不自然。", "より": "比較の意味になり、「ドアより開けて」は文が成立しない。"}, "error_tags": {"の": "所属・修飾", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51601, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家や部屋の入り口にある、開け閉めできるもの", "primary_collocate": null, "pronunciation": "どあ", "ipa": "doa", "syllable_count": 2, "sentences": [{"text": "寒いから、ドアをしっかり閉めてください。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "寒[さむ]いから、ドアをしっかり閉[し]めてください。", "sentence_source": "generated"}, {"text": "弟は自分の部屋のドアに、大きな絵を貼った。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "弟[おとうと]は自分[じぶん]の部屋[へや]のドアに、大[おお]きな絵[え]を貼[は]った。", "sentence_source": "generated"}, {"text": "ノックしてから、ドアを開けるのがマナーだ。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "ノックしてから、ドアを開[あ]けるのがマナーだ。", "sentence_source": "generated"}, {"text": "ドアの向こうから、楽しそうな笑い声が聞こえた。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "ドアの向[む]こうから、楽[たの]しそうな笑[わら]い声[ごえ]が聞[き]こえた。", "sentence_source": "generated"}, {"text": "古い家のドアは、開けるたびにきしむ音がする。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]のドアは、開[あ]けるたびにきしむ音[おと]がする。", "sentence_source": "generated"}, {"text": "荷物で両手がふさがっていて、ドアを開けられなかった。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "荷物[にもつ]で両手[りょうて]がふさがっていて、ドアを開[あ]けられなかった。", "sentence_source": "generated"}, {"text": "白いドアの部屋が私の寝室だ。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "白[しろ]いドアの部屋[へや]が私[わたし]の寝室[しんしつ]だ。", "sentence_source": "generated"}, {"text": "雨がやんだので、ドアを開けて空気を入れ替えた。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "雨[あめ]がやんだので、ドアを開[あ]けて空気[くうき]を入[い]れ替[か]えた。", "sentence_source": "generated"}, {"text": "先生は教室のドアの前で、生徒を待っていた。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "先生[せんせい]は教室[きょうしつ]のドアの前[まえ]で、生徒[せいと]を待[ま]っていた。", "sentence_source": "generated"}, {"text": "子どもが急にドアを開けたので、びっくりした。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "子[こ]どもが急[きゅう]にドアを開[あ]けたので、びっくりした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ドア", "label": "基本形"}], "register": "中立", "sense_fingerprint": "家や部屋の入り口の開け閉めできるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7012c6de-6897-46e9-9295-f4be4ed38c8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51601, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ドア", "is_correct": true, "explanation": "「ドアをしっかり閉めてください」の対象。閉める対象として自然。"}, {"text": "花", "is_correct": false, "explanation": "「花をしっかり閉めて」は成立せず、閉める対象にならない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は閉める対象にならず、文が合わない。"}, {"text": "写真", "is_correct": false, "explanation": "写真は閉める対象にならず、文脈に合わない。"}], "explanations": {"ドア": "「ドアをしっかり閉めてください」の対象。閉める対象として自然。", "花": "「花をしっかり閉めて」は成立せず、閉める対象にならない。", "手紙": "手紙は閉める対象にならず、文が合わない。", "写真": "写真は閉める対象にならず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ドア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱のドアを開けて、中の人形を出した。", "explanation": "ここは〈箱の蓋〉の意味。箱の蓋をドアとは言わない。ドアは家や部屋の出入口に付くものを指す。"}, {"text": "ドアで髪を結った。", "explanation": "ここは〈ヘアゴム〉の意味。ドアは髪を結ぶものではないので、髪を結う場面には合わない。"}, {"text": "本を開くと、最初のドアに題名が書いてあった。", "explanation": "ここは〈本の扉（最初のページ）〉の意味。ドアは家や部屋の入り口に付くものを指すので、本には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51601, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ドア", "is_correct": true, "explanation": "「白いドアの部屋」の名詞として入る正解。家の出入口の仕切りを指す。"}, {"text": "猫", "is_correct": false, "explanation": "「白い猫の部屋」は成立せず、部屋の形容にならない。"}, {"text": "雲", "is_correct": false, "explanation": "「白い雲の部屋」は文脈に合わない。"}, {"text": "石", "is_correct": false, "explanation": "「白い石の部屋」は不自然で、寝室の説明にならない。"}], "explanations": {"ドア": "「白いドアの部屋」の名詞として入る正解。家の出入口の仕切りを指す。", "猫": "「白い猫の部屋」は成立せず、部屋の形容にならない。", "雲": "「白い雲の部屋」は文脈に合わない。", "石": "「白い石の部屋」は不自然で、寝室の説明にならない。"}, "sentence_index": 6, "correct_answer": "ドア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "舞台のドアが上がって、観客が静かになった。", "explanation": "ここは〈幕〉の意味。上下に動く布を指すので、開閉する仕切りのドアとは合わない。"}, {"text": "ホテルのドアが、重い荷物を運んでくれた。", "explanation": "ここは〈ドアマン（扉番の人）〉の意味。ドアは人を指さないので合わない。"}, {"text": "雨が降ってきたので、ドアを広げた。", "explanation": "ここは〈傘を広げる〉の意味。ドアは広げるものではなく、家や部屋の入り口の仕切りを指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51601, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風が強くて、ドアに開けられなかった。", "corrected_sentence": "風が強くて、ドアを開けられなかった。", "error_description": "「ドアに開けられなかった」の「に」が誤り。正しくは「ドアを開けられなかった」。開ける は目的語に「を」を取るため、「に」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51601, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜中、誰かがドアに叩く音がして、目が覚めた。", "corrected_sentence": "夜中、誰かがドアを叩く音がして、目が覚めた。", "error_description": "「ドアに叩く」の「に」が誤り。正しくは「ドアを叩く」。叩く は目的語に「を」を取るため、「に」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51602, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「部屋のドア」の所属を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「部屋がドア」は名詞の修飾にならず、文が成立しない。"}, {"text": "を", "is_correct": false, "explanation": "「部屋をドア」は成立せず、目的語にもならない。"}, {"text": "で", "is_correct": false, "explanation": "「部屋でドア」は場所の意味にならず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「部屋のドア」の所属を示す格助詞。", "が": "「部屋がドア」は名詞の修飾にならず、文が成立しない。", "を": "「部屋をドア」は成立せず、目的語にもならない。", "で": "「部屋でドア」は場所の意味にならず、不自然。"}, "error_tags": {"が": "主格", "を": "対格", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51602, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「建物のドア」の所属を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「建物をドアは重くて」は成り立たず、所属の意味にもならない。"}, {"text": "へ", "is_correct": false, "explanation": "「建物へドア」は方向を示すことになり、不自然。"}, {"text": "から", "is_correct": false, "explanation": "「建物からドア」は起点の意味になり、成立しない。"}], "correct_answer": "の", "explanations": {"の": "「建物のドア」の所属を示す格助詞。", "を": "「を」は目的語。「建物をドアは重くて」は成り立たず、所属の意味にもならない。", "へ": "「建物へドア」は方向を示すことになり、不自然。", "から": "「建物からドア」は起点の意味になり、成立しない。"}, "error_tags": {"へ": "方向", "から": "起点", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51602, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建築物や部屋の出入り口に設けられた、開閉可能な仕切り。通常は取っ手や鍵が付いている。", "primary_collocate": null, "pronunciation": "どあ", "ipa": "doa", "syllable_count": 2, "sentences": [{"text": "森の奥深くに佇む、その赤いドアの小さな家は、かつて祖母が一人で暮らしていた場所だ。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "森[もり]の奥深[おくふか]くに佇[たたず]む、その赤[あか]いドアの小[ちい]さな家[いえ]は、かつて祖母[そぼ]が一人[ひとり]で暮[く]らしていた場所[ばしょ]だ。", "sentence_source": "mined"}, {"text": "部屋のドアには鍵がかかっていて、中に入れなかった。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "部屋[へや]のドアには鍵[かぎ]がかかっていて、中[なか]に入[はい]れなかった。", "sentence_source": "generated"}, {"text": "彼は静かにドアを開けて、会議室に入った。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "彼[かれ]は静[しず]かにドアを開[あ]けて、会議室[かいぎしつ]に入[はい]った。", "sentence_source": "generated"}, {"text": "ドアの取っ手が壊れたので、新しいものに替えた。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "ドアの取[と]っ手[て]が壊[こわ]れたので、新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}, {"text": "風でドアが大きな音を立てて閉まった。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "風[かぜ]でドアが大[おお]きな音[おと]を立[た]てて閉[し]まった。", "sentence_source": "generated"}, {"text": "店のドアに「本日休業」と書いた紙が貼ってあった。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "店[みせ]のドアに「本日休業[ほんじつきゅうぎょう]」と書[か]いた紙[かみ]が貼[は]ってあった。", "sentence_source": "generated"}, {"text": "夜遅く、誰かがドアを叩く音がして、目が覚めた。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "夜遅[よるおそ]く、誰[だれ]かがドアを叩[たた]く音[おと]がして、目[め]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "この建物のドアは重くて、子どもには開けにくい。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "この建物[たてもの]のドアは重[おも]くて、子[こ]どもには開[あ]けにくい。", "sentence_source": "generated"}, {"text": "玄関のドアを開けると、猫が出迎えてくれた。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "玄関[げんかん]のドアを開[あ]けると、猫[ねこ]が出迎[でむか]えてくれた。", "sentence_source": "generated"}, {"text": "鍵をなくしたため、ドアの前で家族の帰りを待った。", "target_word": "ドア", "complexity_tier": "T3", "furigana": "鍵[かぎ]をなくしたため、ドアの前[まえ]で家族[かぞく]の帰[かえ]りを待[ま]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ドア", "label": "基本形"}], "register": "中立", "sense_fingerprint": "取っ手や鍵の付いた建物・部屋の出入り口の仕切り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7012c6de-6897-46e9-9295-f4be4ed38c8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51602, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ドア", "is_correct": true, "explanation": "「赤いドアの小さな家」の名詞として入る正解。建物の出入口の仕切りを指す。"}, {"text": "鍵", "is_correct": false, "explanation": "「赤い鍵の小さな家」は成立せず、家の外観を表さない。"}, {"text": "階段", "is_correct": false, "explanation": "「赤い階段の小さな家」は家の特徴として成立しない。"}, {"text": "絨毯", "is_correct": false, "explanation": "床に敷くもので、「赤い絨毯の小さな家」は文脈に合わない。"}], "explanations": {"ドア": "「赤いドアの小さな家」の名詞として入る正解。建物の出入口の仕切りを指す。", "鍵": "「赤い鍵の小さな家」は成立せず、家の外観を表さない。", "階段": "「赤い階段の小さな家」は家の特徴として成立しない。", "絨毯": "床に敷くもので、「赤い絨毯の小さな家」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ドア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍋のドアを外して、中身を確かめた。", "explanation": "ここは〈蓋〉の意味。鍋の蓋をドアとは言わない。ドアは建物や部屋の出入口の仕切りを指す。"}, {"text": "雨の日は、ドアを履いて出かけた。", "explanation": "ここは〈靴〉の意味。ドアは建物や部屋の仕切りを指し、足に履くものとしては使わない。"}, {"text": "本を開くと、最初のドアに題名が書いてあった。", "explanation": "ここは〈本の扉（表紙をめくった最初のページ）〉の意味。ドアは建物や部屋の仕切りなので、本のページには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51602, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ドア", "is_correct": true, "explanation": "「誰かがドアを叩く音」の対象。ドアを叩く音として自然に成立する。"}, {"text": "花", "is_correct": false, "explanation": "「誰かが花を叩く音」は現実にありえず、文脈に合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は叩く対象にならず、文が成立しない。"}, {"text": "雲", "is_correct": false, "explanation": "「雲を叩く音」は文脈上ありえず、成立しない。"}], "explanations": {"ドア": "「誰かがドアを叩く音」の対象。ドアを叩く音として自然に成立する。", "花": "「誰かが花を叩く音」は現実にありえず、文脈に合わない。", "手紙": "手紙は叩く対象にならず、文が成立しない。", "雲": "「雲を叩く音」は文脈上ありえず、成立しない。"}, "sentence_index": 6, "correct_answer": "ドア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "勝利を祝って、校庭でドアを掲げた。", "explanation": "ここは〈旗を掲げる〉の意味。ドアは持ち上げて掲げるものではなく、建物の仕切りを指す。"}, {"text": "舞台のドアが上がり、観客が静かになった。", "explanation": "ここは〈幕〉の意味。上下に動く布を指すので、開閉する仕切りのドアとは合わない。"}, {"text": "ホテルのドアが、重い荷物を運んでくれた。", "explanation": "ここは〈ドアマン（扉番の人）〉の意味。ドアは人を指さないので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51602, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い日は、ドアで閉めて暖房を入れた。", "corrected_sentence": "寒い日は、ドアを閉めて暖房を入れた。", "error_description": "「ドアで閉めて」の「で」が誤り。正しくは「ドアを閉めて」。閉める は目的語に「を」を取る他動詞で、「で」は手段や場所を表すため合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51602, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "裏口のドアが開けると、猫が出迎えた。", "corrected_sentence": "裏口のドアを開けると、猫が出迎えた。", "error_description": "「ドアが開けると」の「が」が誤り。正しくは「ドアを開けると」。開ける は目的語に「を」を取る他動詞なので、「が」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
