INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51603, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "ここは「祖母が亡くなる」の主語。亡くなるは自動詞なので、主語に「が」が付く。"}, {"text": "を", "is_correct": false, "explanation": "「亡くなる」は目的語をとらないので、「を」は入らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や到達点を示すが、亡くなる主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、亡くなる主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "ここは「祖母が亡くなる」の主語。亡くなるは自動詞なので、主語に「が」が付く。", "を": "「亡くなる」は目的語をとらないので、「を」は入らない。", "に": "「に」は相手や到達点を示すが、亡くなる主語にはならない。", "で": "「で」は場所や手段を示すので、亡くなる主語にはならない。"}, "error_tags": {"を": "目的語", "に": "相手・到達点", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51603, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お父さんやお母さんのお母さんのことです。", "primary_collocate": null, "pronunciation": "そぼ", "ipa": "soβo", "syllable_count": 2, "sentences": [{"text": "母の母にあたる祖母は、今年で八十歳になります。", "target_word": "祖母", "complexity_tier": "T3", "furigana": "母[はは]の母[はは]にあたる祖母[そぼ]は、今年[ことし]で八十歳[はっさいじゅう]になります。", "sentence_source": "generated"}, {"text": "祖母は私が風邪をひくと、いつも生姜湯を作ってくれた。", "target_word": "祖母", "complexity_tier": "T3", "furigana": "祖母[そぼ]は私[わたし]が風邪[かぜ]をひくと、いつも生姜湯[しょうがゆ]を作[つく]ってくれた。", "sentence_source": "generated"}, {"text": "休みの日に、祖母と一緒に着物を整理した。", "target_word": "祖母", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]に、祖母[そぼ]と一緒[いっしょ]に着物[きもの]を整理[せいり]した。", "sentence_source": "generated"}, {"text": "祖母の料理は、母の味とは少し違ってやさしい味がする。", "target_word": "祖母", "complexity_tier": "T3", "furigana": "祖母[そぼ]の料理[りょうり]は、母[はは]の味[あじ]とは少[すこ]し違[ちが]ってやさしい味[あじ]がする。", "sentence_source": "generated"}, {"text": "父の母である祖母は、北海道で一人暮らしをしている。", "target_word": "祖母", "complexity_tier": "T3", "furigana": "父[ちち]の母[はは]である祖母[そぼ]は、北海道[ほっかいどう]で一人暮[ひとりぐ]らしをしている。", "sentence_source": "generated"}, {"text": "祖母は昔、小学校の先生だったそうだ。", "target_word": "祖母", "complexity_tier": "T3", "furigana": "祖母[そぼ]は昔[むかし]、小学校[しょうがっこう]の先生[せんせい]だったそうだ。", "sentence_source": "generated"}, {"text": "祖母に編み物を教わって、マフラーを作りました。", "target_word": "祖母", "complexity_tier": "T3", "furigana": "祖母[そぼ]に編[あ]み物[もの]を教[おそ]わって、マフラーを作[つく]りました。", "sentence_source": "generated"}, {"text": "祖母が亡くなってから、実家はずいぶん静かになった。", "target_word": "祖母", "complexity_tier": "T3", "furigana": "祖母[そぼ]が亡[な]くなってから、実家[じっか]はずいぶん静[しず]かになった。", "sentence_source": "generated"}, {"text": "祖母は孫の私たちに、毎年お年玉を渡してくれる。", "target_word": "祖母", "complexity_tier": "T3", "furigana": "祖母[そぼ]は孫[まご]の私[わたし]たちに、毎年[まいとし]お年玉[としだま]を渡[わた]してくれる。", "sentence_source": "generated"}, {"text": "祖母の若いころの写真を見つけて、母と二人で笑った。", "target_word": "祖母", "complexity_tier": "T3", "furigana": "祖母[そぼ]の若[わか]いころの写真[しゃしん]を見[み]つけて、母[はは]と二人[ふたり]で笑[わら]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "祖母", "label": "base"}], "register": "formal-neutral", "sense_fingerprint": "お父さんやお母さんのお母さん、つまり自分の祖母を指す語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0988d614-3a17-476b-9005-b96be10d1534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51603, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祖母", "is_correct": true, "explanation": "ここは「母の母」にあたる人物を入れる場所。年齢を数えられる人が入るので「八十歳になります」と合う。"}, {"text": "病院", "is_correct": false, "explanation": "病院は場所で、年齢を重ねないので「八十歳になります」と合わない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所で、八十歳にはならない。"}, {"text": "郵便局", "is_correct": false, "explanation": "郵便局は施設で、年齢を重ねない。"}], "explanations": {"祖母": "ここは「母の母」にあたる人物を入れる場所。年齢を数えられる人が入るので「八十歳になります」と合う。", "病院": "病院は場所で、年齢を重ねないので「八十歳になります」と合わない。", "教室": "教室は場所で、八十歳にはならない。", "郵便局": "郵便局は施設で、年齢を重ねない。"}, "sentence_index": 0, "correct_answer": "祖母"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私を産んでくれた祖母は、今も毎朝台所に立っている。", "explanation": "ここは〈母〉の意味。祖母は親の母なので、子どもを産んだ人には使えない。"}, {"text": "父方の祖父である祖母は、毎週末に釣りへ出かける。", "explanation": "ここは〈おじいさん〉の意味。祖母は女性の親族なので、父方の男性には使えない。"}, {"text": "この家の祖母は、江戸時代に城下町で商いをしていたと伝わっている。", "explanation": "ここは〈祖先〉の意味。祖母は親の母の一人なので、江戸時代の人の先祖には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51603, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祖母", "is_correct": true, "explanation": "ここは編み物を教えた人物を入れる場所。「祖母」が入ると、教わった相手として自然に読める。"}, {"text": "玄関", "is_correct": false, "explanation": "玄関は場所で、編み物を教えることはできない。"}, {"text": "毛糸", "is_correct": false, "explanation": "毛糸は材料で、教える人にはならない。"}, {"text": "押し入れ", "is_correct": false, "explanation": "押し入れは収納で、教えることはできない。"}], "explanations": {"祖母": "ここは編み物を教えた人物を入れる場所。「祖母」が入ると、教わった相手として自然に読める。", "玄関": "玄関は場所で、編み物を教えることはできない。", "毛糸": "毛糸は材料で、教える人にはならない。", "押し入れ": "押し入れは収納で、教えることはできない。"}, "sentence_index": 6, "correct_answer": "祖母"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母の母の母である祖母は、明治生まれだ。", "explanation": "ここは〈曽祖母〉の意味。祖母は親の母までで、さらに一世代上の人には使えない。"}, {"text": "母の妹である祖母は、いつも料理の作り方を教えてくれる。", "explanation": "ここは〈叔母〉の意味。祖母は親の母で、親の妹には使えない。"}, {"text": "父の再婚相手である祖母は、いつも優しく接してくれる。", "explanation": "ここは〈継母〉の意味。祖母は親の母で、父の再婚相手には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51603, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末、祖母に一緒に庭の花を植えた。", "corrected_sentence": "週末、祖母と一緒に庭の花を植えた。", "error_description": "「一緒に」の相手を示す「と」が「に」になっている。「祖母と一緒に」が自然で、「に」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51603, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母を毎年、私の誕生日に手紙をくれる。", "corrected_sentence": "祖母は毎年、私の誕生日に手紙をくれる。", "error_description": "「くれる」の主語にあたる「は」が「を」になっている。「祖母を……くれる」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
