INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51605, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "色がだんだんうすくなって、もとの色ではなくなること。", "primary_collocate": null, "pronunciation": "いろあせる", "ipa": "iɾoaseɾɯ", "syllable_count": 5, "sentences": [{"text": "赤いシャツを何度も洗ったら、色褪せてしまった。", "target_word": "色褪せて", "complexity_tier": "T3", "furigana": "赤[あか]いシャツを何度[なんど]も洗[あら]ったら、色褪[いろあ]せてしまった。", "sentence_source": "generated"}, {"text": "窓際に置いた本の表紙が、日に焼けて色褪せた。", "target_word": "色褪せた", "complexity_tier": "T3", "furigana": "窓際[まどぎわ]に置[お]いた本[ほん]の表紙[ひょうし]が、日[ひ]に焼[や]けて色褪[いろあ]せた。", "sentence_source": "generated"}, {"text": "色褪せた青い旗が、風にゆれている。", "target_word": "色褪せた", "complexity_tier": "T3", "furigana": "色褪[いろあ]せた青[あお]い旗[はた]が、風[かぜ]にゆれている。", "sentence_source": "generated"}, {"text": "この絵の具は色褪せにくいので、屋外の作品に向いている。", "target_word": "色褪せ", "complexity_tier": "T3", "furigana": "この絵[え]の具[ぐ]は色褪[いろあ]せにくいので、屋外[おくがい]の作品[さくひん]に向[む]いている。", "sentence_source": "generated"}, {"text": "夏の強い日差しで、庭のベンチが色褪せてきた。", "target_word": "色褪せて", "complexity_tier": "T3", "furigana": "夏[なつ]の強[つよ]い日差[ひざ]しで、庭[にわ]のベンチが色褪[いろあ]せてきた。", "sentence_source": "generated"}, {"text": "色褪せたカーペットを、新品に取り替えた。", "target_word": "色褪せた", "complexity_tier": "T3", "furigana": "色褪[いろあ]せたカーペットを、新品[しんぴん]に取[と]り替[か]えた。", "sentence_source": "generated"}, {"text": "長く飾っていたポスターが色褪せて、絵がぼんやり見える。", "target_word": "色褪せて", "complexity_tier": "T3", "furigana": "長[なが]く飾[かざ]っていたポスターが色褪[いろあ]せて、絵[え]がぼんやり見[み]える。", "sentence_source": "generated"}, {"text": "黒い服は洗うたびに色褪せるので、気をつけて洗っている。", "target_word": "色褪せる", "complexity_tier": "T3", "furigana": "黒[くろ]い服[ふく]は洗[あら]うたびに色褪[いろあ]せるので、気[き]をつけて洗[あら]っている。", "sentence_source": "generated"}, {"text": "色褪せない染料を使ったので、この布は何年たっても美しい。", "target_word": "色褪せない", "complexity_tier": "T3", "furigana": "色褪[いろあ]せない染料[せんりょう]を使[つか]ったので、この布[ぬの]は何年[なんねん]たっても美[うつく]しい。", "sentence_source": "generated"}, {"text": "古い帽子は、茶色が色褪せて薄いベージュになった。", "target_word": "色褪せて", "complexity_tier": "T3", "furigana": "古[ふる]い帽子[ぼうし]は、茶色[ちゃいろ]が色褪[いろあ]せて薄[うす]いベージュになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "色褪せる", "label": "dictionary"}, {"form": "色褪せた", "label": "past"}, {"form": "色褪せて", "label": "te-form"}, {"form": "色褪せにくい", "label": "stem + negative-adjective"}, {"form": "色褪せ", "label": "stem"}], "register": "neutral", "sense_fingerprint": "日光や洗濯などで物の色がだんだん薄くなる、という具体的な変化を表す自動詞（下一段）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0988d614-3a17-476b-9005-b96be10d1534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51605, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "色褪せて", "is_correct": true, "explanation": "ここは色が薄くなる結果を表す。「洗ったら、色褪せてしまった」と自然につながる。"}, {"text": "急いで", "is_correct": false, "explanation": "服は急がないので、「急いでしまった」では変化の文にならない。"}, {"text": "眠って", "is_correct": false, "explanation": "服は眠らないので、「眠ってしまった」は合わない。"}, {"text": "泣いて", "is_correct": false, "explanation": "服は泣かないので、「泣いてしまった」は合わない。"}], "explanations": {"色褪せて": "ここは色が薄くなる結果を表す。「洗ったら、色褪せてしまった」と自然につながる。", "急いで": "服は急がないので、「急いでしまった」では変化の文にならない。", "眠って": "服は眠らないので、「眠ってしまった」は合わない。", "泣いて": "服は泣かないので、「泣いてしまった」は合わない。"}, "sentence_index": 0, "correct_answer": "色褪せて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "薬品をかけた金属が色褪せて、表面が緑に変わった。", "explanation": "ここは〈変色〉の意味。別の色に変わることは、色の薄れとは違うので合わない。"}, {"text": "夏の海で、彼は色褪せて赤くなった。", "explanation": "ここは〈日焼け〉の意味。肌が日に焼けることは、色の薄れとは違うので合わない。"}, {"text": "畑のトマトが色褪せて、食べ頃になった。", "explanation": "ここは〈熟す〉の意味。果実が熟して食べ頃になる変化を指し、色の薄れには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51605, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "色褪せて", "is_correct": true, "explanation": "ここは色が薄くなる原因を示すて形。「色褪せて、絵がぼんやり見える」と自然につながる。"}, {"text": "怒って", "is_correct": false, "explanation": "ポスターは怒らないので、「怒って」は意味が通らない。"}, {"text": "歌って", "is_correct": false, "explanation": "ポスターは歌わないので、合わない。"}, {"text": "転んで", "is_correct": false, "explanation": "ポスターは転ばないので、不自然。"}], "explanations": {"色褪せて": "ここは色が薄くなる原因を示すて形。「色褪せて、絵がぼんやり見える」と自然につながる。", "怒って": "ポスターは怒らないので、「怒って」は意味が通らない。", "歌って": "ポスターは歌わないので、合わない。", "転んで": "ポスターは転ばないので、不自然。"}, "sentence_index": 6, "correct_answer": "色褪せて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パン生地が色褪せて、二倍に膨らんだ。", "explanation": "ここは〈体積が増す〉の意味。体積の変化は色の薄れとは違うので、色褪せるは合わない。"}, {"text": "ダイエットを続けて、彼は色褪せて細くなった。", "explanation": "ここは〈痩せる〉の意味。体形の変化を表し、色の薄れには使わない。"}, {"text": "水を入れすぎて、ジュースの味が色褪せて薄まった。", "explanation": "ここは〈濃さが下がる〉の意味。味の濃さの低下は色の薄れではないので、色褪せるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51605, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "色褪せなく布を選んで、ずっと大切に使っている。", "corrected_sentence": "色褪せない布を選んで、ずっと大切に使っている。", "error_description": "「色褪せない」が「色褪せなく」になっている。名詞を修飾する形は「色褪せない」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "色褪せた", "is_correct": true, "explanation": "た形。文末の過去として、日に焼けて変わった結果を表す。"}, {"text": "色褪せて", "is_correct": false, "explanation": "て形。文末には来られず、「色褪せて。」では文が切れない。"}, {"text": "色褪せない", "is_correct": false, "explanation": "否定形。日に焼けた事実と矛盾する。"}, {"text": "色褪せよう", "is_correct": false, "explanation": "意向形。過去の出来事を述べる文に合わない。"}], "correct_form": "色褪せた", "base_form": "色褪せる", "form_label": "た形", "sentence_index": 1, "explanations": {"色褪せた": "た形。文末の過去として、日に焼けて変わった結果を表す。", "色褪せて": "て形。文末には来られず、「色褪せて。」では文が切れない。", "色褪せない": "否定形。日に焼けた事実と矛盾する。", "色褪せよう": "意向形。過去の出来事を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51605, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "色褪せした本を、大切に持ち歩いている。", "corrected_sentence": "色褪せた本を、大切に持ち歩いている。", "error_description": "「色褪せした」は活用が誤り。過去の形は「色褪せた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "色褪せる", "is_correct": true, "explanation": "辞書形。「洗うたびに〜するので」と続く習慣的な変化を表す。"}, {"text": "色褪せたら", "is_correct": false, "explanation": "条件形「たら」は「〜ので」と重ねられず、「色褪せたら、ので」では文が成立しない。"}, {"text": "色褪せ", "is_correct": false, "explanation": "語幹だけでは「〜ので」の前に置けず、「色褪せので」は文が成立しない。"}, {"text": "色褪せず", "is_correct": false, "explanation": "連用中止形「〜ず」は「〜ので」と続けられず、文が切れない。"}], "correct_form": "色褪せる", "base_form": "色褪せる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"色褪せる": "辞書形。「洗うたびに〜するので」と続く習慣的な変化を表す。", "色褪せたら": "条件形「たら」は「〜ので」と重ねられず、「色褪せたら、ので」では文が成立しない。", "色褪せ": "語幹だけでは「〜ので」の前に置けず、「色褪せので」は文が成立しない。", "色褪せず": "連用中止形「〜ず」は「〜ので」と続けられず、文が切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
