INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51606, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "色があせて、鮮やかさや新しい感じがなくなる。時間がたって、古びた印象になる。", "primary_collocate": null, "pronunciation": "いろあせる", "ipa": "iɾoaseɾɯ", "syllable_count": 5, "sentences": [{"text": "色褪せた外壁や苔むした庭は、過ぎ去った長い年月を静かに物語っている。", "target_word": "色褪せた", "complexity_tier": "T3", "furigana": "色褪[いろあ]せた外壁[がいへき]や苔[こけ]むした庭[にわ]は、過[す]ぎ去[さ]った長[なが]い年月[としつき]を静[しず]かに物語[ものがた]っている。", "sentence_source": "mined"}, {"text": "古い写真は、長い間日に当たって色褪せてしまった。", "target_word": "色褪せて", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]は、長[なが]い間[あいだ]日[ひ]に当[あ]たって色褪[いろあ]せてしまった。", "sentence_source": "generated"}, {"text": "何十年たっても、あの夏の思い出は色褪せない。", "target_word": "色褪せない", "complexity_tier": "T3", "furigana": "何十年[なんじゅうねん]たっても、あの夏[なつ]の思[おも]い出[で]は色褪[いろあ]せない。", "sentence_source": "generated"}, {"text": "カーテンが日光で色褪せたので、新しいものに替えた。", "target_word": "色褪せた", "complexity_tier": "T3", "furigana": "カーテンが日光[にっこう]で色褪[いろあ]せたので、新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}, {"text": "色褪せたポスターを見ると、昔の流行を思い出す。", "target_word": "色褪せた", "complexity_tier": "T3", "furigana": "色褪[いろあ]せたポスターを見[み]ると、昔[むかし]の流行[りゅうこう]を思[おも]い出[だ]す。", "sentence_source": "generated"}, {"text": "時代が変わっても色褪せない名作として、この映画は愛されている。", "target_word": "色褪せない", "complexity_tier": "T3", "furigana": "時代[じだい]が変[か]わっても色褪[いろあ]せない名作[めいさく]として、この映画[えいが]は愛[あい]されている。", "sentence_source": "generated"}, {"text": "はきすぎたジーンズは、すっかり色褪せて白っぽくなった。", "target_word": "色褪せて", "complexity_tier": "T3", "furigana": "はきすぎたジーンズは、すっかり色褪[いろあ]せて白[しろ]っぽくなった。", "sentence_source": "generated"}, {"text": "看板の赤い文字は色褪せて、読みにくくなっている。", "target_word": "色褪せて", "complexity_tier": "T3", "furigana": "看板[かんばん]の赤[あか]い文字[もじ]は色褪[いろあ]せて、読[よ]みにくくなっている。", "sentence_source": "generated"}, {"text": "彼との約束の記憶は、年月とともに色褪せていった。", "target_word": "色褪せて", "complexity_tier": "T3", "furigana": "彼[かれ]との約束[やくそく]の記憶[きおく]は、年月[ねんげつ]とともに色褪[いろあ]せていった。", "sentence_source": "generated"}, {"text": "色褪せた表紙の本が、図書館の棚の奥に残っていた。", "target_word": "色褪せた", "complexity_tier": "T3", "furigana": "色褪[いろあ]せた表紙[ひょうし]の本[ほん]が、図書館[としょかん]の棚[たな]の奥[おく]に残[のこ]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "色褪せる", "label": "dictionary"}, {"form": "色褪せた", "label": "past"}, {"form": "色褪せて", "label": "te-form"}, {"form": "色褪せない", "label": "negative"}, {"form": "色褪せ", "label": "stem"}], "register": "neutral", "sense_fingerprint": "色が薄れるだけでなく、記憶や魅力が時とともに古びて鮮やかさを失うことも表す自動詞（下一段）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0988d614-3a17-476b-9005-b96be10d1534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51606, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "色褪せた", "is_correct": true, "explanation": "ここは古びて鮮やかさがない外壁や庭を表す。「色褪せた」が入ると、長い年月を感じさせる文になる。"}, {"text": "走った", "is_correct": false, "explanation": "「走った外壁」は意味が通らず、外壁は走らない。"}, {"text": "叫んだ", "is_correct": false, "explanation": "「叫んだ外壁」は成り立たず、物は声を出さない。"}, {"text": "眠った", "is_correct": false, "explanation": "「眠った外壁」は古びた様子を表さず、不自然。"}], "explanations": {"色褪せた": "ここは古びて鮮やかさがない外壁や庭を表す。「色褪せた」が入ると、長い年月を感じさせる文になる。", "走った": "「走った外壁」は意味が通らず、外壁は走らない。", "叫んだ": "「叫んだ外壁」は成り立たず、物は声を出さない。", "眠った": "「眠った外壁」は古びた様子を表さず、不自然。"}, "sentence_index": 0, "correct_answer": "色褪せた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "保存していたデータが色褪せて、ファイルが開けなくなった。", "explanation": "ここは〈劣化〉の意味。色褪せるは色が薄れる変化なので、データの劣化には使わない。"}, {"text": "お気に入りの白い靴は、泥はねでひどく色褪せた。", "explanation": "ここは〈汚れる〉の意味。泥で汚れることは色の薄れとは違うので合わない。"}, {"text": "壁にペンキを重ね塗りして、色褪せて厚くなった。", "explanation": "ここは〈厚くなる〉の意味。厚みが増すことは色の薄れや古びとは違うので、色褪せるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51606, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "色褪せて", "is_correct": true, "explanation": "ここは色が薄くなる変化を表す。「すっかり色褪せて白っぽくなった」と自然に続く。"}, {"text": "騒いで", "is_correct": false, "explanation": "ジーンズは騒がないので、「騒いで」は意味が通らない。"}, {"text": "泣いて", "is_correct": false, "explanation": "ジーンズは泣かないので、合わない。"}, {"text": "跳ねて", "is_correct": false, "explanation": "跳ねるのは物の動きで、色の変化を表さない。"}], "explanations": {"色褪せて": "ここは色が薄くなる変化を表す。「すっかり色褪せて白っぽくなった」と自然に続く。", "騒いで": "ジーンズは騒がないので、「騒いで」は意味が通らない。", "泣いて": "ジーンズは泣かないので、合わない。", "跳ねて": "跳ねるのは物の動きで、色の変化を表さない。"}, "sentence_index": 6, "correct_answer": "色褪せて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しいシャツを洗ったら、ほかの服まで色褪せて染まってしまった。", "explanation": "ここは〈色落ち〉の意味。洗ったときに染料が他の服へ移るのは色落ちで、色褪せるとは違う。"}, {"text": "父の声が色褪せて、電話の向こうでよく聞こえない。", "explanation": "ここは〈かすれる〉の意味。声がかすれて聞き取りにくいことは色の薄れとは違うので、色褪せるは合わない。"}, {"text": "作ったスープは、すっかり色褪せて冷めてしまった。", "explanation": "ここは〈温度が下がる〉の意味。温度の変化は色の薄れではないので、色褪せるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51606, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "色褪せな思い出を大切に残している。", "corrected_sentence": "色褪せない思い出を大切に残している。", "error_description": "「色褪せない」が「色褪せな」になっている。名詞を修飾する打ち消しの形は「色褪せない」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "色褪せて", "is_correct": true, "explanation": "て形。「〜てしまった」に続き、長い間の経過の結果を表す。"}, {"text": "色褪せた", "is_correct": false, "explanation": "た形。「〜てしまった」の前には「て形」が必要で、「色褪せたしまった」は不自然。"}, {"text": "色褪せない", "is_correct": false, "explanation": "否定形。日光で色が薄れた事実と合わず、「〜てしまった」と続かない。"}, {"text": "色褪せよう", "is_correct": false, "explanation": "意向形。「〜てしまった」の前には置けない。"}], "correct_form": "色褪せて", "base_form": "色褪せる", "form_label": "て形", "sentence_index": 1, "explanations": {"色褪せて": "て形。「〜てしまった」に続き、長い間の経過の結果を表す。", "色褪せた": "た形。「〜てしまった」の前には「て形」が必要で、「色褪せたしまった」は不自然。", "色褪せない": "否定形。日光で色が薄れた事実と合わず、「〜てしまった」と続かない。", "色褪せよう": "意向形。「〜てしまった」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51606, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その服は、洗っているうちに色褪せるてしまった。", "corrected_sentence": "その服は、洗っているうちに色褪せてしまった。", "error_description": "「色褪せてしまった」の「て形」が辞書形「色褪せる」になっている。「てしまった」には「て形」が必要なので、「色褪せるてしまった」は不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "色褪せて", "is_correct": true, "explanation": "て形。「〜て、読みにくくなっている」と続けて変化の経過を表す。"}, {"text": "色褪せよう", "is_correct": false, "explanation": "意向形。「て、読みにくくなっている」と続く変化の文に合わず、文が切れない。"}, {"text": "色褪せるて", "is_correct": false, "explanation": "辞書形に「て」は続かず、文として成立しない。"}, {"text": "色褪せなかった", "is_correct": false, "explanation": "過去の否定形。色が薄れた現状と矛盾し、「読みにくくなっている」と合わない。"}], "correct_form": "色褪せて", "base_form": "色褪せる", "form_label": "て形", "sentence_index": 7, "explanations": {"色褪せて": "て形。「〜て、読みにくくなっている」と続けて変化の経過を表す。", "色褪せよう": "意向形。「て、読みにくくなっている」と続く変化の文に合わず、文が切れない。", "色褪せるて": "辞書形に「て」は続かず、文として成立しない。", "色褪せなかった": "過去の否定形。色が薄れた現状と矛盾し、「読みにくくなっている」と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
