INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51607, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "あかい色をしていること。", "primary_collocate": null, "pronunciation": "あかい", "ipa": "akai", "syllable_count": 3, "sentences": [{"text": "秋になると、山の木の葉が赤くなる。", "target_word": "赤く", "complexity_tier": "T3", "furigana": "秋[あき]になると、山[やま]の木[き]の葉[は]が赤[あか]くなる。", "sentence_source": "generated"}, {"text": "彼女は赤い傘をさして歩いていた。", "target_word": "赤い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は赤[あか]い傘[かさ]をさして歩[ある]いていた。", "sentence_source": "generated"}, {"text": "泣いたせいで、目が赤い。", "target_word": "赤い", "complexity_tier": "T3", "furigana": "泣[な]いたせいで、目[め]が赤[あか]い。", "sentence_source": "generated"}, {"text": "赤いりんごを三つ買った。", "target_word": "赤い", "complexity_tier": "T3", "furigana": "赤[あか]いりんごを三[みっ]つ買[か]った。", "sentence_source": "generated"}, {"text": "夕日で空が赤く染まった。", "target_word": "赤く", "complexity_tier": "T3", "furigana": "夕日[ゆうひ]で空[そら]が赤[あか]く染[そ]まった。", "sentence_source": "generated"}, {"text": "寒くて、鼻が赤くなってしまった。", "target_word": "赤く", "complexity_tier": "T3", "furigana": "寒[さむ]くて、鼻[はな]が赤[あか]くなってしまった。", "sentence_source": "generated"}, {"text": "赤い花が庭いっぱいに咲いている。", "target_word": "赤い", "complexity_tier": "T3", "furigana": "赤[あか]い花[はな]が庭[にわ]いっぱいに咲[さ]いている。", "sentence_source": "generated"}, {"text": "恥ずかしくて、顔が赤い。", "target_word": "赤い", "complexity_tier": "T3", "furigana": "恥[は]ずかしくて、顔[かお]が赤[あか]い。", "sentence_source": "generated"}, {"text": "赤いポストの前で友だちを待った。", "target_word": "赤い", "complexity_tier": "T3", "furigana": "赤[あか]いポストの前[まえ]で友[とも]だちを待[ま]った。", "sentence_source": "generated"}, {"text": "日焼けして、背中が赤くなった。", "target_word": "赤く", "complexity_tier": "T3", "furigana": "日焼[ひや]けして、背中[せなか]が赤[あか]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "赤い", "label": "辞書形"}, {"form": "赤く", "label": "連用形"}, {"form": "赤かった", "label": "過去形"}, {"form": "赤くない", "label": "否定形"}, {"form": "赤くて", "label": "て形"}], "register": "neutral", "sense_fingerprint": "血やりんごのような、あかい色をしていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8f1722b-8f6a-484b-8e04-67ac74b730cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51607, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赤く", "is_correct": true, "explanation": "「葉が赤くなる」は葉の色が変わる意味になり、ここで合う。"}, {"text": "痛く", "is_correct": false, "explanation": "「葉が痛くなる」は意味が通らず、秋の色づきという文脈に合わない。"}, {"text": "甘く", "is_correct": false, "explanation": "「葉が甘くなる」は意味が通らず、文脈に合わない。"}, {"text": "遠く", "is_correct": false, "explanation": "「葉が遠くなる」は意味が通らず、色の変化という文脈に合わない。"}], "explanations": {"赤く": "「葉が赤くなる」は葉の色が変わる意味になり、ここで合う。", "痛く": "「葉が痛くなる」は意味が通らず、秋の色づきという文脈に合わない。", "甘く": "「葉が甘くなる」は意味が通らず、文脈に合わない。", "遠く": "「葉が遠くなる」は意味が通らず、色の変化という文脈に合わない。"}, "sentence_index": 0, "correct_answer": "赤く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は赤い本音を語った。", "explanation": "〈赤裸々〉（包み隠さないこと）と混同している。〈赤い〉は色の意味で、率直に話す様子は表せない。"}, {"text": "この会社は、今年も赤い業績が続いている。", "explanation": "〈赤字〉（損失が出ている状態）と混同している。色の意味の〈赤い〉では業績を表せない。"}, {"text": "彼のテストの点数は赤い。", "explanation": "〈赤点〉（不合格の点数）と混同している。色を表す〈赤い〉では、点数の評価は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51607, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赤い", "is_correct": true, "explanation": "「赤い花」は色を表して花を修飾し、ここで合う。"}, {"text": "厚い", "is_correct": false, "explanation": "「厚い花」は意味が通らず、庭いっぱいに咲く花の文脈に合わない。"}, {"text": "重い", "is_correct": false, "explanation": "「重い花」は意味が通らず、咲いているという文脈に合わない。"}, {"text": "熱い", "is_correct": false, "explanation": "「熱い花」は意味が通らず、文脈に合わない。"}], "explanations": {"赤い": "「赤い花」は色を表して花を修飾し、ここで合う。", "厚い": "「厚い花」は意味が通らず、庭いっぱいに咲く花の文脈に合わない。", "重い": "「重い花」は意味が通らず、咲いているという文脈に合わない。", "熱い": "「熱い花」は意味が通らず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "赤い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の話し方は、もう赤い。", "explanation": "〈熱弁〉（熱をこめて話すこと）と混同している。〈赤い〉は色の意味で、話し方の様子は表せない。"}, {"text": "パンを焼きすぎて、赤くなって焦げてしまった。", "explanation": "〈こんがり〉〈茶色く〉のような焼き色と混同している。パンの焼き色を〈赤く〉とは言わない。"}, {"text": "寒さで、窓ガラスが赤くなった。", "explanation": "〈曇る〉と混同している。窓ガラスの変化に〈赤く〉は使わず、この言葉はこう使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51607, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕焼けで雲が赤いなった。", "corrected_sentence": "夕焼けで雲が赤くなった。", "error_description": "「なる」の前は連用形の「赤く」にする必要がある。「赤い」のままでは「なった」に続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "赤い", "is_correct": true, "explanation": "名詞「傘」を修飾する連体形で、ここで合う。"}, {"text": "赤く", "is_correct": false, "explanation": "連用形で、名詞を直接修飾できないため「赤く傘」は不自然。"}, {"text": "赤くて", "is_correct": false, "explanation": "て形で、名詞を修飾できないため「赤くて傘」は成り立たない。"}, {"text": "赤ければ", "is_correct": false, "explanation": "仮定形のため、「赤ければ傘」とは続かず名詞を修飾できない。"}], "correct_form": "赤い", "base_form": "赤い", "form_label": "連体形", "sentence_index": 1, "explanations": {"赤い": "名詞「傘」を修飾する連体形で、ここで合う。", "赤く": "連用形で、名詞を直接修飾できないため「赤く傘」は不自然。", "赤くて": "て形で、名詞を修飾できないため「赤くて傘」は成り立たない。", "赤ければ": "仮定形のため、「赤ければ傘」とは続かず名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51607, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "赤くて屋根の家が、山の上に建っている。", "corrected_sentence": "赤い屋根の家が、山の上に建っている。", "error_description": "名詞を修飾するには連体形の「赤い」が必要。「赤くて」はて形なので、名詞の前に置けない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "赤い", "is_correct": true, "explanation": "終止形で、文を言い切る形。ここで合う。"}, {"text": "赤さ", "is_correct": false, "explanation": "名詞のため、文を言い切れず「顔が赤さ。」は成り立たない。"}, {"text": "赤める", "is_correct": false, "explanation": "他動詞「赤める」は「顔が赤める。」と自動詞の文に使えず、形容詞の終止形の代わりにはならない。"}, {"text": "赤そう", "is_correct": false, "explanation": "様態の語幹形で、「そうだ」を伴わないと文を言い切れず、事実として顔の色を述べる文には合わない。"}], "correct_form": "赤い", "base_form": "赤い", "form_label": "終止形", "sentence_index": 7, "explanations": {"赤い": "終止形で、文を言い切る形。ここで合う。", "赤さ": "名詞のため、文を言い切れず「顔が赤さ。」は成り立たない。", "赤める": "他動詞「赤める」は「顔が赤める。」と自動詞の文に使えず、形容詞の終止形の代わりにはならない。", "赤そう": "様態の語幹形で、「そうだ」を伴わないと文を言い切れず、事実として顔の色を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51609, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「外壁がレンガでできている」の主語を示す『が』が正しい。"}, {"text": "に", "is_correct": false, "explanation": "『外壁にレンガでできていて』は、材料を表す文として意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "『外壁でレンガでできていて』は、場所と材料の関係が不自然で成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "『外壁とレンガでできていて』は並列になり、建物の材料の説明にならない。"}], "correct_answer": "が", "explanations": {"が": "「外壁がレンガでできている」の主語を示す『が』が正しい。", "に": "『外壁にレンガでできていて』は、材料を表す文として意味が通らない。", "で": "『外壁でレンガでできていて』は、場所と材料の関係が不自然で成り立たない。", "と": "『外壁とレンガでできていて』は並列になり、建物の材料の説明にならない。"}, "error_tags": {"に": "材料の説明として意味が通らない", "で": "場所と材料の関係が不自然", "と": "並列になり材料の説明にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51609, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「古い外壁をはがす」で、はがす対象を示す目的語の『を』が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "『外壁へはがす』は方向を示すが、はがす対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "『外壁のはがす』では所属の『の』だけが残り、動詞に直接つながらない。"}, {"text": "より", "is_correct": false, "explanation": "『外壁よりはがす』は比較の意味になり、はがす対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「古い外壁をはがす」で、はがす対象を示す目的語の『を』が正しい。", "へ": "『外壁へはがす』は方向を示すが、はがす対象にはならない。", "の": "『外壁のはがす』では所属の『の』だけが残り、動詞に直接つながらない。", "より": "『外壁よりはがす』は比較の意味になり、はがす対象を示せない。"}, "error_tags": {"へ": "方向の意味でははがす対象にならない", "の": "動詞に直接つながらず文が成立しない", "より": "比較の意味になりはがす対象を示せない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51609, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物の外側の壁。", "primary_collocate": null, "pronunciation": "がいへき", "ipa": "ɡaihekʲi", "syllable_count": 4, "sentences": [{"text": "外壁を新しくしたら、家全体が明るく見えるようになった。", "target_word": "外壁", "complexity_tier": "T3", "furigana": "外壁[がいへき]を新[あたら]しくしたら、家全体[いえぜんたい]が明[あか]るく見[み]えるようになった。", "sentence_source": "generated"}, {"text": "隣の家は外壁がレンガでできていて、とても立派だ。", "target_word": "外壁", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]は外壁[がいへき]がレンガでできていて、とても立派[りっぱ]だ。", "sentence_source": "generated"}, {"text": "職人がはしごに登って、外壁を丁寧に塗っている。", "target_word": "外壁", "complexity_tier": "T3", "furigana": "職人[しょくにん]がはしごに登[のぼ]って、外壁[がいへき]を丁寧[ていねい]に塗[ぬ]っている。", "sentence_source": "generated"}, {"text": "地震で外壁の一部がくずれたため、建物は立ち入り禁止になった。", "target_word": "外壁", "complexity_tier": "T3", "furigana": "地震[じしん]で外壁[がいへき]の一部[いちぶ]がくずれたため、建物[たてもの]は立[た]ち入[い]り禁止[きんし]になった。", "sentence_source": "generated"}, {"text": "この地域では、火事を防ぐために外壁に燃えにくい材料を使う。", "target_word": "外壁", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、火事[かじ]を防[ふせ]ぐために外壁[がいへき]に燃[も]えにくい材料[ざいりょう]を使[つか]う。", "sentence_source": "generated"}, {"text": "外壁の工事中は、窓を開けられないので少し不便だ。", "target_word": "外壁", "complexity_tier": "T3", "furigana": "外壁[がいへき]の工事中[こうじちゅう]は、窓[まど]を開[あ]けられないので少[すこ]し不便[ふべん]だ。", "sentence_source": "generated"}, {"text": "外壁に当たる雨の音が、部屋の中まで響いている。", "target_word": "外壁", "complexity_tier": "T3", "furigana": "外壁[がいへき]に当[あ]たる雨[あめ]の音[おと]が、部屋[へや]の中[なか]まで響[ひび]いている。", "sentence_source": "generated"}, {"text": "古い外壁をはがすと、中から昔の新聞紙が出てきた。", "target_word": "外壁", "complexity_tier": "T3", "furigana": "古[ふる]い外壁[がいへき]をはがすと、中[なか]から昔[むかし]の新聞紙[しんぶんし]が出[で]てきた。", "sentence_source": "generated"}, {"text": "外壁の掃除は大変なので、専門の業者にたのんだ。", "target_word": "外壁", "complexity_tier": "T3", "furigana": "外壁[がいへき]の掃除[そうじ]は大変[たいへん]なので、専門[せんもん]の業者[ぎょうしゃ]にたのんだ。", "sentence_source": "generated"}, {"text": "お城の外壁は白くて高く、敵が入りにくい造りになっている。", "target_word": "外壁", "complexity_tier": "T3", "furigana": "お城[しろ]の外壁[がいへき]は白[しろ]くて高[たか]く、敵[てき]が入[はい]りにくい造[つく]りになっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外壁", "label": "base"}], "register": "neutral", "sense_fingerprint": "家やビルなど建物の外側を囲む壁を指す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0988d614-3a17-476b-9005-b96be10d1534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51609, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外壁", "is_correct": true, "explanation": "建物の外側の面を新しくすると、家全体の見た目が明るくなるので、ここには『外壁』が入る。"}, {"text": "管理人", "is_correct": false, "explanation": "管理人を新しくしても家全体の見た目は変わらず、文の意味が通らない。"}, {"text": "町内会長", "is_correct": false, "explanation": "町内会長を新しくしても家が明るく見えるわけではなく、文の意味が通らない。"}, {"text": "家訓", "is_correct": false, "explanation": "家訓を新しくしても家全体が明るく見えるわけではなく、見た目の変化を表さない。"}], "explanations": {"外壁": "建物の外側の面を新しくすると、家全体の見た目が明るくなるので、ここには『外壁』が入る。", "管理人": "管理人を新しくしても家全体の見た目は変わらず、文の意味が通らない。", "町内会長": "町内会長を新しくしても家が明るく見えるわけではなく、文の意味が通らない。", "家訓": "家訓を新しくしても家全体が明るく見えるわけではなく、見た目の変化を表さない。"}, "sentence_index": 0, "correct_answer": "外壁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外壁の鍵をかけ忘れて、出かけてしまった。", "explanation": "ここは〈玄関〉の意味。外壁には鍵がなく、出入りの口として鍵をかける対象ではない。"}, {"text": "車の外壁を磨くと、新車のように光る。", "explanation": "ここは〈外装〉の意味。外壁は建物の外側の壁なので、車の車体の表面を指す外装の代わりにはならない。"}, {"text": "外壁が冷たいので、スリッパをはいて歩く。", "explanation": "ここは〈床〉の意味。外壁は建物の外側の壁なので、スリッパで歩く床の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51609, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外壁", "is_correct": true, "explanation": "建物の外側の壁に雨が当たると、その音が部屋の中まで響くので、ここには『外壁』が入る。"}, {"text": "植木鉢", "is_correct": false, "explanation": "植木鉢は庭の小さな容器で、雨音が部屋の中まで響く大きさや位置ではない。"}, {"text": "床下", "is_correct": false, "explanation": "床下は床の下の空間で、雨が当たって部屋の中まで響く場所ではない。"}, {"text": "床の間", "is_correct": false, "explanation": "床の間は座敷の飾り場所で、外から雨が当たる場所ではない。"}], "explanations": {"外壁": "建物の外側の壁に雨が当たると、その音が部屋の中まで響くので、ここには『外壁』が入る。", "植木鉢": "植木鉢は庭の小さな容器で、雨音が部屋の中まで響く大きさや位置ではない。", "床下": "床下は床の下の空間で、雨が当たって部屋の中まで響く場所ではない。", "床の間": "床の間は座敷の飾り場所で、外から雨が当たる場所ではない。"}, "sentence_index": 6, "correct_answer": "外壁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの人は外壁が厚く、だれにも心を開かない。", "explanation": "ここは〈心の壁〉の比喩の意味。外壁は建物の外側の壁を指すので、人の性格には使わない。"}, {"text": "寒いので、外壁を閉めた。", "explanation": "ここは〈扉〉の意味。外壁は開け閉めする物ではないので、閉めるという動作には合わない。"}, {"text": "外壁を回すと、台所の空気が入れ替わる。", "explanation": "ここは〈換気扇〉の意味。外壁は回す装置ではないので、空気の入れ替えには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51609, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は、外壁を一週間かけて掃いた。", "corrected_sentence": "祖父は、外壁を一週間かけて塗った。", "error_description": "誤りは『掃いた』、正しくは『塗った』。『掃く』はごみや床に使う動詞で、外壁の塗装作業には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51609, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日でも、外壁を色が目立たない塗料を選んだ。", "corrected_sentence": "雨の日でも、外壁の色が目立たない塗料を選んだ。", "error_description": "誤りは『外壁を』、正しくは『外壁の』。『を』は目的語を示すが、後ろの『色が目立たない』と続く関係では所有を表す『の』が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
