INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51611, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "苔がはえる。", "primary_collocate": null, "pronunciation": "こけむす", "ipa": "kokemɯsɯ", "syllable_count": 4, "sentences": [{"text": "長い間使われなかった井戸のふたは、すっかり苔むしていた。", "target_word": "苔むして", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]使[つか]われなかった井戸[いど]のふたは、すっかり苔[こけ]むしていた。", "sentence_source": "generated"}, {"text": "梅雨のあいだに、玄関の石畳が苔むしてきた。", "target_word": "苔むして", "complexity_tier": "T3", "furigana": "梅雨[つゆ]のあいだに、玄関[げんかん]の石畳[いしだたみ]が苔[こけ]むしてきた。", "sentence_source": "generated"}, {"text": "苔むした岩の上に、小さなカエルが座っていた。", "target_word": "苔むした", "complexity_tier": "T3", "furigana": "苔[こけ]むした岩[いわ]の上[うえ]に、小[ちい]さなカエルが座[すわ]っていた。", "sentence_source": "generated"}, {"text": "森の奥には、苔むした倒木がいくつも横たわっている。", "target_word": "苔むした", "complexity_tier": "T3", "furigana": "森[もり]の奥[おく]には、苔[こけ]むした倒木[とうぼく]がいくつも横[よこ]たわっている。", "sentence_source": "generated"}, {"text": "古い寺の参道は、両側の石灯籠が苔むして静かな雰囲気だった。", "target_word": "苔むして", "complexity_tier": "T3", "furigana": "古[ふる]い寺[てら]の参道[さんどう]は、両側[りょうがわ]の石灯籠[いしどうろう]が苔[こけ]むして静[しず]かな雰囲気[ふんいき]だった。", "sentence_source": "generated"}, {"text": "水をやりすぎると、鉢の土の表面が苔むすことがある。", "target_word": "苔むす", "complexity_tier": "T3", "furigana": "水[みず]をやりすぎると、鉢[はち]の土[つち]の表面[ひょうめん]が苔[こけ]むすことがある。", "sentence_source": "generated"}, {"text": "この石は百年前からここにあり、全体が苔むしている。", "target_word": "苔むして", "complexity_tier": "T3", "furigana": "この石[いし]は百年前[ひゃくねんまえ]からここにあり、全体[ぜんたい]が苔[こけ]むしている。", "sentence_source": "generated"}, {"text": "日陰の石段は苔むしやすいので、歩くときは気をつけてください。", "target_word": "苔むし", "complexity_tier": "T3", "furigana": "日陰[ひかげ]の石段[いしだん]は苔[こけ]むしやすいので、歩[ある]くときは気[き]をつけてください。", "sentence_source": "generated"}, {"text": "庭師は、石がほどよく苔むすまで十年待った。", "target_word": "苔むす", "complexity_tier": "T3", "furigana": "庭師[にわし]は、石[いし]がほどよく苔[こけ]むすまで十年[じゅうねん]待[ま]った。", "sentence_source": "generated"}, {"text": "苔むした屋根の下で、猫が昼寝をしている。", "target_word": "苔むした", "complexity_tier": "T3", "furigana": "苔[こけ]むした屋根[やね]の下[した]で、猫[ねこ]が昼寝[ひるね]をしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "苔むさ", "label": "未然形"}, {"form": "苔むし", "label": "連用形"}, {"form": "苔むす", "label": "終止形・連体形"}, {"form": "苔むせ", "label": "仮定形・命令形"}, {"form": "苔むした", "label": "過去形"}, {"form": "苔むして", "label": "て形"}], "register": "文章語", "sense_fingerprint": "古い石や木などに苔が生える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0988d614-3a17-476b-9005-b96be10d1534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51611, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苔むして", "is_correct": true, "explanation": "「すっかり苔むしていた」の『て』形に『いた』が続く正しい形。"}, {"text": "苔むさ", "is_correct": false, "explanation": "未然形で、『いた』に続けられないので空欄に入らない。"}, {"text": "苔むせ", "is_correct": false, "explanation": "仮定形・命令形で、『いた』に続けられないので空欄に入らない。"}, {"text": "苔むす", "is_correct": false, "explanation": "終止形で、『いた』に直接続けられないので空欄に入らない。"}], "explanations": {"苔むして": "「すっかり苔むしていた」の『て』形に『いた』が続く正しい形。", "苔むさ": "未然形で、『いた』に続けられないので空欄に入らない。", "苔むせ": "仮定形・命令形で、『いた』に続けられないので空欄に入らない。", "苔むす": "終止形で、『いた』に直接続けられないので空欄に入らない。"}, "sentence_index": 0, "correct_answer": "苔むして"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨で服が苔むして、体が冷えた。", "explanation": "ここは〈濡れる〉の意味。苔むすは苔が生えることで、水にぬれることには使わない。"}, {"text": "ペットボトルの水が苔むして、ふたが開かない。", "explanation": "ここは〈凍る〉の意味。苔むすは苔が生えることなので、水が固まることには使わない。"}, {"text": "けがをした足首が苔むして、歩けなくなった。", "explanation": "ここは〈腫れる〉の意味。苔むすは苔が生えることで、皮膚がふくらむことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51611, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苔むして", "is_correct": true, "explanation": "「全体が苔むしている」の『て』形に『いる』が続く正しい形。"}, {"text": "歌って", "is_correct": false, "explanation": "石は歌わないので、『全体が歌っている』は意味が成り立たない。"}, {"text": "錆びて", "is_correct": false, "explanation": "金属がさびる意味になり、石に苔がつく様子とは合わない。"}, {"text": "腫れて", "is_correct": false, "explanation": "皮膚がふくらむ意味で、石の状態を表す文に合わない。"}], "explanations": {"苔むして": "「全体が苔むしている」の『て』形に『いる』が続く正しい形。", "歌って": "石は歌わないので、『全体が歌っている』は意味が成り立たない。", "錆びて": "金属がさびる意味になり、石に苔がつく様子とは合わない。", "腫れて": "皮膚がふくらむ意味で、石の状態を表す文に合わない。"}, "sentence_index": 6, "correct_answer": "苔むして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ガラスのコップが苔むして、手を切った。", "explanation": "ここは〈割れる〉の意味。苔むすは苔が生えることで、ひびが入って砕けることには使わない。"}, {"text": "夕方の庭に、花が苔むしている。", "explanation": "ここは〈咲く〉の意味。苔むすは苔が生えることで、花が開いて咲くことには使わない。"}, {"text": "フライパンが苔むして、油がはねた。", "explanation": "ここは〈熱くなる〉の意味。苔むすは苔が生えることで、温度が上がることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51611, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の多い時期は、庭の石がすぐに苔むする。", "corrected_sentence": "雨の多い時期は、庭の石がすぐに苔むす。", "error_description": "誤りは『苔むする』、正しくは『苔むす』。『苔むす』は五段活用で終止形は『す』なので、『る』を付けた形は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "苔むして", "is_correct": true, "explanation": "「玄関の石畳が苔むしてきた」の『て』形で、続く『きた』につながる正しい形。"}, {"text": "苔むせ", "is_correct": false, "explanation": "仮定形・命令形で、『きた』には続かないので誤り。"}, {"text": "苔むさ", "is_correct": false, "explanation": "未然形で、『きた』に続かないので誤り。"}, {"text": "苔むす", "is_correct": false, "explanation": "終止形で、『きた』に直接続けられないので誤り。"}], "correct_form": "苔むして", "base_form": "苔むす", "form_label": "て形", "sentence_index": 1, "explanations": {"苔むして": "「玄関の石畳が苔むしてきた」の『て』形で、続く『きた』につながる正しい形。", "苔むせ": "仮定形・命令形で、『きた』には続かないので誤り。", "苔むさ": "未然形で、『きた』に続かないので誤り。", "苔むす": "終止形で、『きた』に直接続けられないので誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51611, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は石段が苔むせやすいので、歩くときは気をつけよう。", "corrected_sentence": "雨の日は石段が苔むしやすいので、歩くときは気をつけよう。", "error_description": "誤りは『苔むせ』、正しくは『苔むし』。『～やすい』には連用形『苔むし』が付くので、仮定形の『苔むせ』は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "苔むし", "is_correct": true, "explanation": "「苔むしやすい」の連用形で、『やすい』に続く正しい形。"}, {"text": "苔むせ", "is_correct": false, "explanation": "仮定形・命令形で、『やすい』には続かないので誤り。"}, {"text": "苔むした", "is_correct": false, "explanation": "過去の連体形で、『やすい』に続けられないので誤り。"}, {"text": "苔むさない", "is_correct": false, "explanation": "否定形で、『やすい』に直接続けられないので誤り。"}], "correct_form": "苔むし", "base_form": "苔むす", "form_label": "連用形", "sentence_index": 7, "explanations": {"苔むし": "「苔むしやすい」の連用形で、『やすい』に続く正しい形。", "苔むせ": "仮定形・命令形で、『やすい』には続かないので誤り。", "苔むした": "過去の連体形で、『やすい』に続けられないので誤り。", "苔むさない": "否定形で、『やすい』に直接続けられないので誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
