INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51612, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "表面に苔が生えること。", "primary_collocate": null, "pronunciation": "こけむす", "ipa": "kokemɯsɯ", "syllable_count": 4, "sentences": [{"text": "色褪せた外壁や苔むした庭は、過ぎ去った長い年月を静かに物語っている。", "target_word": "苔むした", "complexity_tier": "T3", "furigana": "色褪[いろあ]せた外壁[がいへき]や苔[こけ]むした庭[にわ]は、過[す]ぎ去[さ]った長[なが]い年月[としつき]を静[しず]かに物語[ものがた]っている。", "sentence_source": "mined"}, {"text": "雨の多い山道では、石段がすぐに苔むしてしまう。", "target_word": "苔むして", "complexity_tier": "T3", "furigana": "雨[あめ]の多[おお]い山道[やまみち]では、石段[いしだん]がすぐに苔[こけ]むしてしまう。", "sentence_source": "generated"}, {"text": "祖父が植えた古い灯籠は、今では一面に苔むしている。", "target_word": "苔むしている", "complexity_tier": "T3", "furigana": "祖父[そふ]が植[う]えた古[ふる]い灯籠[とうろう]は、今[いま]では一面[いちめん]に苔[こけ]むしている。", "sentence_source": "generated"}, {"text": "手入れをしないと、庭の岩はすぐに苔むす。", "target_word": "苔むす", "complexity_tier": "T3", "furigana": "手入[ていれ]れをしないと、庭[にわ]の岩[いわ]はすぐに苔[こけ]むす。", "sentence_source": "generated"}, {"text": "苔むした石垣の間から、小さな花が顔を出していた。", "target_word": "苔むした", "complexity_tier": "T3", "furigana": "苔[こけ]むした石垣[いしがき]の間[あいだ]から、小[ちい]さな花[はな]が顔[かお]を出[だ]していた。", "sentence_source": "generated"}, {"text": "この寺の屋根瓦は長い雨にさらされて苔むし、深い緑色になった。", "target_word": "苔むし", "complexity_tier": "T3", "furigana": "この寺[てら]の屋根瓦[やねがわら]は長[なが]い雨[あめ]にさらされて苔[こけ]むし、深[ふか]い緑色[みどりいろ]になった。", "sentence_source": "generated"}, {"text": "湿気が多いので、北側の塀だけが苔むしている。", "target_word": "苔むして", "complexity_tier": "T3", "furigana": "湿気[しっけ]が多[おお]いので、北側[きたがわ]の塀[へい]だけが苔[こけ]むしている。", "sentence_source": "generated"}, {"text": "苔むした墓石に刻まれた名前は、もう読めなかった。", "target_word": "苔むした", "complexity_tier": "T3", "furigana": "苔[こけ]むした墓石[はかいし]に刻[きざ]まれた名前[なまえ]は、もう読[よ]めなかった。", "sentence_source": "generated"}, {"text": "日当たりが悪い場所では、木の幹も苔むしやすい。", "target_word": "苔むし", "complexity_tier": "T3", "furigana": "日当[ひあ]たりが悪[わる]い場所[ばしょ]では、木[き]の幹[みき]も苔[こけ]むしやすい。", "sentence_source": "generated"}, {"text": "川沿いの古い橋は苔むして、足もとが滑りやすかった。", "target_word": "苔むして", "complexity_tier": "T3", "furigana": "川沿[かわぞ]いの古[ふる]い橋[はし]は苔[こけ]むして、足[あし]もとが滑[すべ]りやすかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "苔むさ", "label": "未然形"}, {"form": "苔むし", "label": "連用形"}, {"form": "苔むす", "label": "終止形・連体形"}, {"form": "苔むせ", "label": "仮定形・命令形"}, {"form": "苔むした", "label": "過去形"}, {"form": "苔むして", "label": "て形"}], "register": "文章語", "sense_fingerprint": "石・屋根・木など物の表面に苔が一面に生える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0988d614-3a17-476b-9005-b96be10d1534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51612, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苔むした", "is_correct": true, "explanation": "「色褪せた外壁や苔むした庭」と、後ろの『庭』を修飾する過去の連体形『苔むした』が正しい。"}, {"text": "苔むさ", "is_correct": false, "explanation": "未然形で、名詞『庭』を修飾できないので空欄に入らない。"}, {"text": "苔むし", "is_correct": false, "explanation": "連用形で、名詞『庭』を修飾できないので空欄に入らない。"}, {"text": "苔むせ", "is_correct": false, "explanation": "仮定形・命令形で、名詞『庭』を修飾できないので空欄に入らない。"}], "explanations": {"苔むした": "「色褪せた外壁や苔むした庭」と、後ろの『庭』を修飾する過去の連体形『苔むした』が正しい。", "苔むさ": "未然形で、名詞『庭』を修飾できないので空欄に入らない。", "苔むし": "連用形で、名詞『庭』を修飾できないので空欄に入らない。", "苔むせ": "仮定形・命令形で、名詞『庭』を修飾できないので空欄に入らない。"}, "sentence_index": 0, "correct_answer": "苔むした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い釘が苔むして、ドアが開かなくなった。", "explanation": "ここは〈錆びる〉の意味。苔むすは苔が一面に生えることで、金属がさびて固くなることには使わない。"}, {"text": "ペンキが苔むして、壁が寂しく見える。", "explanation": "ここは〈色あせる〉の意味。苔むすは苔で表面が覆われることで、色が落ちることには使わない。"}, {"text": "洗濯物が苔むして、いいにおいがする。", "explanation": "ここは〈乾く〉の意味。苔むすは苔が生えることなので、水分が抜けることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51612, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苔むして", "is_correct": true, "explanation": "「北側の塀だけが苔むしている」の『て』形で、『いる』に続く正しい形。"}, {"text": "歌って", "is_correct": false, "explanation": "塀は歌わないので、「北側の塀だけが歌っている」は成り立たない。"}, {"text": "走って", "is_correct": false, "explanation": "塀は走らないので、「走っている」では意味が通らない。"}, {"text": "笑って", "is_correct": false, "explanation": "塀は笑わないので、空欄に入れると意味が合わない。"}], "explanations": {"苔むして": "「北側の塀だけが苔むしている」の『て』形で、『いる』に続く正しい形。", "歌って": "塀は歌わないので、「北側の塀だけが歌っている」は成り立たない。", "走って": "塀は走らないので、「走っている」では意味が通らない。", "笑って": "塀は笑わないので、空欄に入れると意味が合わない。"}, "sentence_index": 6, "correct_answer": "苔むして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪が苔むして、道路が濡れた。", "explanation": "ここは〈溶ける〉の意味。苔むすは苔が生えることで、雪が解けて水になることには使わない。"}, {"text": "トーストが苔むして、いい香りがする。", "explanation": "ここは〈焦げる〉の意味。苔むすは苔が生えることで、焼けて黒くなることには使わない。"}, {"text": "夜の湖面が苔むして、月明かりで光る。", "explanation": "ここは〈藻が一面に生える〉の意味。苔は陸の石や木に生えるもので、湖の水面を覆う藻には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51612, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この石段は、雨が続くと苔むさやすい。", "corrected_sentence": "この石段は、雨が続くと苔むしやすい。", "error_description": "誤りは『苔むさ』、正しくは『苔むし』。『～やすい』には連用形『苔むし』が付くので、未然形の『苔むさ』は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "苔むして", "is_correct": true, "explanation": "「苔むしてしまう」の『て』形で、続く『しまう』につながる正しい形。"}, {"text": "苔むし", "is_correct": false, "explanation": "連用形で、『てしまう』に続けるには『て』が必要なので誤り。"}, {"text": "苔むした", "is_correct": false, "explanation": "過去の連体形で、『てしまう』に続く形ではないので誤り。"}, {"text": "苔むす", "is_correct": false, "explanation": "終止形で、『てしまう』に直接続けられないので誤り。"}], "correct_form": "苔むして", "base_form": "苔むす", "form_label": "て形", "sentence_index": 1, "explanations": {"苔むして": "「苔むしてしまう」の『て』形で、続く『しまう』につながる正しい形。", "苔むし": "連用形で、『てしまう』に続けるには『て』が必要なので誤り。", "苔むした": "過去の連体形で、『てしまう』に続く形ではないので誤り。", "苔むす": "終止形で、『てしまう』に直接続けられないので誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51612, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湿った石段を苔むしやすい。", "corrected_sentence": "湿った石段が苔むしやすい。", "error_description": "誤りは『を』、正しくは『が』。自動詞『苔むす』の主語は『が』で示す。『を』は目的語を示すので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "苔むした", "is_correct": true, "explanation": "「苔むした墓石」の過去の連体形で、名詞『墓石』を修飾する正しい形。"}, {"text": "苔むさ", "is_correct": false, "explanation": "未然形で、名詞『墓石』を修飾できないので誤り。"}, {"text": "苔むせ", "is_correct": false, "explanation": "仮定形・命令形で、名詞『墓石』を修飾できないので誤り。"}, {"text": "苔むして", "is_correct": false, "explanation": "て形で、名詞『墓石』を直接修飾できないので誤り。"}], "correct_form": "苔むした", "base_form": "苔むす", "form_label": "過去の連体形", "sentence_index": 7, "explanations": {"苔むした": "「苔むした墓石」の過去の連体形で、名詞『墓石』を修飾する正しい形。", "苔むさ": "未然形で、名詞『墓石』を修飾できないので誤り。", "苔むせ": "仮定形・命令形で、名詞『墓石』を修飾できないので誤り。", "苔むして": "て形で、名詞『墓石』を直接修飾できないので誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
