INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51613, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "じかんがすぎていくこと。", "primary_collocate": null, "pronunciation": "すぎさる", "ipa": "sɯɡisaɾɯ", "syllable_count": 4, "sentences": [{"text": "楽しい夏休みは、あっという間に過ぎ去った。", "target_word": "過ぎ去った", "complexity_tier": "T3", "furigana": "楽[たの]しい夏休[なつやす]みは、あっという間[ま]に過[す]ぎ去[さ]った。", "sentence_source": "generated"}, {"text": "過ぎ去った日々を思い出すと、少しさみしくなる。", "target_word": "過ぎ去った", "complexity_tier": "T3", "furigana": "過[す]ぎ去[さ]った日々[ひび]を思[おも]い出[だ]すと、少[すこ]しさみしくなる。", "sentence_source": "generated"}, {"text": "若かった日々は、気づかないうちに過ぎ去っていた。", "target_word": "過ぎ去って", "complexity_tier": "T3", "furigana": "若[わか]かった日々[ひび]は、気[き]づかないうちに過[す]ぎ去[さ]っていた。", "sentence_source": "generated"}, {"text": "忙しい毎日が過ぎ去り、やっと春が来た。", "target_word": "過ぎ去り", "complexity_tier": "T3", "furigana": "忙[いそが]しい毎日[まいにち]が過[す]ぎ去[さ]り、やっと春[はる]が来[き]た。", "sentence_source": "generated"}, {"text": "過ぎ去った時間は、お金で買い戻せない。", "target_word": "過ぎ去った", "complexity_tier": "T3", "furigana": "過[す]ぎ去[さ]った時間[じかん]は、お金[かね]で買[か]い戻[もど]せない。", "sentence_source": "generated"}, {"text": "悲しい季節が過ぎ去るのを、じっと待った。", "target_word": "過ぎ去る", "complexity_tier": "T3", "furigana": "悲[かな]しい季節[きせつ]が過[す]ぎ去[さ]るのを、じっと待[ま]った。", "sentence_source": "generated"}, {"text": "子どものころの思い出は、遠く過ぎ去った夢のようだ。", "target_word": "過ぎ去った", "complexity_tier": "T3", "furigana": "子[こ]どものころの思[おも]い出[で]は、遠[とお]く過[す]ぎ去[さ]った夢[ゆめ]のようだ。", "sentence_source": "generated"}, {"text": "試験の週が過ぎ去り、やっと自由な時間ができた。", "target_word": "過ぎ去り", "complexity_tier": "T3", "furigana": "試験[しけん]の週[しゅう]が過[す]ぎ去[さ]り、やっと自由[じゆう]な時間[じかん]ができた。", "sentence_source": "generated"}, {"text": "年月が過ぎ去っても、あの日の約束は忘れない。", "target_word": "過ぎ去って", "complexity_tier": "T3", "furigana": "年月[としつき]が過[す]ぎ去[さ]っても、あの日[ひ]の約束[やくそく]は忘[わす]れない。", "sentence_source": "generated"}, {"text": "つらかった時期が過ぎ去り、今は毎日が楽しい。", "target_word": "過ぎ去り", "complexity_tier": "T3", "furigana": "つらかった時期[じき]が過[す]ぎ去[さ]り、今[いま]は毎日[まいにち]が楽[たの]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "過ぎ去る", "label": "辞書形"}, {"form": "過ぎ去った", "label": "過去形"}, {"form": "過ぎ去って", "label": "て形"}, {"form": "過ぎ去らない", "label": "否定形"}, {"form": "過ぎ去り", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "時間や時期が、戻らないまま通り過ぎて行ってしまうこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8f1722b-8f6a-484b-8e04-67ac74b730cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51613, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "過ぎ去った", "is_correct": true, "explanation": "「あっという間に過ぎ去った」は時間が戻らず過ぎたという意味になり、ここで合う。"}, {"text": "壊れた", "is_correct": false, "explanation": "「夏休みが壊れた」は意味が通らず、時間の経過という文脈に合わない。"}, {"text": "凍った", "is_correct": false, "explanation": "凍るのは物体の状態なので、時間を主語にすると意味が通らない。"}, {"text": "届いた", "is_correct": false, "explanation": "「夏休みが届いた」は意味が通らず、文脈に合わない。"}], "explanations": {"過ぎ去った": "「あっという間に過ぎ去った」は時間が戻らず過ぎたという意味になり、ここで合う。", "壊れた": "「夏休みが壊れた」は意味が通らず、時間の経過という文脈に合わない。", "凍った": "凍るのは物体の状態なので、時間を主語にすると意味が通らない。", "届いた": "「夏休みが届いた」は意味が通らず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "過ぎ去った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車が駅を過ぎ去って、乗り遅れてしまった。", "explanation": "〈通り過ぎる〉（場所を通って行く）と混同している。〈過ぎ去る〉は時間や時期に使うので、この言葉はこう使わない。"}, {"text": "猫が庭を過ぎ去ってしまった。", "explanation": "〈通り抜ける〉と混同している。〈過ぎ去る〉は時間や時期に使い、動物が場所を通るときには使わない。"}, {"text": "服の汚れが過ぎ去って、きれいになった。", "explanation": "〈落ちる〉と混同している。汚れが取れる場合には〈過ぎ去る〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51613, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "過ぎ去った", "is_correct": true, "explanation": "「遠く過ぎ去った夢」は、遠い過去に過ぎ去った夢という意味になり、ここで合う。"}, {"text": "焼けた", "is_correct": false, "explanation": "「遠く焼けた夢」は意味が通らず、思い出を述べる文脈に合わない。"}, {"text": "溶けた", "is_correct": false, "explanation": "「遠く溶けた夢」は意味が通らず、文脈に合わない。"}, {"text": "割れた", "is_correct": false, "explanation": "「遠く割れた夢」は意味が通らず、文脈に合わない。"}], "explanations": {"過ぎ去った": "「遠く過ぎ去った夢」は、遠い過去に過ぎ去った夢という意味になり、ここで合う。", "焼けた": "「遠く焼けた夢」は意味が通らず、思い出を述べる文脈に合わない。", "溶けた": "「遠く溶けた夢」は意味が通らず、文脈に合わない。", "割れた": "「遠く割れた夢」は意味が通らず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "過ぎ去った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗濯を重ねて、シャツの赤が過ぎ去った。", "explanation": "〈色褪せる〉と混同している。色の変化には〈過ぎ去る〉ではなく〈色褪せる〉を使う。"}, {"text": "来年の春は、もう過ぎ去ってしまった。", "explanation": "〈過ぎ去る〉は時間が過ぎて去った後に使う。まだ来ていない春には〈やってくる〉を使い、〈過ぎ去る〉とは言わない。"}, {"text": "彼は部屋を過ぎ去って、すぐに寝た。", "explanation": "〈立ち去る〉と混同している。人が部屋から出て行く動作には〈過ぎ去る〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51613, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "長い冬が過ぎ去るて、やっと春が来た。", "corrected_sentence": "長い冬が過ぎ去って、やっと春が来た。", "error_description": "辞書形の「過ぎ去る」には「て」が続かない。て形は「過ぎ去って」にする必要がある。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "過ぎ去った", "is_correct": true, "explanation": "過去形で、ここでは過去の時期を修飾する形として合う。"}, {"text": "過ぎ去ろう", "is_correct": false, "explanation": "意志形のため名詞を修飾できず、「過ぎ去ろう日々」は成り立たない。"}, {"text": "過ぎ去って", "is_correct": false, "explanation": "て形のため名詞を修飾できず、「過ぎ去って日々」は成り立たない。"}, {"text": "過ぎ去り", "is_correct": false, "explanation": "連用形のため名詞を修飾できず、「過ぎ去り日々」は成り立たない。"}], "correct_form": "過ぎ去った", "base_form": "過ぎ去る", "form_label": "過去形", "sentence_index": 1, "explanations": {"過ぎ去った": "過去形で、ここでは過去の時期を修飾する形として合う。", "過ぎ去ろう": "意志形のため名詞を修飾できず、「過ぎ去ろう日々」は成り立たない。", "過ぎ去って": "て形のため名詞を修飾できず、「過ぎ去って日々」は成り立たない。", "過ぎ去り": "連用形のため名詞を修飾できず、「過ぎ去り日々」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51613, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "苦しい時期が過ぎ去るを、ひたすら待った。", "corrected_sentence": "苦しい時期が過ぎ去るのを、ひたすら待った。", "error_description": "動詞を「待つ」の対象として名詞化するには「の」が必要。「過ぎ去るを」ではなく「過ぎ去るのを」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "過ぎ去り", "is_correct": true, "explanation": "連用形で、後ろに「やっと自由な時間ができた」と続けられるので、ここで合う。"}, {"text": "過ぎ去る", "is_correct": false, "explanation": "終止形で文が切れてしまい、後ろの「やっと」と自然につながらない。"}, {"text": "過ぎ去らない", "is_correct": false, "explanation": "否定の形になり、時期が終わらないという反対の意味になるため文意が合わない。"}, {"text": "過ぎ去ろう", "is_correct": false, "explanation": "意志形のため文を言い切れず、「過ぎ去ろう、やっと…」とは続かない。"}], "correct_form": "過ぎ去り", "base_form": "過ぎ去る", "form_label": "連用形", "sentence_index": 7, "explanations": {"過ぎ去り": "連用形で、後ろに「やっと自由な時間ができた」と続けられるので、ここで合う。", "過ぎ去る": "終止形で文が切れてしまい、後ろの「やっと」と自然につながらない。", "過ぎ去らない": "否定の形になり、時期が終わらないという反対の意味になるため文意が合わない。", "過ぎ去ろう": "意志形のため文を言い切れず、「過ぎ去ろう、やっと…」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51615, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51615, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「生徒たちに物語った」と、受け手を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「生徒たちを物語った」は受け手に「を」を取る形として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「生徒たちで」は手段・場所の意味になり、受け手を示せない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では「生徒たちの物語った」となり文にならない。"}], "correct_answer": "に", "explanations": {"に": "正解。「生徒たちに物語った」と、受け手を示す格助詞。", "を": "「生徒たちを物語った」は受け手に「を」を取る形として不自然。", "で": "「生徒たちで」は手段・場所の意味になり、受け手を示せない。", "の": "連体修飾の「の」では「生徒たちの物語った」となり文にならない。"}, "error_tags": {"を": "対象の格不一致", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51615, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "体験や出来事の話を、まとまりとして人に語り聞かせること。", "primary_collocate": null, "pronunciation": "ものがたる", "ipa": "monogatarɯ", "syllable_count": 5, "sentences": [{"text": "祖父は戦争中の体験を、孫たちにゆっくりと物語った。", "target_word": "物語った", "complexity_tier": "T3", "furigana": "祖父[そふ]は戦争中[せんそうちゅう]の体験[たいけん]を、孫[まご]たちにゆっくりと物語[ものがた]った。", "sentence_source": "generated"}, {"text": "旅人は村人を前に、遠い国での冒険を物語り始めた。", "target_word": "物語り", "complexity_tier": "T3", "furigana": "旅人[たびびと]は村人[むらびと]を前[まえ]に、遠[とお]い国[くに]での冒険[ぼうけん]を物語[ものがた]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "夜になると、祖母は昔話を物語ってくれた。", "target_word": "物語って", "complexity_tier": "T3", "furigana": "夜[よる]になると、祖母[そぼ]は昔話[むかしばなし]を物語[ものがた]ってくれた。", "sentence_source": "generated"}, {"text": "彼は自分の生い立ちを、涙ながらに物語った。", "target_word": "物語った", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の生[お]い立[た]ちを、涙[なみだ]ながらに物語[ものがた]った。", "sentence_source": "generated"}, {"text": "老人が物語る昔の村の話に、子どもたちは耳を傾けた。", "target_word": "物語る", "complexity_tier": "T3", "furigana": "老人[ろうじん]が物語[ものがた]る昔[むかし]の村[むら]の話[はなし]に、子[こ]どもたちは耳[みみ]を傾[かたむ]けた。", "sentence_source": "generated"}, {"text": "語り部は、先祖から伝わる伝説を物語っている。", "target_word": "物語って", "complexity_tier": "T3", "furigana": "語[かた]り部[べ]は、先祖[せんぞ]から伝[つた]わる伝説[でんせつ]を物語[ものがた]っている。", "sentence_source": "generated"}, {"text": "彼女は事件のいきさつを、順を追って物語った。", "target_word": "物語った", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は事件[じけん]のいきさつを、順[じゅん]を追[お]って物語[ものがた]った。", "sentence_source": "generated"}, {"text": "退職した校長先生が、昔の学校での出来事を生徒たちに物語った。", "target_word": "物語った", "complexity_tier": "T3", "furigana": "退職[たいしょく]した校長[こうちょう]先生[せんせい]が、昔[むかし]の学校[がっこう]での出来事[できごと]を生徒[せいと]たちに物語[ものがた]った。", "sentence_source": "generated"}, {"text": "船乗りは嵐の夜に見た不思議な光を物語った。", "target_word": "物語った", "complexity_tier": "T3", "furigana": "船乗[ふなの]りは嵐[あらし]の夜[よる]に見[み]た不思議[ふしぎ]な光[ひかり]を物語[ものがた]った。", "sentence_source": "generated"}, {"text": "年老いた漁師が、若い頃の航海を物語ってくれた。", "target_word": "物語って", "complexity_tier": "T3", "furigana": "年老[としお]いた漁師[りょうし]が、若[わか]い頃[ころ]の航海[こうかい]を物語[ものがた]ってくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物語ら", "label": "未然形"}, {"form": "物語り", "label": "連用形"}, {"form": "物語る", "label": "終止形・連体形"}, {"form": "物語れ", "label": "仮定形・命令形"}, {"form": "物語った", "label": "過去形"}, {"form": "物語って", "label": "て形"}], "register": "標準", "sense_fingerprint": "人が体験や話をひとまとまりに語り聞かせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0988d614-3a17-476b-9005-b96be10d1534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51615, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物語った", "is_correct": true, "explanation": "正解。文末の過去形。"}, {"text": "物語ら", "is_correct": false, "explanation": "未然形は文末に立てず、「物語ら。」は成立しない。"}, {"text": "物語れ", "is_correct": false, "explanation": "仮定形・命令形では文が締まらず、意味も合わない。"}, {"text": "物語って", "is_correct": false, "explanation": "て形では文を締められず、「物語って。」は成立しない。"}], "explanations": {"物語った": "正解。文末の過去形。", "物語ら": "未然形は文末に立てず、「物語ら。」は成立しない。", "物語れ": "仮定形・命令形では文が締まらず、意味も合わない。", "物語って": "て形では文を締められず、「物語って。」は成立しない。"}, "sentence_index": 0, "correct_answer": "物語った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は会議で、新しい案への反対意見を物語った。", "explanation": "ここは〈述べる〉の意味。意見や立場を伝えるのは〈述べる〉で、〈物語る〉は出来事や話の内容に使う。"}, {"text": "父は私に、自転車の乗り方を物語った。", "explanation": "ここは〈教える〉の意味。手順や方法を伝える場面では〈教える〉を使い、〈物語る〉は体験や出来事の話に使う。"}, {"text": "店員は客に、商品の値段を物語った。", "explanation": "ここは〈伝える〉の意味。値段などの情報を知らせるのは〈伝える〉で、〈物語る〉は話の内容や出来事を語る場合に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51615, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物語った", "is_correct": true, "explanation": "正解。文末の過去形。"}, {"text": "物語れば", "is_correct": false, "explanation": "仮定形＋「ば」で文が締まらず、「物語れば。」は成立しない。"}, {"text": "物語らず", "is_correct": false, "explanation": "「ず」の形で文は締まらず、「物語らず。」は成立しない。"}, {"text": "物語り", "is_correct": false, "explanation": "連用形は文末に立てず、「物語り。」は成立しない。"}], "explanations": {"物語った": "正解。文末の過去形。", "物語れば": "仮定形＋「ば」で文が締まらず、「物語れば。」は成立しない。", "物語らず": "「ず」の形で文は締まらず、「物語らず。」は成立しない。", "物語り": "連用形は文末に立てず、「物語り。」は成立しない。"}, "sentence_index": 6, "correct_answer": "物語った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は生徒に、廊下を走らないよう物語った。", "explanation": "ここは〈注意する〉の意味。禁止や注意の内容を伝えるのは〈注意する〉で、〈物語る〉は出来事を語るときに使う。"}, {"text": "校長は全員に、すぐ帰るよう怒鳴った。", "explanation": "ここは〈怒鳴る〉の意味。大声で指示する行為は〈怒鳴る〉で、〈物語る〉は話の内容を語るときに使う。"}, {"text": "彼は群衆に、静かに指示を物語った。", "explanation": "ここは〈指示する〉の意味。指示を出す行為は〈指示する〉で、〈物語る〉は出来事や経験の話に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51615, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅人は、遠い国での冒険を村人で物語った。", "corrected_sentence": "旅人は、遠い国での冒険を村人に物語った。", "error_description": "「物語った」の相手（受け手）は「に」で示す。「で」は手段・場所を表すので誤り（誤：で、正：に）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "物語り", "is_correct": true, "explanation": "正解。「物語り始めた」の連用形。"}, {"text": "物語ら", "is_correct": false, "explanation": "未然形では「物語ら始めた」となり成立しない。"}, {"text": "物語れ", "is_correct": false, "explanation": "仮定形・命令形では「物語れ始めた」となり成立しない。"}, {"text": "物語った", "is_correct": false, "explanation": "過去形では「物語った始めた」となり成立しない。"}], "correct_form": "物語り", "base_form": "物語る", "form_label": "連用形", "sentence_index": 1, "explanations": {"物語り": "正解。「物語り始めた」の連用形。", "物語ら": "未然形では「物語ら始めた」となり成立しない。", "物語れ": "仮定形・命令形では「物語れ始めた」となり成立しない。", "物語った": "過去形では「物語った始めた」となり成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51615, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は戦争の話を、孫たちを物語った。", "corrected_sentence": "祖父は戦争の話を、孫たちに物語った。", "error_description": "「物語る」の受け手は「に」で示す。「を」にすると受け手の格が誤り（誤：を、正：に）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "物語った", "is_correct": true, "explanation": "正解。過去形。"}, {"text": "物語って", "is_correct": false, "explanation": "て形では文が締まらず、「生徒たちに物語って。」は成立しない。"}, {"text": "物語らず", "is_correct": false, "explanation": "「ず」の形では文が締まらず、成立しない。"}, {"text": "物語れば", "is_correct": false, "explanation": "仮定形＋「ば」では文が締まらず、成立しない。"}], "correct_form": "物語った", "base_form": "物語る", "form_label": "過去形", "sentence_index": 7, "explanations": {"物語った": "正解。過去形。", "物語って": "て形では文が締まらず、「生徒たちに物語って。」は成立しない。", "物語らず": "「ず」の形では文が締まらず、成立しない。", "物語れば": "仮定形＋「ば」では文が締まらず、成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51616, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「賑わいを物語る」と、物語る対象を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「賑わいに物語る」は対象を示せず、文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では「賑わいの物語っている」となり文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、物語る対象とは合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「賑わいを物語る」と、物語る対象を示す格助詞。", "に": "「賑わいに物語る」は対象を示せず、文が成立しない。", "の": "連体修飾の「の」では「賑わいの物語っている」となり文にならない。", "へ": "方向を示す「へ」は、物語る対象とは合わない。"}, "error_tags": {"に": "対象の格不一致", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51616, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「日々を物語る」と、物語る対象を示す格助詞。"}, {"text": "で", "is_correct": false, "explanation": "「日々で物語っている」は手段・場所の意味になり、物語る対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「日々と物語っている」は並列・相手の意味になり、対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「日々より物語っている」は比較の意味になり、物語る対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「日々を物語る」と、物語る対象を示す格助詞。", "で": "「日々で物語っている」は手段・場所の意味になり、物語る対象を示せない。", "と": "「日々と物語っている」は並列・相手の意味になり、対象を示せない。", "より": "「日々より物語っている」は比較の意味になり、物語る対象を示せない。"}, "error_tags": {"で": "手段・場所", "と": "並列・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51616, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事の様子や跡が、過去の出来事や時の経過を示していること。", "primary_collocate": null, "pronunciation": "ものがたる", "ipa": "monogatarɯ", "syllable_count": 5, "sentences": [{"text": "色褪せた外壁や苔むした庭は、過ぎ去った長い年月を静かに物語っている。", "target_word": "物語っ", "complexity_tier": "T3", "furigana": "色褪[いろあ]せた外壁[がいへき]や苔[こけ]むした庭[にわ]は、過[す]ぎ去[さ]った長[なが]い年月[としつき]を静[しず]かに物語[ものがた]っている。", "sentence_source": "mined"}, {"text": "古い駅舎の柱に残る傷は、かつての賑わいを物語っている。", "target_word": "物語って", "complexity_tier": "T3", "furigana": "古[ふる]い駅舎[えきしゃ]の柱[はしら]に残[のこ]る傷[きず]は、かつての賑[にぎ]わいを物語[ものがた]っている。", "sentence_source": "generated"}, {"text": "彼の日に焼けた手は、長年の苦労を物語っている。", "target_word": "物語って", "complexity_tier": "T3", "furigana": "彼[かれ]の日[ひ]に焼[や]けた手[て]は、長年[ながねん]の苦労[くろう]を物語[ものがた]っている。", "sentence_source": "generated"}, {"text": "壊れた橋は、昨夜の洪水の激しさを物語っていた。", "target_word": "物語って", "complexity_tier": "T3", "furigana": "壊[こわ]れた橋[はし]は、昨夜[さくや]の洪水[こうずい]の激[はげ]しさを物語[ものがた]っていた。", "sentence_source": "generated"}, {"text": "祖母のしわの深い顔が、人生の長さを物語る。", "target_word": "物語る", "complexity_tier": "T3", "furigana": "祖母[そぼ]のしわの深[ふか]い顔[かお]が、人生[じんせい]の長[なが]さを物語[ものがた]る。", "sentence_source": "generated"}, {"text": "すり減った階段は、多くの人が通ったことを物語っている。", "target_word": "物語って", "complexity_tier": "T3", "furigana": "すり減[へ]った階段[かいだん]は、多[おお]くの人[ひと]が通[とお]ったことを物語[ものがた]っている。", "sentence_source": "generated"}, {"text": "空き家の増えた町並みは、人口が減った現実を物語っていた。", "target_word": "物語って", "complexity_tier": "T3", "furigana": "空[あ]き家[や]の増[ふ]えた町並[まちな]みは、人口[じんこう]が減[へ]った現実[げんじつ]を物語[ものがた]っていた。", "sentence_source": "generated"}, {"text": "色の落ちた制服が、三年間の部活の日々を物語っている。", "target_word": "物語って", "complexity_tier": "T3", "furigana": "色[いろ]の落[お]ちた制服[せいふく]が、三年間[さんねんかん]の部活[ぶかつ]の日々[ひび]を物語[ものがた]っている。", "sentence_source": "generated"}, {"text": "この遺跡から出た土器は、昔の暮らしぶりを物語る貴重な資料だ。", "target_word": "物語る", "complexity_tier": "T3", "furigana": "この遺跡[いせき]から出[で]た土器[どき]は、昔[むかし]の暮[く]らしぶりを物語[ものがた]る貴重[きちょう]な資料[しりょう]だ。", "sentence_source": "generated"}, {"text": "厚くたまった埃が、長い間誰も来なかったことを物語っていた。", "target_word": "物語って", "complexity_tier": "T3", "furigana": "厚[あつ]くたまった埃[ほこり]が、長[なが]い間[あいだ]誰[だれ]も来[こ]なかったことを物語[ものがた]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物語ら", "label": "未然形"}, {"form": "物語り", "label": "連用形"}, {"form": "物語る", "label": "終止形・連体形"}, {"form": "物語れ", "label": "仮定形・命令形"}, {"form": "物語った", "label": "過去形"}, {"form": "物語って", "label": "て形"}], "register": "標準", "sense_fingerprint": "物事の様子や跡が、過去の出来事や背景を示し伝える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0988d614-3a17-476b-9005-b96be10d1534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51616, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物語っ", "is_correct": true, "explanation": "正解。「物語っている」のうち、「ている」に続く「物語っ」（て形の語幹）。"}, {"text": "物語ら", "is_correct": false, "explanation": "未然形のため「物語らている」となり成立しない。"}, {"text": "物語れ", "is_correct": false, "explanation": "仮定形・命令形のため「物語れている」は成立しない。"}, {"text": "物語る", "is_correct": false, "explanation": "終止形のままでは「物語るている」となり成立しない。"}], "explanations": {"物語っ": "正解。「物語っている」のうち、「ている」に続く「物語っ」（て形の語幹）。", "物語ら": "未然形のため「物語らている」となり成立しない。", "物語れ": "仮定形・命令形のため「物語れている」は成立しない。", "物語る": "終止形のままでは「物語るている」となり成立しない。"}, "sentence_index": 0, "correct_answer": "物語っ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は新製品の発売日を、来年の春に物語っている。", "explanation": "ここは〈予告する〉の意味。将来の予定を知らせるのは〈予告する〉で、〈物語る〉は既に起きた出来事や状況が示す内容に使う。"}, {"text": "会議で彼は、反対の理由を一つずつ物語った。", "explanation": "ここは〈述べる〉の意味。理由や意見を筋道立てて述べる場面では〈述べる〉を使い、〈物語る〉は使わない。"}, {"text": "先生は生徒の質問に、丁寧に物語った。", "explanation": "ここは〈答える〉の意味。質問への回答は〈答える〉で、〈物語る〉は出来事の経緯や跡が示す内容に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51616, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物語って", "is_correct": true, "explanation": "正解。「物語っていた」の「て形」で、「いた」に続く。"}, {"text": "物語った", "is_correct": false, "explanation": "過去形のため「物語ったいた」となり成立しない。"}, {"text": "物語る", "is_correct": false, "explanation": "終止形のため「物語るいた」となり成立しない。"}, {"text": "物語り", "is_correct": false, "explanation": "連用形のため「物語りいた」となり成立しない。"}], "explanations": {"物語って": "正解。「物語っていた」の「て形」で、「いた」に続く。", "物語った": "過去形のため「物語ったいた」となり成立しない。", "物語る": "終止形のため「物語るいた」となり成立しない。", "物語り": "連用形のため「物語りいた」となり成立しない。"}, "sentence_index": 6, "correct_answer": "物語って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究員は試薬を、ピペットで物語った。", "explanation": "ここは〈注ぐ〉の意味。液体を移す操作は〈注ぐ〉で、〈物語る〉は話の内容や跡が示す様子に使う。"}, {"text": "気象台は明日の天気を、正午に物語った。", "explanation": "ここは〈発表する〉の意味。公式に知らせる場合は〈発表する〉で、〈物語る〉は既にある跡や様子が示す内容に使う。"}, {"text": "技師は部品を、一つずつ物語った。", "explanation": "ここは〈数える〉の意味。部品を一つずつ数える場合は〈数える〉で、〈物語る〉は出来事や跡が示す内容に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51616, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母の手紙は、昔の暮らしの厳しさに物語っていた。", "corrected_sentence": "祖母の手紙は、昔の暮らしの厳しさを物語っていた。", "error_description": "「物語る」の対象は「を」で示す。「に」を使うと対象の格が誤り（誤：に、正：を）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "物語って", "is_correct": true, "explanation": "正解。「物語っている」の「て形」。"}, {"text": "物語った", "is_correct": false, "explanation": "過去形では「物語ったいる」となり、状態を表す「ている」に続かない。"}, {"text": "物語る", "is_correct": false, "explanation": "終止形・連体形では「物語るいる」となり成立しない。"}, {"text": "物語れ", "is_correct": false, "explanation": "仮定形・命令形では「物語れている」は成立しない。"}], "correct_form": "物語って", "base_form": "物語る", "form_label": "て形", "sentence_index": 1, "explanations": {"物語って": "正解。「物語っている」の「て形」。", "物語った": "過去形では「物語ったいる」となり、状態を表す「ている」に続かない。", "物語る": "終止形・連体形では「物語るいる」となり成立しない。", "物語れ": "仮定形・命令形では「物語れている」は成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51616, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古びた看板は、店の長い歴史を物語れている。", "corrected_sentence": "古びた看板は、店の長い歴史を物語っている。", "error_description": "「物語っている」のて形「物語って」が正しい。「物語れ」は仮定形・命令形で、「ている」に続かない（誤：物語れ、正：物語って）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "物語って", "is_correct": true, "explanation": "正解。「物語っている」の「て形」。"}, {"text": "物語ら", "is_correct": false, "explanation": "未然形のため「物語らている」となり成立しない。"}, {"text": "物語り", "is_correct": false, "explanation": "連用形のため「物語りている」となり、「ている」を直接続けられない。"}, {"text": "物語ろう", "is_correct": false, "explanation": "意志形のため「物語ろうている」となり成立しない。"}], "correct_form": "物語って", "base_form": "物語る", "form_label": "て形", "sentence_index": 7, "explanations": {"物語って": "正解。「物語っている」の「て形」。", "物語ら": "未然形のため「物語らている」となり成立しない。", "物語り": "連用形のため「物語りている」となり、「ている」を直接続けられない。", "物語ろう": "意志形のため「物語ろうている」となり成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
