INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51617, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「年月を費やす」の目的語として「を」が正しい。時間を使うことを表す形。"}, {"text": "が", "is_correct": false, "explanation": "「年月が費やしてきた」は、目的語を取る「費やす」の対象にならず、文が成立しない。"}, {"text": "から", "is_correct": false, "explanation": "「年月から費やしてきた」は起点の「から」が、費やす対象を示せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「年月より費やしてきた」は比較の「より」が動詞の目的語を示せず、文にならない。"}], "correct_answer": "を", "explanations": {"を": "「年月を費やす」の目的語として「を」が正しい。時間を使うことを表す形。", "が": "「年月が費やしてきた」は、目的語を取る「費やす」の対象にならず、文が成立しない。", "から": "「年月から費やしてきた」は起点の「から」が、費やす対象を示せず不自然。", "より": "「年月より費やしてきた」は比較の「より」が動詞の目的語を示せず、文にならない。"}, "error_tags": {"が": "主格", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51617, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "長い時間のこと", "primary_collocate": null, "pronunciation": "としつき", "ipa": "toɕitsɯki", "syllable_count": 4, "sentences": [{"text": "長い年月を経て、ふたりはようやく再会できた。", "target_word": "年月", "complexity_tier": "T3", "furigana": "長(なが)い年月(としつき)を経(へ)て、ふたりはようやく再会(さいかい)できた。", "sentence_source": "generated"}, {"text": "私が故郷を離れてから、もう十年という年月が過ぎた。", "target_word": "年月", "complexity_tier": "T3", "furigana": "私(わたし)が故郷(こきょう)を離(はな)れてから、もう十年(じゅうねん)という年月(としつき)が過(す)ぎた。", "sentence_source": "generated"}, {"text": "年月が経てば、悲しい思い出もやさしく思えるようになる。", "target_word": "年月", "complexity_tier": "T3", "furigana": "年月(としつき)が経(た)てば、悲(かな)しい思(おも)い出(で)もやさしく思(おも)えるようになる。", "sentence_source": "generated"}, {"text": "祖母は長い年月にわたって、毎朝同じ道を歩いてきた。", "target_word": "年月", "complexity_tier": "T3", "furigana": "祖母(そぼ)は長(なが)い年月(としつき)にわたって、毎朝(まいあさ)同(おな)じ道(みち)を歩(ある)いてきた。", "sentence_source": "generated"}, {"text": "この古い木は、長い年月をかけて大きく育った。", "target_word": "年月", "complexity_tier": "T3", "furigana": "この古(ふる)い木(き)は、長(なが)い年月(としつき)をかけて大(おお)きく育(そだ)った。", "sentence_source": "generated"}, {"text": "年月とともに、町の景色も少しずつ変わっていく。", "target_word": "年月", "complexity_tier": "T3", "furigana": "年月(としつき)とともに、町(まち)の景色(けしき)も少(すこ)しずつ変(か)わっていく。", "sentence_source": "generated"}, {"text": "長い年月が過ぎたのに、あの味は今も変わらない。", "target_word": "年月", "complexity_tier": "T3", "furigana": "長(なが)い年月(としつき)が過(す)ぎたのに、あの味(あじ)は今(いま)も変(か)わらない。", "sentence_source": "generated"}, {"text": "彼はこの仕事に長い年月を費やしてきた。", "target_word": "年月", "complexity_tier": "T3", "furigana": "彼(かれ)はこの仕事(しごと)に長(なが)い年月(としつき)を費(つい)やしてきた。", "sentence_source": "generated"}, {"text": "古い写真は、流れた年月を教えてくれる。", "target_word": "年月", "complexity_tier": "T3", "furigana": "古(ふる)い写真(しゃしん)は、流(なが)れた年月(としつき)を教(おし)えてくれる。", "sentence_source": "generated"}, {"text": "大変だった年月も、今ではいい思い出だ。", "target_word": "年月", "complexity_tier": "T3", "furigana": "大変(たいへん)だった年月(としつき)も、今(いま)ではいい思(おも)い出(で)だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年月", "label": "基本形"}], "register": "plain", "sense_fingerprint": "長い時間・過ぎ去った歳月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4171fa00-9184-4481-a2ec-a876e376ecb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51617, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年月", "is_correct": true, "explanation": "「長い年月を経て」は時間の長さを表し、経過の対象として自然。"}, {"text": "手紙", "is_correct": false, "explanation": "「長い手紙を経て」は成り立たない。経るのは時間や過程で、手紙は経られない。"}, {"text": "包装", "is_correct": false, "explanation": "「長い包装を経て」は意味が合わず、再会までの経過を表せない。"}, {"text": "指示", "is_correct": false, "explanation": "「長い指示を経て」は再会までの時間の経過を示せず、文に合わない。"}], "explanations": {"年月": "「長い年月を経て」は時間の長さを表し、経過の対象として自然。", "手紙": "「長い手紙を経て」は成り立たない。経るのは時間や過程で、手紙は経られない。", "包装": "「長い包装を経て」は意味が合わず、再会までの経過を表せない。", "指示": "「長い指示を経て」は再会までの時間の経過を示せず、文に合わない。"}, "sentence_index": 0, "correct_answer": "年月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "髪を乾かす年月は十分ある。", "explanation": "「時間」の位置に入れた誤用。年月は数年以上の長さを指すので、髪を乾かすような数分の時間には合わない。"}, {"text": "提出の年月は今週の金曜日です。", "explanation": "「期限」の位置に入れた誤用。年月は長い期間を表すので、締め切りの一日を指すことはできない。"}, {"text": "母は年月より若く見える。", "explanation": "「年齢より若く見える」の年齢を入れ替えた誤用。年月は期間を表し、若さの基準にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51617, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年月", "is_correct": true, "explanation": "「長い年月が過ぎたのに」は時間の経過を表し、味が変わらないという文に合う。"}, {"text": "理屈", "is_correct": false, "explanation": "「長い理屈が過ぎた」は意味をなさず、時間の長さを表せない。"}, {"text": "感覚", "is_correct": false, "explanation": "「長い感覚が過ぎた」は時間の流れを表す語として合わない。"}, {"text": "語彙", "is_correct": false, "explanation": "「長い語彙が過ぎた」は時間の経過とは結びつかず、文が成り立たない。"}], "explanations": {"年月": "「長い年月が過ぎたのに」は時間の経過を表し、味が変わらないという文に合う。", "理屈": "「長い理屈が過ぎた」は意味をなさず、時間の長さを表せない。", "感覚": "「長い感覚が過ぎた」は時間の流れを表す語として合わない。", "語彙": "「長い語彙が過ぎた」は時間の経過とは結びつかず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "年月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会費の年月は五千円です。", "explanation": "「金額」の位置に入れた誤用。年月は時間の長さなので、お金の額を示す文には使えない。"}, {"text": "彼の年月は六十キロだ。", "explanation": "「体重」の位置に入れた誤用。年月は時間の長さなので、人の体重を示す文には合わない。"}, {"text": "今日の年月は一万歩だった。", "explanation": "「歩数」の位置に入れた誤用。年月は時間の長さで、歩いた回数を表すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51617, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は長い年月でかけて、ようやく家を建てた。", "corrected_sentence": "祖父は長い年月をかけて、ようやく家を建てた。", "error_description": "誤りは「年月で」。「かける」は時間の量を「を」で受けるので、正しくは「年月をかけて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51617, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大変な年月が乗り越えて、ようやく今がある。", "corrected_sentence": "大変な年月を乗り越えて、ようやく今がある。", "error_description": "誤りは「年月が」。「乗り越える」は困難な時間を「を」で受けるので、正しくは「年月を乗り越えて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51619, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「遺産をめぐって」で争いの対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「遺産にめぐって」は「めぐる」の対象を示す形として成り立たず、対象・方向の誤りになる。"}, {"text": "で", "is_correct": false, "explanation": "「遺産でめぐって」は手段や場所を示すが、争いの対象を表せず、手段・場所の誤りになる。"}, {"text": "と", "is_correct": false, "explanation": "「遺産とめぐって」は相手や並列を示すが、「めぐる」の対象として成り立たず、相手・並列の誤りになる。"}], "correct_answer": "を", "explanations": {"を": "正解。「遺産をめぐって」で争いの対象を示す。", "に": "「遺産にめぐって」は「めぐる」の対象を示す形として成り立たず、対象・方向の誤りになる。", "で": "「遺産でめぐって」は手段や場所を示すが、争いの対象を表せず、手段・場所の誤りになる。", "と": "「遺産とめぐって」は相手や並列を示すが、「めぐる」の対象として成り立たず、相手・並列の誤りになる。"}, "error_tags": {"に": "対象・方向の誤り", "で": "手段・場所の誤り", "と": "相手・並列の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51619, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「遺産を受け取る」で受け取る対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「遺産に受け取る」は受け取る対象を示す形として成り立たず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「遺産の受け取るために」では連体修飾になるが、後に名詞がなく文が成り立たない。連体修飾の誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「遺産へ受け取る」は方向を示すが、受け取る対象を表せず不自然。方向の誤り。"}], "correct_answer": "を", "explanations": {"を": "正解。「遺産を受け取る」で受け取る対象を示す。", "に": "「遺産に受け取る」は受け取る対象を示す形として成り立たず、不自然。", "の": "「遺産の受け取るために」では連体修飾になるが、後に名詞がなく文が成り立たない。連体修飾の誤り。", "へ": "「遺産へ受け取る」は方向を示すが、受け取る対象を表せず不自然。方向の誤り。"}, "error_tags": {"に": "対象・位置の誤り", "の": "連体修飾の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51619, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "死んだ人が残したお金や物のこと。", "primary_collocate": null, "pronunciation": "いさん", "ipa": "isaɴ", "syllable_count": 3, "sentences": [{"text": "祖父が亡くなって、家族みんなで遺産の話をしました。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "祖父[そふ]が亡[な]くなって、家族[かぞく]みんなで遺産[いさん]の話[はなし]をしました。", "sentence_source": "generated"}, {"text": "遺産をめぐって、兄弟が争いました。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "遺産[いさん]をめぐって、兄弟[きょうだい]が争[あらそ]いました。", "sentence_source": "generated"}, {"text": "彼女は父の遺産で小さな店を開きました。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は父[ちち]の遺産[いさん]で小[ちい]さな店[みせ]を開[ひら]きました。", "sentence_source": "generated"}, {"text": "遺産が多いと、税金も高くなります。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "遺産[いさん]が多[おお]いと、税金[ぜいきん]も高[たか]くなります。", "sentence_source": "generated"}, {"text": "おじさんは遺産を全部、病院に寄付しました。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "おじさんは遺産[いさん]を全部[ぜんぶ]、病院[びょういん]に寄付[きふ]しました。", "sentence_source": "generated"}, {"text": "遺産といっても、古い時計と本だけでした。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "遺産[いさん]といっても、古[ふる]い時計[とけい]と本[ほん]だけでした。", "sentence_source": "generated"}, {"text": "母は遺産を子どもたちに等しく分けました。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "母[はは]は遺産[いさん]を子[こ]どもたちに等[ひと]しく分[わ]けました。", "sentence_source": "generated"}, {"text": "遺産を受け取るために、書類を出さなければなりません。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "遺産[いさん]を受[う]け取[と]るために、書類[しょるい]を出[だ]さなければなりません。", "sentence_source": "generated"}, {"text": "祖母の遺産は、小さな家と少しの貯金でした。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "祖母[そぼ]の遺産[いさん]は、小[ちい]さな家[いえ]と少[すこ]しの貯金[ちょきん]でした。", "sentence_source": "generated"}, {"text": "遺産がなかったので、親の死後も争いは起きませんでした。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "遺産[いさん]がなかったので、親[おや]の死後[しご]も争[あらそ]いは起[お]きませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遺産", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "亡くなった人が残した財産", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ac41b1-bf6a-4b52-9986-43adaca85130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51619, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遺産", "is_correct": true, "explanation": "亡くなった人が残したものとして、家族が遺産について話す場面に合う。"}, {"text": "花火", "is_correct": false, "explanation": "祖父が亡くなった後の家族の話題として花火は合わず、文脈に不釣り合い。"}, {"text": "夕立", "is_correct": false, "explanation": "夕立は天気のことで、家族が財産や遺品を話し合う場面には合わない。"}, {"text": "台風", "is_correct": false, "explanation": "台風の話は葬儀の後の家族の会話として唐突で、亡くなった人の話題に合わない。"}], "explanations": {"遺産": "亡くなった人が残したものとして、家族が遺産について話す場面に合う。", "花火": "祖父が亡くなった後の家族の話題として花火は合わず、文脈に不釣り合い。", "夕立": "夕立は天気のことで、家族が財産や遺品を話し合う場面には合わない。", "台風": "台風の話は葬儀の後の家族の会話として唐突で、亡くなった人の話題に合わない。"}, "sentence_index": 0, "correct_answer": "遺産"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の今の遺産を計算すると、貯金が二十万円増えていました。", "explanation": "ここは〈資産〉の意味。遺産は亡くなった人が残したものを指すので、生きている人が今持っている財産には使わない。"}, {"text": "遺産を見直すと、毎月の掛け金を減らせました。", "explanation": "ここは〈保険〉の意味。遺産は故人が残した財産で、毎月払う掛け金の見直しとは関係しない。"}, {"text": "遺産を返すために、毎月少しずつ払っています。", "explanation": "ここは〈借金〉の意味。遺産は受け取るものであり、返すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51619, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遺産", "is_correct": true, "explanation": "母が子どもたちに分ける対象として、亡くなった人の残したものである遺産が合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は分けて渡せるものではないので、「分けました」の目的語として成り立たない。"}, {"text": "挨拶", "is_correct": false, "explanation": "挨拶は分けて渡すものではなく、「子どもたちに等しく分ける」の対象として合わない。"}, {"text": "夕日", "is_correct": false, "explanation": "夕日は誰かに分けられるものではなく、この文の目的語として不自然。"}], "explanations": {"遺産": "母が子どもたちに分ける対象として、亡くなった人の残したものである遺産が合う。", "天気": "天気は分けて渡せるものではないので、「分けました」の目的語として成り立たない。", "挨拶": "挨拶は分けて渡すものではなく、「子どもたちに等しく分ける」の対象として合わない。", "夕日": "夕日は誰かに分けられるものではなく、この文の目的語として不自然。"}, "sentence_index": 6, "correct_answer": "遺産"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宝くじで遺産が当たったので、家族で旅行に行きました。", "explanation": "ここは〈賞金〉の意味。遺産は亡くなった人が残したものなので、くじの当たりには使わない。"}, {"text": "遺産は、毎年の金額を決めておくと安心です。", "explanation": "ここは〈寄付〉の意味。遺産は残された財産で、毎年の寄付額を決める話には合わない。"}, {"text": "遺産は、仕事の対価として毎月もらっています。", "explanation": "ここは〈報酬〉の意味。遺産は亡くなった人が残したものなので、働いて得る報酬の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51619, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父の遺産に、兄と妹で分けました。", "corrected_sentence": "父の遺産を、兄と妹で分けました。", "error_description": "助詞の誤り。正しくは「遺産を」（目的語）。「遺産に」では「分ける」の対象が示されず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51619, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母の遺産を食べるまで、少し時間がかかりました。", "corrected_sentence": "祖母の遺産を受け取るまで、少し時間がかかりました。", "error_description": "動詞の選び方の誤り。遺産は「受け取る」もので、「食べる」は食べ物に使うので遺産には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51620, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「遺産を分ける」の目的語として「を」が正しい。分割の対象を示す形。"}, {"text": "へ", "is_correct": false, "explanation": "「遺産へ分ける」は方向の「へ」が分割の対象と結びつかず、文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「遺産と分ける」は、共に行う相手を表す「と」が分割の対象を示せず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「遺産の分けるか」は、分ける動作の目的語を示せず、文の形が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「遺産を分ける」の目的語として「を」が正しい。分割の対象を示す形。", "へ": "「遺産へ分ける」は方向の「へ」が分割の対象と結びつかず、文が成立しない。", "と": "「遺産と分ける」は、共に行う相手を表す「と」が分割の対象を示せず、不自然。", "の": "「遺産の分けるか」は、分ける動作の目的語を示せず、文の形が崩れる。"}, "error_tags": {"へ": "方向", "と": "共同", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51620, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「遺産の額」の連体修飾として「の」が正しい。遺産に属する額を示す。"}, {"text": "を", "is_correct": false, "explanation": "「遺産を額」は目的語になれず、額が大きいという文を組み立てられない。"}, {"text": "に", "is_correct": false, "explanation": "「遺産に額が大きい」は帰着の「に」が額の大きさと結びつかず、意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「遺産から額が大きい」は起点の「から」が額の大きさを示せず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「遺産の額」の連体修飾として「の」が正しい。遺産に属する額を示す。", "を": "「遺産を額」は目的語になれず、額が大きいという文を組み立てられない。", "に": "「遺産に額が大きい」は帰着の「に」が額の大きさと結びつかず、意味が通らない。", "から": "「遺産から額が大きい」は起点の「から」が額の大きさを示せず、不自然。"}, "error_tags": {"を": "目的語", "に": "帰着", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51620, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が亡くなった後に残された財産や権利、義務などの総称。", "primary_collocate": null, "pronunciation": "いさん", "ipa": "isaɴ", "syllable_count": 3, "sentences": [{"text": "父の死後、兄は遺産の管理を任された。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "父(ちち)の死後(しご)、兄(あに)は遺産(いさん)の管理(かんり)を任(まか)された。", "sentence_source": "generated"}, {"text": "祖父が亡くなり、家族は遺産をどう分けるか話し合った。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "祖父(そふ)が亡(な)くなり、家族(かぞく)は遺産(いさん)をどう分(わ)けるか話(はな)し合(あ)った。", "sentence_source": "generated"}, {"text": "遺産には、預金だけでなく借金も含まれることがある。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "遺産(いさん)には、預金(よきん)だけでなく借金(しゃっきん)も含(ふく)まれることがある。", "sentence_source": "generated"}, {"text": "父は遺産を残さなかったので、兄弟で争うことはなかった。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "父(ちち)は遺産(いさん)を残(のこ)さなかったので、兄弟(きょうだい)で争(あらそ)うことはなかった。", "sentence_source": "generated"}, {"text": "彼女は叔父の遺産を相続して、小さな店を開いた。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は叔父(おじ)の遺産(いさん)を相続(そうぞく)して、小(ちい)さな店(みせ)を開(ひら)いた。", "sentence_source": "generated"}, {"text": "遺産の分け方をめぐって、親戚の間で意見が分かれた。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "遺産(いさん)の分(わ)け方(かた)をめぐって、親戚(しんせき)の間(あいだ)で意見(いけん)が分(わ)かれた。", "sentence_source": "generated"}, {"text": "弁護士は遺産に関する書類を丁寧に確認した。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "弁護士(べんごし)は遺産(いさん)に関(かん)する書類(しょるい)を丁寧(ていねい)に確認(かくにん)した。", "sentence_source": "generated"}, {"text": "遺産の額が大きいので、相続税も高くなる。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "遺産(いさん)の額(がく)が大(おお)きいので、相続税(そうぞくぜい)も高(たか)くなる。", "sentence_source": "generated"}, {"text": "遺言書には、遺産を全部子どもに譲ると書いてあった。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "遺言書(ゆいごんしょ)には、遺産(いさん)を全部(ぜんぶ)子(こ)どもに譲(ゆず)ると書(か)いてあった。", "sentence_source": "generated"}, {"text": "彼は遺産を受け取る権利を、兄に譲った。", "target_word": "遺産", "complexity_tier": "T3", "furigana": "彼(かれ)は遺産(いさん)を受(う)け取(と)る権利(けんり)を、兄(あに)に譲(ゆず)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遺産", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "死後に残る財産・権利・義務の総称(相続の対象)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4171fa00-9184-4481-a2ec-a876e376ecb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51620, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遺産", "is_correct": true, "explanation": "「遺産の管理」は死後に残された財産を管理する意味で、この文の文脈に合う。"}, {"text": "咳払い", "is_correct": false, "explanation": "「咳払いの管理」は成り立たず、管理の対象にならない。"}, {"text": "悲鳴", "is_correct": false, "explanation": "「悲鳴の管理」は意味をなさず、任せる対象にならない。"}, {"text": "ため息", "is_correct": false, "explanation": "「ため息の管理」は意味が通らず、任せる対象にならない。"}], "explanations": {"遺産": "「遺産の管理」は死後に残された財産を管理する意味で、この文の文脈に合う。", "咳払い": "「咳払いの管理」は成り立たず、管理の対象にならない。", "悲鳴": "「悲鳴の管理」は意味をなさず、任せる対象にならない。", "ため息": "「ため息の管理」は意味が通らず、任せる対象にならない。"}, "sentence_index": 0, "correct_answer": "遺産"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この病気は遺産によって子どもに伝わる。", "explanation": "「遺伝」の位置に入れた誤用。病気が親から子に伝わるのは遺伝で、遺産（死後に残された財産）とは別の概念なので、ここでは合わない。"}, {"text": "父は遺産を書いて、弁護士に預けた。", "explanation": "「遺言書」の位置に入れた誤用。遺産は財産そのもので、書いて作るものではない。書くのは遺言書なので合わない。"}, {"text": "父の遺産は三人いる。", "explanation": "「相続人」の位置に入れた誤用。遺産は人ではないので、人数を数える文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51620, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遺産", "is_correct": true, "explanation": "「遺産に関する書類」は相続財産の書類を指し、弁護士が確認する文と合う。"}, {"text": "鼻歌", "is_correct": false, "explanation": "「鼻歌に関する書類」は内容として成り立たず、確認の対象にならない。"}, {"text": "足音", "is_correct": false, "explanation": "「足音に関する書類」は記録の対象として不自然で、弁護士が確認する文に合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "「寝息に関する書類」は内容として不自然で、丁寧に確認する対象にならない。"}], "explanations": {"遺産": "「遺産に関する書類」は相続財産の書類を指し、弁護士が確認する文と合う。", "鼻歌": "「鼻歌に関する書類」は内容として成り立たず、確認の対象にならない。", "足音": "「足音に関する書類」は記録の対象として不自然で、弁護士が確認する文に合わない。", "寝息": "「寝息に関する書類」は内容として不自然で、丁寧に確認する対象にならない。"}, "sentence_index": 6, "correct_answer": "遺産"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は毎月の遺産で、家族を養っている。", "explanation": "「給料」の位置に入れた誤用。遺産は死後に一度に受け取る財産で、毎月定期的に入る給料とは性質が違うので、この文には合わない。"}, {"text": "この電池の遺産は三年だ。", "explanation": "「寿命」の位置に入れた誤用。遺産は期間を表さず、電池が使える期間の文には使えない。"}, {"text": "この土地の遺産は父だ。", "explanation": "「所有者」の位置に入れた誤用。遺産は財産そのもので、土地の持ち主を示す人ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51620, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "叔父は遺産で相続して、古い家を守っている。", "corrected_sentence": "叔父は遺産を相続して、古い家を守っている。", "error_description": "誤りは「遺産で」。「相続する」は財産を「を」で受けるので、正しくは「遺産を相続して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51620, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は遺産で弟に譲った。", "corrected_sentence": "父は遺産を弟に譲った。", "error_description": "誤りは「遺産で」。「譲る」は譲る財産を「を」で受けるので、正しくは「遺産を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51621, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「荷物を整理して」の「を」は、整理の対象を示す正しい格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「荷物に整理」は目的語の格として不自然で、対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は整理の対象を示せず、この位置では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は整理の対象にならず、ここでは不自然。"}], "correct_answer": "を", "explanations": {"を": "「荷物を整理して」の「を」は、整理の対象を示す正しい格助詞。", "に": "「荷物に整理」は目的語の格として不自然で、対象を示せない。", "より": "比較の「より」は整理の対象を示せず、この位置では意味が通らない。", "へ": "方向の「へ」は整理の対象にならず、ここでは不自然。"}, "error_tags": {"に": "目的語の格を誤り", "より": "比較の助詞", "へ": "方向の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
