INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51621, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ばらばらになっているものを、きちんとまとめること。", "primary_collocate": null, "pronunciation": "せいり", "ipa": "seːɾi", "syllable_count": 3, "sentences": [{"text": "床に散らばった本を整理して、箱にまとめた。", "target_word": "整理", "complexity_tier": "T3", "furigana": "床(ゆか)に散(ち)らばった本(ほん)を整理(せいり)して、箱(はこ)にまとめた。", "sentence_source": "generated"}, {"text": "引っ越しの前に、荷物を整理して箱に入れた。", "target_word": "整理", "complexity_tier": "T3", "furigana": "引(ひ)っ越(こ)しの前(まえ)に、荷物(にもつ)を整理(せいり)して箱(はこ)に入(い)れた。", "sentence_source": "generated"}, {"text": "机の上の書類を整理して、ファイルにとじた。", "target_word": "整理", "complexity_tier": "T3", "furigana": "机(つくえ)の上(うえ)の書類(しょるい)を整理(せいり)して、ファイルにとじた。", "sentence_source": "generated"}, {"text": "部屋が散らかっているので、まず整理から始めよう。", "target_word": "整理", "complexity_tier": "T3", "furigana": "部屋(へや)が散(ち)らかっているので、まず整理(せいり)から始(はじ)めよう。", "sentence_source": "generated"}, {"text": "古い手紙を整理していたら、昔の写真が出てきた。", "target_word": "整理", "complexity_tier": "T3", "furigana": "古(ふる)い手紙(てがみ)を整理(せいり)していたら、昔(むかし)の写真(しゃしん)が出(で)てきた。", "sentence_source": "generated"}, {"text": "彼はばらばらのメモを整理して、一つのレポートにした。", "target_word": "整理", "complexity_tier": "T3", "furigana": "彼(かれ)はばらばらのメモを整理(せいり)して、一(ひと)つのレポートにした。", "sentence_source": "generated"}, {"text": "整理されたかばんの中は、とても見やすい。", "target_word": "整理", "complexity_tier": "T3", "furigana": "整理(せいり)されたかばんの中(なか)は、とても見(み)やすい。", "sentence_source": "generated"}, {"text": "母は週末に、押し入れの整理をした。", "target_word": "整理", "complexity_tier": "T3", "furigana": "母(はは)は週末(しゅうまつ)に、押(お)し入(い)れの整理(せいり)をした。", "sentence_source": "generated"}, {"text": "作業が終わったら、道具を整理して元の場所に戻す。", "target_word": "整理", "complexity_tier": "T3", "furigana": "作業(さぎょう)が終(お)わったら、道具(どうぐ)を整理(せいり)して元(もと)の場所(ばしょ)に戻(もど)す。", "sentence_source": "generated"}, {"text": "財布の中のレシートを整理した。", "target_word": "整理", "complexity_tier": "T3", "furigana": "財布(さいふ)の中(なか)のレシートを整理(せいり)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "整理", "label": "基本形"}, {"form": "整理する", "label": "サ変動詞 終止形"}, {"form": "整理した", "label": "過去形"}, {"form": "整理して", "label": "て形"}, {"form": "整理される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "散らばったものをきちんとまとめる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4171fa00-9184-4481-a2ec-a876e376ecb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51621, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整理", "is_correct": true, "explanation": "「床に散らばった本を整理して」は、散らばった物をまとめる意味で自然に入る。"}, {"text": "撮影", "is_correct": false, "explanation": "本を撮影して箱にまとめるのは意味が通らない。"}, {"text": "洗濯", "is_correct": false, "explanation": "本は洗濯しないので、空所に入らない。"}, {"text": "加熱", "is_correct": false, "explanation": "本を加熱して箱にまとめることはなく、ここでは成り立たない。"}], "explanations": {"整理": "「床に散らばった本を整理して」は、散らばった物をまとめる意味で自然に入る。", "撮影": "本を撮影して箱にまとめるのは意味が通らない。", "洗濯": "本は洗濯しないので、空所に入らない。", "加熱": "本を加熱して箱にまとめることはなく、ここでは成り立たない。"}, "sentence_index": 0, "correct_answer": "整理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "体重を整理して、三キロ減らした。", "explanation": "ここは〈減量〉の意味。整理は体重を減らす意味はなく、並べ直すことを表す。"}, {"text": "床のシミを整理して、きれいにした。", "explanation": "ここは〈取り除く〉の意味。整理は並べ直すことで、シミを取り除く意味はない。"}, {"text": "なくした鍵を、部屋中で整理した。", "explanation": "ここは〈探す〉の意味。整理は並べ直すことで、見えなくなったものを見つけ出す意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51621, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整理", "is_correct": true, "explanation": "「整理されたかばん」は、中身を並べ直した状態を表し自然に入る。"}, {"text": "加熱", "is_correct": false, "explanation": "「加熱されたかばん」は成り立たず、空所に入らない。"}, {"text": "解凍", "is_correct": false, "explanation": "かばんは解凍しないので、空所に入らない。"}, {"text": "点火", "is_correct": false, "explanation": "かばんに点火することはなく、ここでは意味が通らない。"}], "explanations": {"整理": "「整理されたかばん」は、中身を並べ直した状態を表し自然に入る。", "加熱": "「加熱されたかばん」は成り立たず、空所に入らない。", "解凍": "かばんは解凍しないので、空所に入らない。", "点火": "かばんに点火することはなく、ここでは意味が通らない。"}, "sentence_index": 6, "correct_answer": "整理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボールを整理して、ゴールに入れた。", "explanation": "ここは〈シュート〉の意味。整理は物を並べ直すことで、ボールを蹴って入れる行為ではない。"}, {"text": "胃の調子を整理して、薬を飲まずに治した。", "explanation": "ここは〈回復〉の意味。整理は物事を分けてまとめることで、体の不調を治す意味はない。"}, {"text": "髪を整理して、色を染め直した。", "explanation": "ここは〈染色〉の意味。整理は髪の色を変える意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51621, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い手紙を整理て、箱にしまった。", "corrected_sentence": "古い手紙を整理して、箱にしまった。", "error_description": "「整理て」は誤った活用形。て形は「整理して」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51621, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "財布の中の小銭に整理してから、買い物に行った。", "corrected_sentence": "財布の中の小銭を整理してから、買い物に行った。", "error_description": "「整理」は目的語に「を」を取る。「に」は誤りで、「小銭を整理」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51622, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「引き出しを整理」の「を」は、整理の対象を示す正しい格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「引き出しに整理」は目的語の格として不自然で、対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は整理の対象を示せず、この位置では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は整理の対象にならず、ここでは不自然。"}], "correct_answer": "を", "explanations": {"を": "「引き出しを整理」の「を」は、整理の対象を示す正しい格助詞。", "に": "「引き出しに整理」は目的語の格として不自然で、対象を示せない。", "より": "比較の「より」は整理の対象を示せず、この位置では意味が通らない。", "へ": "方向の「へ」は整理の対象にならず、ここでは不自然。"}, "error_tags": {"に": "目的語の格を誤り", "より": "比較の助詞", "へ": "方向の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51622, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「データを整理しないと」の「を」は、整理の対象を示す正しい格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は整理の対象にならず、ここでは不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は整理の対象を示せず、この位置では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は整理の対象を示せず、「データから整理」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「データを整理しないと」の「を」は、整理の対象を示す正しい格助詞。", "へ": "方向の「へ」は整理の対象にならず、ここでは不自然。", "より": "比較の「より」は整理の対象を示せず、この位置では意味が通らない。", "から": "起点の「から」は整理の対象を示せず、「データから整理」は不自然。"}, "error_tags": {"へ": "方向の助詞", "より": "比較の助詞", "から": "起点の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51622, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事を整えて、使いやすくしたり、分かりやすくしたりすること。", "primary_collocate": null, "pronunciation": "せいり", "ipa": "seːɾi", "syllable_count": 3, "sentences": [{"text": "旅行に出る前に、持ち物を整理してかばんにまとめた。", "target_word": "整理", "complexity_tier": "T3", "furigana": "旅行(りょこう)に出(で)る前(まえ)に、持(も)ち物(もの)を整理(せいり)してかばんにまとめた。", "sentence_source": "generated"}, {"text": "机の引き出しを整理したら、使いやすくなった。", "target_word": "整理", "complexity_tier": "T3", "furigana": "机(つくえ)の引(ひ)き出(だ)しを整理(せいり)したら、使(つか)いやすくなった。", "sentence_source": "generated"}, {"text": "発表の前に、集めた資料を整理して読みやすくした。", "target_word": "整理", "complexity_tier": "T3", "furigana": "発表(はっぴょう)の前(まえ)に、集(あつ)めた資料(しりょう)を整理(せいり)して読(よ)みやすくした。", "sentence_source": "generated"}, {"text": "書類の整理が終わるまで、会議室は使えない。", "target_word": "整理", "complexity_tier": "T3", "furigana": "書類(しょるい)の整理(せいり)が終(お)わるまで、会議室(かいぎしつ)は使(つか)えない。", "sentence_source": "generated"}, {"text": "彼女は毎週日曜日に、クローゼットの整理をする。", "target_word": "整理", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は毎週(まいしゅう)日曜日(にちようび)に、クローゼットの整理(せいり)をする。", "sentence_source": "generated"}, {"text": "考えを整理してから話すと、相手によく伝わる。", "target_word": "整理", "complexity_tier": "T3", "furigana": "考(かんが)えを整理(せいり)してから話(はな)すと、相手(あいて)によく伝(つた)わる。", "sentence_source": "generated"}, {"text": "本棚の本をジャンル別に整理すると、探しやすい。", "target_word": "整理", "complexity_tier": "T3", "furigana": "本棚(ほんだな)の本(ほん)をジャンル別(べつ)に整理(せいり)すると、探(さが)しやすい。", "sentence_source": "generated"}, {"text": "写真のデータを整理しないと、どこにあるか分からなくなる。", "target_word": "整理", "complexity_tier": "T3", "furigana": "写真(しゃしん)のデータを整理(せいり)しないと、どこにあるか分(わ)からなくなる。", "sentence_source": "generated"}, {"text": "情報を整理したノートは、試験の前に役に立った。", "target_word": "整理", "complexity_tier": "T3", "furigana": "情報(じょうほう)を整理(せいり)したノートは、試験(しけん)の前(まえ)に役(やく)に立(た)った。", "sentence_source": "generated"}, {"text": "店長は倉庫の整理を、新人に任せた。", "target_word": "整理", "complexity_tier": "T3", "furigana": "店長(てんちょう)は倉庫(そうこ)の整理(せいり)を、新人(しんじん)に任(まか)せた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "整理", "label": "基本形"}, {"form": "整理する", "label": "サ変動詞 終止形"}, {"form": "整理した", "label": "過去形"}, {"form": "整理して", "label": "て形"}, {"form": "整理しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "物や情報を整えて使いやすく・分かりやすくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4171fa00-9184-4481-a2ec-a876e376ecb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51622, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整理", "is_correct": true, "explanation": "「持ち物を整理してかばんにまとめた」は物を整えて使いやすくする意味で自然に入る。"}, {"text": "散歩", "is_correct": false, "explanation": "「持ち物を散歩して」は成り立たず、空所に入らない。"}, {"text": "解凍", "is_correct": false, "explanation": "「持ち物を解凍して」は不自然で、意味が成立しない。"}, {"text": "運動", "is_correct": false, "explanation": "「持ち物を運動して」は成り立たず、空所に入らない。"}], "explanations": {"整理": "「持ち物を整理してかばんにまとめた」は物を整えて使いやすくする意味で自然に入る。", "散歩": "「持ち物を散歩して」は成り立たず、空所に入らない。", "解凍": "「持ち物を解凍して」は不自然で、意味が成立しない。", "運動": "「持ち物を運動して」は成り立たず、空所に入らない。"}, "sentence_index": 0, "correct_answer": "整理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い車を整理してもらったら、よく走るようになった。", "explanation": "ここは〈整備〉の意味。整理は物をまとめて分かりやすくすることで、車の手入れには使わない。"}, {"text": "窓ガラスを整理して、ぴかぴかにした。", "explanation": "ここは〈掃除〉の意味。整理は汚れを落とすことではなく、物を並べ直すことを指す。"}, {"text": "体調を整理して、明日の試合に備えた。", "explanation": "ここは〈調整〉の意味。整理は物事を分けてまとめることで、体の状態を整えるのには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51622, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整理", "is_correct": true, "explanation": "「ジャンル別に整理する」は自然な連語で、空所に入る語として正しい。"}, {"text": "撮影", "is_correct": false, "explanation": "「ジャンル別に撮影」は不自然で、空所に入らない。"}, {"text": "塗装", "is_correct": false, "explanation": "本棚の本を塗装することはなく、ここでは意味が通らない。"}, {"text": "解凍", "is_correct": false, "explanation": "解凍は冷凍品に使う語で、本には使わない。"}], "explanations": {"整理": "「ジャンル別に整理する」は自然な連語で、空所に入る語として正しい。", "撮影": "「ジャンル別に撮影」は不自然で、空所に入らない。", "塗装": "本棚の本を塗装することはなく、ここでは意味が通らない。", "解凍": "解凍は冷凍品に使う語で、本には使わない。"}, "sentence_index": 6, "correct_answer": "整理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壊れた電線を整理して、電気を通した。", "explanation": "ここは〈修理〉の意味。整理は物を並べ直すことで、断線を直す意味はない。"}, {"text": "ボールペンのインクを整理して、書けるようにした。", "explanation": "ここは〈補充〉の意味。整理は物をまとめる意味で、足りないインクを足すことは表さない。"}, {"text": "試験の点数を整理して、合格した。", "explanation": "ここは〈向上〉の意味。整理は点数を上げることではなく、並べ直すことを指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51622, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝、机の上を整理てから仕事を始める。", "corrected_sentence": "毎朝、机の上を整理してから仕事を始める。", "error_description": "「整理て」は誤った活用形。て形は「整理して」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51622, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "床の本が整理したあと、部屋を出た。", "corrected_sentence": "床の本を整理したあと、部屋を出た。", "error_description": "「整理」は目的語に「を」を取る。「が」は誤りで、「床の本を整理」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51623, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ブランコが軋む」の「が」は、軋む主体を示す正しい格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「ブランコを軋む」は目的語として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「ブランコに軋む」は位置を示し、主語として不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は軋む主体を示せず、ここでは不自然。"}], "correct_answer": "が", "explanations": {"が": "「ブランコが軋む」の「が」は、軋む主体を示す正しい格助詞。", "を": "「ブランコを軋む」は目的語として不自然。", "に": "「ブランコに軋む」は位置を示し、主語として不自然。", "より": "比較の「より」は軋む主体を示せず、ここでは不自然。"}, "error_tags": {"を": "目的語", "に": "位置・方向の助詞", "より": "比較の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51623, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「座るたびに軋む」の「に」は、軋む契機を示す正しい格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「座るたびが軋む」は不自然で、契機を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「座るたびを軋む」は目的語として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「座るたびで軋む」は手段を示し、この位置では不自然。"}], "correct_answer": "に", "explanations": {"に": "「座るたびに軋む」の「に」は、軋む契機を示す正しい格助詞。", "が": "「座るたびが軋む」は不自然で、契機を示せない。", "を": "「座るたびを軋む」は目的語として不自然。", "で": "「座るたびで軋む」は手段を示し、この位置では不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51623, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものがきしむのは、ぎゅうっと押されたりして、いやな音がすることだよ。", "primary_collocate": null, "pronunciation": "きしむ", "ipa": "kiɕimɯ", "syllable_count": 3, "sentences": [{"text": "古い階段を上ると、ぎしぎしと軋む。", "target_word": "軋む", "complexity_tier": "T2", "furigana": "古[ふる]い階段[かいだん]を上[のぼ]ると、ぎしぎしと軋[きし]む。", "sentence_source": "generated"}, {"text": "ブランコが軋む音が、公園に響いていた。", "target_word": "軋む", "complexity_tier": "T3", "furigana": "ブランコが軋[きし]む音[おと]が、公園[こうえん]に響[ひび]いていた。", "sentence_source": "generated"}, {"text": "弟が飛びはねたので、ベッドが軋んだ。", "target_word": "軋んだ", "complexity_tier": "T2", "furigana": "弟[おとうと]が飛[と]びはねたので、ベッドが軋[きし]んだ。", "sentence_source": "generated"}, {"text": "木の床が軋むから、静かに歩いてね。", "target_word": "軋む", "complexity_tier": "T2", "furigana": "木[き]の床[ゆか]が軋[きし]むから、静[しず]かに歩[ある]いてね。", "sentence_source": "generated"}, {"text": "重い箱をのせると、机が軋んだ。", "target_word": "軋んだ", "complexity_tier": "T2", "furigana": "重[おも]い箱[はこ]をのせると、机[つくえ]が軋[きし]んだ。", "sentence_source": "generated"}, {"text": "窓が風で軋んで、眠れなかった。", "target_word": "軋んで", "complexity_tier": "T2", "furigana": "窓[まど]が風[かぜ]で軋[きし]んで、眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "戸が軋まないように、ゆっくり開けた。", "target_word": "軋まない", "complexity_tier": "T2", "furigana": "戸[と]が軋[きし]まないように、ゆっくり開[あ]けた。", "sentence_source": "generated"}, {"text": "古い椅子は、座るたびに軋む。", "target_word": "軋む", "complexity_tier": "T2", "furigana": "古[ふる]い椅子[いす]は、座[すわ]るたびに軋[きし]む。", "sentence_source": "generated"}, {"text": "床板が軋んでいるので、直してもらった。", "target_word": "軋んで", "complexity_tier": "T3", "furigana": "床板[ゆかいた]が軋[きし]んでいるので、直[なお]してもらった。", "sentence_source": "generated"}, {"text": "橋がぎゅっと軋んだ瞬間、みんな立ち止まった。", "target_word": "軋んだ", "complexity_tier": "T3", "furigana": "橋[はし]がぎゅっと軋[きし]んだ瞬間[しゅんかん]、みんな立[た]ち止[ど]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "軋む", "label": "終止形"}, {"form": "軋んだ", "label": "過去形"}, {"form": "軋んで", "label": "て形"}, {"form": "軋まない", "label": "否定形"}, {"form": "軋み", "label": "連用形"}], "register": "中立", "sense_fingerprint": "力が加わった物が、ギシギシといやな音を出す(床・ベッド・ブランコなど)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4171fa00-9184-4481-a2ec-a876e376ecb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51623, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "軋む", "is_correct": true, "explanation": "「ぎしぎしと軋む」は、階段が体重でいやな音を立てる様子を表し、自然に入る。"}, {"text": "光る", "is_correct": false, "explanation": "「ぎしぎしと光る」は成り立たず、音の描写に合わない。"}, {"text": "咲く", "is_correct": false, "explanation": "「ぎしぎしと咲く」は不自然で、花の動作は音の描写に合わない。"}, {"text": "晴れる", "is_correct": false, "explanation": "「ぎしぎしと晴れる」は意味が通らず、天候は音の描写に合わない。"}], "explanations": {"軋む": "「ぎしぎしと軋む」は、階段が体重でいやな音を立てる様子を表し、自然に入る。", "光る": "「ぎしぎしと光る」は成り立たず、音の描写に合わない。", "咲く": "「ぎしぎしと咲く」は不自然で、花の動作は音の描写に合わない。", "晴れる": "「ぎしぎしと晴れる」は意味が通らず、天候は音の描写に合わない。"}, "sentence_index": 0, "correct_answer": "軋む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ベルが軋むから、静かに止めてね。", "explanation": "ここは〈鳴る〉の意味。軋むは硬い物が擦れて出すいやな音で、澄んだベルの音には使わない。"}, {"text": "古い瓶が軋んで、粉々に砕けた。", "explanation": "ここは〈砕ける〉の意味。軋むはきしみ音を出す語で、物がこなごなになることは表さない。"}, {"text": "遠くの汽笛が、軋んで谷間に響いた。", "explanation": "ここは〈響く〉の意味。軋むは硬いもの同士が擦れて出す音で、遠くまで伝わる響きは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51623, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "軋まない", "is_correct": true, "explanation": "「戸が軋まないように」は、音を立てないようにする意味で自然に入る。"}, {"text": "咲かない", "is_correct": false, "explanation": "戸は咲かないので、「咲かないように」は成り立たない。"}, {"text": "香らない", "is_correct": false, "explanation": "戸は香るものではなく、空所に入らない。"}, {"text": "輝かない", "is_correct": false, "explanation": "「輝かないように」は戸の音の話として意味が通らず、空所に入らない。"}], "explanations": {"軋まない": "「戸が軋まないように」は、音を立てないようにする意味で自然に入る。", "咲かない": "戸は咲かないので、「咲かないように」は成り立たない。", "香らない": "戸は香るものではなく、空所に入らない。", "輝かない": "「輝かないように」は戸の音の話として意味が通らず、空所に入らない。"}, "sentence_index": 6, "correct_answer": "軋まない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空がぎゅっと軋んだ瞬間、雨が降った。", "explanation": "ここは〈曇る〉の意味。軋むは硬いもの同士が擦れて出す音で、空の様子を表す語ではない。"}, {"text": "ケーキがぎゅっと軋んだ瞬間、みんな笑った。", "explanation": "ここは〈潰れる〉の意味。軋むは音を出す語で、柔らかい菓子が形を失うことは表さない。"}, {"text": "スマホがぎゅっと軋んだ瞬間、画面が消えた。", "explanation": "ここは〈止まる〉の意味。軋むは音を表す語で、機器の動きが止まることは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51623, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベッドは、寝返りを打つたびに軋むで、眠れない。", "corrected_sentence": "ベッドは、寝返りを打つたびに軋んで、眠れない。", "error_description": "「軋むで」は誤った接続。て形の「軋んで」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "軋む", "is_correct": true, "explanation": "「軋む音」は連体形で、音を修飾する形として正しい。"}, {"text": "軋んで", "is_correct": false, "explanation": "て形は名詞の直前に置けず、「軋んで音が」は成り立たない。"}, {"text": "軋まない", "is_correct": false, "explanation": "否定形では、音が出ているという内容と合わない。"}, {"text": "軋み", "is_correct": false, "explanation": "名詞形では連体修飾の形にならず、「軋む音」の文脈に合わない。"}], "correct_form": "軋む", "base_form": "軋む", "form_label": "連体形", "sentence_index": 1, "explanations": {"軋む": "「軋む音」は連体形で、音を修飾する形として正しい。", "軋んで": "て形は名詞の直前に置けず、「軋んで音が」は成り立たない。", "軋まない": "否定形では、音が出ているという内容と合わない。", "軋み": "名詞形では連体修飾の形にならず、「軋む音」の文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51623, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "床に軋むので、そっと歩いた。", "corrected_sentence": "床が軋むので、そっと歩いた。", "error_description": "「軋む」の主語は「床が」。「床に」は位置を示し、軋む主体として誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "軋む", "is_correct": true, "explanation": "「座るたびに軋む」は終止形で、文の述語として正しい。"}, {"text": "軋んで", "is_correct": false, "explanation": "て形では文を言い切れず、「座るたびに軋んで。」では文が終わらない。"}, {"text": "軋まなかった", "is_correct": false, "explanation": "否定の過去形では、座るたびに音が出るという習慣的な内容と合わず、音が出なかったという意味になる。"}, {"text": "軋まなく", "is_correct": false, "explanation": "連用形は文の述語にならず、「座るたびに軋まなく。」は文が成り立たない。"}], "correct_form": "軋む", "base_form": "軋む", "form_label": "終止形", "sentence_index": 7, "explanations": {"軋む": "「座るたびに軋む」は終止形で、文の述語として正しい。", "軋んで": "て形では文を言い切れず、「座るたびに軋んで。」では文が終わらない。", "軋まなかった": "否定の過去形では、座るたびに音が出るという習慣的な内容と合わず、音が出なかったという意味になる。", "軋まなく": "連用形は文の述語にならず、「座るたびに軋まなく。」は文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51625, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ノブに手をかける」で、手をかける目標を示すので「に」が合う。"}, {"text": "が", "is_correct": false, "explanation": "「ノブが手をかけた」では、ノブが手をかける主体になり意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「手を」が既にあるため、ノブにも「を」を付けると二重になり不自然。"}, {"text": "と", "is_correct": false, "explanation": "「ノブと手をかけた」は、ノブと手を並べる意味になり文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「ノブに手をかける」で、手をかける目標を示すので「に」が合う。", "が": "「ノブが手をかけた」では、ノブが手をかける主体になり意味が通らない。", "を": "「手を」が既にあるため、ノブにも「を」を付けると二重になり不自然。", "と": "「ノブと手をかけた」は、ノブと手を並べる意味になり文が成り立たない。"}, "error_tags": {"が": "主語の誤り", "を": "目的語の二重", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51625, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51625, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ドアを開けるときに、手で回す取っ手のことだよ。", "primary_collocate": null, "pronunciation": "のぶ", "ipa": "nobɯ", "syllable_count": 2, "sentences": [{"text": "ドアのノブを回して、中に入った。", "target_word": "ノブ", "complexity_tier": "T2", "furigana": "ドアのノブを回[まわ]して、中[なか]に入[はい]った。", "sentence_source": "generated"}, {"text": "外から帰ってきて、玄関のノブに手をかけた。", "target_word": "ノブ", "complexity_tier": "T2", "furigana": "外[そと]から帰[かえ]ってきて、玄関[げんかん]のノブに手[て]をかけた。", "sentence_source": "generated"}, {"text": "ノブが壊れて、トイレから出られなくなった。", "target_word": "ノブ", "complexity_tier": "T2", "furigana": "ノブが壊[こわ]れて、トイレから出[で]られなくなった。", "sentence_source": "generated"}, {"text": "子どもの手が届かない高さに、ノブがついている。", "target_word": "ノブ", "complexity_tier": "T3", "furigana": "子[こ]どもの手[て]が届[とど]かない高[たか]さに、ノブがついている。", "sentence_source": "generated"}, {"text": "ノブを強く引いたが、ドアは開かなかった。", "target_word": "ノブ", "complexity_tier": "T2", "furigana": "ノブを強[つよ]く引[ひ]いたが、ドアは開[あ]かなかった。", "sentence_source": "generated"}, {"text": "朝、ノブに触ったら静電気でぱちっとした。", "target_word": "ノブ", "complexity_tier": "T3", "furigana": "朝[あさ]、ノブに触[さわ]ったら静電気[せいでんき]でぱちっとした。", "sentence_source": "generated"}, {"text": "母は買い物袋をドアのノブにかけておいた。", "target_word": "ノブ", "complexity_tier": "T2", "furigana": "母[はは]は買い物袋[かいものぶくろ]をドアのノブにかけておいた。", "sentence_source": "generated"}, {"text": "古いドアのノブは、少しゆるんでガタガタする。", "target_word": "ノブ", "complexity_tier": "T3", "furigana": "古[ふる]いドアのノブは、少[すこ]しゆるんでガタガタする。", "sentence_source": "generated"}, {"text": "彼はノブを回したまま、しばらく動かなかった。", "target_word": "ノブ", "complexity_tier": "T3", "furigana": "彼[かれ]はノブを回[まわ]したまま、しばらく動[うご]かなかった。", "sentence_source": "generated"}, {"text": "白いノブがかわいくて、このドアが気に入った。", "target_word": "ノブ", "complexity_tier": "T3", "furigana": "白[しろ]いノブがかわいくて、このドアが気[き]に入[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ノブ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ドアを開けるときに手で握って回す、丸い取っ手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4171fa00-9184-4481-a2ec-a876e376ecb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51625, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ノブ", "is_correct": true, "explanation": "手で回して開ける取っ手なので、「ドアのノブを回して」に合う。"}, {"text": "表札", "is_correct": false, "explanation": "表札はドアに掲げる名札で、回して操作するものではないので合わない。"}, {"text": "枠", "is_correct": false, "explanation": "枠はドアを囲む骨組みで、回す部品ではないので合わない。"}, {"text": "覗き穴", "is_correct": false, "explanation": "覗き穴は外を見るための小さな穴で、回せる部品ではないので合わない。"}], "explanations": {"ノブ": "手で回して開ける取っ手なので、「ドアのノブを回して」に合う。", "表札": "表札はドアに掲げる名札で、回して操作するものではないので合わない。", "枠": "枠はドアを囲む骨組みで、回す部品ではないので合わない。", "覗き穴": "覗き穴は外を見るための小さな穴で、回せる部品ではないので合わない。"}, "sentence_index": 0, "correct_answer": "ノブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ピアノのノブを踏んで、音を響かせた。", "explanation": "ここは〈ペダル〉の意味。ノブは手で回す取っ手で、足で踏む部品には使わない。"}, {"text": "キーボードのノブを押して、文字を入力した。", "explanation": "ここは〈キー〉の意味。ノブは回す取っ手で、文字を入力するための押すキーには使わない。"}, {"text": "自転車のノブを握って、坂を下った。", "explanation": "ここは〈ハンドル〉の意味。ノブは開閉のための取っ手で、自転車の操舵部には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51625, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ノブ", "is_correct": true, "explanation": "取っ手に袋を掛けるのに合うので、「ドアのノブにかけておいた」に合う。"}, {"text": "影", "is_correct": false, "explanation": "影には袋を掛けられないので、文の意味が成り立たない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは掛けるものではないので、「かけておいた」に合わない。"}, {"text": "色", "is_correct": false, "explanation": "色に袋を掛けるのは意味をなさないので合わない。"}], "explanations": {"ノブ": "取っ手に袋を掛けるのに合うので、「ドアのノブにかけておいた」に合う。", "影": "影には袋を掛けられないので、文の意味が成り立たない。", "重さ": "重さは掛けるものではないので、「かけておいた」に合わない。", "色": "色に袋を掛けるのは意味をなさないので合わない。"}, "sentence_index": 6, "correct_answer": "ノブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関のノブを押すと、家の中で音が鳴った。", "explanation": "ここは〈チャイム〉の意味。ノブは回して開閉する取っ手で、音を鳴らすために押す装置には使わない。"}, {"text": "傘のノブを握って、雨の中を歩いた。", "explanation": "ここは〈持ち手〉の意味。傘の持ち手はノブとは言わず、開閉のための取っ手とは別物なので合わない。"}, {"text": "リモコンのノブを押して、テレビを消した。", "explanation": "ここは〈ボタン〉の意味（リモコン）。ノブは回す取っ手で、押すボタンのことではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51625, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアのノブで手を伸ばし、開けた。", "corrected_sentence": "ドアのノブに手を伸ばし、開けた。", "error_description": "「手を伸ばす」は目標を「に」で示す。ノブに「で」を付けたのが誤りで、正しくは「ノブに手を伸ばし」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51625, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ドアのノブを開いて、廊下へ出た。", "corrected_sentence": "ドアのノブを回して、廊下へ出た。", "error_description": "ノブに結ぶ動詞は「回す」。「開く」はドアなど開閉する対象に使うため、「ノブを開く」は不自然で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51626, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51626, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ノブを『標準』に合わせる」で、ノブが動作の対象なので「を」が合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」にすると、ノブが主語になり「合わせる」の対象が消えるので文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「ノブに」と「標準に」が重なり二重になるため不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すため、ノブを比べる意味にしかならず合わない。"}], "correct_answer": "を", "explanations": {"を": "「ノブを『標準』に合わせる」で、ノブが動作の対象なので「を」が合う。", "が": "「が」にすると、ノブが主語になり「合わせる」の対象が消えるので文が崩れる。", "に": "「ノブに」と「標準に」が重なり二重になるため不自然。", "より": "「より」は比較の基準を示すため、ノブを比べる意味にしかならず合わない。"}, "error_tags": {"が": "主語の誤り", "に": "合わせ先の重複", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51626, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ノブは、ドアや機械などを操作するために手で握る部分です。特に、回したり引いたりして開閉するための取っ手を指します。", "primary_collocate": null, "pronunciation": "のぶ", "ipa": "nobɯ", "syllable_count": 2, "sentences": [{"text": "私は遺産整理のために錆びついたノブに手をかけ、ゆっくりとそれを開けた。", "target_word": "ノブ", "complexity_tier": "T4", "furigana": "私[わたし]は遺産[いさん]整理[せいり]のために錆[さ]びついたノブに手[て]をかけ、ゆっくりとそれを開[あ]けた。", "sentence_source": "generated"}, {"text": "部屋に入ろうとしたが、ノブが回らなかった。", "target_word": "ノブ", "complexity_tier": "T2", "furigana": "部屋[へや]に入[はい]ろうとしたが、ノブが回[まわ]らなかった。", "sentence_source": "generated"}, {"text": "彼女はそっとノブを回して、ドアを開けた。", "target_word": "ノブ", "complexity_tier": "T2", "furigana": "彼女[かのじょ]はそっとノブを回[まわ]して、ドアを開[あ]けた。", "sentence_source": "generated"}, {"text": "冬は金属のノブが冷たくて、触るのがいやになる。", "target_word": "ノブ", "complexity_tier": "T3", "furigana": "冬[ふゆ]は金属[きんぞく]のノブが冷[つめ]たくて、触[さわ]るのがいやになる。", "sentence_source": "generated"}, {"text": "ラジオのノブを右に回すと、音が大きくなる。", "target_word": "ノブ", "complexity_tier": "T3", "furigana": "ラジオのノブを右[みぎ]に回[まわ]すと、音[おと]が大[おお]きくなる。", "sentence_source": "generated"}, {"text": "古い戸棚のノブが取れてしまったので、新しいものに替えた。", "target_word": "ノブ", "complexity_tier": "T3", "furigana": "古[ふる]い戸棚[とだな]のノブが取[と]れてしまったので、新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}, {"text": "鍵をかけ忘れたのか、ノブを引くとドアはすぐに開いた。", "target_word": "ノブ", "complexity_tier": "T3", "furigana": "鍵[かぎ]をかけ忘[わす]れたのか、ノブを引[ひ]くとドアはすぐに開[あ]いた。", "sentence_source": "generated"}, {"text": "洗濯機のノブを「標準」に合わせてから、スタートボタンを押した。", "target_word": "ノブ", "complexity_tier": "T4", "furigana": "洗濯機[せんたくき]のノブを「標準[ひょうじゅん]」に合[あ]わせてから、スタートボタンを押[お]した。", "sentence_source": "generated"}, {"text": "濡れた手でノブをつかんだら、滑って回せなかった。", "target_word": "ノブ", "complexity_tier": "T3", "furigana": "濡[ぬ]れた手[て]でノブをつかんだら、滑[すべ]って回[まわ]せなかった。", "sentence_source": "generated"}, {"text": "修理屋さんはノブのねじを締め直し、ぐらつきを直してくれた。", "target_word": "ノブ", "complexity_tier": "T4", "furigana": "修理屋[しゅうりや]さんはノブのねじを締[し]め直[なお]し、ぐらつきを直[なお]してくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ノブ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ドアや戸棚・機械などについた、手で握って回したり引いたりする取っ手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: ぐらつき (Zipf 1.5)']::text[], '4171fa00-9184-4481-a2ec-a876e376ecb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51626, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ノブ", "is_correct": true, "explanation": "錆びつく金属の取っ手で、手をかけて開ける対象として合う。"}, {"text": "ため息", "is_correct": false, "explanation": "ため息は錆びつかず、手をかけて開けるものでもないので合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の現象で、錆びつくことも手をかけることもできないので合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は開けられるが、錆びついて手をかけるものではないので文脈に合わない。"}], "explanations": {"ノブ": "錆びつく金属の取っ手で、手をかけて開ける対象として合う。", "ため息": "ため息は錆びつかず、手をかけて開けるものでもないので合わない。", "夕焼け": "夕焼けは空の現象で、錆びつくことも手をかけることもできないので合わない。", "手紙": "手紙は開けられるが、錆びついて手をかけるものではないので文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ノブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エレベーターのノブを押して、三階へ行った。", "explanation": "ここは〈ボタン〉の意味。ノブは回して開閉する取っ手で、押して操作するエレベーターのボタンには使わない。"}, {"text": "コップのノブに指をかけた。", "explanation": "ここは〈取っ手〉の意味。コップの取っ手はノブとは言わず、回して開閉する部品ではないので合わない。"}, {"text": "インターホンのノブを押して、呼び出した。", "explanation": "ここは〈ブザー〉の意味。ノブは回す取っ手で、呼び出すために押す装置には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51626, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ノブ", "is_correct": true, "explanation": "引くとドアが開く取っ手なので、「ノブを引くと」に合う。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は引いて動かすものではなく、引いてもドアは開かないので合わない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋を引いてドアが開く関係は成り立たないので合わない。"}, {"text": "絵画", "is_correct": false, "explanation": "絵画を引いてもドアは開かないので、文の流れに合わない。"}], "explanations": {"ノブ": "引くとドアが開く取っ手なので、「ノブを引くと」に合う。", "花瓶": "花瓶は引いて動かすものではなく、引いてもドアは開かないので合わない。", "鍋": "鍋を引いてドアが開く関係は成り立たないので合わない。", "絵画": "絵画を引いてもドアは開かないので、文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "ノブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ビンのノブを抜いて、ワインを注いだ。", "explanation": "ここは〈栓〉の意味。ビンの栓は抜くもので、回して開閉する取っ手のノブとは言わない。"}, {"text": "鍵穴にノブを差し込んで、ドアを開けた。", "explanation": "ここは〈鍵〉の意味。鍵は差し込んで回す部品で、ノブは差し込むものではないので合わない。"}, {"text": "玄関のノブを押すと、家の中で音が鳴った。", "explanation": "ここは〈チャイム〉の意味。ノブは回して開閉する取っ手で、音を鳴らすために押す装置には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51626, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ノブが回して、倉庫の扉を開けた。", "corrected_sentence": "ノブを回して、倉庫の扉を開けた。", "error_description": "「回す」は目的語「ノブを」を取る他動詞。ノブに付く助詞が「が」になっているのが誤りで、正しくは「ノブを回して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51626, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ノブを回るとドアが開いた。", "corrected_sentence": "ノブを回すとドアが開いた。", "error_description": "「ノブを」と結ぶ他動詞は「回す」。自動詞「回る」は目的語を取れないため、「回る」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51627, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「鍵」が主語となり、錆びて動かなくなる主体を示すので正解。"}, {"text": "を", "is_correct": false, "explanation": "「錆び付く」は自動詞なので目的語の「を」は取れず、「鍵を錆び付いて」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、鍵の状態を主語として述べる位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「鍵で錆び付く」は不自然で状態の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「鍵」が主語となり、錆びて動かなくなる主体を示すので正解。", "を": "「錆び付く」は自動詞なので目的語の「を」は取れず、「鍵を錆び付いて」は成り立たない。", "に": "「に」は場所や相手を示すが、鍵の状態を主語として述べる位置には合わない。", "で": "「で」は手段や場所を示すが、「鍵で錆び付く」は不自然で状態の主語にならない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51627, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51627, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "さびて、うごかなくなること。", "primary_collocate": null, "pronunciation": "さびつく", "ipa": "sabitsɯkɯ", "syllable_count": 4, "sentences": [{"text": "長い間使わなかった自転車のチェーンが、錆び付いて動かない。", "target_word": "錆び付いて", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]使[つか]わなかった自転車[じてんしゃ]のチェーンが、錆[さ]び付[つ]いて動[うご]かない。", "sentence_source": "generated"}, {"text": "雨にぬれた鍵が錆び付いて、回らなくなった。", "target_word": "錆び付いて", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれた鍵[かぎ]が錆[さ]び付[つ]いて、回[まわ]らなくなった。", "sentence_source": "generated"}, {"text": "古い門の扉は錆び付いていて、押してもびくともしない。", "target_word": "錆び付いて", "complexity_tier": "T3", "furigana": "古[ふる]い門[もん]の扉[とびら]は錆[さ]び付[つ]いていて、押[お]してもびくともしない。", "sentence_source": "generated"}, {"text": "倉庫のはさみが錆び付き、紙が切れなくなった。", "target_word": "錆び付き", "complexity_tier": "T3", "furigana": "倉庫[そうこ]のはさみが錆[さ]び付[つ]き、紙[かみ]が切[き]れなくなった。", "sentence_source": "generated"}, {"text": "海の近くでは、機械が錆び付きやすい。", "target_word": "錆び付き", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くでは、機械[きかい]が錆[さ]び付[つ]きやすい。", "sentence_source": "generated"}, {"text": "錆び付いた歯車は、油をさしても動かなかった。", "target_word": "錆び付いた", "complexity_tier": "T3", "furigana": "錆[さ]び付[つ]いた歯車[はぐるま]は、油[あぶら]をさしても動[うご]かなかった。", "sentence_source": "generated"}, {"text": "何年も放っておいたので、ネジが錆び付いてしまった。", "target_word": "錆び付いて", "complexity_tier": "T3", "furigana": "何年[なんねん]も放[ほう]っておいたので、ネジが錆[さ]び付[つ]いてしまった。", "sentence_source": "generated"}, {"text": "錆び付いたブランコは、もう揺れなくなった。", "target_word": "錆び付いた", "complexity_tier": "T3", "furigana": "錆[さ]び付[つ]いたブランコは、もう揺[ゆ]れなくなった。", "sentence_source": "generated"}, {"text": "水がたまると、エンジンが錆び付くことがある。", "target_word": "錆び付く", "complexity_tier": "T3", "furigana": "水[みず]がたまると、エンジンが錆[さ]び付[つ]くことがある。", "sentence_source": "generated"}, {"text": "海風のせいで、窓のわくが錆び付いて開かなくなった。", "target_word": "錆び付いて", "complexity_tier": "T3", "furigana": "海風[うみかぜ]のせいで、窓[まど]のわくが錆[さ]び付[つ]いて開[あ]かなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "錆び付く", "label": "辞書形"}, {"form": "錆び付いた", "label": "過去形"}, {"form": "錆び付いて", "label": "て形"}, {"form": "錆び付かない", "label": "否定形"}, {"form": "錆び付き", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "鉄などがさびて、固まって動かなくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8f1722b-8f6a-484b-8e04-67ac74b730cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51627, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "錆び付いて", "is_correct": true, "explanation": "「錆びて固まり、動かなくなる」意味で、長く使わなかった自転車のチェーンが動かない状況に合う。"}, {"text": "光って", "is_correct": false, "explanation": "「光る」は輝く意味で、チェーンが動かない状態や原因を表せない。"}, {"text": "太って", "is_correct": false, "explanation": "「太る」は体重や体積が増えることで、動かなくなる状態を表せない。"}, {"text": "歌って", "is_correct": false, "explanation": "「歌う」は声を出す動作で、機械部品の状態には使えない。"}], "explanations": {"錆び付いて": "「錆びて固まり、動かなくなる」意味で、長く使わなかった自転車のチェーンが動かない状況に合う。", "光って": "「光る」は輝く意味で、チェーンが動かない状態や原因を表せない。", "太って": "「太る」は体重や体積が増えることで、動かなくなる状態を表せない。", "歌って": "「歌う」は声を出す動作で、機械部品の状態には使えない。"}, "sentence_index": 0, "correct_answer": "錆び付いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ペンキが錆び付いて、ふたが開かなくなった。", "explanation": "ここは〈固まる〉の意味。錆び付くは金属がさびることなので、ペンキには使わない。"}, {"text": "野菜が錆び付いて、捨てることになった。", "explanation": "ここは〈腐る〉の意味。錆び付くは金属のさびに使い、野菜の傷みには使わない。"}, {"text": "あの部屋には、タバコの臭いが錆び付いている。", "explanation": "ここは〈染み付く〉の意味。錆び付くは金属のさびを指し、臭いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51627, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "錆び付いて", "is_correct": true, "explanation": "金属がさびて固まり動かなくなった状況に合い、ネジが外れなくなった結果を表す。"}, {"text": "煮て", "is_correct": false, "explanation": "「煮る」は食材を加熱する意味で、ネジの状態には使えない。"}, {"text": "吠えて", "is_correct": false, "explanation": "「吠える」は動物が声を出す意味で、物の状態には合わない。"}, {"text": "寝て", "is_correct": false, "explanation": "「寝る」は眠る意味で、ネジの状態には使えない。"}], "explanations": {"錆び付いて": "金属がさびて固まり動かなくなった状況に合い、ネジが外れなくなった結果を表す。", "煮て": "「煮る」は食材を加熱する意味で、ネジの状態には使えない。", "吠えて": "「吠える」は動物が声を出す意味で、物の状態には合わない。", "寝て": "「寝る」は眠る意味で、ネジの状態には使えない。"}, "sentence_index": 6, "correct_answer": "錆び付いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湖が錆び付いて、船が動けなくなった。", "explanation": "ここは〈凍る〉の意味。錆び付くは金属のさびを指し、水が固まる変化には使わない。"}, {"text": "この服は色が錆び付いてしまった。", "explanation": "ここは〈褪せる〉の意味。錆び付くは金属のさびを指し、布の色あせには使えない。"}, {"text": "お気に入りの陶器の皿が錆び付いて、使えなくなった。", "explanation": "ここは〈割れる〉の意味。錆び付くは金属がさびることを指し、陶器が壊れる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51627, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアの蝶番が錆び付きて、開かなくなった。", "corrected_sentence": "ドアの蝶番が錆び付いて、開かなくなった。", "error_description": "「錆び付く」のて形は「錆び付いて」。「錆び付きて」は誤った活用形で、正しくは「錆び付いて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "錆び付いて", "is_correct": true, "explanation": "て形。「〜て、回らなくなった」と原因と結果をつなぐので合う。"}, {"text": "錆び付く", "is_correct": false, "explanation": "辞書形は「、」の前で文を続けられず、「錆び付く、回らなくなった」は不自然。"}, {"text": "錆び付いた", "is_correct": false, "explanation": "過去の連体形で名詞を修飾するため、「、回らなくなった」と続けられない。"}, {"text": "錆び付かない", "is_correct": false, "explanation": "否定形で錆びていないという意味になり、回らなくなった結果と矛盾する。"}], "correct_form": "錆び付いて", "base_form": "錆び付く", "form_label": "て形", "sentence_index": 1, "explanations": {"錆び付いて": "て形。「〜て、回らなくなった」と原因と結果をつなぐので合う。", "錆び付く": "辞書形は「、」の前で文を続けられず、「錆び付く、回らなくなった」は不自然。", "錆び付いた": "過去の連体形で名詞を修飾するため、「、回らなくなった」と続けられない。", "錆び付かない": "否定形で錆びていないという意味になり、回らなくなった結果と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51627, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍵を錆び付いて、回らない。", "corrected_sentence": "鍵が錆び付いて、回らない。", "error_description": "「錆び付く」は自動詞なので、主語には「が」を使う。「鍵を」の「を」は目的語を示すもので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "錆び付いた", "is_correct": true, "explanation": "過去の連体形で、後ろの「ブランコ」を修飾しており文に合う。"}, {"text": "錆び付いて", "is_correct": false, "explanation": "て形で名詞を修飾できず、「ブランコは」に続かない。"}, {"text": "錆び付き", "is_correct": false, "explanation": "連用形で名詞を修飾できず、「ブランコは」と続けられない。"}, {"text": "錆び付かず", "is_correct": false, "explanation": "否定の連用形で名詞を修飾できず、錆びていないという意味も結果と矛盾する。"}], "correct_form": "錆び付いた", "base_form": "錆び付く", "form_label": "過去の連体形", "sentence_index": 7, "explanations": {"錆び付いた": "過去の連体形で、後ろの「ブランコ」を修飾しており文に合う。", "錆び付いて": "て形で名詞を修飾できず、「ブランコは」に続かない。", "錆び付き": "連用形で名詞を修飾できず、「ブランコは」と続けられない。", "錆び付かず": "否定の連用形で名詞を修飾できず、錆びていないという意味も結果と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51633, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「入れる」の対象を示す。「シナモンを入れると」が自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、「シナモンが入れると」は入れる対象が消えてしまう。"}, {"text": "で", "is_correct": false, "explanation": "手段を示し、「シナモンで入れると」は道具の意味になり不自然。"}, {"text": "の", "is_correct": false, "explanation": "名詞修飾になり、「シナモンの入れると」は文が続かない。"}], "correct_answer": "を", "explanations": {"を": "「入れる」の対象を示す。「シナモンを入れると」が自然な文になる。", "が": "主語を示すため、「シナモンが入れると」は入れる対象が消えてしまう。", "で": "手段を示し、「シナモンで入れると」は道具の意味になり不自然。", "の": "名詞修飾になり、「シナモンの入れると」は文が続かない。"}, "error_tags": {"が": "主格", "で": "手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51633, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「入れる」の対象を示す。「シナモンを一本入れて」が自然な文になる。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を示し、「牛乳よりシナモン入れて」は動詞の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「シナモンへ入れて」は入れる対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示し、「シナモンから入れて」は入れる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「入れる」の対象を示す。「シナモンを一本入れて」が自然な文になる。", "より": "比較や起点を示し、「牛乳よりシナモン入れて」は動詞の対象を示せない。", "へ": "方向を示すため、「シナモンへ入れて」は入れる対象にならない。", "から": "起点を示し、「シナモンから入れて」は入れる対象を示せない。"}, "error_tags": {"より": "比較・起点", "へ": "方向", "から": "起点・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51633, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "スパイスの一種で、甘くて温かい香りがする粉のことです。", "primary_collocate": null, "pronunciation": "しなもん", "ipa": "ɕinamoɴ", "syllable_count": 4, "sentences": [{"text": "白いトーストの上に、茶色いシナモンをふりかけた。", "target_word": "シナモン", "complexity_tier": "T2", "furigana": "白[しろ]いトーストの上[うえ]に、茶色[ちゃいろ]いシナモンをふりかけた。", "sentence_source": "generated"}, {"text": "コーヒーにシナモンを入れると、甘い香りが広がる。", "target_word": "シナモン", "complexity_tier": "T2", "furigana": "コーヒーにシナモンを入[い]れると、甘[あま]い香[かお]りが広[ひろ]がる。", "sentence_source": "generated"}, {"text": "棚の奥に、古いシナモンの瓶が一本だけ残っていた。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "棚[たな]の奥[おく]に、古[ふる]いシナモンの瓶[びん]が一本[いっぽん]だけ残[のこ]っていた。", "sentence_source": "generated"}, {"text": "シナモンは粉になっているものが売られていて、使いやすい。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "シナモンは粉[こな]になっているものが売[う]られていて、使[つか]いやすい。", "sentence_source": "generated"}, {"text": "姉はアップルパイを焼くとき、必ずシナモンを加える。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "姉[あね]はアップルパイを焼[や]くとき、必[かなら]ずシナモンを加[くわ]える。", "sentence_source": "generated"}, {"text": "スプーン一杯のシナモンを入れただけで、スープの味が変わった。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "スプーン一杯[いっぱい]のシナモンを入[い]れただけで、スープの味[あじ]が変[か]わった。", "sentence_source": "generated"}, {"text": "シナモンの粉を吸い込んで、思わずせきが出てしまった。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "シナモンの粉[こな]を吸[す]い込[こ]んで、思[おも]わずせきが出[で]てしまった。", "sentence_source": "generated"}, {"text": "子どもの頃、牛乳にシナモンを入れて飲むのが好きだった。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "子[こ]どもの頃[ころ]、牛乳[ぎゅうにゅう]にシナモンを入[い]れて飲[の]むのが好[す]きだった。", "sentence_source": "generated"}, {"text": "このお茶はシナモンが強すぎて、私には少し飲みにくい。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "このお茶[ちゃ]はシナモンが強[つよ]すぎて、私[わたし]には少[すこ]し飲[の]みにくい。", "sentence_source": "generated"}, {"text": "パン屋のおじさんは生地にシナモンを混ぜて、丁寧に丸めていた。", "target_word": "シナモン", "complexity_tier": "T4", "furigana": "パン屋[や]のおじさんは生地[きじ]にシナモンを混[ま]ぜて、丁寧[ていねい]に丸[まる]めていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シナモン", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "粉状にして使う香辛料のシナモン。甘くて温かい香りの粉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51633, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シナモン", "is_correct": true, "explanation": "粉状の香辛料で、トーストにふりかけるものとして文に合う。"}, {"text": "段ボール", "is_correct": false, "explanation": "紙の素材で、食べ物にふりかける対象ではない。"}, {"text": "ハンドル", "is_correct": false, "explanation": "自転車などの部品で、食べ物にふりかけることはできない。"}, {"text": "紅葉", "is_correct": false, "explanation": "樹木の色づいた葉で、ふりかけることはできない。"}], "explanations": {"シナモン": "粉状の香辛料で、トーストにふりかけるものとして文に合う。", "段ボール": "紙の素材で、食べ物にふりかける対象ではない。", "ハンドル": "自転車などの部品で、食べ物にふりかけることはできない。", "紅葉": "樹木の色づいた葉で、ふりかけることはできない。"}, "sentence_index": 0, "correct_answer": "シナモン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "シナモンは水で溶いて鍋に少しずつ入れると、とろみがつく。", "explanation": "〈片栗粉〉の働き（とろみをつける）。シナモンはとろみを生まないので誤り。"}, {"text": "シナモンはお湯で点てて、茶碗に注いで飲む。", "explanation": "〈抹茶〉の使い方（点てて飲む）。シナモンは点てて飲むものではないので合わない。"}, {"text": "シナモンを練ると、グルテンができて生地が伸びる。", "explanation": "〈小麦粉〉の性質（練るとグルテンができる）。シナモンにはグルテンがないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51633, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シナモン", "is_correct": true, "explanation": "香辛料の粉で、吸い込むとせきが出る文脈に合う。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "布製品で、粉の名前として使われない。"}, {"text": "電池", "is_correct": false, "explanation": "電気を蓄える部品で、吸い込む粉にはならない。"}, {"text": "夜空", "is_correct": false, "explanation": "空の様子を表し、吸い込む粉の名前にはならない。"}], "explanations": {"シナモン": "香辛料の粉で、吸い込むとせきが出る文脈に合う。", "ハンカチ": "布製品で、粉の名前として使われない。", "電池": "電気を蓄える部品で、吸い込む粉にはならない。", "夜空": "空の様子を表し、吸い込む粉の名前にはならない。"}, "sentence_index": 6, "correct_answer": "シナモン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "シナモンは火にかけて溶かすと、カラメルになる。", "explanation": "〈砂糖〉の性質（溶かすとカラメルになる）。シナモンは糖ではないので、この変化は起こらない。"}, {"text": "シナモンで生地がふくらんで、ケーキが大きくなった。", "explanation": "〈ベーキングパウダー〉の働き（膨張させる）。シナモンは生地を膨らませないので誤り。"}, {"text": "シナモンは水で戻すと、肉厚な傘が開いて弾力が出る。", "explanation": "〈干し椎茸〉の性質（水で戻すと肉厚になる）。シナモンは水で戻しても肉厚にならないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51633, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ヨーグルトに、シナモンにふりかけた。", "corrected_sentence": "ヨーグルトに、シナモンをふりかけた。", "error_description": "「ふりかける」は〈を〉で目的語を取る。〈に〉は誤りで、正しくは〈を〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51633, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ホットケーキの生地に、シナモンが少し混ぜた。", "corrected_sentence": "ホットケーキの生地に、シナモンを少し混ぜた。", "error_description": "「混ぜる」は他動詞で、対象に〈を〉を取る。〈が〉では主語になり、混ぜる対象が示せない。誤りは〈が〉、正しくは〈を〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51634, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ふりかける」の対象を示す。「シナモンを」が目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "主格を示すため、「シナモンがふりかけた」となり、かける対象が消える。"}, {"text": "で", "is_correct": false, "explanation": "手段の意味になり、「シナモンでふりかける」は道具を使う不自然な言い方になる。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を示し、「シナモンとふりかける」は文として成立しない。"}], "correct_answer": "を", "explanations": {"を": "「ふりかける」の対象を示す。「シナモンを」が目的語になる。", "が": "主格を示すため、「シナモンがふりかけた」となり、かける対象が消える。", "で": "手段の意味になり、「シナモンでふりかける」は道具を使う不自然な言い方になる。", "と": "共同や引用を示し、「シナモンとふりかける」は文として成立しない。"}, "error_tags": {"が": "主格", "で": "手段", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51634, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「入れる」の対象を示す。「シナモンを一本入れて」が自然な文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「シナモンへ一本入れて」は入れる対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を示し、「シナモンより一本入れて」は文が続かない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する形で、「シナモンの一本入れて」は動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「入れる」の対象を示す。「シナモンを一本入れて」が自然な文になる。", "へ": "方向を示すため、「シナモンへ一本入れて」は入れる対象にならない。", "より": "比較や起点を示し、「シナモンより一本入れて」は文が続かない。", "の": "名詞を修飾する形で、「シナモンの一本入れて」は動詞の目的語にならない。"}, "error_tags": {"へ": "方向", "より": "比較・起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51634, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "料理やお菓子に使われる、甘くて少し辛い香りのあるスパイス。", "primary_collocate": null, "pronunciation": "しなもん", "ipa": "ɕinamoɴ", "syllable_count": 4, "sentences": [{"text": "軋む音とともに、懐かしいシナモンの匂いが記憶の奥から鮮やかに蘇り、私は思わず息を呑んだ。", "target_word": "シナモン", "complexity_tier": "T4", "furigana": "軋[きし]む音[おと]とともに、懐[なつ]かしいシナモンの匂[にお]いが記憶[きおく]の奥[おく]から鮮[あざ]やかに蘇[よみがえ]り、私[わたし]は思[おも]わず息[いき]を呑[の]んだ。", "sentence_source": "mined"}, {"text": "朝ごはんに、焼いたリンゴにシナモンをかけて食べた。", "target_word": "シナモン", "complexity_tier": "T2", "furigana": "朝[あさ]ごはんに、焼[や]いたリンゴにシナモンをかけて食[た]べた。", "sentence_source": "generated"}, {"text": "このパンにはシナモンが入っているので、とても甘い香りがする。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "このパンにはシナモンが入[はい]っているので、とても甘[あま]い香[かお]りがする。", "sentence_source": "generated"}, {"text": "シナモンはお菓子だけでなく、カレーの隠し味にも使われる。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "シナモンはお菓子[かし]だけでなく、カレーの隠[かく]し味[あじ]にも使[つか]われる。", "sentence_source": "generated"}, {"text": "紅茶にシナモンを少し入れると、体が温まる。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "紅茶[こうちゃ]にシナモンを少[すこ]し入[い]れると、体[からだ]が温[あたた]まる。", "sentence_source": "generated"}, {"text": "母が焼いたクッキーは、シナモンの香りがして、懐かしい味だった。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "母[はは]が焼[や]いたクッキーは、シナモンの香[かお]りがして、懐[なつ]かしい味[あじ]だった。", "sentence_source": "generated"}, {"text": "店の前を通ると、シナモンの甘い匂いが漂ってきて、思わず足を止めた。", "target_word": "シナモン", "complexity_tier": "T4", "furigana": "店[みせ]の前[まえ]を通[とお]ると、シナモンの甘[あま]い匂[にお]いが漂[ただよ]ってきて、思[おも]わず足[あし]を止[と]めた。", "sentence_source": "generated"}, {"text": "寒い夜、ホットワインにシナモンを一本入れて、ゆっくり飲んだ。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "寒[さむ]い夜[よる]、ホットワインにシナモンを一本[いっぽん]入[い]れて、ゆっくり飲[の]んだ。", "sentence_source": "generated"}, {"text": "シナモンは木の皮から作られるスパイスで、独特の甘い香りと少し辛い味がある。", "target_word": "シナモン", "complexity_tier": "T4", "furigana": "シナモンは木[き]の皮[かわ]から作[つく]られるスパイスで、独特[どくとく]の甘[あま]い香[かお]りと少[すこ]し辛[から]い味[あじ]がある。", "sentence_source": "generated"}, {"text": "シナモンが苦手な人のために、ケーキには入れずに別の皿に出した。", "target_word": "シナモン", "complexity_tier": "T3", "furigana": "シナモンが苦手[にがて]な人[ひと]のために、ケーキには入[い]れずに別[べつ]の皿[さら]に出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シナモン", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "香辛料のシナモン。甘くて少し辛い香りを持つスパイス", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51634, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シナモン", "is_correct": true, "explanation": "「懐かしい〇〇の匂い」に入る香りのあるスパイス。文の「匂い」と一致する。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさを表す語で、匂いの元にはならない。"}, {"text": "締切", "is_correct": false, "explanation": "期限を表す語で、匂いを出さないので合わない。"}, {"text": "計算", "is_correct": false, "explanation": "数や式を処理する行為で、匂いの原因にはならない。"}], "explanations": {"シナモン": "「懐かしい〇〇の匂い」に入る香りのあるスパイス。文の「匂い」と一致する。", "音量": "音の大きさを表す語で、匂いの元にはならない。", "締切": "期限を表す語で、匂いを出さないので合わない。", "計算": "数や式を処理する行為で、匂いの原因にはならない。"}, "sentence_index": 0, "correct_answer": "シナモン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "肉料理には、シナモンを一粒だけ入れると香りが強すぎない。", "explanation": "ここは〈クローブ〉の使い方。シナモンは棒状や粉で量り、一粒と数えないので誤り。"}, {"text": "シナモンは、噛むとスーッと冷たさが鼻に抜ける。", "explanation": "〈ミント〉の清涼感（スーッと冷たさが抜ける）。シナモンは温かい香りで、冷たさは感じないので合わない。"}, {"text": "シナモンは根を薄く切って、お湯に入れて煮出す。", "explanation": "〈生姜〉の使い方（根を薄く切る）。シナモンは樹皮なので、根を切って使うとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51634, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シナモン", "is_correct": true, "explanation": "「店の前の甘い匂い」に入る、甘い香りのスパイス。文の意味に合う。"}, {"text": "警報", "is_correct": false, "explanation": "危険を知らせる音で、甘い匂いとは結びつかない。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場で、匂いを出すものではない。"}, {"text": "保険", "is_correct": false, "explanation": "契約の仕組みで、香りとは関係しない。"}], "explanations": {"シナモン": "「店の前の甘い匂い」に入る、甘い香りのスパイス。文の意味に合う。", "警報": "危険を知らせる音で、甘い匂いとは結びつかない。", "会議": "話し合いの場で、匂いを出すものではない。", "保険": "契約の仕組みで、香りとは関係しない。"}, "sentence_index": 6, "correct_answer": "シナモン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "シナモンは鞘を縦に割って、中の種をかき出す。", "explanation": "〈バニラ〉の処理法（鞘から種をかき出す）。シナモンは樹皮なので、この作業は当てはまらない。"}, {"text": "シナモンは湯せんで溶かしてから型に流す。", "explanation": "〈チョコレート〉の性質（溶かして型に流す）。シナモンは溶けて固まる性質がないので、この操作は合わない。"}, {"text": "シナモンは莢を割って、中の種を粒のまま使う。", "explanation": "〈カルダモン〉の使い方（莢の中の種を使う）。シナモンには莢も種もないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51634, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ホットミルクにシナモンでふりかけて飲んだ。", "corrected_sentence": "ホットミルクにシナモンをふりかけて飲んだ。", "error_description": "「ふりかける」は目的語に〈を〉を取る。〈で〉は手段の意味になり、ここでは文が成立しない。誤りは〈で〉で、正しくは〈を〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51634, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ヨーグルトにシナモンを混ぜ食べた。", "corrected_sentence": "ヨーグルトにシナモンを混ぜて食べた。", "error_description": "「混ぜて食べた」の〈混ぜて〉は〜て形が必要。〈混ぜ食べた〉は動詞の続け方が成立しない。誤りは〈混ぜ〉、正しくは〈混ぜて〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
