INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51635, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「息を止める」の目的語を示す。止める対象として自然。"}, {"text": "に", "is_correct": false, "explanation": "帰着や対象を示し、「息に止めた」は止める動作の目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を示し、「息と止めた」は文が成立しない。"}, {"text": "が", "is_correct": false, "explanation": "主格を示し、「息が止めた」では主語になって止める対象が消える。"}], "correct_answer": "を", "explanations": {"を": "「息を止める」の目的語を示す。止める対象として自然。", "に": "帰着や対象を示し、「息に止めた」は止める動作の目的語にならない。", "と": "共同や引用を示し、「息と止めた」は文が成立しない。", "が": "主格を示し、「息が止めた」では主語になって止める対象が消える。"}, "error_tags": {"に": "帰着・対象", "と": "共同・引用", "が": "主格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51635, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "空気を体の中に入れたり、出したりすること。", "primary_collocate": null, "pronunciation": "いき", "ipa": "iki", "syllable_count": 2, "sentences": [{"text": "医者に言われて、ゆっくり息を吸ったり吐いたりした。", "target_word": "息", "complexity_tier": "T3", "furigana": "医者[いしゃ]に言[い]われて、ゆっくり息[いき]を吸[す]ったり吐[は]いたりした。", "sentence_source": "generated"}, {"text": "水泳では、顔を上げて息をするタイミングが大切だ。", "target_word": "息", "complexity_tier": "T3", "furigana": "水泳[すいえい]では、顔[かお]を上[あ]げて息[いき]をするタイミングが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "眠っている赤ちゃんの息が、静かに聞こえる。", "target_word": "息", "complexity_tier": "T2", "furigana": "眠[ねむ]っている赤[あか]ちゃんの息[いき]が、静[しず]かに聞[き]こえる。", "sentence_source": "generated"}, {"text": "煙の中では、口を押さえて息をしないようにした。", "target_word": "息", "complexity_tier": "T3", "furigana": "煙[けむり]の中[なか]では、口[くち]を押[お]さえて息[いき]をしないようにした。", "sentence_source": "generated"}, {"text": "マラソンの後半は、息が上がって足も重くなった。", "target_word": "息", "complexity_tier": "T3", "furigana": "マラソンの後半[こうはん]は、息[いき]が上[あ]がって足[あし]も重[おも]くなった。", "sentence_source": "generated"}, {"text": "彼は大きく息を吐いて、椅子に座り込んだ。", "target_word": "息", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]きく息[いき]を吐[は]いて、椅子[いす]に座[すわ]り込[こ]んだ。", "sentence_source": "generated"}, {"text": "風邪をひいて鼻が詰まり、息がしにくい。", "target_word": "息", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいて鼻[はな]が詰[つ]まり、息[いき]がしにくい。", "sentence_source": "generated"}, {"text": "先生の合図で、みんな一度息を止めた。", "target_word": "息", "complexity_tier": "T2", "furigana": "先生[せんせい]の合図[あいず]で、みんな一度[いちど]息[いき]を止[と]めた。", "sentence_source": "generated"}, {"text": "歌う前に息を整えると、声が安定する。", "target_word": "息", "complexity_tier": "T3", "furigana": "歌[うた]う前[まえ]に息[いき]を整[ととの]えると、声[こえ]が安定[あんてい]する。", "sentence_source": "generated"}, {"text": "冬の夜道では、自分の息の音しか聞こえなかった。", "target_word": "息", "complexity_tier": "T3", "furigana": "冬[ふゆ]の夜道[よみち]では、自分[じぶん]の息[いき]の音[おと]しか聞[き]こえなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "息", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "空気を出し入れする呼吸という動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51635, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "息", "is_correct": true, "explanation": "「息を吸ったり吐いたり」の対象で、呼吸の動作として自然。"}, {"text": "荷物", "is_correct": false, "explanation": "運ぶ物で、吸ったり吐いたりする対象にはならない。"}, {"text": "塩", "is_correct": false, "explanation": "調味料で、吸ったり吐いたりできるものではない。"}, {"text": "鍵", "is_correct": false, "explanation": "錠を開ける道具で、吸ったり吐いたりする対象にならない。"}], "explanations": {"息": "「息を吸ったり吐いたり」の対象で、呼吸の動作として自然。", "荷物": "運ぶ物で、吸ったり吐いたりする対象にはならない。", "塩": "調味料で、吸ったり吐いたりできるものではない。", "鍵": "錠を開ける道具で、吸ったり吐いたりする対象にならない。"}, "sentence_index": 0, "correct_answer": "息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の終わりに、彼は息を大きく投げて、観客を沸かせた。", "explanation": "〈ボール〉を投げる（投げる）の意味。息は物ではないので投げられず、ここでは合わない。"}, {"text": "彼は息子を大きく吸って、深く吐いた。", "explanation": "〈息子〉の意味。息子は吸ったり吐いたりする対象ではないので動作に合わない。"}, {"text": "マラソンのあと、額の息を手で拭った。", "explanation": "〈汗〉の意味（拭う）。息は拭えないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51635, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "息", "is_correct": true, "explanation": "「息がしにくい」の主語で、鼻が詰まったときの呼吸を表す。"}, {"text": "ドア", "is_correct": false, "explanation": "建具で、呼吸のしやすさを表す主語にはならない。"}, {"text": "名刺", "is_correct": false, "explanation": "紙製の名刺で、呼吸とは結びつかない。"}, {"text": "財布", "is_correct": false, "explanation": "持ち物で、呼吸のしやすさを表す主語にはならない。"}], "explanations": {"息": "「息がしにくい」の主語で、鼻が詰まったときの呼吸を表す。", "ドア": "建具で、呼吸のしやすさを表す主語にはならない。", "名刺": "紙製の名刺で、呼吸とは結びつかない。", "財布": "持ち物で、呼吸のしやすさを表す主語にはならない。"}, "sentence_index": 6, "correct_answer": "息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜、怖い息を見て、夜中に目が覚めた。", "explanation": "〈夢〉を見る（夢の内容）の意味。息は見るものではないので、ここでは合わない。"}, {"text": "悲しくて、息を流してしまった。", "explanation": "〈涙〉の意味（流す）。息は流せないので誤り。"}, {"text": "鼻が詰まったので、ティッシュで息をかんだ。", "explanation": "〈鼻をかむ〉の意味。息はかめないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51635, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休憩中に、ゆっくり息に整えた。", "corrected_sentence": "休憩中に、ゆっくり息を整えた。", "error_description": "〈整える〉は〈を〉で目的語を取る。〈に〉を使うと文が成立せず、誤りは〈に〉、正しくは〈を〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51635, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゆっくり息を止めるてから、数を数えた。", "corrected_sentence": "ゆっくり息を止めてから、数を数えた。", "error_description": "〈止める〉の〜て形は〈止めて〉。〈止めるて〉は活用が誤っていて、文として成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
