INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51636, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "呼吸によって、空気を肺に取り入れたり、吐き出したりする行為。また、その空気。", "primary_collocate": null, "pronunciation": "いき", "ipa": "iki", "syllable_count": 2, "sentences": [{"text": "軋む音とともに、懐かしいシナモンの匂いが記憶の奥から鮮やかに蘇り、私は思わず息を呑んだ。", "target_word": "息", "complexity_tier": "T4", "furigana": "軋[きし]む音[おと]とともに、懐[なつ]かしいシナモンの匂[にお]いが記憶[きおく]の奥[おく]から鮮[あざ]やかに蘇[よみがえ]り、私[わたし]は思[おも]わず息[いき]を呑[の]んだ。", "sentence_source": "mined"}, {"text": "寒い朝は、外に出ると息が白くなる。", "target_word": "息", "complexity_tier": "T2", "furigana": "寒[さむ]い朝[あさ]は、外[そと]に出[で]ると息[いき]が白[しろ]くなる。", "sentence_source": "generated"}, {"text": "階段を走って上ったので、息が切れてしまった。", "target_word": "息", "complexity_tier": "T3", "furigana": "階段[かいだん]を走[はし]って上[のぼ]ったので、息[いき]が切[き]れてしまった。", "sentence_source": "generated"}, {"text": "深く息を吸ってから、ゆっくり吐いてください。", "target_word": "息", "complexity_tier": "T2", "furigana": "深[ふか]く息[いき]を吸[す]ってから、ゆっくり吐[は]いてください。", "sentence_source": "generated"}, {"text": "水の中では、息を止めていられる時間が短い。", "target_word": "息", "complexity_tier": "T3", "furigana": "水[みず]の中[なか]では、息[いき]を止[と]めていられる時間[じかん]が短[みじか]い。", "sentence_source": "generated"}, {"text": "彼女は窓に息を吹きかけて、小さなハートを描いた。", "target_word": "息", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は窓[まど]に息[いき]を吹[ふ]きかけて、小[ちい]さなハートを描[えが]いた。", "sentence_source": "generated"}, {"text": "犬は走ったあと、舌を出して荒い息をしていた。", "target_word": "息", "complexity_tier": "T3", "furigana": "犬[いぬ]は走[はし]ったあと、舌[した]を出[だ]して荒[あら]い息[いき]をしていた。", "sentence_source": "generated"}, {"text": "緊張のせいで、本番の前に息が苦しくなった。", "target_word": "息", "complexity_tier": "T3", "furigana": "緊張[きんちょう]のせいで、本番[ほんばん]の前[まえ]に息[いき]が苦[くる]しくなった。", "sentence_source": "generated"}, {"text": "冷たい手に息をかけて温めながら、バスを待った。", "target_word": "息", "complexity_tier": "T3", "furigana": "冷[つめ]たい手[て]に息[いき]をかけて温[あたた]めながら、バスを待[ま]った。", "sentence_source": "generated"}, {"text": "山の頂上は空気が薄くて、息をするのも大変だった。", "target_word": "息", "complexity_tier": "T3", "furigana": "山[やま]の頂上[ちょうじょう]は空気[くうき]が薄[うす]くて、息[いき]をするのも大変[たいへん]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "息", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "呼吸で出入りする空気。吐く息・吸う息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 軋む (Zipf 2.32)']::text[], '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51636, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "息", "is_correct": true, "explanation": "「息を呑む」は驚いて息を止める表現で、文の意味に合う。"}, {"text": "財布", "is_correct": false, "explanation": "持ち物で、呑むことができるものではない。"}, {"text": "窓", "is_correct": false, "explanation": "建具で、呑むという動作の対象にならない。"}, {"text": "時計", "is_correct": false, "explanation": "計器で、呑むという動作の対象にならない。"}], "explanations": {"息": "「息を呑む」は驚いて息を止める表現で、文の意味に合う。", "財布": "持ち物で、呑むことができるものではない。", "窓": "建具で、呑むという動作の対象にならない。", "時計": "計器で、呑むという動作の対象にならない。"}, "sentence_index": 0, "correct_answer": "息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "焼き魚の息が部屋中に広がって、食欲をそそった。", "explanation": "〈匂い〉の意味（部屋に広がる）。焼き魚の香りは息とは言わず、息は呼吸や吐き出した空気の意味で使うので合わない。"}, {"text": "彼の息は今年から大学に通っている。", "explanation": "〈息子〉の意味。〈息〉は呼吸なので、人を指すことはできない。"}, {"text": "大きな声を出そうとして、息を張り上げて叫んだ。", "explanation": "〈声〉の意味（張り上げる）。息は声のように張り上げられないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51636, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "息", "is_correct": true, "explanation": "「荒い息をしていた」の形で、走ったあとの呼吸を表す。"}, {"text": "鍵", "is_correct": false, "explanation": "錠を開ける道具で、荒い呼吸とは結びつかない。"}, {"text": "鍋", "is_correct": false, "explanation": "調理器具で、荒いことはあっても呼吸の意味にならない。"}, {"text": "瓦", "is_correct": false, "explanation": "屋根材で、呼吸の様子を表せない。"}], "explanations": {"息": "「荒い息をしていた」の形で、走ったあとの呼吸を表す。", "鍵": "錠を開ける道具で、荒い呼吸とは結びつかない。", "鍋": "調理器具で、荒いことはあっても呼吸の意味にならない。", "瓦": "屋根材で、呼吸の様子を表せない。"}, "sentence_index": 6, "correct_answer": "息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は教室で、息を一つ言ってから出て行った。", "explanation": "〈言葉〉を言う（一言言う）の意味。息は言葉として言うことはできないので、ここでは合わない。"}, {"text": "暑い日、額の息を拭ってから、涼しい風に当たった。", "explanation": "〈汗〉の意味（拭う）。息は拭えないので誤り。"}, {"text": "映画の最後で、息を流して泣いた。", "explanation": "〈涙〉の意味（流す）。息は流せないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51636, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の上では、息を少し苦しくなる。", "corrected_sentence": "山の上では、息が少し苦しくなる。", "error_description": "〈苦しい〉の主語は〈息が〉の形になる。〈を〉を使うと文が成立しない。誤りは〈を〉、正しくは〈が〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51636, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大きく息を吸いて、気持ちを落ち着かせた。", "corrected_sentence": "大きく息を吸って、気持ちを落ち着かせた。", "error_description": "〈吸う〉の〜て形は〈吸って〉。〈吸いて〉は活用が誤っていて、文として成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51637, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51637, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語。花が元の状態に戻る文になり、自動詞の蘇ったに合う。"}, {"text": "に", "is_correct": false, "explanation": "帰着点。「花に蘇る」は不自然で、よみがえる主体の説明にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向。「花へ蘇る」は文の意味を成さない。"}, {"text": "より", "is_correct": false, "explanation": "比較。「花より蘇る」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "主語。花が元の状態に戻る文になり、自動詞の蘇ったに合う。", "に": "帰着点。「花に蘇る」は不自然で、よみがえる主体の説明にならない。", "へ": "方向。「花へ蘇る」は文の意味を成さない。", "より": "比較。「花より蘇る」は成り立たない。"}, "error_tags": {"に": "帰着点。「花に蘇る」は不自然で、よみがえる主体の説明にならない。", "へ": "方向。「花へ蘇る」は文の意味を成さない。", "より": "比較。「花より蘇る」は成り立たない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51637, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "わすれていたことや、なくなりかけていたものが、もういちどよみがえること。", "primary_collocate": null, "pronunciation": "よみがえる", "ipa": "jomiɡaeɾɯ", "syllable_count": 5, "sentences": [{"text": "長い間行われていなかった古い祭りが、町の人の努力で蘇った。", "target_word": "蘇った", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]行[おこな]われていなかった古[ふる]い祭[まつ]りが、町[まち]の人[ひと]の努力[どりょく]で蘇[よみがえ]った。", "sentence_source": "generated"}, {"text": "雨が降ると、枯れかけていた庭の草花が蘇る。", "target_word": "蘇る", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ると、枯[か]れかけていた庭[にわ]の草花[くさばな]が蘇[よみがえ]る。", "sentence_source": "generated"}, {"text": "保護活動によって、湖の自然が少しずつ蘇ってきた。", "target_word": "蘇ってきた", "complexity_tier": "T3", "furigana": "保護[ほご]活動[かつどう]によって、湖[みずうみ]の自然[しぜん]が少[すこ]しずつ蘇[よみがえ]ってきた。", "sentence_source": "generated"}, {"text": "一度は消えたと思われた伝統の味が、孫の手で蘇った。", "target_word": "蘇った", "complexity_tier": "T3", "furigana": "一度[いちど]は消[き]えたと思[おも]われた伝統[でんとう]の味[あじ]が、孫[まご]の手[て]で蘇[よみがえ]った。", "sentence_source": "generated"}, {"text": "春になって、冬の間眠っていた野山に命が蘇る。", "target_word": "蘇る", "complexity_tier": "T3", "furigana": "春[はる]になって、冬[ふゆ]の間[あいだ]眠[ねむ]っていた野山[のやま]に命[いのち]が蘇[よみがえ]る。", "sentence_source": "generated"}, {"text": "古い映画が修復され、当時の美しい映像が蘇った。", "target_word": "蘇った", "complexity_tier": "T3", "furigana": "古[ふる]い映画[えいが]が修復[しゅうふく]され、当時[とうじ]の美[うつく]しい映像[えいぞう]が蘇[よみがえ]った。", "sentence_source": "generated"}, {"text": "負けた後も練習を続けた結果、チームの強さが蘇った。", "target_word": "蘇った", "complexity_tier": "T3", "furigana": "負[ま]けた後[あと]も練習[れんしゅう]を続[つづ]けた結果[けっか]、チームの強[つよ]さが蘇[よみがえ]った。", "sentence_source": "generated"}, {"text": "水を与えたら、しおれていた花が見事に蘇った。", "target_word": "蘇った", "complexity_tier": "T3", "furigana": "水[みず]を与[あた]えたら、しおれていた花[はな]が見事[みごと]に蘇[よみがえ]った。", "sentence_source": "generated"}, {"text": "閉鎖された商店街に活気が蘇る日を、町の人々は待ち望んでいる。", "target_word": "蘇る", "complexity_tier": "T3", "furigana": "閉鎖[へいさ]された商店街[しょうてんがい]に活気[かっき]が蘇[よみがえ]る日[ひ]を、町[まち]の人々[ひとびと]は待[ま]ち望[のぞ]んでいる。", "sentence_source": "generated"}, {"text": "昔の技術が蘇れば、この町の産業も変わるかもしれない。", "target_word": "蘇れば", "complexity_tier": "T3", "furigana": "昔[むかし]の技術[ぎじゅつ]が蘇[よみがえ]れば、この町[まち]の産業[さんぎょう]も変[か]わるかもしれない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蘇る", "label": "終止形"}, {"form": "蘇らない", "label": "否定形"}, {"form": "蘇り", "label": "連用形"}, {"form": "蘇って", "label": "て形"}, {"form": "蘇った", "label": "過去形"}, {"form": "蘇れば", "label": "仮定形"}], "register": "普通体の書き言葉", "sense_fingerprint": "衰えたり消えかけたりしたものが元の状態に戻る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51637, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蘇った", "is_correct": true, "explanation": "祭りが努力の結果に元へ戻ったという過去の出来事を表し、文に合う。"}, {"text": "蘇って", "is_correct": false, "explanation": "て形で文を終えられず、述語として機能しない。"}, {"text": "蘇れ", "is_correct": false, "explanation": "命令形で、祭りが戻った経緯の説明にならない。"}, {"text": "蘇らせ", "is_correct": false, "explanation": "使役の連用形で、祭りが自ら戻ったという文に合わない。"}], "explanations": {"蘇った": "祭りが努力の結果に元へ戻ったという過去の出来事を表し、文に合う。", "蘇って": "て形で文を終えられず、述語として機能しない。", "蘇れ": "命令形で、祭りが戻った経緯の説明にならない。", "蘇らせ": "使役の連用形で、祭りが自ら戻ったという文に合わない。"}, "sentence_index": 0, "correct_answer": "蘇った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その村には一度も存在しなかった伝統が、突然蘇った。", "explanation": "ここは〈生まれる〉の意味。蘇るは一度なくなったものが戻ることなので、初めて生まれたものには使わない。"}, {"text": "夜空に一度も見たことのない新しい星が蘇った。", "explanation": "ここは〈出現する〉の意味。蘇るは一度衰えたり消えたりしたものが戻ることなので、初めて現れた星には使わない。"}, {"text": "田んぼの真ん中に、新しい体育館が蘇った。", "explanation": "ここは〈建つ・できる〉の意味。蘇るは一度衰えたものが元に戻ることなので、新しく建ったものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51637, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蘇った", "is_correct": true, "explanation": "練習を続けた結果としての過去の出来事を表し、文に合う。"}, {"text": "蘇らず", "is_correct": false, "explanation": "否定の連用形で、文を終えられない。"}, {"text": "蘇りかけ", "is_correct": false, "explanation": "途中の段階を表し、結果の説明にならない。"}, {"text": "蘇るまで", "is_correct": false, "explanation": "まで節で、文の述語として終わらない。"}], "explanations": {"蘇った": "練習を続けた結果としての過去の出来事を表し、文に合う。", "蘇らず": "否定の連用形で、文を終えられない。", "蘇りかけ": "途中の段階を表し、結果の説明にならない。", "蘇るまで": "まで節で、文の述語として終わらない。"}, "sentence_index": 6, "correct_answer": "蘇った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい店が蘇った。", "explanation": "ここは〈誕生する〉の意味。蘇るは一度衰えたものが元に戻ることなので、新しく生まれたものには使わない。"}, {"text": "新しい橋が蘇った。", "explanation": "ここは〈完成する〉の意味。蘇るは元の状態へ戻ることなので、初めて完成したものには合わない。"}, {"text": "席に蘇った。", "explanation": "ここは〈戻る〉の意味。蘇るは衰えたものが元の状態へ戻ることで、人が席へ戻る行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51637, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "閉鎖された工場に活気を蘇る日を、町の人々は待っている。", "corrected_sentence": "閉鎖された工場に活気が蘇る日を、町の人々は待っている。", "error_description": "蘇るは自動詞なので、よみがえる「活気」は主語として「が」で示す。「を」は他動詞の目的語に使うため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "蘇る", "is_correct": true, "explanation": "「雨が降ると」の条件のもと、草花がよみがえる終止形で、文に合う。"}, {"text": "蘇らせ", "is_correct": false, "explanation": "使役形で、草花が自ら蘇るという文の主語と合わない。"}, {"text": "蘇らない", "is_correct": false, "explanation": "否定形で、草花がよみがえる事実と逆になる。"}, {"text": "蘇れば", "is_correct": false, "explanation": "仮定形で、「〜と」と条件が重なり不自然。"}], "correct_form": "蘇る", "base_form": "蘇る", "form_label": "終止形（〜と）", "sentence_index": 1, "explanations": {"蘇る": "「雨が降ると」の条件のもと、草花がよみがえる終止形で、文に合う。", "蘇らせ": "使役形で、草花が自ら蘇るという文の主語と合わない。", "蘇らない": "否定形で、草花がよみがえる事実と逆になる。", "蘇れば": "仮定形で、「〜と」と条件が重なり不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51637, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い家が修理されて、昔の姿が蘇らた。", "corrected_sentence": "古い家が修理されて、昔の姿が蘇った。", "error_description": "蘇るの過去形は「蘇った」。「蘇らた」は五段活用の音便を誤った形なので、正しい過去形にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "蘇った", "is_correct": true, "explanation": "水を与えた結果、花が元に戻った過去の出来事を表す。"}, {"text": "蘇らせた", "is_correct": false, "explanation": "使役の過去で、花を生き返らせる主体が違い、文の内容と合わない。"}, {"text": "蘇れる", "is_correct": false, "explanation": "可能形で、「見事に蘇った」という結果の説明にならない。"}, {"text": "蘇りかけ", "is_correct": false, "explanation": "途中の段階を表し、完了した結果を表せない。"}], "correct_form": "蘇った", "base_form": "蘇る", "form_label": "過去形", "sentence_index": 7, "explanations": {"蘇った": "水を与えた結果、花が元に戻った過去の出来事を表す。", "蘇らせた": "使役の過去で、花を生き返らせる主体が違い、文の内容と合わない。", "蘇れる": "可能形で、「見事に蘇った」という結果の説明にならない。", "蘇りかけ": "途中の段階を表し、完了した結果を表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51638, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語。思い出が自然によみがえる文になり、自動詞の蘇るに合う。"}, {"text": "を", "is_correct": false, "explanation": "他動詞の目的語。蘇るは自動詞なので「思い出を蘇る」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段。思い出は場所ではないので「思い出で蘇る」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手・並列。「思い出と蘇る」は文の意味を成さない。"}], "correct_answer": "が", "explanations": {"が": "主語。思い出が自然によみがえる文になり、自動詞の蘇るに合う。", "を": "他動詞の目的語。蘇るは自動詞なので「思い出を蘇る」は成り立たない。", "で": "場所・手段。思い出は場所ではないので「思い出で蘇る」は不自然。", "と": "相手・並列。「思い出と蘇る」は文の意味を成さない。"}, "error_tags": {"を": "他動詞の目的語。蘇るは自動詞なので「思い出を蘇る」は成り立たない。", "で": "場所・手段。思い出は場所ではないので「思い出で蘇る」は不自然。", "と": "相手・並列。「思い出と蘇る」は文の意味を成さない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51638, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51638, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "一度失われたり、忘れられたりしていたものが、再び現れたり、感じられたりすること。", "primary_collocate": null, "pronunciation": "よみがえる", "ipa": "jomiɡaeɾɯ", "syllable_count": 5, "sentences": [{"text": "軋む音とともに、懐かしいシナモンの匂いが記憶の奥から鮮やかに蘇り、私は思わず息を呑んだ。", "target_word": "蘇り", "complexity_tier": "T4", "furigana": "軋[きし]む音[おと]とともに、懐[なつ]かしいシナモンの匂[にお]いが記憶[きおく]の奥[おく]から鮮[あざ]やかに蘇[よみがえ]り、私[わたし]は思[おも]わず息[いき]を呑[の]んだ。", "sentence_source": "mined"}, {"text": "古い写真を見ると、子どもの頃の夏の思い出が蘇る。", "target_word": "蘇る", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]を見[み]ると、子[こ]どもの頃[ころ]の夏[なつ]の思[おも]い出[で]が蘇[よみがえ]る。", "sentence_source": "generated"}, {"text": "その歌を聞いたとたん、忘れていた悲しみが胸に蘇った。", "target_word": "蘇った", "complexity_tier": "T3", "furigana": "その歌[うた]を聞[き]いたとたん、忘[わす]れていた悲[かな]しみが胸[むね]に蘇[よみがえ]った。", "sentence_source": "generated"}, {"text": "祖父の声を思い出すたびに、あの日の記憶が蘇ってくる。", "target_word": "蘇ってくる", "complexity_tier": "T3", "furigana": "祖父[そふ]の声[こえ]を思[おも]い出[だ]すたびに、あの日[ひ]の記憶[きおく]が蘇[よみがえ]ってくる。", "sentence_source": "generated"}, {"text": "久しぶりに故郷の駅に立つと、当時の感覚が体に蘇った。", "target_word": "蘇った", "complexity_tier": "T3", "furigana": "久[ひさ]しぶりに故郷[こきょう]の駅[えき]に立[た]つと、当時[とうじ]の感覚[かんかく]が体[からだ]に蘇[よみがえ]った。", "sentence_source": "generated"}, {"text": "雨の匂いをかぐと、あの試合の緊張が蘇る。", "target_word": "蘇る", "complexity_tier": "T3", "furigana": "雨[あめ]の匂[にお]いをかぐと、あの試合[しあい]の緊張[きんちょう]が蘇[よみがえ]る。", "sentence_source": "generated"}, {"text": "日記を読み返したら、十年前の気持ちが鮮やかに蘇った。", "target_word": "蘇った", "complexity_tier": "T3", "furigana": "日記[にっき]を読[よ]み返[かえ]したら、十年前[じゅうねんまえ]の気持[きも]ちが鮮[あざ]やかに蘇[よみがえ]った。", "sentence_source": "generated"}, {"text": "事故の恐怖が夜になると蘇り、なかなか眠れない。", "target_word": "蘇り", "complexity_tier": "T3", "furigana": "事故[じこ]の恐怖[きょうふ]が夜[よる]になると蘇[よみがえ]り、なかなか眠[ねむ]れない。", "sentence_source": "generated"}, {"text": "手紙の文字を見た瞬間、遠い日の約束が蘇った。", "target_word": "蘇った", "complexity_tier": "T3", "furigana": "手紙[てがみ]の文字[もじ]を見[み]た瞬間[しゅんかん]、遠[とお]い日[ひ]の約束[やくそく]が蘇[よみがえ]った。", "sentence_source": "generated"}, {"text": "昔の友人に会って話すうちに、学生時代の笑い声が蘇ってきた。", "target_word": "蘇ってきた", "complexity_tier": "T3", "furigana": "昔[むかし]の友人[ゆうじん]に会[あ]って話[はな]すうちに、学生時代[がくせいじだい]の笑[わら]い声[ごえ]が蘇[よみがえ]ってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蘇る", "label": "終止形"}, {"form": "蘇らない", "label": "否定形"}, {"form": "蘇り", "label": "連用形"}, {"form": "蘇って", "label": "て形"}, {"form": "蘇った", "label": "過去形"}, {"form": "蘇れば", "label": "仮定形"}], "register": "普通体の書き言葉", "sense_fingerprint": "忘れていた記憶や感覚が心によみがえる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51638, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蘇り", "is_correct": true, "explanation": "連用形で、「、私は息を呑んだ」と続く流れに合う。"}, {"text": "蘇る", "is_correct": false, "explanation": "終止形では文が切れ、「、私は」と続かない。"}, {"text": "蘇らない", "is_correct": false, "explanation": "否定形で、記憶が戻った描写と逆になる。"}, {"text": "蘇らせ", "is_correct": false, "explanation": "使役の連用形で、記憶を蘇らせる主体がなく、文が成立しない。"}], "explanations": {"蘇り": "連用形で、「、私は息を呑んだ」と続く流れに合う。", "蘇る": "終止形では文が切れ、「、私は」と続かない。", "蘇らない": "否定形で、記憶が戻った描写と逆になる。", "蘇らせ": "使役の連用形で、記憶を蘇らせる主体がなく、文が成立しない。"}, "sentence_index": 0, "correct_answer": "蘇り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が上がって、空に初めての虹が蘇った。", "explanation": "ここは〈出現する〉の意味。蘇るは一度あったものが再び現れることなので、初めて現れたものには使わない。"}, {"text": "まだ誰も聞いたことのない音が、その楽器から蘇った。", "explanation": "ここは〈生まれる〉の意味。蘇るは一度失われたものが戻ることなので、誰も聞いたことのない音には使わない。"}, {"text": "ようやく届いた荷物が、玄関に蘇った。", "explanation": "ここは〈届く〉の意味。蘇るは一度失われたものが戻ることなので、初めて届いたものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51638, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蘇った", "is_correct": true, "explanation": "日記を読んだ結果としての過去の出来事を表し、文に合う。"}, {"text": "蘇って", "is_correct": false, "explanation": "て形で文を終えられず、述語として機能しない。"}, {"text": "蘇れ", "is_correct": false, "explanation": "命令形で、日記を読んだ後の出来事の説明にならない。"}, {"text": "蘇らず", "is_correct": false, "explanation": "否定の連用形で、文を終えられない。"}], "explanations": {"蘇った": "日記を読んだ結果としての過去の出来事を表し、文に合う。", "蘇って": "て形で文を終えられず、述語として機能しない。", "蘇れ": "命令形で、日記を読んだ後の出来事の説明にならない。", "蘇らず": "否定の連用形で、文を終えられない。"}, "sentence_index": 6, "correct_answer": "蘇った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "若い料理人の手で、新しい郷土料理が蘇った。", "explanation": "ここは〈誕生する〉の意味。蘇るは一度失われたものが戻ることなので、新しく生まれた料理には使わない。"}, {"text": "旅行を終えて、やっと家に蘇った。", "explanation": "ここは〈戻る〉の意味。蘇るは記憶や感覚がよみがえることで、人が場所へ帰る話には使わない。"}, {"text": "舞台に新人が蘇った。", "explanation": "ここは〈登場する〉の意味。蘇るは記憶や感覚のよみがえりで、新しい人物が現れる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51638, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その歌を聞くと、忘れていた故郷の景色を蘇る。", "corrected_sentence": "その歌を聞くと、忘れていた故郷の景色が蘇る。", "error_description": "蘇るは自動詞なので、よみがえる対象は主語として「が」で示す。「を」は他動詞の目的語に使うため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "蘇る", "is_correct": true, "explanation": "「〜と」の条件のもとで思い出がよみがえる、終止形の基本形。"}, {"text": "蘇らせる", "is_correct": false, "explanation": "使役形で、思い出が自然によみがえる文の意味と合わない。"}, {"text": "蘇れば", "is_correct": false, "explanation": "仮定形で、「〜と」と条件が重なり不自然。"}, {"text": "蘇って", "is_correct": false, "explanation": "て形で文を終えられず、「〜と」の結果を述べられない。"}], "correct_form": "蘇る", "base_form": "蘇る", "form_label": "終止形（〜と）", "sentence_index": 1, "explanations": {"蘇る": "「〜と」の条件のもとで思い出がよみがえる、終止形の基本形。", "蘇らせる": "使役形で、思い出が自然によみがえる文の意味と合わない。", "蘇れば": "仮定形で、「〜と」と条件が重なり不自然。", "蘇って": "て形で文を終えられず、「〜と」の結果を述べられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51638, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事故の恐怖が夜になると蘇ら、なかなか眠れない夜が続く。", "corrected_sentence": "事故の恐怖が夜になると蘇り、なかなか眠れない夜が続く。", "error_description": "「蘇る」は五段活用。連用中止の「〜、」には連用形「蘇り」を使う。未然形の「蘇ら」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "蘇り", "is_correct": true, "explanation": "「、なかなか眠れない」と続く連用形で、文の流れに合う。"}, {"text": "蘇らせ", "is_correct": false, "explanation": "使役形で、恐怖を蘇らせる主体がなく、主語と合わない。"}, {"text": "蘇れ", "is_correct": false, "explanation": "命令形で、恐怖が夜によみがえる説明にならない。"}, {"text": "蘇らず", "is_correct": false, "explanation": "否定形で、恐怖がよみがえるという内容と逆になる。"}], "correct_form": "蘇り", "base_form": "蘇る", "form_label": "連用形（並列の「、」の前）", "sentence_index": 7, "explanations": {"蘇り": "「、なかなか眠れない」と続く連用形で、文の流れに合う。", "蘇らせ": "使役形で、恐怖を蘇らせる主体がなく、主語と合わない。", "蘇れ": "命令形で、恐怖が夜によみがえる説明にならない。", "蘇らず": "否定形で、恐怖がよみがえるという内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51641, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「話が持ち上がっている」の主語を示す格助詞で、話が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "を は他動詞の目的語に付く。持ち上がるは自動詞なので合わない。"}, {"text": "で", "is_correct": false, "explanation": "で は場所や手段を示す。話の主語を示すことはできない。"}, {"text": "に", "is_correct": false, "explanation": "に は方向や対象を示す。「話に持ち上がっている」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「話が持ち上がっている」の主語を示す格助詞で、話が主語になる。", "を": "を は他動詞の目的語に付く。持ち上がるは自動詞なので合わない。", "で": "で は場所や手段を示す。話の主語を示すことはできない。", "に": "に は方向や対象を示す。「話に持ち上がっている」は成り立たない。"}, "error_tags": {"を": "transitive_object", "で": "location_or_means", "に": "wrong_case"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51641, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「案が持ち上がった」の主語を示す格助詞で、出た案が主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "へ は方向を示す。「案へ持ち上がった」では方向の意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "と は引用や相手を示す。案の主語を示す役割はない。"}, {"text": "より", "is_correct": false, "explanation": "より は比較を示す。比べる対象がなく、文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「案が持ち上がった」の主語を示す格助詞で、出た案が主語になる。", "へ": "へ は方向を示す。「案へ持ち上がった」では方向の意味が合わない。", "と": "と は引用や相手を示す。案の主語を示す役割はない。", "より": "より は比較を示す。比べる対象がなく、文が成立しない。"}, "error_tags": {"へ": "direction", "と": "quotation_or_partner", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51641, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが、みんなの中で話に出ること。", "primary_collocate": null, "pronunciation": "もちあがる", "ipa": "mo̞tɕiaɡaɾɯ", "syllable_count": 5, "sentences": [{"text": "クラスで、遠足の行き先を変える話が持ち上がった。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "クラスで、遠足[えんそく]の行[い]き先[さき]を変[か]える話[はなし]が持[も]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "家族の中で、犬を飼う話が持ち上がっている。", "target_word": "持ち上がっている", "complexity_tier": "T3", "furigana": "家族[かぞく]の中[なか]で、犬[いぬ]を飼[か]う話[はなし]が持[も]ち上[あ]がっている。", "sentence_source": "generated"}, {"text": "会議で新しい問題が持ち上がり、みんな困った。", "target_word": "持ち上がり", "complexity_tier": "T3", "furigana": "会議[かいぎ]で新[あたら]しい問題[もんだい]が持[も]ち上[あ]がり、みんな困[こま]った。", "sentence_source": "generated"}, {"text": "引っ越しの話が持ち上がったのは、先月のことだ。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの話[はなし]が持[も]ち上[あ]がったのは、先月[せんげつ]のことだ。", "sentence_source": "generated"}, {"text": "町では、駅の前に図書館を作る話が持ち上がった。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "町[まち]では、駅[えき]の前[まえ]に図書館[としょかん]を作[つく]る話[はなし]が持[も]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "友だちの間で、パーティーを開く話が持ち上がった。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "友[とも]だちの間[あいだ]で、パーティーを開[ひら]く話[はなし]が持[も]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "会社で、給料を上げるかどうかの話が持ち上がった。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "会社[かいしゃ]で、給料[きゅうりょう]を上[あ]げるかどうかの話[はなし]が持[も]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "試合の前に、メンバーを変える案が持ち上がった。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]に、メンバーを変[か]える案[あん]が持[も]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "祖母の誕生日を祝う話が持ち上がり、家族全員が賛成した。", "target_word": "持ち上がり", "complexity_tier": "T3", "furigana": "祖母[そぼ]の誕生日[たんじょうび]を祝[いわ]う話[はなし]が持[も]ち上[あ]がり、家族全員[かぞくぜんいん]が賛成[さんせい]した。", "sentence_source": "generated"}, {"text": "山の道を広げる話が持ち上がると、村の人たちは集まって相談した。", "target_word": "持ち上がる", "complexity_tier": "T3", "furigana": "山[やま]の道[みち]を広[ひろ]げる話[はなし]が持[も]ち上[あ]がると、村[むら]の人[ひと]たちは集[あつ]まって相談[そうだん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "持ち上がる", "label": "辞書形"}, {"form": "持ち上がらない", "label": "ない形"}, {"form": "持ち上がり", "label": "連用形"}, {"form": "持ち上がって", "label": "て形"}, {"form": "持ち上がった", "label": "た形"}, {"form": "持ち上がれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ある話や案がみんなの間で話題に出る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51641, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持ち上がった", "is_correct": true, "explanation": "「話が」を主語にする自動詞の過去形で、遠足の行き先の話が出た意味に合う。"}, {"text": "持ち歩いた", "is_correct": false, "explanation": "他動詞で、物を持って移動する意味。「話が持ち歩いた」では主語と動詞が合わない。"}, {"text": "持ち寄った", "is_correct": false, "explanation": "他動詞で、物や意見を集める意味。目的語がないため「話が」を主語にできない。"}, {"text": "持ち上げた", "is_correct": false, "explanation": "他動詞で「〜を持ち上げた」と目的語が要る。「話が」を主語にできない。"}], "explanations": {"持ち上がった": "「話が」を主語にする自動詞の過去形で、遠足の行き先の話が出た意味に合う。", "持ち歩いた": "他動詞で、物を持って移動する意味。「話が持ち歩いた」では主語と動詞が合わない。", "持ち寄った": "他動詞で、物や意見を集める意味。目的語がないため「話が」を主語にできない。", "持ち上げた": "他動詞で「〜を持ち上げた」と目的語が要る。「話が」を主語にできない。"}, "sentence_index": 0, "correct_answer": "持ち上がった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家族の絆が持ち上がった。", "explanation": "ここは〈深まる〉（気持ちの結びつきが強くなる）の意味。持ち上がるは話や案が出る意味で、関係の深まりには使わない。"}, {"text": "試合の終盤、会場が持ち上がった。", "explanation": "ここは〈盛り上がる〉（場が活気づく）の意味。持ち上がるは話や案が出る意味で、会場の雰囲気には使わない。"}, {"text": "昨夜から体温が持ち上がった。", "explanation": "ここは〈体温が上昇する〉の意味。持ち上がるは話や案が出る意味で、数値の上昇には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51641, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持ち上がった", "is_correct": true, "explanation": "「給料を上げる話が」を主語にする自動詞の過去形で、話が出た意味に合う。"}, {"text": "切り上げた", "is_correct": false, "explanation": "他動詞で、作業や話を打ち切る意味。「話が切り上げた」では主語と動詞が合わない。"}, {"text": "組み上げた", "is_correct": false, "explanation": "他動詞で、組み立てる意味。主語の「話」と結びつかない。"}, {"text": "差し上げた", "is_correct": false, "explanation": "他動詞で、目上の人に物を渡す意味。主語と動詞が合わない。"}], "explanations": {"持ち上がった": "「給料を上げる話が」を主語にする自動詞の過去形で、話が出た意味に合う。", "切り上げた": "他動詞で、作業や話を打ち切る意味。「話が切り上げた」では主語と動詞が合わない。", "組み上げた": "他動詞で、組み立てる意味。主語の「話」と結びつかない。", "差し上げた": "他動詞で、目上の人に物を渡す意味。主語と動詞が合わない。"}, "sentence_index": 6, "correct_answer": "持ち上がった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い夜が持ち上がった。", "explanation": "ここは〈夜が明ける〉の意味。持ち上がるは話や案が出る意味で、時間の経過には使わない。"}, {"text": "大きな音で目が持ち上がった。", "explanation": "ここは〈目が覚める〉の意味。持ち上がるは話や案が出る意味で、目の状態には使わない。"}, {"text": "春になって新芽が持ち上がった。", "explanation": "ここは〈芽吹く〉の意味。持ち上がるは話や案が出る意味で、植物の成長には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51641, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校の行事の話を持ち上がったのは、先週のことだ。", "corrected_sentence": "学校の行事の話が持ち上がったのは、先週のことだ。", "error_description": "持ち上がるは自動詞で、話や案が主語になる。主語には「が」を付けるので、「を」は誤り（正しくは「話が持ち上がった」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "持ち上がっている", "is_correct": true, "explanation": "ている形で、話がいま出ている状態を表し、「犬を飼う話が持ち上がっている」に合う。"}, {"text": "持ち上がって", "is_correct": false, "explanation": "て形で文を続ける形。文末には置けず、この文は終わらない。"}, {"text": "持ち上がらない", "is_correct": false, "explanation": "否定形。話が出ていないことになり、家族の中で話題になっている文脈と逆になる。"}, {"text": "持ち上がれば", "is_correct": false, "explanation": "仮定形。条件節のままで文が終わらず、現在の状態を述べる文として完結しない。"}], "correct_form": "持ち上がっている", "base_form": "持ち上がる", "form_label": "ている形", "sentence_index": 1, "explanations": {"持ち上がっている": "ている形で、話がいま出ている状態を表し、「犬を飼う話が持ち上がっている」に合う。", "持ち上がって": "て形で文を続ける形。文末には置けず、この文は終わらない。", "持ち上がらない": "否定形。話が出ていないことになり、家族の中で話題になっている文脈と逆になる。", "持ち上がれば": "仮定形。条件節のままで文が終わらず、現在の状態を述べる文として完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51641, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その案は、先月ようやく持ち上がり。", "corrected_sentence": "その案は、先月ようやく持ち上がった。", "error_description": "過去の出来事を述べる「た形」が必要。「持ち上がり」は連用形で、文末に置くと文が完結しない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "持ち上がった", "is_correct": true, "explanation": "た形で、先に行われた話の出来事を述べる文に合う。"}, {"text": "持ち上がって", "is_correct": false, "explanation": "て形で文を続ける形。文末には置けず、この文は終わらない。"}, {"text": "持ち上がれ", "is_correct": false, "explanation": "命令形。事実を述べる文にならず、命令の意味になる。"}, {"text": "持ち上がり", "is_correct": false, "explanation": "連用形で、文末には使えず、文が完結しない。"}], "correct_form": "持ち上がった", "base_form": "持ち上がる", "form_label": "過去形（た形）", "sentence_index": 7, "explanations": {"持ち上がった": "た形で、先に行われた話の出来事を述べる文に合う。", "持ち上がって": "て形で文を続ける形。文末には置けず、この文は終わらない。", "持ち上がれ": "命令形。事実を述べる文にならず、命令の意味になる。", "持ち上がり": "連用形で、文末には使えず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51642, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「案が持ち上がった」の主語を示す格助詞で、出てきた案が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "を は他動詞の目的語に付く。持ち上がるは自動詞なので目的語を取らない。"}, {"text": "に", "is_correct": false, "explanation": "に は方向や対象を示す。「案に持ち上がった」では主語が立たない。"}, {"text": "で", "is_correct": false, "explanation": "で は場所や手段を示す。「案で持ち上がった」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「案が持ち上がった」の主語を示す格助詞で、出てきた案が主語になる。", "を": "を は他動詞の目的語に付く。持ち上がるは自動詞なので目的語を取らない。", "に": "に は方向や対象を示す。「案に持ち上がった」では主語が立たない。", "で": "で は場所や手段を示す。「案で持ち上がった」は意味が通らない。"}, "error_tags": {"を": "transitive_object", "に": "wrong_case", "で": "location_or_means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51642, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「話が持ち上がる」の主語を示す格助詞で、出てくる話が主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "へ は方向を示す。「話へ持ち上がる」では方向の意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "と は相手や引用を示す。ここでは話を主語として受ける形になっていない。"}, {"text": "より", "is_correct": false, "explanation": "より は比較を示す。比べる対象がなく、「話より持ち上がる」は成立しない。"}], "correct_answer": "が", "explanations": {"が": "「話が持ち上がる」の主語を示す格助詞で、出てくる話が主語になる。", "へ": "へ は方向を示す。「話へ持ち上がる」では方向の意味が合わない。", "と": "と は相手や引用を示す。ここでは話を主語として受ける形になっていない。", "より": "より は比較を示す。比べる対象がなく、「話より持ち上がる」は成立しない。"}, "error_tags": {"へ": "direction", "と": "quotation_or_partner", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51642, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある事柄が話題や検討の対象として現れる、または提案されること。", "primary_collocate": null, "pronunciation": "もちあがる", "ipa": "mo̞tɕiaɡaɾɯ", "syllable_count": 5, "sentences": [{"text": "庭の片隅に、子供のための遊び小屋を建てる計画が持ち上がった。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "庭[にわ]の片隅[かたすみ]に、子供[こども]のための遊[あそ]び小屋[ごや]を建[た]てる計画[けいかく]が持[も]ち上[あ]がった。", "sentence_source": "mined"}, {"text": "会議の最後に、来年の旅行先を変える案が持ち上がった。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "会議[かいぎ]の最後[さいご]に、来年[らいねん]の旅行先[りょこうさき]を変[か]える案[あん]が持[も]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "駅前に大きな商業施設を作る計画が持ち上がり、住民は驚いた。", "target_word": "持ち上がり", "complexity_tier": "T3", "furigana": "駅前[えきまえ]に大[おお]きな商業施設[しょうぎょうしせつ]を作[つく]る計画[けいかく]が持[も]ち上[あ]がり、住民[じゅうみん]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "学校では、制服を見直す話が持ち上がっているそうだ。", "target_word": "持ち上がっている", "complexity_tier": "T3", "furigana": "学校[がっこう]では、制服[せいふく]を見直[みなお]す話[はなし]が持[も]ち上[あ]がっているそうだ。", "sentence_source": "generated"}, {"text": "結婚の話が持ち上がったとき、彼女はまだ迷っていた。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "結婚[けっこん]の話[はなし]が持[も]ち上[あ]がったとき、彼女[かのじょ]はまだ迷[まよ]っていた。", "sentence_source": "generated"}, {"text": "新しい問題が持ち上がったため、予定していた発表は延期された。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "新[あたら]しい問題[もんだい]が持[も]ち上[あ]がったため、予定[よてい]していた発表[はっぴょう]は延期[えんき]された。", "sentence_source": "generated"}, {"text": "工事の途中で、費用をめぐるトラブルが持ち上がった。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "工事[こうじ]の途中[とちゅう]で、費用[ひよう]をめぐるトラブルが持[も]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "合併の話が持ち上がると、社員たちの間に不安が広がった。", "target_word": "持ち上がる", "complexity_tier": "T3", "furigana": "合併[がっぺい]の話[はなし]が持[も]ち上[あ]がると、社員[しゃいん]たちの間[あいだ]に不安[ふあん]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "村の祭りを中止するかどうかという議論が持ち上がった。", "target_word": "持ち上がった", "complexity_tier": "T3", "furigana": "村[むら]の祭[まつ]りを中止[ちゅうし]するかどうかという議論[ぎろん]が持[も]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "去年消えたはずの増税の話が、また持ち上がってきた。", "target_word": "持ち上がってきた", "complexity_tier": "T3", "furigana": "去年[きょねん]消[き]えたはずの増税[ぞうぜい]の話[はなし]が、また持[も]ち上[あ]がってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "持ち上がる", "label": "辞書形"}, {"form": "持ち上がらない", "label": "ない形"}, {"form": "持ち上がり", "label": "連用形"}, {"form": "持ち上がって", "label": "て形"}, {"form": "持ち上がった", "label": "た形"}, {"form": "持ち上がれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "計画・問題・話などが話題や検討の対象として表に出てくる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51642, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持ち上がった", "is_correct": true, "explanation": "「計画が」を主語にする自動詞の過去形で、計画が話題として表に出た意味に合う。"}, {"text": "持ち上げた", "is_correct": false, "explanation": "他動詞で「〜を持ち上げた」と目的語が要るため、「計画が」を主語にできない。"}, {"text": "持ち込んだ", "is_correct": false, "explanation": "他動詞で、物や案件を場に持ち込む意味。「計画が持ち込んだ」では主語と動詞が合わない。"}, {"text": "持ち出した", "is_correct": false, "explanation": "他動詞で「〜を持ち出した」と目的語が要る。「計画が」を主語にすると成り立たない。"}], "explanations": {"持ち上がった": "「計画が」を主語にする自動詞の過去形で、計画が話題として表に出た意味に合う。", "持ち上げた": "他動詞で「〜を持ち上げた」と目的語が要るため、「計画が」を主語にできない。", "持ち込んだ": "他動詞で、物や案件を場に持ち込む意味。「計画が持ち込んだ」では主語と動詞が合わない。", "持ち出した": "他動詞で「〜を持ち出した」と目的語が要る。「計画が」を主語にすると成り立たない。"}, "sentence_index": 0, "correct_answer": "持ち上がった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の終盤、観客の声が持ち上がった。", "explanation": "ここは〈盛り上がる〉（場が活気づく）の意味。持ち上がるは話題や案が表に出る意味で、声や雰囲気には使わない。"}, {"text": "喜びが持ち上がって、涙が出た。", "explanation": "ここは〈込み上げる〉（感情が急に湧く）の意味。持ち上がるは話題や提案が表に出る意味で、感情には使わない。"}, {"text": "被災地の復興に向けて、人々が持ち上がった。", "explanation": "ここは〈立ち上がる〉（行動を起こす）の意味。持ち上がるは話題や案が表に出る意味で、人が行動を起こす文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51642, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持ち上がった", "is_correct": true, "explanation": "「トラブルが」を主語にする自動詞の過去形で、問題が表に出た意味に合う。"}, {"text": "押し上げた", "is_correct": false, "explanation": "他動詞で「〜を押し上げた」と目的語が要る。「トラブルが押し上げた」は成立しない。"}, {"text": "差し上げた", "is_correct": false, "explanation": "他動詞で、目上の人に物を渡す意味。「トラブルが」を主語にすると意味が通らない。"}, {"text": "切り上げた", "is_correct": false, "explanation": "作業や話し合いを打ち切る意味で、目的語が要る。「トラブルが切り上げた」は文として成立しない。"}], "explanations": {"持ち上がった": "「トラブルが」を主語にする自動詞の過去形で、問題が表に出た意味に合う。", "押し上げた": "他動詞で「〜を押し上げた」と目的語が要る。「トラブルが押し上げた」は成立しない。", "差し上げた": "他動詞で、目上の人に物を渡す意味。「トラブルが」を主語にすると意味が通らない。", "切り上げた": "作業や話し合いを打ち切る意味で、目的語が要る。「トラブルが切り上げた」は文として成立しない。"}, "sentence_index": 6, "correct_answer": "持ち上がった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "最近、株価が持ち上がった。", "explanation": "ここは〈株価が上昇する〉の意味。持ち上がるは話題や提案が現れる意味で、数値の上昇には使わない。"}, {"text": "会議で新人が持ち上がった。", "explanation": "ここは〈目立つ〉（人が注目を集める）の意味。持ち上がるは話題の意味で、人の振る舞いには使わない。"}, {"text": "祭りの日、町が持ち上がった。", "explanation": "ここは〈活気づく〉の意味。持ち上がるは話題の意味で、場所の雰囲気には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51642, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の再開発の話を持ち上がったのは、昨年の春だ。", "corrected_sentence": "町の再開発の話が持ち上がったのは、昨年の春だ。", "error_description": "持ち上がるは自動詞で、話や案が主語になる。主語には「が」を付けるので、「を」は誤り（正しくは「話が持ち上がった」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "持ち上がった", "is_correct": true, "explanation": "た形で、会議で案が出たという完了した出来事を述べる文に合う。"}, {"text": "持ち上がらない", "is_correct": false, "explanation": "否定の非過去形。「会議の最後に」と過去の出来事を述べる文では時制が合わず、案が出なかったという過去の内容にもならない。"}, {"text": "持ち上がれば", "is_correct": false, "explanation": "仮定形。条件節のままで文が終わらず、報告の文として完結しない。"}, {"text": "持ち上がって", "is_correct": false, "explanation": "て形で、文を続ける形。文末には置けず、この文は終わっていない。"}], "correct_form": "持ち上がった", "base_form": "持ち上がる", "form_label": "過去形（た形）", "sentence_index": 1, "explanations": {"持ち上がった": "た形で、会議で案が出たという完了した出来事を述べる文に合う。", "持ち上がらない": "否定の非過去形。「会議の最後に」と過去の出来事を述べる文では時制が合わず、案が出なかったという過去の内容にもならない。", "持ち上がれば": "仮定形。条件節のままで文が終わらず、報告の文として完結しない。", "持ち上がって": "て形で、文を続ける形。文末には置けず、この文は終わっていない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51642, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "選挙の前に、新しい公約が持ち上がって。", "corrected_sentence": "選挙の前に、新しい公約が持ち上がった。", "error_description": "過去の出来事を言い切る「た形」が必要。「持ち上がって」は「て形」で、文末に置くと文が終わらない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "持ち上がる", "is_correct": true, "explanation": "辞書形で、「話が持ち上がると」の条件の「と」の前に置く形に合う。"}, {"text": "持ち上がれ", "is_correct": false, "explanation": "命令形。命令の意味になり、事実を述べる文にならない。"}, {"text": "持ち上がり", "is_correct": false, "explanation": "連用形で、文末には使えず、「と」で条件を作れない。"}, {"text": "持ち上がらなかった", "is_correct": false, "explanation": "否定の過去形。話が出なかったことになり、文の内容と逆になる。"}], "correct_form": "持ち上がる", "base_form": "持ち上がる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"持ち上がる": "辞書形で、「話が持ち上がると」の条件の「と」の前に置く形に合う。", "持ち上がれ": "命令形。命令の意味になり、事実を述べる文にならない。", "持ち上がり": "連用形で、文末には使えず、「と」で条件を作れない。", "持ち上がらなかった": "否定の過去形。話が出なかったことになり、文の内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51644, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "保管する場所を表す「に」。「二階の物置に保管している」で自然"}, {"text": "を", "is_correct": false, "explanation": "「保管する」の目的語は服などの品物。「物置を保管している」は場所を対象にする形になり不自然"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「物置が保管している」では物置が保管の主体になり、文が通らない"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」。「物置から保管している」では保管先を表せない"}], "correct_answer": "に", "explanations": {"に": "保管する場所を表す「に」。「二階の物置に保管している」で自然", "を": "「保管する」の目的語は服などの品物。「物置を保管している」は場所を対象にする形になり不自然", "が": "主語を示す「が」。「物置が保管している」では物置が保管の主体になり、文が通らない", "から": "起点を示す「から」。「物置から保管している」では保管先を表せない"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51644, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51644, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物をしまっておくための場所や部屋のこと。倉庫や収納スペースを指す。", "primary_collocate": null, "pronunciation": "ものおき", "ipa": "monookʲi", "syllable_count": 4, "sentences": [{"text": "新しい家には、広い物置がついている。", "target_word": "物置", "complexity_tier": "T3", "furigana": "新[あたら]しい家[いえ]には、広[ひろ]い物置[ものおき]がついている。", "sentence_source": "generated"}, {"text": "冬の服は、二階の物置に保管している。", "target_word": "物置", "complexity_tier": "T3", "furigana": "冬[ふゆ]の服[ふく]は、二階[にかい]の物置[ものおき]に保管[ほかん]している。", "sentence_source": "generated"}, {"text": "学校の物置には、運動会の道具がそろっている。", "target_word": "物置", "complexity_tier": "T3", "furigana": "学校[がっこう]の物置[ものおき]には、運動会[うんどうかい]の道具[どうぐ]がそろっている。", "sentence_source": "generated"}, {"text": "物置が小さいので、荷物が入りきらない。", "target_word": "物置", "complexity_tier": "T3", "furigana": "物置[ものおき]が小[ちい]さいので、荷物[にもつ]が入[はい]りきらない。", "sentence_source": "generated"}, {"text": "祖父の物置は、工具や木材でいっぱいだ。", "target_word": "物置", "complexity_tier": "T3", "furigana": "祖父[そふ]の物置[ものおき]は、工具[こうぐ]や木材[もくざい]でいっぱいだ。", "sentence_source": "generated"}, {"text": "彼は物置を改造して、小さな作業部屋にした。", "target_word": "物置", "complexity_tier": "T3", "furigana": "彼[かれ]は物置[ものおき]を改造[かいぞう]して、小[ちい]さな作業部屋[さぎょうべや]にした。", "sentence_source": "generated"}, {"text": "家族の荷物が増えて、物置が足りなくなった。", "target_word": "物置", "complexity_tier": "T3", "furigana": "家族[かぞく]の荷物[にもつ]が増[ふ]えて、物置[ものおき]が足[た]りなくなった。", "sentence_source": "generated"}, {"text": "階段の下の物置に、掃除機を入れている。", "target_word": "物置", "complexity_tier": "T3", "furigana": "階段[かいだん]の下[した]の物置[ものおき]に、掃除機[そうじき]を入[い]れている。", "sentence_source": "generated"}, {"text": "大きな物置を買って、庭に置いた。", "target_word": "物置", "complexity_tier": "T3", "furigana": "大[おお]きな物置[ものおき]を買[か]って、庭[にわ]に置[お]いた。", "sentence_source": "generated"}, {"text": "引っ越しの荷物を、しばらく物置にしまっておいた。", "target_word": "物置", "complexity_tier": "T3", "furigana": "引っ越[ひっこ]しの荷物[にもつ]を、しばらく物置[ものおき]にしまっておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物置", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "家や学校にある、荷物をしまうための部屋や収納スペース", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8f1722b-8f6a-484b-8e04-67ac74b730cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51644, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物置", "is_correct": true, "explanation": "家の中の荷物をしまう部屋を指し、「新しい家には広い物置がついている」と文意が通る"}, {"text": "蛇口", "is_correct": false, "explanation": "水を出す設備で、「広い蛇口がついている」は大きさの描写として不自然"}, {"text": "電球", "is_correct": false, "explanation": "照明の部品で、「広い電球がついている」は意味が通らない"}, {"text": "表札", "is_correct": false, "explanation": "門や玄関に掛ける名札で、「広い表札がついている」は用途と合わない"}], "explanations": {"物置": "家の中の荷物をしまう部屋を指し、「新しい家には広い物置がついている」と文意が通る", "蛇口": "水を出す設備で、「広い蛇口がついている」は大きさの描写として不自然", "電球": "照明の部品で、「広い電球がついている」は意味が通らない", "表札": "門や玄関に掛ける名札で、「広い表札がついている」は用途と合わない"}, "sentence_index": 0, "correct_answer": "物置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ご飯は、物置で食べることにしている。", "explanation": "ここは〈食堂〉（食事をする部屋）の意味。物置は荷物をしまう場所で、食事をする部屋には使わない。"}, {"text": "お客さんは、物置から家の中に上がってきた。", "explanation": "ここは〈玄関〉（家の出入り口）の意味。物置は人が出入りする場所ではないので、客の出入り口には合わない"}, {"text": "急にお腹が痛くなり、物置に駆け込んだ。", "explanation": "ここは〈トイレ〉（用を足す設備のある場所）の意味。物置には設備がないので、用を足す場所にはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51644, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物置", "is_correct": true, "explanation": "家族の荷物を収める場所で、「荷物が増えて物置が足りなくなった」と文の流れが合う"}, {"text": "洗剤", "is_correct": false, "explanation": "消耗品で、荷物が増えたこととは結びつかず、「荷物が増えて洗剤が足りなくなった」は流れが合わない"}, {"text": "乾電池", "is_correct": false, "explanation": "荷物の増加と関係がなく、「荷物が増えて乾電池が足りなくなった」は文の流れが合わない"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "個人の日用品で、荷物の増加と結びつかず、「歯ブラシが足りなくなった」は意味が通らない"}], "explanations": {"物置": "家族の荷物を収める場所で、「荷物が増えて物置が足りなくなった」と文の流れが合う", "洗剤": "消耗品で、荷物が増えたこととは結びつかず、「荷物が増えて洗剤が足りなくなった」は流れが合わない", "乾電池": "荷物の増加と関係がなく、「荷物が増えて乾電池が足りなくなった」は文の流れが合わない", "歯ブラシ": "個人の日用品で、荷物の増加と結びつかず、「歯ブラシが足りなくなった」は意味が通らない"}, "sentence_index": 6, "correct_answer": "物置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗濯物を物置に干して、夕方に取り込んだ。", "explanation": "ここは〈物干し〉（洗濯物を干す場所）の意味。物置は荷物をしまう場所で、洗濯物を干す場所にはならない"}, {"text": "手は物置で洗ってから、食事をする。", "explanation": "ここは〈洗面所〉（手や顔を洗う設備のある場所）の意味。物置には水を使う設備がないので、手は洗えない"}, {"text": "寒い日は、物置で湯船につかって体を温める。", "explanation": "ここは〈浴室〉（湯船のある入浴の場所）の意味。物置には湯船がないので、ここで入浴はできない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51644, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏用の道具が増えて、物置をもう足りない。", "corrected_sentence": "夏用の道具が増えて、物置がもう足りない。", "error_description": "「足りない」は「〜が足りない」の形で、不足するものを「が」で示す。ここで「を」を使うのは目的語の格を誤っており、「物置が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51644, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝袋は、使わない時は物置がしまう。", "corrected_sentence": "寝袋は、使わない時は物置にしまう。", "error_description": "「しまう」の行き先は「に」で示す。「物置が」と主格にすると物置が寝袋をしまう主体になり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51645, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51645, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「刺激が足りない」の主語を示す格助詞で、刺激が主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "へ は方向を示す。「刺激へ足りない」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "より は比較を示す。比べる対象がなく、文が成立しない。"}, {"text": "から", "is_correct": false, "explanation": "から は起点や理由を示す。「刺激から足りない」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「刺激が足りない」の主語を示す格助詞で、刺激が主語になる。", "へ": "へ は方向を示す。「刺激へ足りない」は成り立たない。", "より": "より は比較を示す。比べる対象がなく、文が成立しない。", "から": "から は起点や理由を示す。「刺激から足りない」は意味が通らない。"}, "error_tags": {"へ": "direction", "より": "comparison", "から": "source_or_reason"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51645, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをする気持ちを、もっと強くさせること。", "primary_collocate": null, "pronunciation": "しげき", "ipa": "ɕiɡeki", "syllable_count": 3, "sentences": [{"text": "友人の合格が刺激になって、私も勉強時間を増やした。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "ゆうじんのごうかくがしげきになって、わたしもべんきょうじかんをふやした。", "sentence_source": "generated"}, {"text": "ライバルの活躍は、選手にとって何よりの刺激だ。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "ライバルのかつやくは、せんしゅにとってなによりのしげきだ。", "sentence_source": "generated"}, {"text": "兄の成功に刺激されて、弟も起業を決意した。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "あにのせいこうにしげきされて、おとうともきぎょうをけついした。", "sentence_source": "generated"}, {"text": "同じ目標の仲間がいると、お互いに刺激し合って練習が続く。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "おなじもくひょうのなかまがいると、おたがいにしげきしあってれんしゅうがつづく。", "sentence_source": "generated"}, {"text": "彼女の熱心な姿が刺激となり、クラス全体のやる気が高まった。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "かのじょのねっしんなすがたがしげきとなり、クラスぜんたいのやるきがたかまった。", "sentence_source": "generated"}, {"text": "大会の結果を見て強い刺激を受け、毎朝走る決心をした。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "たいかいのけっかをみてつよいしげきをうけ、まいあさはしるけっしんをした。", "sentence_source": "generated"}, {"text": "努力する先輩の姿は、後輩にとって大きな刺激になる。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "どりょくするせんぱいのすがたは、こうはいにとっておおきなしげきになる。", "sentence_source": "generated"}, {"text": "一人で勉強していると、刺激が足りなくてやる気が続かない。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "ひとりでべんきょうしていると、しげきがたりなくてやるきがつづかない。", "sentence_source": "generated"}, {"text": "弟の上達ぶりに刺激を受けて、私もピアノの練習を再開した。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "おとうとのじょうたつぶりにしげきをうけて、わたしもピアノのれんしゅうをさいかいした。", "sentence_source": "generated"}, {"text": "新しい挑戦をしている同僚の話が刺激になり、私も資格を取ろうと思った。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "あたらしいちょうせんをしているどうりょうのはなしがしげきになり、わたしもしかくをとろうとおもった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "刺激", "label": "基本形"}, {"form": "刺激する", "label": "動詞形"}, {"form": "刺激される", "label": "受身形"}, {"form": "刺激し合う", "label": "相互形"}], "register": "中立（常体）", "sense_fingerprint": "他人の姿や出来事がやる気を強めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51645, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刺激", "is_correct": true, "explanation": "刺激になって（きっかけとなって）の意味で、友人の合格が勉強のきっかけになった文に合う。"}, {"text": "衝突", "is_correct": false, "explanation": "衝突（ぶつかる）の意味。友人の合格が衝突になって勉強時間を増やしたとは言えない。"}, {"text": "停滞", "is_correct": false, "explanation": "停滞（進まない）の意味。停滞になって勉強時間を増やす因果が合わない。"}, {"text": "分析", "is_correct": false, "explanation": "分析（くわしく調べる）の意味。分析になって勉強時間を増やすとは言えない。"}], "explanations": {"刺激": "刺激になって（きっかけとなって）の意味で、友人の合格が勉強のきっかけになった文に合う。", "衝突": "衝突（ぶつかる）の意味。友人の合格が衝突になって勉強時間を増やしたとは言えない。", "停滞": "停滞（進まない）の意味。停滞になって勉強時間を増やす因果が合わない。", "分析": "分析（くわしく調べる）の意味。分析になって勉強時間を増やすとは言えない。"}, "sentence_index": 0, "correct_answer": "刺激"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い機械を刺激して、動かした。", "explanation": "ここは〈動かす〉（機械を作動させる）の意味。刺激はやる気を強める意味で、機械を作動させる場面には使わない。"}, {"text": "冷めたスープを刺激して、温めた。", "explanation": "ここは〈温める〉の意味。刺激は気持ちを強める意味で、料理の温度を上げる場面には使わない。"}, {"text": "失恋した友人を刺激した。", "explanation": "ここは〈慰める〉の意味。刺激はやる気を強める意味で、落ち込んだ人を慰める場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51645, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刺激", "is_correct": true, "explanation": "刺激になる（励みになる）の意味で、先輩の姿が後輩のやる気を高める文に合う。"}, {"text": "寄付", "is_correct": false, "explanation": "寄付（金品をあげる）の意味。大きな寄付になるとは言えず、文意が通らない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便（手紙や荷物を送る）の意味。大きな郵便になるとは言えない。"}, {"text": "水道", "is_correct": false, "explanation": "水道（水を送る設備）の意味。大きな水道になるとは言えない。"}], "explanations": {"刺激": "刺激になる（励みになる）の意味で、先輩の姿が後輩のやる気を高める文に合う。", "寄付": "寄付（金品をあげる）の意味。大きな寄付になるとは言えず、文意が通らない。", "郵便": "郵便（手紙や荷物を送る）の意味。大きな郵便になるとは言えない。", "水道": "水道（水を送る設備）の意味。大きな水道になるとは言えない。"}, "sentence_index": 6, "correct_answer": "刺激"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "赤ちゃんを、やさしく刺激して寝かせた。", "explanation": "ここは〈寝かせる〉の意味。刺激はやる気を強める意味で、眠らせる場面には使わない。"}, {"text": "古い屋根を刺激して、修繕した。", "explanation": "ここは〈修繕する〉の意味。刺激はやる気を強める意味で、建物を直す場面には使わない。"}, {"text": "この薬は風邪を刺激して、早く治す。", "explanation": "ここは〈治す〉（病気を取り除く）の意味。刺激はやる気を強める意味で、病気を治す働きは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51645, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩の挑戦が、私のやる気に刺激した。", "corrected_sentence": "先輩の挑戦が、私のやる気を刺激した。", "error_description": "刺激する（他動詞）の目的語には「を」を使う。「やる気に」は誤り（正しくは「やる気を刺激した」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51645, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩の成功が、私の意欲を刺激し。", "corrected_sentence": "先輩の成功が、私の意欲を刺激した。", "error_description": "過去の出来事を述べる「た形」が必要。「刺激し」は連用形で、文末に置くと文が終わらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51646, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「刺激を与える」の目的語を示す格助詞で、与えるものが刺激になる。"}, {"text": "に", "is_correct": false, "explanation": "に は与える相手や帰着点に付く。「刺激に与える」では目的語の形が合わない。"}, {"text": "で", "is_correct": false, "explanation": "で は手段や場所を示す。「刺激で与える」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "と は相手や並列を示す。「刺激と与える」は文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "「刺激を与える」の目的語を示す格助詞で、与えるものが刺激になる。", "に": "に は与える相手や帰着点に付く。「刺激に与える」では目的語の形が合わない。", "で": "で は手段や場所を示す。「刺激で与える」は意味が通らない。", "と": "と は相手や並列を示す。「刺激と与える」は文が成立しない。"}, "error_tags": {"に": "wrong_case", "で": "means_or_location", "と": "partner_or_list"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51646, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「刺激がある」の主語を示す格助詞で、旅行にある刺激が主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "へ は方向を示す。「刺激へある」では存在の主語が合わない。"}, {"text": "より", "is_correct": false, "explanation": "より は比較を示す。比べる対象がなく、文が成立しない。"}, {"text": "から", "is_correct": false, "explanation": "から は起点や理由を示す。「刺激からある」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「刺激がある」の主語を示す格助詞で、旅行にある刺激が主語になる。", "へ": "へ は方向を示す。「刺激へある」では存在の主語が合わない。", "より": "より は比較を示す。比べる対象がなく、文が成立しない。", "から": "から は起点や理由を示す。「刺激からある」は意味が通らない。"}, "error_tags": {"へ": "direction", "より": "comparison", "から": "source_or_reason"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51646, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や物に働きかけて、行動や考えを活発にさせること。", "primary_collocate": null, "pronunciation": "しげき", "ipa": "ɕiɡeki", "syllable_count": 3, "sentences": [{"text": "単なる物置きではなく、創造性を刺激する空間にしたいと考えたのだ。", "target_word": "刺激", "complexity_tier": "T4", "furigana": "たんなるものおきではなく、そうぞうせいをしげきするくうかんにしたいとかんがえたのだ。", "sentence_source": "mined"}, {"text": "新しい環境での生活は、毎日の考え方に大きな刺激を与えてくれる。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "あたらしいかんきょうでのせいかつは、まいにちのかんがえかたにおおきなしげきをあたえてくれる。", "sentence_source": "generated"}, {"text": "美術館で見た作品に刺激を受けて、自分でも絵を描き始めた。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "びじゅつかんでみたさくひんにしげきをうけて、じぶんでもえをかきはじめた。", "sentence_source": "generated"}, {"text": "外国の友人との会話は、私の考えを刺激する。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "がいこくのゆうじんとのかいわは、わたしのかんがえをしげきする。", "sentence_source": "generated"}, {"text": "毎日同じ仕事ばかりで、考えを刺激するものがなく、アイデアが出てこない。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "毎日[まいにち]同[おな]じ仕事[しごと]ばかりで、考[かんが]えを刺激[しげき]するものがなく、アイデアが出[で]てこない。", "sentence_source": "generated"}, {"text": "赤ちゃんの脳を刺激するために、色のきれいなおもちゃを使う。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "あかちゃんののうをしげきするために、いろのきれいなおもちゃをつかう。", "sentence_source": "generated"}, {"text": "先輩の発表が若い社員を刺激し、会議が一気に活発になった。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "せんぱいのはっぴょうがわかいしゃいんをしげきし、かいぎがいっきにかっぱつになった。", "sentence_source": "generated"}, {"text": "旅行は日常にない刺激があるから、新しい発想が生まれやすい。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "りょこうはにちじょうにないしげきがあるから、あたらしいはっそうがうまれやすい。", "sentence_source": "generated"}, {"text": "彼の意見は私たちの議論を刺激して、新しい案がいくつも出た。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "かれのいけんはわたしたちのぎろんをしげきして、あたらしいあんがいくつもでた。", "sentence_source": "generated"}, {"text": "刺激の少ない毎日では、人は考えることをやめてしまいがちだ。", "target_word": "刺激", "complexity_tier": "T3", "furigana": "しげきのすくないまいにちでは、ひとはかんがえることをやめてしまいがちだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "刺激", "label": "基本形"}, {"form": "刺激する", "label": "動詞形"}, {"form": "刺激した", "label": "過去形"}, {"form": "刺激される", "label": "受身形"}], "register": "中立（常体）", "sense_fingerprint": "外からの働きかけで人の行動や考えを活発にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51646, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刺激", "is_correct": true, "explanation": "刺激する（働きかけて活発にする）の意味で、創造性を高める空間にしたいという文に合う。"}, {"text": "防止", "is_correct": false, "explanation": "防止する（起こさせない）の意味。「創造性を防止する空間」では文意が通らない。"}, {"text": "抑制", "is_correct": false, "explanation": "抑制する（おさえる）の意味。創造性を抑える空間では目指す内容と逆になる。"}, {"text": "監視", "is_correct": false, "explanation": "監視する（見張る）の意味。「創造性を監視する空間」では文意が通らない。"}], "explanations": {"刺激": "刺激する（働きかけて活発にする）の意味で、創造性を高める空間にしたいという文に合う。", "防止": "防止する（起こさせない）の意味。「創造性を防止する空間」では文意が通らない。", "抑制": "抑制する（おさえる）の意味。創造性を抑える空間では目指す内容と逆になる。", "監視": "監視する（見張る）の意味。「創造性を監視する空間」では文意が通らない。"}, "sentence_index": 0, "correct_answer": "刺激"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ひびの入った壁を刺激して、塗り直した。", "explanation": "ここは〈塗り直す〉の意味。刺激は人や物に働きかけて行動や考えを活発にさせる意味で、壁の補修の場面には使わない。"}, {"text": "冷めたお茶を刺激して、温めた。", "explanation": "ここは〈温める〉の意味。刺激は行動や考えを活発にさせる意味で、飲み物の温度を上げる場面には使わない。"}, {"text": "熱くなったエンジンを刺激した。", "explanation": "ここは〈冷却する〉の意味。刺激は人の行動や考えを活発にする意味で、機械を冷やす場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51646, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刺激", "is_correct": true, "explanation": "刺激し（働きかけて活発にする）の形で、会議が活発になった原因を示す文に合う。"}, {"text": "排除", "is_correct": false, "explanation": "排除する（取り除く）の意味。若い社員を排除すると会議が活発になる理屈が合わない。"}, {"text": "解消", "is_correct": false, "explanation": "解消する（なくす）の意味。若い社員を解消するとは言えず、文意が通らない。"}, {"text": "停止", "is_correct": false, "explanation": "停止する（止める）の意味。若い社員を停止させると会議が活発になる文脈に合わない。"}], "explanations": {"刺激": "刺激し（働きかけて活発にする）の形で、会議が活発になった原因を示す文に合う。", "排除": "排除する（取り除く）の意味。若い社員を排除すると会議が活発になる理屈が合わない。", "解消": "解消する（なくす）の意味。若い社員を解消するとは言えず、文意が通らない。", "停止": "停止する（止める）の意味。若い社員を停止させると会議が活発になる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "刺激"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壊れた時計を、そっと刺激した。", "explanation": "ここは〈修理する〉の意味。刺激は人の行動や考えを活発にする意味で、壊れた物を直す場面には使わない。"}, {"text": "洗濯物を刺激して、乾かした。", "explanation": "ここは〈乾かす〉の意味。刺激は人の行動や考えを活発にする意味で、物を乾かす場面には使わない。"}, {"text": "庭の雑草を刺激して、抜いた。", "explanation": "ここは〈抜く〉の意味。刺激は行動や考えを活発にさせる意味で、草を引き抜く場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51646, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友人との会話が私の考えに刺激した。", "corrected_sentence": "友人との会話が私の考えを刺激した。", "error_description": "刺激する（他動詞）の目的語は「を」で示す。「考えに」は誤り（正しくは「考えを刺激した」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51646, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい本が私の考えを刺激し。", "corrected_sentence": "新しい本が私の考えを刺激した。", "error_description": "過去の出来事を言い切る「た形」が必要。「刺激し」は連用形で、文末に置くと文が終わらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51649, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「参考にして」の「に」で、手本とする対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "「参考で」は手段や場所を示す。手本の対象を示す位置には合わない。"}, {"text": "を", "is_correct": false, "explanation": "「参考をして」は不自然。「参考にする」は「に」を取る。"}, {"text": "が", "is_correct": false, "explanation": "「参考が」は主語を示す。ここは手本の対象を示す位置なので合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。「参考にして」の「に」で、手本とする対象を示す。", "で": "「参考で」は手段や場所を示す。手本の対象を示す位置には合わない。", "を": "「参考をして」は不自然。「参考にする」は「に」を取る。", "が": "「参考が」は主語を示す。ここは手本の対象を示す位置なので合わない。"}, "error_tags": {"で": "手段・場所の誤り", "を": "目的語の誤り", "が": "主語の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51649, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「参考にして」の「に」で、手本とする対象を示す。"}, {"text": "の", "is_correct": false, "explanation": "「参考の」は名詞を修飾する形で、「雑誌を参考の」と続けても「して」の動詞句が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「参考へ」は方向を示す。手本の対象を示す位置には合わず、「参考へして」は文が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「参考より」は比較を示し、比べる対象がないので「して」に続かず文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「参考にして」の「に」で、手本とする対象を示す。", "の": "「参考の」は名詞を修飾する形で、「雑誌を参考の」と続けても「して」の動詞句が成り立たない。", "へ": "「参考へ」は方向を示す。手本の対象を示す位置には合わず、「参考へして」は文が通らない。", "より": "「参考より」は比較を示し、比べる対象がないので「して」に続かず文が成り立たない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51649, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かを作るときに、見てまねをするためのもの。", "primary_collocate": null, "pronunciation": "さんこう", "ipa": "saŋkoː", "syllable_count": 4, "sentences": [{"text": "弟は図鑑の写真を参考にして、紙で恐竜を作った。", "target_word": "参考", "complexity_tier": "T3", "furigana": "おとうとはずかんのしゃしんをさんこうにして、かみできょうりゅうをつくった。", "sentence_source": "generated"}, {"text": "母は雑誌の料理を参考にして、夕食を作った。", "target_word": "参考", "complexity_tier": "T3", "furigana": "はははざっしのりょうりをさんこうにして、ゆうしょくをつくった。", "sentence_source": "generated"}, {"text": "見本を参考に、同じ形のぼうしを編んだ。", "target_word": "参考", "complexity_tier": "T3", "furigana": "みほんをさんこうに、おなじかたちのぼうしをあんだ。", "sentence_source": "generated"}, {"text": "この絵を参考にして、花の模様を描く。", "target_word": "参考", "complexity_tier": "T3", "furigana": "このえをさんこうにして、はなのもようをかく。", "sentence_source": "generated"}, {"text": "兄は設計図を参考に、木の船を組み立てた。", "target_word": "参考", "complexity_tier": "T3", "furigana": "あにはせっけいずをさんこうに、きのふねをくみたてた。", "sentence_source": "generated"}, {"text": "私は先生が作った作品を参考にして、粘土で犬を作った。", "target_word": "参考", "complexity_tier": "T3", "furigana": "わたしはせんせいがつくったさくひんをさんこうにして、ねんどでいぬをつくった。", "sentence_source": "generated"}, {"text": "本物の写真を参考にすると、絵が上手に描ける。", "target_word": "参考", "complexity_tier": "T3", "furigana": "ほんもののしゃしんをさんこうにすると、えがじょうずにかける。", "sentence_source": "generated"}, {"text": "彼女は洋服の雑誌を参考にして、自分でスカートを縫った。", "target_word": "参考", "complexity_tier": "T3", "furigana": "かのじょはようふくのざっしをさんこうにして、じぶんでスカートをぬった。", "sentence_source": "generated"}, {"text": "完成した家の模型を参考に、庭の形を決めた。", "target_word": "参考", "complexity_tier": "T3", "furigana": "かんせいしたいえのもけいをさんこうに、にわのかたちをきめた。", "sentence_source": "generated"}, {"text": "友だちのノートを参考にして、自由研究のポスターを作った。", "target_word": "参考", "complexity_tier": "T3", "furigana": "ともだちのノートをさんこうにして、じゆうけんきゅうのポスターをつくった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "参考", "label": "基本形"}, {"form": "参考にする", "label": "動詞句形"}, {"form": "参考にした", "label": "過去形"}, {"form": "参考にして", "label": "接続形"}], "register": "中立（常体）", "sense_fingerprint": "物を作るときに見てまねる手本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51649, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参考", "is_correct": true, "explanation": "正解。図鑑の写真を手本にして作るという意味で、「参考にして」が自然。"}, {"text": "中止", "is_correct": false, "explanation": "中止は途中でやめる意味で、写真を見てまねる文には合わない。"}, {"text": "解約", "is_correct": false, "explanation": "解約は契約を終わらせる意味で、写真を手本にする文には合わない。"}, {"text": "削除", "is_correct": false, "explanation": "削除は消す意味で、写真を見て恐竜を作る文の意味が成り立たない。"}], "explanations": {"参考": "正解。図鑑の写真を手本にして作るという意味で、「参考にして」が自然。", "中止": "中止は途中でやめる意味で、写真を見てまねる文には合わない。", "解約": "解約は契約を終わらせる意味で、写真を手本にする文には合わない。", "削除": "削除は消す意味で、写真を見て恐竜を作る文の意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "参考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店の棚には商品の参考が並べてある。", "explanation": "ここは〈見本〉（展示用の実物例）の意味。見本と取り違えやすいが、参考は見て真似る手本で、店頭に並べる品物にはならない。"}, {"text": "今日の参考は、ケーキを十個作ることだ。", "explanation": "ここは〈目標〉（達成を目指す到達点）の意味。目標と取り違えやすいが、参考は見て真似る手本で、目指す到達点ではないので合わない。"}, {"text": "玄関の参考に、赤いリボンを結んだ。", "explanation": "ここは〈目印〉（場所を示す印）の意味。目印と取り違えやすいが、参考は見て真似る手本で、場所を示す印にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51649, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参考", "is_correct": true, "explanation": "正解。本物の写真を手本にして描くという意味で、「参考にすると」が自然。"}, {"text": "延期", "is_correct": false, "explanation": "延期は予定を先送りする意味で、写真を見て絵を描く文には合わない。"}, {"text": "撤去", "is_correct": false, "explanation": "撤去は取り除く意味で、写真を見て絵を上手に描く文には合わない。"}, {"text": "放棄", "is_correct": false, "explanation": "放棄は投げ出す意味で、写真を手本に絵を描く文には合わない。"}], "explanations": {"参考": "正解。本物の写真を手本にして描くという意味で、「参考にすると」が自然。", "延期": "延期は予定を先送りする意味で、写真を見て絵を描く文には合わない。", "撤去": "撤去は取り除く意味で、写真を見て絵を上手に描く文には合わない。", "放棄": "放棄は投げ出す意味で、写真を手本に絵を描く文には合わない。"}, "sentence_index": 6, "correct_answer": "参考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この参考を店頭で配って、ケーキの宣伝をした。", "explanation": "ここは〈宣伝物〉（広告として配るもの）の意味。宣伝物と取り違えやすいが、参考は見て真似る手本で、配って宣伝に使うものではないので合わない。"}, {"text": "完成した参考に色をつけて、仕上げの絵を完成させた。", "explanation": "ここは〈下図〉（完成前の下書き）の意味。参考は見て真似る手本で、色を塗って仕上げる下書きにはならない。"}, {"text": "待ち合わせの参考に、赤い旗を立てた。", "explanation": "ここは〈目印〉（場所を示す印）の意味。参考は見て真似る手本で、待ち合わせ場所を示す旗の代わりにはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51649, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は絵本の挿絵を参考をして、折り紙で鶴を折った。", "corrected_sentence": "妹は絵本の挿絵を参考にして、折り紙で鶴を折った。", "error_description": "誤りは「参考をして」の「を」。正しくは「参考にして」の「に」で、「参考にする」は手本の対象を「に」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51649, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は雑誌の写真を参考にす、ケーキを飾り付けた。", "corrected_sentence": "姉は雑誌の写真を参考にして、ケーキを飾り付けた。", "error_description": "誤りは「参考にす」の「す」。正しくは「参考にして」の「して」で、文を続けるにはて形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51650, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「参考にして」の「に」で、材料として利用する対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "「参考で」は手段や場所を示す。利用の対象を示す位置には合わず、「して」と続かない。"}, {"text": "を", "is_correct": false, "explanation": "「参考をして」は不自然。「参考にする」は「に」を取る。"}, {"text": "が", "is_correct": false, "explanation": "「参考が」は主語を示す。ここは利用の対象を示す位置なので合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。「参考にして」の「に」で、材料として利用する対象を示す。", "で": "「参考で」は手段や場所を示す。利用の対象を示す位置には合わず、「して」と続かない。", "を": "「参考をして」は不自然。「参考にする」は「に」を取る。", "が": "「参考が」は主語を示す。ここは利用の対象を示す位置なので合わない。"}, "error_tags": {"で": "手段・場所の誤り", "を": "目的語の誤り", "が": "主語の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51650, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51650, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を進める際に、判断や決定の手がかりとして利用する材料や情報。", "primary_collocate": null, "pronunciation": "さんこう", "ipa": "saŋkoː", "syllable_count": 4, "sentences": [{"text": "そこで、デザインを決める際、子供が自由に描いた絵を参考にすることにした。", "target_word": "参考", "complexity_tier": "T4", "furigana": "そこで、デザインをきめるさい、こどもがじゆうにえがいたえをさんこうにすることにした。", "sentence_source": "mined"}, {"text": "先輩の意見を参考にして、旅行の計画を立て直した。", "target_word": "参考", "complexity_tier": "T3", "furigana": "せんぱいのいけんをさんこうにして、りょこうのけいかくをたてなおした。", "sentence_source": "generated"}, {"text": "購入前に、利用者の感想を参考にする人は多い。", "target_word": "参考", "complexity_tier": "T3", "furigana": "こうにゅうまえに、りようしゃのかんそうをさんこうにするひとはおおい。", "sentence_source": "generated"}, {"text": "この数字はあくまで参考であり、最終的な判断は担当者が行う。", "target_word": "参考", "complexity_tier": "T3", "furigana": "このすうじはあくまでさんこうであり、さいしゅうてきなはんだんはたんとうしゃがおこなう。", "sentence_source": "generated"}, {"text": "過去の事例を参考に、新しい規則を決めた。", "target_word": "参考", "complexity_tier": "T3", "furigana": "かこのじれいをさんこうに、あたらしいきそくをきめた。", "sentence_source": "generated"}, {"text": "専門家の話は、治療法を選ぶうえで大いに参考になった。", "target_word": "参考", "complexity_tier": "T3", "furigana": "せんもんかのはなしは、ちりょうほうをえらぶうえでおおいにさんこうになった。", "sentence_source": "generated"}, {"text": "値段を決める際、他店の価格を参考にした。", "target_word": "参考", "complexity_tier": "T3", "furigana": "ねだんをきめるさい、ほかてんのかかくをさんこうにした。", "sentence_source": "generated"}, {"text": "地図アプリの所要時間は参考程度に考えておいたほうがよい。", "target_word": "参考", "complexity_tier": "T3", "furigana": "ちずアプリのしょようじかんはさんこうていどにかんがえておいたほうがよい。", "sentence_source": "generated"}, {"text": "失敗した人の経験談は、これから始める人にとって参考になる。", "target_word": "参考", "complexity_tier": "T3", "furigana": "しっぱいしたひとのけいけんだんは、これからはじめるひとにとってさんこうになる。", "sentence_source": "generated"}, {"text": "試験の合格者の勉強法を参考にして、計画を作った。", "target_word": "参考", "complexity_tier": "T3", "furigana": "しけんのごうかくしゃのべんきょうほうをさんこうにして、けいかくをつくった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "参考", "label": "基本形"}, {"form": "参考にする", "label": "動詞句形"}, {"form": "参考になる", "label": "状態変化形"}, {"form": "参考にした", "label": "過去形"}], "register": "中立（常体）", "sense_fingerprint": "判断や決定の手がかりにする材料や情報", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51650, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参考", "is_correct": true, "explanation": "正解。判断の手がかりとして絵を利用するという意味で、「参考にする」が自然。"}, {"text": "延期", "is_correct": false, "explanation": "延期は予定を先送りする意味で、絵を判断の手がかりにする文脈には合わない。"}, {"text": "撤去", "is_correct": false, "explanation": "撤去は取り除く意味で、絵を手がかりに使う文とは意味が合わない。"}, {"text": "放棄", "is_correct": false, "explanation": "放棄は投げ出す意味で、絵を利用する文には合わない。"}], "explanations": {"参考": "正解。判断の手がかりとして絵を利用するという意味で、「参考にする」が自然。", "延期": "延期は予定を先送りする意味で、絵を判断の手がかりにする文脈には合わない。", "撤去": "撤去は取り除く意味で、絵を手がかりに使う文とは意味が合わない。", "放棄": "放棄は投げ出す意味で、絵を利用する文には合わない。"}, "sentence_index": 0, "correct_answer": "参考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "安全の参考として、この数値は必ず守らなければならない。", "explanation": "ここは〈基準〉（守るべき規準）の意味。基準と取り違えやすいが、参考は強制力のない材料なので、必ず守る文には合わない。"}, {"text": "今月の参考は、売上を十割増しにすることだ。", "explanation": "ここは〈目標〉（達成を目指す到達点）の意味。目標と取り違えやすいが、参考は判断の材料であって目指す到達点ではないので合わない。"}, {"text": "交差点の参考に、赤い旗を立てた。", "explanation": "ここは〈目印〉（場所を示す印）の意味。目印と取り違えやすいが、参考は判断の材料で、場所を示す旗の代わりにはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51650, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参考", "is_correct": true, "explanation": "正解。他店の価格を判断の手がかりにしたという意味で、「参考にした」が自然。"}, {"text": "中断", "is_correct": false, "explanation": "中断は途中で止める意味で、価格を比べて決める文には合わない。"}, {"text": "解約", "is_correct": false, "explanation": "解約は契約を終わらせる意味で、他店の価格を手がかりにする文脈では成り立たない。"}, {"text": "削除", "is_correct": false, "explanation": "削除は消し去る意味で、価格を判断材料に使う文とは合わない。"}], "explanations": {"参考": "正解。他店の価格を判断の手がかりにしたという意味で、「参考にした」が自然。", "中断": "中断は途中で止める意味で、価格を比べて決める文には合わない。", "解約": "解約は契約を終わらせる意味で、他店の価格を手がかりにする文脈では成り立たない。", "削除": "削除は消し去る意味で、価格を判断材料に使う文とは合わない。"}, "sentence_index": 6, "correct_answer": "参考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生の参考に従って、課題を提出した。", "explanation": "ここは〈指示〉（従うべき命令）の意味。参考は自分で判断するための材料で、従う対象にはならない。"}, {"text": "店頭の参考として、新しい商品を一つ並べた。", "explanation": "ここは〈見本〉（展示用の実物例）の意味。参考は判断の材料で、店頭に並べる実物例とは違うので合わない。"}, {"text": "この参考は全員に適用される。", "explanation": "ここは〈規定〉の意味。参考は強制力のない材料なので、全員に適用するという文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51650, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は地図の情報を参考をして、ハイキングの計画を立てた。", "corrected_sentence": "兄は地図の情報を参考にして、ハイキングの計画を立てた。", "error_description": "誤りは「参考をして」の「を」。正しくは「参考にして」の「に」で、「参考にする」は利用の対象を「に」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51650, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店長は売上の資料を参考にす、新しい販売計画を作った。", "corrected_sentence": "店長は売上の資料を参考にして、新しい販売計画を作った。", "error_description": "誤りは「参考にす」の「す」。正しくは「参考にして」の「して」で、文を続けるにはて形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51651, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「よくない」の主語を示す。「雰囲気がよくない」が自然。"}, {"text": "で", "is_correct": false, "explanation": "「雰囲気でよくない」は手段の文脈にならず不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「雰囲気からよくない」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「雰囲気へよくない」は意味をなさない。"}], "correct_answer": "が", "explanations": {"が": "「よくない」の主語を示す。「雰囲気がよくない」が自然。", "で": "「雰囲気でよくない」は手段の文脈にならず不自然。", "から": "起点を示すが、「雰囲気からよくない」は成り立たない。", "へ": "方向を示すが、「雰囲気へよくない」は意味をなさない。"}, "error_tags": {"で": "手段・場所", "から": "起点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51651, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「大切にする」の目的語を示す。「雰囲気を大切にする」が自然。"}, {"text": "に", "is_correct": false, "explanation": "「雰囲気に大切にする」は成り立たず、「大切にする」は「を」を取る。"}, {"text": "と", "is_correct": false, "explanation": "「雰囲気と大切にする」は文として不自然。"}, {"text": "の", "is_correct": false, "explanation": "「雰囲気の大切にする」は修飾関係が成り立たず、文として不自然。"}], "correct_answer": "を", "explanations": {"を": "「大切にする」の目的語を示す。「雰囲気を大切にする」が自然。", "に": "「雰囲気に大切にする」は成り立たず、「大切にする」は「を」を取る。", "と": "「雰囲気と大切にする」は文として不自然。", "の": "「雰囲気の大切にする」は修飾関係が成り立たず、文として不自然。"}, "error_tags": {"に": "相手・位置", "と": "相手・引用", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51651, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "その場所の感じや空気のことです。", "primary_collocate": null, "pronunciation": "ふんいき", "ipa": "ɸɯɴ.i.ki", "syllable_count": 4, "sentences": [{"text": "このカフェは落ち着いた雰囲気で、ゆっくり本が読める。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "このカフェは落[お]ち着[つ]いた雰囲気[ふんいき]で、ゆっくり本[ほん]が読[よ]める。", "sentence_source": "generated"}, {"text": "駅前の店は雰囲気がよくないので、あまり入りたくない。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の店[みせ]は雰囲気[ふんいき]がよくないので、あまり入[はい]りたくない。", "sentence_source": "generated"}, {"text": "京都の古い旅館は、静かで和風の雰囲気に包まれている。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "京都[きょうと]の古[ふる]い旅館[りょかん]は、静[しず]かで和風[わふう]の雰囲気[ふんいき]に包[つつ]まれている。", "sentence_source": "generated"}, {"text": "教室の雰囲気が明るいと、生徒も発言しやすい。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の雰囲気[ふんいき]が明[あか]るいと、生徒[せいと]も発言[はつげん]しやすい。", "sentence_source": "generated"}, {"text": "結婚式の会場は華やかな雰囲気で、みんな笑顔だった。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]の会場[かいじょう]は華[はな]やかな雰囲気[ふんいき]で、みんな笑顔[えがお]だった。", "sentence_source": "generated"}, {"text": "雰囲気のいいレストランを予約して、記念日を祝った。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "雰囲気[ふんいき]のいいレストランを予約[よやく]して、記念日[きねんび]を祝[いわ]った。", "sentence_source": "generated"}, {"text": "夜の公園は昼とは違う雰囲気で、少し怖かった。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "夜[よる]の公園[こうえん]は昼[ひる]とは違[ちが]う雰囲気[ふんいき]で、少[すこ]し怖[こわ]かった。", "sentence_source": "generated"}, {"text": "店の雰囲気を大切にするため、音楽は小さめにしている。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "店[みせ]の雰囲気[ふんいき]を大切[たいせつ]にするため、音楽[おんがく]は小[ちい]さめにしている。", "sentence_source": "generated"}, {"text": "病院の待合室は静かな雰囲気で、みな黙って順番を待っていた。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "病院[びょういん]の待合室[まちあいしつ]は静[しず]かな雰囲気[ふんいき]で、みな黙[だま]って順番[じゅんばん]を待[ま]っていた。", "sentence_source": "generated"}, {"text": "この部屋は木の家具が多く、温かい雰囲気がある。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "この部屋[へや]は木[き]の家具[かぐ]が多[おお]く、温[あたた]かい雰囲気[ふんいき]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雰囲気", "label": "基本形"}, {"form": "雰囲気の", "label": "連体形(の)"}, {"form": "雰囲気が", "label": "主格形(が)"}], "register": "neutral", "sense_fingerprint": "店・部屋・町など、ある場所が持つ空気や居心地の感じ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91bf9503-6e90-4a50-bc73-1b4ba1d76038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51651, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雰囲気", "is_correct": true, "explanation": "店の空気や居心地を表し、「落ち着いた」で修飾されて自然。"}, {"text": "眠気", "is_correct": false, "explanation": "「落ち着いた眠気で」は意味をなさない。眠気は人の状態。"}, {"text": "金額", "is_correct": false, "explanation": "「落ち着いた金額で」は不自然で、場所の感じを表さない。"}, {"text": "締め切り", "is_correct": false, "explanation": "期限を指すので、場所の空気を表す文脈には合わない。"}], "explanations": {"雰囲気": "店の空気や居心地を表し、「落ち着いた」で修飾されて自然。", "眠気": "「落ち着いた眠気で」は意味をなさない。眠気は人の状態。", "金額": "「落ち着いた金額で」は不自然で、場所の感じを表さない。", "締め切り": "期限を指すので、場所の空気を表す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "雰囲気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は雰囲気が広くて、家具を十個置ける。", "explanation": "ここは〈広さ〉の意味。雰囲気は広さを測れず、部屋の大きさには使わない。"}, {"text": "この店は雰囲気の値段が高く、ランチも二千円を超える。", "explanation": "ここは〈値段〉の意味。雰囲気には値段がつかないので、料金の話には使わない。"}, {"text": "引っ越しの日、ソファと一緒に雰囲気を運んだ。", "explanation": "ここは〈物〉の意味。雰囲気は目に見えず運べないので、ソファと並べて運ぶ物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51651, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雰囲気", "is_correct": true, "explanation": "場所が持つ感じを表し、「昼とは違う」で修飾されて自然。"}, {"text": "体温", "is_correct": false, "explanation": "「昼とは違う体温で」は意味をなさない。体温は人の体の状態。"}, {"text": "年齢", "is_correct": false, "explanation": "「昼とは違う年齢で」は意味をなさない。年齢は人の属性で、場所には当てはまらない。"}, {"text": "値段", "is_correct": false, "explanation": "「昼とは違う値段で」は文として成り立たない。"}], "explanations": {"雰囲気": "場所が持つ感じを表し、「昼とは違う」で修飾されて自然。", "体温": "「昼とは違う体温で」は意味をなさない。体温は人の体の状態。", "年齢": "「昼とは違う年齢で」は意味をなさない。年齢は人の属性で、場所には当てはまらない。", "値段": "「昼とは違う値段で」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "雰囲気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店の雰囲気が三人いて、席がいっぱいだ。", "explanation": "ここは〈人〉の意味。雰囲気は人ではないので、人数を数える主語にはできない。"}, {"text": "エアコンで雰囲気を二十五度に設定した。", "explanation": "ここは〈温度〉の意味。雰囲気は温度のように度数で設定できないので、エアコンの設定には使わない。"}, {"text": "店の雰囲気が風邪をひいて、今日は休みだ。", "explanation": "ここは〈体〉の意味。雰囲気は体を持たないので、風邪をひくことはできず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51651, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は落ち着いた雰囲気が気に入るて、よく来ている。", "corrected_sentence": "この店は落ち着いた雰囲気が気に入って、よく来ている。", "error_description": "「気に入る」のテ形は「気に入って」。「気に入るて」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51651, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店の雰囲気を合わせて音楽を選んでいる。", "corrected_sentence": "店の雰囲気に合わせて音楽を選んでいる。", "error_description": "「合わせる」は「に」を取る。「を」は誤りで、正しくは「雰囲気に合わせて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51652, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「持つ」の目的語を示す。「優しい雰囲気を持つ」が自然。"}, {"text": "に", "is_correct": false, "explanation": "「雰囲気に持つ」は不自然で、「持つ」は目的語に「を」を取る。"}, {"text": "で", "is_correct": false, "explanation": "「雰囲気で持つ」は手段を表す文脈にならず、意味をなさない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「雰囲気へ持つ」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「持つ」の目的語を示す。「優しい雰囲気を持つ」が自然。", "に": "「雰囲気に持つ」は不自然で、「持つ」は目的語に「を」を取る。", "で": "「雰囲気で持つ」は手段を表す文脈にならず、意味をなさない。", "へ": "方向を示すが、「雰囲気へ持つ」は成り立たない。"}, "error_tags": {"に": "相手・位置", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51652, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ある」の主語を示す。「雰囲気があるので」が自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「雰囲気からあるので」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「雰囲気よりあるので」は文として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「雰囲気とあるので」は意味が通らず、「ある」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「ある」の主語を示す。「雰囲気があるので」が自然。", "から": "起点を示すが、「雰囲気からあるので」は成り立たない。", "より": "比較を示すが、「雰囲気よりあるので」は文として不自然。", "と": "「雰囲気とあるので」は意味が通らず、「ある」の主語にはならない。"}, "error_tags": {"から": "起点", "より": "比較", "と": "相手・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51652, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "その場に漂う、人や物から受ける全体的な感じ。", "primary_collocate": null, "pronunciation": "ふんいき", "ipa": "ɸɯɴ.i.ki", "syllable_count": 4, "sentences": [{"text": "最終的に、その雰囲気を取り入れた、木漏れ日が差し込む開放的な小屋が完成し、家族の新たな憩いの場となった。", "target_word": "雰囲気", "complexity_tier": "T4", "furigana": "最終的[さいしゅうてき]に、その雰囲気[ふんいき]を取[と]り入[い]れた、木漏[こも]れ日[び]が差[さ]し込[こ]む開放的[かいほうてき]な小屋[こや]が完成[かんせい]し、家族[かぞく]の新[あら]たな憩[いこ]いの場[ば]となった。", "sentence_source": "mined"}, {"text": "彼女は優しい雰囲気を持っていて、初対面でもすぐ話しやすかった。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は優[やさ]しい雰囲気[ふんいき]を持[も]っていて、初対面[しょたいめん]でもすぐ話[はな]しやすかった。", "sentence_source": "generated"}, {"text": "この映画は昭和の雰囲気がよく出ていて、まるで当時にいるようだった。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "この映画[えいが]は昭和[しょうわ]の雰囲気[ふんいき]がよく出[で]ていて、まるで当時[とうじ]にいるようだった。", "sentence_source": "generated"}, {"text": "新しい店長が来てから、店の雰囲気がずいぶん明るくなった。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "新[あたら]しい店長[てんちょう]が来[き]てから、店[みせ]の雰囲気[ふんいき]がずいぶん明[あか]るくなった。", "sentence_source": "generated"}, {"text": "彼は怖い雰囲気の人だと思っていたが、話してみると親切だった。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "彼[かれ]は怖[こわ]い雰囲気[ふんいき]の人[ひと]だと思[おも]っていたが、話[はな]してみると親切[しんせつ]だった。", "sentence_source": "generated"}, {"text": "古い街並みの雰囲気が気に入って、この町に引っ越すことにした。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "古[ふる]い街並[まちな]みの雰囲気[ふんいき]が気[き]に入[い]って、この町[まち]に引[ひ]っ越[こ]すことにした。", "sentence_source": "generated"}, {"text": "会議の雰囲気が重かったので、誰も意見を言おうとしなかった。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "会議[かいぎ]の雰囲気[ふんいき]が重[おも]かったので、誰[だれ]も意見[いけん]を言[い]おうとしなかった。", "sentence_source": "generated"}, {"text": "この曲は秋らしい雰囲気があるので、静かな夜によく合う。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "この曲[きょく]は秋[あき]らしい雰囲気[ふんいき]があるので、静[しず]かな夜[よる]によく合[あ]う。", "sentence_source": "generated"}, {"text": "髪型を変えただけで、先生の雰囲気ががらりと変わった。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "髪型[かみがた]を変[か]えただけで、先生[せんせい]の雰囲気[ふんいき]ががらりと変[か]わった。", "sentence_source": "generated"}, {"text": "母の若いころの写真は、今の私とよく似た雰囲気だ。", "target_word": "雰囲気", "complexity_tier": "T3", "furigana": "母[はは]の若[わか]いころの写真[しゃしん]は、今[いま]の私[わたし]とよく似[に]た雰囲気[ふんいき]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雰囲気", "label": "基本形"}, {"form": "雰囲気の", "label": "連体形(の)"}, {"form": "雰囲気が", "label": "主格形(が)"}], "register": "neutral", "sense_fingerprint": "人・物・場面全体から受ける、言葉にしにくい総合的な印象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: がらり (Zipf 2.1)']::text[], '91bf9503-6e90-4a50-bc73-1b4ba1d76038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51652, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雰囲気", "is_correct": true, "explanation": "その場全体の感じを表し、「取り入れる」の対象になる。"}, {"text": "眠気", "is_correct": false, "explanation": "「その眠気を取り入れた」は意味をなさない。眠気は自分の状態で、取り入れる対象ではない。"}, {"text": "金額", "is_correct": false, "explanation": "「その金額を取り入れた」は文として成り立たない。"}, {"text": "締め切り", "is_correct": false, "explanation": "期限を指すので、「取り入れた」の対象にはならない。"}], "explanations": {"雰囲気": "その場全体の感じを表し、「取り入れる」の対象になる。", "眠気": "「その眠気を取り入れた」は意味をなさない。眠気は自分の状態で、取り入れる対象ではない。", "金額": "「その金額を取り入れた」は文として成り立たない。", "締め切り": "期限を指すので、「取り入れた」の対象にはならない。"}, "sentence_index": 0, "correct_answer": "雰囲気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カレーを作るために、雰囲気を三つ買ってきた。", "explanation": "ここは〈材料〉の意味。雰囲気は買えず数えられないので、材料の代わりにはならない。"}, {"text": "彼は雰囲気が力持ちで、重い荷物も一人で運べる。", "explanation": "ここは〈体力〉の意味。雰囲気は場の感じを表すので、人の力の強さには使わず合わない。"}, {"text": "このはかりは雰囲気を0.1グラム単位で計れる。", "explanation": "ここは〈重さ〉の意味。雰囲気は計量できないので、はかりで計る対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51652, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雰囲気", "is_correct": true, "explanation": "会議全体の重苦しい感じを表し、「重かった」と合う。"}, {"text": "空腹", "is_correct": false, "explanation": "「会議の空腹が重かった」は意味をなさない。空腹は体の感覚。"}, {"text": "体重", "is_correct": false, "explanation": "会議に体重は結びつかず、「重かった」も場の感じとして不自然。"}, {"text": "時給", "is_correct": false, "explanation": "給与の額を指すので、会議の雰囲気を表せない。"}], "explanations": {"雰囲気": "会議全体の重苦しい感じを表し、「重かった」と合う。", "空腹": "「会議の空腹が重かった」は意味をなさない。空腹は体の感覚。", "体重": "会議に体重は結びつかず、「重かった」も場の感じとして不自然。", "時給": "給与の額を指すので、会議の雰囲気を表せない。"}, "sentence_index": 6, "correct_answer": "雰囲気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このセーターは雰囲気がざらざらして、肌に合わない。", "explanation": "ここは〈手触り〉の意味。雰囲気は触って感じるものではないので、ざらざらといった触感には使わない。"}, {"text": "隣の部屋の雰囲気が大きくて、夜は眠れない。", "explanation": "ここは〈音〉の意味。雰囲気には大きさや音量がなく、騒音の説明には使えない。"}, {"text": "その提案を聞いて、雰囲気はにっこり笑った。", "explanation": "ここは〈人〉の意味。雰囲気は笑うことができないので、笑う主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51652, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その店は落ち着いた雰囲気をあり、ゆっくり食事ができる。", "corrected_sentence": "その店は落ち着いた雰囲気があり、ゆっくり食事ができる。", "error_description": "「ある」は主語の「雰囲気」に「が」を取る。「を」は誤りで、正しくは「雰囲気があり」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51652, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その絵からは、明るい雰囲気を食べている。", "corrected_sentence": "その絵からは、明るい雰囲気を感じている。", "error_description": "雰囲気は感じ取るものなので、「感じる」が正しい。「食べる」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51653, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「詰まる」の主語「ごみ」を示す。「ごみが詰まって」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「ごみを詰まって」は自動詞「詰まる」と合わず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「ごみへ詰まって」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「ごみから詰まって」は意味をなさない。"}], "correct_answer": "が", "explanations": {"が": "「詰まる」の主語「ごみ」を示す。「ごみが詰まって」が自然。", "を": "「ごみを詰まって」は自動詞「詰まる」と合わず、不自然。", "へ": "方向を示すが、「ごみへ詰まって」は成り立たない。", "から": "起点を示すが、「ごみから詰まって」は意味をなさない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51653, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「詰まる」の主語「インク」を示す。「インクが詰まって」が自然。"}, {"text": "の", "is_correct": false, "explanation": "「インクの詰まって」は修飾になり、文の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「インクと詰まって」は主語を示せず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「インクより詰まって」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「詰まる」の主語「インク」を示す。「インクが詰まって」が自然。", "の": "「インクの詰まって」は修飾になり、文の主語にならない。", "と": "「インクと詰まって」は主語を示せず、不自然。", "より": "比較を示すが、「インクより詰まって」は成り立たない。"}, "error_tags": {"の": "所属・修飾", "と": "相手・引用", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51653, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものがたくさん入っていて、動かなくなることです。", "primary_collocate": null, "pronunciation": "つまる", "ipa": "tsɯ.ma.ɾɯ", "syllable_count": 3, "sentences": [{"text": "風邪をひいて鼻が詰まり、夜よく眠れなかった。", "target_word": "詰まり", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいて鼻[はな]が詰[つ]まり、夜[よる]よく眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "台所の排水口にごみが詰まって、水が流れない。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "台所[だいどころ]の排水口[はいすいこう]にごみが詰[つ]まって、水[みず]が流[なが]れない。", "sentence_source": "generated"}, {"text": "餅が喉に詰まって、お正月に救急車を呼ぶ人もいる。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "餅[もち]が喉[のど]に詰[つ]まって、お正月[しょうがつ]に救急車[きゅうきゅうしゃ]を呼[よ]ぶ人[ひと]もいる。", "sentence_source": "generated"}, {"text": "落ち葉で雨どいが詰まり、雨水が外にあふれてしまった。", "target_word": "詰まり", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]で雨[あま]どいが詰[つ]まり、雨水[あまみず]が外[そと]にあふれてしまった。", "sentence_source": "generated"}, {"text": "トイレが詰まったので、業者に直してもらった。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "トイレが詰[つ]まったので、業者[ぎょうしゃ]に直[なお]してもらった。", "sentence_source": "generated"}, {"text": "フィルターに髪の毛が詰まると、掃除機の力が弱くなる。", "target_word": "詰まる", "complexity_tier": "T3", "furigana": "フィルターに髪[かみ]の毛[け]が詰[つ]まると、掃除機[そうじき]の力[ちから]が弱[よわ]くなる。", "sentence_source": "generated"}, {"text": "古い水道管に汚れが詰まって、蛇口から水が出なくなった。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "古[ふる]い水道管[すいどうかん]に汚[よご]れが詰[つ]まって、蛇口[じゃぐち]から水[みず]が出[で]なくなった。", "sentence_source": "generated"}, {"text": "ペンの先にインクが詰まって、字が書けなくなった。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "ペンの先[さき]にインクが詰[つ]まって、字[じ]が書[か]けなくなった。", "sentence_source": "generated"}, {"text": "鼻が詰まっているときは、温かいお茶を飲むと楽になる。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "鼻[はな]が詰[つ]まっているときは、温[あたた]かいお茶[ちゃ]を飲[の]むと楽[らく]になる。", "sentence_source": "generated"}, {"text": "排水管が詰まった原因を調べたら、小さなおもちゃが出てきた。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "排水管[はいすいかん]が詰[つ]まった原因[げんいん]を調[しら]べたら、小[ちい]さなおもちゃが出[で]てきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "詰まる", "label": "終止形"}, {"form": "詰まった", "label": "過去形"}, {"form": "詰まって", "label": "テ形"}, {"form": "詰まらない", "label": "否定形"}, {"form": "詰まります", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "管・穴・鼻・喉などにものが入ってふさがり、通らなくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91bf9503-6e90-4a50-bc73-1b4ba1d76038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51653, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "詰まり", "is_correct": true, "explanation": "「鼻が詰まり」の形。通り道がふさがる意味に合う。"}, {"text": "眠り", "is_correct": false, "explanation": "「鼻が眠り」は主語と合わず、意味をなさない。"}, {"text": "笑い", "is_correct": false, "explanation": "「鼻が笑い」は成り立たない。笑うのは人。"}, {"text": "優しさ", "is_correct": false, "explanation": "「鼻が優しさ」は意味をなさない。"}], "explanations": {"詰まり": "「鼻が詰まり」の形。通り道がふさがる意味に合う。", "眠り": "「鼻が眠り」は主語と合わず、意味をなさない。", "笑い": "「鼻が笑い」は成り立たない。笑うのは人。", "優しさ": "「鼻が優しさ」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "詰まり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試験前で頭に知識がぎっしり詰まって、もう一行も覚えられなかった。", "explanation": "ここは〈知識でいっぱいになる〉の意味。管などがふさがって動かなくなる意味の文ではないので、この問題では不正解。"}, {"text": "タイヤのパンクで空気が詰まって、どんどん抜けていった。", "explanation": "ここは〈抜ける〉の意味。詰まるは中に入って動かなくなることなので、空気が抜けていく様子とは合わない。"}, {"text": "この時計は針が詰まって動かないのに、いつも十分進んでいる。", "explanation": "ここは〈進む〉の意味。詰まって動かなくなるのは止まることなので、十分進んでいるという結果とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51653, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "詰まっ", "is_correct": true, "explanation": "「汚れが詰まって」の形。通り道がふさがる意味に合う。"}, {"text": "座っ", "is_correct": false, "explanation": "「汚れが座って」は意味をなさない。"}, {"text": "怒っ", "is_correct": false, "explanation": "「汚れが怒って」は成り立たない。"}, {"text": "払っ", "is_correct": false, "explanation": "「汚れが払って」は主語と合わず、意味をなさない。"}], "explanations": {"詰まっ": "「汚れが詰まって」の形。通り道がふさがる意味に合う。", "座っ": "「汚れが座って」は意味をなさない。", "怒っ": "「汚れが怒って」は成り立たない。", "払っ": "「汚れが払って」は主語と合わず、意味をなさない。"}, "sentence_index": 6, "correct_answer": "詰まっ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓が詰まって、冷たい風がよく入ってくる。", "explanation": "ここは〈開いている〉の意味。詰まるは隙間がなくなって動かなくなることなので、風がよく入る開いた状態とは合わない。"}, {"text": "この歌は、旅の思い出を口にすると言葉が詰まって、すらすら歌える。", "explanation": "ここは〈すらすら言える〉の意味。言葉が詰まるのは言い淀むことなので、すらすら歌えるという結果とは合わない。"}, {"text": "試合の終了直前、ボールがゴール前でするすると詰まって、一気に決まった。", "explanation": "ここは〈なめらかに通る〉の意味。詰まるは流れがふさがることなので、なめらかに通って決まった話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51653, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い排水管にごみを詰まって、水が流れない。", "corrected_sentence": "古い排水管にごみが詰まって、水が流れない。", "error_description": "「詰まる」は自動詞なので、主語の「ごみ」には「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "詰まっ", "is_correct": true, "explanation": "「ごみが詰まって」のテ形。「て」に続いて自然につながる。"}, {"text": "詰まり", "is_correct": false, "explanation": "連用形で、「て」に続けると不自然。"}, {"text": "詰まる", "is_correct": false, "explanation": "辞書形で、「て」に続けると「詰まるて」となり誤り。"}, {"text": "詰まら", "is_correct": false, "explanation": "未然形で、「て」には続かない。"}], "correct_form": "詰まっ", "base_form": "詰まる", "form_label": "テ形", "sentence_index": 1, "explanations": {"詰まっ": "「ごみが詰まって」のテ形。「て」に続いて自然につながる。", "詰まり": "連用形で、「て」に続けると不自然。", "詰まる": "辞書形で、「て」に続けると「詰まるて」となり誤り。", "詰まら": "未然形で、「て」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51653, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いポンプに砂が詰めて、水が出なくなった。", "corrected_sentence": "古いポンプに砂が詰まって、水が出なくなった。", "error_description": "主語は「砂」なので自動詞「詰まる」を使う。「詰めて」は他動詞で、主語と合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "詰まっ", "is_correct": true, "explanation": "「インクが詰まって」のテ形。「て」に続いて自然につながる。"}, {"text": "詰まった", "is_correct": false, "explanation": "過去形で、「て」に続けると「詰まったて」となり誤り。"}, {"text": "詰まって", "is_correct": false, "explanation": "テ形を重ねると「詰まってて」となり不自然。"}, {"text": "詰まらな", "is_correct": false, "explanation": "否定の語幹で、「て」には続かない。"}], "correct_form": "詰まっ", "base_form": "詰まる", "form_label": "テ形", "sentence_index": 7, "explanations": {"詰まっ": "「インクが詰まって」のテ形。「て」に続いて自然につながる。", "詰まった": "過去形で、「て」に続けると「詰まったて」となり誤り。", "詰まって": "テ形を重ねると「詰まってて」となり不自然。", "詰まらな": "否定の語幹で、「て」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51654, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「詰まる」の主語を示す。「思い出が詰まっている」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「思い出を詰まっている」は自動詞「詰まる」と合わず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「思い出で詰まっている」は手段の意味になり、不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「思い出から詰まっている」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「詰まる」の主語を示す。「思い出が詰まっている」が自然。", "を": "「思い出を詰まっている」は自動詞「詰まる」と合わず、不自然。", "で": "「思い出で詰まっている」は手段の意味になり、不自然。", "から": "起点を示すが、「思い出から詰まっている」は成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51654, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「詰まっていた」の主語を示す。「苦労が詰まっていた」が自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「苦労へ詰まっていた」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「苦労と詰まっていた」は主語を示せず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「苦労の詰まっていた」は修飾になり、文の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「詰まっていた」の主語を示す。「苦労が詰まっていた」が自然。", "へ": "方向を示すが、「苦労へ詰まっていた」は成り立たない。", "と": "「苦労と詰まっていた」は主語を示せず不自然。", "の": "「苦労の詰まっていた」は修飾になり、文の主語にならない。"}, "error_tags": {"へ": "方向", "と": "相手・引用", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51654, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "隙間なく満たされていて、それ以上何も入らない状態になること。転じて、ある感情や考えでいっぱいになること。", "primary_collocate": null, "pronunciation": "つまる", "ipa": "tsɯ.ma.ɾɯ", "syllable_count": 3, "sentences": [{"text": "現実的な設計図とは異なるが、その絵には彼が求める理想の世界が詰まっている。", "target_word": "詰まっ", "complexity_tier": "T4", "furigana": "現実的[げんじつてき]な設計図[せっけいず]とは異[こと]なるが、その絵[え]には彼[かれ]が求[もと]める理想[りそう]の世界[せかい]が詰[つ]まっている。", "sentence_source": "mined"}, {"text": "この小説には、作者の若いころの思い出が詰まっている。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]には、作者[さくしゃ]の若[わか]いころの思[おも]い出[で]が詰[つ]まっている。", "sentence_source": "generated"}, {"text": "母の手紙には、私への愛情がいっぱい詰まっていた。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "母[はは]の手紙[てがみ]には、私[わたし]への愛情[あいじょう]がいっぱい詰[つ]まっていた。", "sentence_source": "generated"}, {"text": "別れの場面で、胸が詰まって言葉が出なかった。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "別[わか]れの場面[ばめん]で、胸[むね]が詰[つ]まって言葉[ことば]が出[で]なかった。", "sentence_source": "generated"}, {"text": "この小さな店には、店主のこだわりが詰まっている。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "この小[ちい]さな店[みせ]には、店主[てんしゅ]のこだわりが詰[つ]まっている。", "sentence_source": "generated"}, {"text": "一年間の努力が詰まったノートを、彼は大切に保管している。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "一年間[いちねんかん]の努力[どりょく]が詰[つ]まったノートを、彼[かれ]は大切[たいせつ]に保管[ほかん]している。", "sentence_source": "generated"}, {"text": "このアルバムには、バンドの十年間の歴史が詰まっている。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "このアルバムには、バンドの十年間[じゅうねんかん]の歴史[れきし]が詰[つ]まっている。", "sentence_source": "generated"}, {"text": "彼の短い言葉には、長年の苦労が詰まっていた。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "彼[かれ]の短[みじか]い言葉[ことば]には、長年[ながねん]の苦労[くろう]が詰[つ]まっていた。", "sentence_source": "generated"}, {"text": "この歌には、故郷への切ない気持ちが詰まっている。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "この歌[うた]には、故郷[こきょう]への切[せつ]ない気持[きも]ちが詰[つ]まっている。", "sentence_source": "generated"}, {"text": "優勝トロフィーには、チーム全員の夢が詰まっている。", "target_word": "詰まっ", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]トロフィーには、チーム全員[ぜんいん]の夢[ゆめ]が詰[つ]まっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "詰まる", "label": "終止形"}, {"form": "詰まった", "label": "過去形"}, {"form": "詰まって", "label": "テ形"}, {"form": "詰まらない", "label": "否定形"}, {"form": "詰まります", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "作品や言葉などに思い・経験・感情がぎっしり込められている、または感情で胸がいっぱいになる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91bf9503-6e90-4a50-bc73-1b4ba1d76038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51654, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "詰まっ", "is_correct": true, "explanation": "「理想の世界が詰まっている」の形。ものや思いが中にいっぱいある意味に合う。"}, {"text": "食べ", "is_correct": false, "explanation": "「理想の世界が食べている」は主語と動詞が合わず、意味をなさない。"}, {"text": "泣い", "is_correct": false, "explanation": "「理想の世界が泣いている」は成り立たない。泣くのは人。"}, {"text": "見", "is_correct": false, "explanation": "「理想の世界が見ている」は、見る主体が世界では不自然。"}], "explanations": {"詰まっ": "「理想の世界が詰まっている」の形。ものや思いが中にいっぱいある意味に合う。", "食べ": "「理想の世界が食べている」は主語と動詞が合わず、意味をなさない。", "泣い": "「理想の世界が泣いている」は成り立たない。泣くのは人。", "見": "「理想の世界が見ている」は、見る主体が世界では不自然。"}, "sentence_index": 0, "correct_answer": "詰まっ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "恐怖で足が詰まって、一歩も動けなかった。", "explanation": "ここは〈身がすくむ〉の意味。恐怖で体が固まるのは『すくむ』を使い、詰まるは物や感情で満たされる状態に使うので合わない。"}, {"text": "研究が詰まって、三日で論文が完成した。", "explanation": "ここは〈順調に進む〉の意味。詰まるは行き詰まって止まることなので、三日で完成した話とは合わない。"}, {"text": "月末、財布が詰まって、一円も残らなかった。", "explanation": "ここは〈空になる〉の意味。詰まるは中がいっぱいの状態なので、残金ゼロとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51654, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "詰まっ", "is_correct": true, "explanation": "「歴史が詰まっている」の形。長い時間の中身がいっぱいある意味に合う。"}, {"text": "笑っ", "is_correct": false, "explanation": "「歴史が笑っている」は主語と動詞が合わず、意味をなさない。"}, {"text": "怒っ", "is_correct": false, "explanation": "「歴史が怒っている」は成り立たない。怒るのは人。"}, {"text": "座っ", "is_correct": false, "explanation": "「歴史が座っている」は比喩としても不自然。"}], "explanations": {"詰まっ": "「歴史が詰まっている」の形。長い時間の中身がいっぱいある意味に合う。", "笑っ": "「歴史が笑っている」は主語と動詞が合わず、意味をなさない。", "怒っ": "「歴史が怒っている」は成り立たない。怒るのは人。", "座っ": "「歴史が座っている」は比喩としても不自然。"}, "sentence_index": 6, "correct_answer": "詰まっ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は感動でいっぱい詰まって、言葉が出なかった。", "explanation": "ここは〈人全体が感情でいっぱいになる〉の意味。詰まるのは胸など体の部位が主語のときで、人全体には使わないので合わない。"}, {"text": "ステージの段差に、優勝の喜びが詰まって、つまずいた。", "explanation": "ここは〈つまずく〉の意味。詰まるは物や感情で満たされる意味で、段差につまずく動きは表さないので合わない。"}, {"text": "優勝の夢は、練習のたびに詰まって、少しずつしぼんでいった。", "explanation": "ここは〈しぼむ〉の意味。詰まるは中がいっぱいになることなので、しぼんでいく様子とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51654, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "あの手紙には、祖母の思いが詰めっていた。", "corrected_sentence": "あの手紙には、祖母の思いが詰まっていた。", "error_description": "「詰まっていた」が正しい形。「詰めって」は「詰める」の活用としても成り立たない誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "詰まっ", "is_correct": true, "explanation": "「ている」に続く形。「思い出が詰まっている」と自然につながる。"}, {"text": "詰まり", "is_correct": false, "explanation": "連用形で、「ている」には続かない。"}, {"text": "詰まる", "is_correct": false, "explanation": "辞書形で、「ている」の前には置けない。"}, {"text": "詰まら", "is_correct": false, "explanation": "未然形で、「ている」には続かない。"}], "correct_form": "詰まっ", "base_form": "詰まる", "form_label": "テ形", "sentence_index": 1, "explanations": {"詰まっ": "「ている」に続く形。「思い出が詰まっている」と自然につながる。", "詰まり": "連用形で、「ている」には続かない。", "詰まる": "辞書形で、「ている」の前には置けない。", "詰まら": "未然形で、「ている」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51654, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その家には、家族の笑い声を詰まっている。", "corrected_sentence": "その家には、家族の笑い声が詰まっている。", "error_description": "「詰まる」は自動詞で、主語の「笑い声」には「が」を使う。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "詰まっ", "is_correct": true, "explanation": "「ていた」に続く形。「苦労が詰まっていた」と自然につながる。"}, {"text": "詰まった", "is_correct": false, "explanation": "過去形で、「ていた」の前には置けない。"}, {"text": "詰まって", "is_correct": false, "explanation": "テ形で、「ていた」と続けると「詰まっていていた」となり不自然。"}, {"text": "詰まらな", "is_correct": false, "explanation": "否定の語幹で、「ていた」には続かない。"}], "correct_form": "詰まっ", "base_form": "詰まる", "form_label": "テ形", "sentence_index": 7, "explanations": {"詰まっ": "「ていた」に続く形。「苦労が詰まっていた」と自然につながる。", "詰まった": "過去形で、「ていた」の前には置けない。", "詰まって": "テ形で、「ていた」と続けると「詰まっていていた」となり不自然。", "詰まらな": "否定の語幹で、「ていた」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
