INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51655, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が入れるくらいの小さな建物。", "primary_collocate": null, "pronunciation": "こや", "ipa": "ko.ja", "syllable_count": 2, "sentences": [{"text": "森の奥に、誰も使っていない小さな小屋が建っている。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "森[もり]の奥[おく]に、誰[だれ]も使[つか]っていない小[ちい]さな小屋[こや]が建[た]っている。", "sentence_source": "generated"}, {"text": "木材を運んで、川の近くに小屋を建てた。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "木材[もくざい]を運[はこ]んで、川[かわ]の近[ちか]くに小屋[こや]を建[た]てた。", "sentence_source": "generated"}, {"text": "小屋の中は狭いが、ストーブがあるのであたたかい。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "小屋[こや]の中[なか]は狭[せま]いが、ストーブがあるのであたたかい。", "sentence_source": "generated"}, {"text": "畑の横にある小屋には、スコップやバケツが置いてある。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "畑[はたけ]の横[よこ]にある小屋[こや]には、スコップやバケツが置[お]いてある。", "sentence_source": "generated"}, {"text": "子供たちは、空き地に板を集めて秘密の小屋を作った。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "子供[こども]たちは、空[あ]き地[ち]に板[いた]を集[あつ]めて秘密[ひみつ]の小屋[こや]を作[つく]った。", "sentence_source": "generated"}, {"text": "嵐の夜、牧場の小屋で羊たちが身を寄せ合っていた。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "嵐[あらし]の夜[よる]、牧場[ぼくじょう]の小屋[こや]で羊[ひつじ]たちが身[み]を寄[よ]せ合[あ]っていた。", "sentence_source": "generated"}, {"text": "古い小屋の戸を開けると、ほこりのにおいがした。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "古[ふる]い小屋[こや]の戸[と]を開[あ]けると、ほこりのにおいがした。", "sentence_source": "generated"}, {"text": "池のそばの小屋は、釣り人が休むために使われている。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "池[いけ]のそばの小屋[こや]は、釣[つ]り人[びと]が休[やす]むために使[つか]われている。", "sentence_source": "generated"}, {"text": "小屋の屋根に雪が積もって、ぎしぎしと音を立てていた。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "小屋[こや]の屋根[やね]に雪[ゆき]が積[つ]もって、ぎしぎしと音[おと]を立[た]てていた。", "sentence_source": "generated"}, {"text": "彼は小屋の前で薪を割り、夕食の準備を始めた。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "彼[かれ]は小屋[こや]の前[まえ]で薪[まき]を割[わ]り、夕食[ゆうしょく]の準備[じゅんび]を始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "小屋", "label": "基本形"}, {"form": "小屋の", "label": "属格(の)"}, {"form": "小屋に", "label": "場所格(に)"}], "register": "neutral", "sense_fingerprint": "人が中に入れる程度の大きさの、粗末で小さな建物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: ぎしぎし (Zipf 1.64)']::text[], '91bf9503-6e90-4a50-bc73-1b4ba1d76038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51655, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小屋", "is_correct": true, "explanation": "人が入れる程度の小さな建物で、森の奥に建っている文脈に合う。"}, {"text": "花壇", "is_correct": false, "explanation": "花を植える区画で、建つものではない。「小さな花壇が建っている」は不自然。"}, {"text": "水槽", "is_correct": false, "explanation": "水を入れる容器で、建つものではない。"}, {"text": "岩", "is_correct": false, "explanation": "自然にあるもので、「建っている」とは言わない。"}], "explanations": {"小屋": "人が入れる程度の小さな建物で、森の奥に建っている文脈に合う。", "花壇": "花を植える区画で、建つものではない。「小さな花壇が建っている」は不自然。", "水槽": "水を入れる容器で、建つものではない。", "岩": "自然にあるもので、「建っている」とは言わない。"}, "sentence_index": 0, "correct_answer": "小屋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の日は、この小屋に大勢の観客が集まり、選手に大きな声援を送る。", "explanation": "ここは〈競技場・体育館〉の意味。大勢の観客が集まる施設には、人が入る程度の小さな建物を指す小屋は合わない。"}, {"text": "この小屋からは毎朝六時に特急列車が発車し、乗客が大勢乗り込む。", "explanation": "ここは〈駅〉の意味。特急列車が発着する施設には、人が入る程度の小さな建物を指す小屋は合わない。"}, {"text": "この小屋はガラス張りで広く、大勢の客が商品を選んで買い物をする。", "explanation": "ここは〈店舗〉の意味。広い売り場で客が買い物をする施設には、粗末な小屋は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51655, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小屋", "is_correct": true, "explanation": "古い小屋の戸として、古い建物の入口を指す文脈に合う。"}, {"text": "鞄", "is_correct": false, "explanation": "持ち運ぶ袋で、戸はない。「古い鞄の戸」は成り立たない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花を挿す容器で、戸はない。"}, {"text": "鉢", "is_correct": false, "explanation": "植物を植える容器で、戸はない。"}], "explanations": {"小屋": "古い小屋の戸として、古い建物の入口を指す文脈に合う。", "鞄": "持ち運ぶ袋で、戸はない。「古い鞄の戸」は成り立たない。", "花瓶": "花を挿す容器で、戸はない。", "鉢": "植物を植える容器で、戸はない。"}, "sentence_index": 6, "correct_answer": "小屋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市民は、この小屋で住民票を取り、窓口で税金を納める。", "explanation": "ここは〈市役所〉の意味。窓口で行政手続きを行う施設には、人が入る程度の小さな建物を指す小屋は合わない。"}, {"text": "新入社員はこの小屋に入寮し、共同の食堂で毎日の食事をとる。", "explanation": "ここは〈寮〉の意味。共同の食堂を備えた集合の施設は、小屋とは言わない。"}, {"text": "けが人はこの小屋に運ばれ、医師が手術を行った。", "explanation": "ここは〈病院〉の意味。手術の設備がある施設は、小屋では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51655, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "嵐の晩に、森の小屋が一晩過ごした。", "corrected_sentence": "嵐の晩に、森の小屋で一晩過ごした。", "error_description": "誤りは「が」。正しくは「小屋で過ごす」（場所を表す「で」）。「が」にすると小屋が過ごす主語になり、不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51655, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "川辺に小屋を張って、夏を過ごした。", "corrected_sentence": "川辺に小屋を建てて、夏を過ごした。", "error_description": "誤りは「張って」。正しくは「小屋を建てる」。「張る」はテントや幕に使う動詞で、小屋とは組み合わせない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
