INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51656, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「小屋を借りて」で、借りる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「小屋が借りて」では小屋が借りる主語になり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「小屋に借りて」では借りる相手や場所の形になり、借りる対象を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「小屋で借りて」では借りる場所になり、借りる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「小屋を借りて」で、借りる対象を示す。", "が": "「小屋が借りて」では小屋が借りる主語になり、文が成り立たない。", "に": "「小屋に借りて」では借りる相手や場所の形になり、借りる対象を表せない。", "で": "「小屋で借りて」では借りる場所になり、借りる対象を示せない。"}, "error_tags": {"が": "主語", "に": "相手・場所", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51656, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が住んだり、物を置いたりするための小さな建物。", "primary_collocate": null, "pronunciation": "こや", "ipa": "ko.ja", "syllable_count": 2, "sentences": [{"text": "庭の片隅に、子供たちが使う小屋を建てる計画が持ち上がった。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "庭[にわ]の片隅[かたすみ]に、子供[こども]たちが使[つか]う小屋[こや]を建[た]てる計画[けいかく]が持[も]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "最終的に、その雰囲気を取り入れた、木漏れ日が差し込む開放的な小屋が完成し、家族の新たな憩いの場となった。", "target_word": "小屋", "complexity_tier": "T4", "furigana": "最終的[さいしゅうてき]に、その雰囲気[ふんいき]を取[と]り入[い]れた、木漏[こも]れ日[び]が差[さ]し込[こ]む開放的[かいほうてき]な小屋[こや]が完成[かんせい]し、家族[かぞく]の新[あら]たな憩[いこ]いの場[ば]となった。", "sentence_source": "mined"}, {"text": "山の中の小屋で、猟師は一人静かに暮らしていた。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "山[やま]の中[なか]の小屋[こや]で、猟師[りょうし]は一人[ひとり]静[しず]かに暮[く]らしていた。", "sentence_source": "generated"}, {"text": "庭の小屋には、古い自転車や道具がしまってある。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "庭[にわ]の小屋[こや]には、古[ふる]い自転車[じてんしゃ]や道具[どうぐ]がしまってある。", "sentence_source": "generated"}, {"text": "急に雨が降ってきたので、畑の小屋で雨宿りした。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "急[きゅう]に雨[あめ]が降[ふ]ってきたので、畑[はたけ]の小屋[こや]で雨宿[あまやど]りした。", "sentence_source": "generated"}, {"text": "父は休みの日に、木で小さな小屋を作っている。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "父[ちち]は休[やす]みの日[ひ]に、木[き]で小[ちい]さな小屋[こや]を作[つく]っている。", "sentence_source": "generated"}, {"text": "吹雪がひどくなり、私たちは谷の小屋まで急いで逃げ込んだ。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "吹雪[ふぶき]がひどくなり、私[わたし]たちは谷[たに]の小屋[こや]まで急[いそ]いで逃[に]げ込[こ]んだ。", "sentence_source": "generated"}, {"text": "海辺の小屋を借りて、夏の間だけ絵を描いて過ごした。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "海辺[うみべ]の小屋[こや]を借[か]りて、夏[なつ]の間[あいだ]だけ絵[え]を描[か]いて過[す]ごした。", "sentence_source": "generated"}, {"text": "農具は小屋にまとめて入れておくと、探す手間が省ける。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "農具[のうぐ]は小屋[こや]にまとめて入[い]れておくと、探[さが]す手間[てま]が省[はぶ]ける。", "sentence_source": "generated"}, {"text": "この小屋は古いが、屋根も壁もしっかりしていて安心だ。", "target_word": "小屋", "complexity_tier": "T3", "furigana": "この小屋[こや]は古[ふる]いが、屋根[やね]も壁[かべ]もしっかりしていて安心[あんしん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "小屋", "label": "基本形"}, {"form": "小屋の", "label": "属格(の)"}, {"form": "小屋に", "label": "場所格(に)"}], "register": "neutral", "sense_fingerprint": "住まい・物置・作業などに使う、簡素で小さな建物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91bf9503-6e90-4a50-bc73-1b4ba1d76038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51656, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小屋", "is_correct": true, "explanation": "子供たちが使う、人が入れる程度の小さな建物を建てる文脈に合う。"}, {"text": "花壇", "is_correct": false, "explanation": "花を植える区画で、建てるものではない。「花壇を建てる」は不自然。"}, {"text": "水槽", "is_correct": false, "explanation": "水を入れる容器で、建てる対象にはならない。"}, {"text": "金魚鉢", "is_correct": false, "explanation": "金魚を入れる小さな鉢で、建てる対象にはならない。"}], "explanations": {"小屋": "子供たちが使う、人が入れる程度の小さな建物を建てる文脈に合う。", "花壇": "花を植える区画で、建てるものではない。「花壇を建てる」は不自然。", "水槽": "水を入れる容器で、建てる対象にはならない。", "金魚鉢": "金魚を入れる小さな鉢で、建てる対象にはならない。"}, "sentence_index": 0, "correct_answer": "小屋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい小屋は十二階建てで、一階には銀行が入っている。", "explanation": "ここは〈高層ビル〉の意味。小屋は小さく簡素な建物を指すので、十二階建てのビルには使わない。"}, {"text": "この小屋は客室が百室あり、ロビーでは毎朝ビュッフェを開いている。", "explanation": "ここは〈大型ホテル〉の意味。客室が百室もあり朝食を出す施設には、小さな建物を指す小屋は合わない。"}, {"text": "この小屋では数十台の機械が一日中動いていて、工員たちが交代で作業している。", "explanation": "ここは〈工場〉の意味。数十台の機械と多くの工員が働く大規模な施設には、小屋は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51656, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小屋", "is_correct": true, "explanation": "谷の小屋は身を隠せる小さな建物で、吹雪の中で逃げ込む場所として合う。"}, {"text": "金庫", "is_correct": false, "explanation": "中に物をしまう箱で、人が逃げ込む場所ではない。"}, {"text": "鉄塔", "is_correct": false, "explanation": "送電線を支える高い構造物で、人が逃げ込む場所ではない。"}, {"text": "石碑", "is_correct": false, "explanation": "文字を刻んだ石で、人が中に入る場所ではない。"}], "explanations": {"小屋": "谷の小屋は身を隠せる小さな建物で、吹雪の中で逃げ込む場所として合う。", "金庫": "中に物をしまう箱で、人が逃げ込む場所ではない。", "鉄塔": "送電線を支える高い構造物で、人が逃げ込む場所ではない。", "石碑": "文字を刻んだ石で、人が中に入る場所ではない。"}, "sentence_index": 6, "correct_answer": "小屋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この小屋は部屋数が多く、家族五人が余裕を持って暮らせる。", "explanation": "ここは〈住宅〉の意味。部屋数が多く家族五人が暮らす家は、小さく簡素な建物を指す小屋とは合わない。"}, {"text": "新入社員はこの小屋に入寮し、共同の食堂で毎日の食事をとる。", "explanation": "ここは〈寮〉の意味。共同の食堂を備えた集合の施設は、小屋とは言わない。"}, {"text": "けが人はこの小屋に運ばれ、医師が手術を行った。", "explanation": "ここは〈病院〉の意味。手術の設備がある施設は、小屋では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51656, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は休みの日に、裏山に小屋を張って道具を置いている。", "corrected_sentence": "父は休みの日に、裏山に小屋を建てて道具を置いている。", "error_description": "誤りは「張って」。正しくは「小屋を建てる」。「張る」はテントや幕に使う動詞で、小屋とは組み合わせない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51656, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の間、山の小屋が一人暮らしをした。", "corrected_sentence": "夏の間、山の小屋で一人暮らしをした。", "error_description": "誤りは「が」。正しくは「で」（場所を表す）。小屋が一人暮らしをするという主語になり、意味が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
