INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51657, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51657, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを自分のところに持ってきて、使うこと。", "primary_collocate": null, "pronunciation": "とりいれる", "ipa": "toɾiiɾeɾɯ", "syllable_count": 5, "sentences": [{"text": "窓を開けて、新しい空気を部屋に取り入れた。", "target_word": "取り入れた", "complexity_tier": "T2", "furigana": "窓[まど]を開[あ]けて、新[あたら]しい空気[くうき]を部屋[へや]に取[と]り入[い]れた。", "sentence_source": "generated"}, {"text": "雨が降る前に、洗濯物を取り入れてください。", "target_word": "取り入れて", "complexity_tier": "T2", "furigana": "雨[あめ]が降[ふ]る前[まえ]に、洗濯物[せんたくもの]を取[と]り入[い]れてください。", "sentence_source": "generated"}, {"text": "この家は大きな窓から光を取り入れる設計になっている。", "target_word": "取り入れる", "complexity_tier": "T3", "furigana": "この家[いえ]は大[おお]きな窓[まど]から光[ひかり]を取[と]り入[い]れる設計[せっけい]になっている。", "sentence_source": "generated"}, {"text": "農家の人は川の水を畑に取り入れて、野菜を育てている。", "target_word": "取り入れて", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は川[かわ]の水[みず]を畑[はたけ]に取[と]り入[い]れて、野菜[やさい]を育[そだ]てている。", "sentence_source": "generated"}, {"text": "船は海の水を取り入れて、機械を冷やしている。", "target_word": "取り入れて", "complexity_tier": "T3", "furigana": "船[ふね]は海[うみ]の水[みず]を取[と]り入[い]れて、機械[きかい]を冷[ひ]やしている。", "sentence_source": "generated"}, {"text": "祖父は夕方になると、庭の干し柿を家の中に取り入れる。", "target_word": "取り入れる", "complexity_tier": "T3", "furigana": "祖父[そふ]は夕方[ゆうがた]になると、庭[にわ]の干[ほ]し柿[がき]を家[いえ]の中[なか]に取[と]り入[い]れる。", "sentence_source": "generated"}, {"text": "冬の間、寒さを防ぐために、鉢の植物を部屋に取り入れた。", "target_word": "取り入れた", "complexity_tier": "T4", "furigana": "冬[ふゆ]の間[あいだ]、寒[さむ]さを防[ふせ]ぐために、鉢[はち]の植物[しょくぶつ]を部屋[へや]に取[と]り入[い]れた。", "sentence_source": "generated"}, {"text": "部屋に自然の光を取り入れると、昼間は電気をつけなくてもよい。", "target_word": "取り入れる", "complexity_tier": "T4", "furigana": "部屋[へや]に自然[しぜん]の光[ひかり]を取[と]り入[い]れると、昼間[ひるま]は電気[でんき]をつけなくてもよい。", "sentence_source": "generated"}, {"text": "夏は冷たい風を取り入れるため、夜に窓を開けて寝る。", "target_word": "取り入れる", "complexity_tier": "T3", "furigana": "夏[なつ]は冷[つめ]たい風[かぜ]を取[と]り入[い]れるため、夜[よる]に窓[まど]を開[あ]けて寝[ね]る。", "sentence_source": "generated"}, {"text": "工場は新しい機械を取り入れて、作業を速くした。", "target_word": "取り入れて", "complexity_tier": "T3", "furigana": "工場[こうじょう]は新[あたら]しい機械[きかい]を取[と]り入[い]れて、作業[さぎょう]を速[はや]くした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り入れる", "label": "辞書形"}, {"form": "取り入れ", "label": "連用形"}, {"form": "取り入れた", "label": "過去形"}, {"form": "取り入れて", "label": "て形"}, {"form": "取り入れない", "label": "否定形"}, {"form": "取り入れれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "物や空気や光を内へ持ち込んで使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91bf9503-6e90-4a50-bc73-1b4ba1d76038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51657, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り入れた", "is_correct": true, "explanation": "窓から外の空気を部屋へ持ち込む文脈で、「取り入れる」の意味に合う。"}, {"text": "掃除した", "is_correct": false, "explanation": "部屋を掃除するとは言えるが、「部屋に掃除した」は成り立たない。"}, {"text": "捨てた", "is_correct": false, "explanation": "空気を部屋に捨てるとは言えず、文の流れに合わない。"}, {"text": "散らかした", "is_correct": false, "explanation": "部屋を散らかすとは言えるが、空気を部屋に散らかすとは言えない。"}], "explanations": {"取り入れた": "窓から外の空気を部屋へ持ち込む文脈で、「取り入れる」の意味に合う。", "掃除した": "部屋を掃除するとは言えるが、「部屋に掃除した」は成り立たない。", "捨てた": "空気を部屋に捨てるとは言えず、文の流れに合わない。", "散らかした": "部屋を散らかすとは言えるが、空気を部屋に散らかすとは言えない。"}, "sentence_index": 0, "correct_answer": "取り入れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い倉庫を取り入れて、更地にした。", "explanation": "ここは〈取り壊す〉の意味。建物を壊す場面は「取り壊す」で表し、「取り入れる」は持ってきて使う意味なので合わない。"}, {"text": "箱から古い道具を取り入れて、中身を並べ直した。", "explanation": "ここは〈取り出す〉の意味。「取り入れる」は外から内へ持ち込む動作で、中から出す動作には使わない。"}, {"text": "なくした財布を取り入れて、すぐに喜んだ。", "explanation": "ここは〈取り戻す〉の意味。なくしたものを取り返す場面は「取り戻す」で表し、「取り入れる」は持ち込んで使う意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51657, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り入れた", "is_correct": true, "explanation": "寒さを防ぐために植物を部屋へ持ち込んだという流れに合う。"}, {"text": "踏んだ", "is_correct": false, "explanation": "植物を踏むとは言えるが、「部屋に踏んだ」は成り立たない。"}, {"text": "割った", "is_correct": false, "explanation": "鉢を割るとは言えるが、部屋に割ったとは言えず、寒さを防ぐ流れにも合わない。"}, {"text": "枯らした", "is_correct": false, "explanation": "植物を枯らすとは言えるが、部屋に枯らしたとは言えず、流れにも合わない。"}], "explanations": {"取り入れた": "寒さを防ぐために植物を部屋へ持ち込んだという流れに合う。", "踏んだ": "植物を踏むとは言えるが、「部屋に踏んだ」は成り立たない。", "割った": "鉢を割るとは言えるが、部屋に割ったとは言えず、寒さを防ぐ流れにも合わない。", "枯らした": "植物を枯らすとは言えるが、部屋に枯らしたとは言えず、流れにも合わない。"}, "sentence_index": 6, "correct_answer": "取り入れた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の雑草を取り入れて、ごみ袋に詰めた。", "explanation": "ここは〈取り除く〉の意味。雑草を抜く場面は「取り除く」で表し、「取り入れる」は内へ持ち込む意味なので合わない。"}, {"text": "古い看板を取り入れて、店の改装を進めた。", "explanation": "ここは〈撤去する〉の意味。取り除く動作は「撤去する」で表し、「取り入れる」は持ち込む意味なので合わない。"}, {"text": "使わなくなった家具を取り入れて、処分の手続きを済ませた。", "explanation": "ここは〈処分する〉の意味。不要になったものを手放す動作は「処分する」で表し、「取り入れる」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51657, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方になったので、庭の洗濯物で取り入れた。", "corrected_sentence": "夕方になったので、庭の洗濯物を取り入れた。", "error_description": "誤りは「で」。正しくは「洗濯物を取り入れた」（対象を示す「を」）。「で」にすると取り入れる対象が示せない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り入れて", "is_correct": true, "explanation": "て形。「取り入れてください」と依頼の形に続く。"}, {"text": "取り入れる", "is_correct": false, "explanation": "辞書形。「ください」に直接続けられず、依頼の形が成り立たない。"}, {"text": "取り入れ", "is_correct": false, "explanation": "連用形。「ください」に続かず、依頼の文として成り立たない。"}, {"text": "取り入れない", "is_correct": false, "explanation": "否定形。取り入れる指示と逆の意味になり、文が合わない。"}], "correct_form": "取り入れて", "base_form": "取り入れる", "form_label": "て形", "sentence_index": 1, "explanations": {"取り入れて": "て形。「取り入れてください」と依頼の形に続く。", "取り入れる": "辞書形。「ください」に直接続けられず、依頼の形が成り立たない。", "取り入れ": "連用形。「ください」に続かず、依頼の文として成り立たない。", "取り入れない": "否定形。取り入れる指示と逆の意味になり、文が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51657, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓を開けて、新しい空気を取り入れでから、ごみを片づけた。", "corrected_sentence": "窓を開けて、新しい空気を取り入れてから、ごみを片づけた。", "error_description": "誤りは「取り入れでから」。正しくは「取り入れてから」（て形）。「で」は誤った形で、この形は成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り入れる", "is_correct": true, "explanation": "辞書形。「取り入れると」と条件の「と」に続く形。"}, {"text": "取り入れ", "is_correct": false, "explanation": "連用形。「と」には続かず、文が成り立たない。"}, {"text": "取り入れて", "is_correct": false, "explanation": "て形。「と」には続かず、文が成り立たない。"}, {"text": "取り入れれば", "is_correct": false, "explanation": "仮定形。「と」と重なり、文の形が合わない。"}], "correct_form": "取り入れる", "base_form": "取り入れる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"取り入れる": "辞書形。「取り入れると」と条件の「と」に続く形。", "取り入れ": "連用形。「と」には続かず、文が成り立たない。", "取り入れて": "て形。「と」には続かず、文が成り立たない。", "取り入れれば": "仮定形。「と」と重なり、文の形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51658, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51658, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51658, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "外部から何かを自分のものとして受け入れ、利用すること。特に、アイデアや雰囲気などを取り込むこと。", "primary_collocate": null, "pronunciation": "とりいれる", "ipa": "toɾiiɾeɾɯ", "syllable_count": 5, "sentences": [{"text": "最終的に、その雰囲気を取り入れた、木漏れ日が差し込む開放的な小屋が完成し、家族の新たな憩いの場となった。", "target_word": "取り入れた", "complexity_tier": "T4", "furigana": "最終的[さいしゅうてき]に、その雰囲気[ふんいき]を取[と]り入[い]れた、木漏[こも]れ日[び]が差[さ]し込[こ]む開放的[かいほうてき]な小屋[こや]が完成[かんせい]し、家族[かぞく]の新[あら]たな憩[いこ]いの場[ば]となった。", "sentence_source": "mined"}, {"text": "新しいチームは、他の国のやり方を取り入れて、仕事の進め方を変えた。", "target_word": "取り入れて", "complexity_tier": "T3", "furigana": "新[あたら]しいチームは、他[ほか]の国[くに]のやり方[かた]を取[と]り入[い]れて、仕事[しごと]の進[すす]め方[かた]を変[か]えた。", "sentence_source": "generated"}, {"text": "私は友だちの意見を取り入れて、発表の内容を直した。", "target_word": "取り入れて", "complexity_tier": "T3", "furigana": "私[わたし]は友[とも]だちの意見[いけん]を取[と]り入[い]れて、発表[はっぴょう]の内容[ないよう]を直[なお]した。", "sentence_source": "generated"}, {"text": "この店は、和風の雰囲気を取り入れた内装が人気だ。", "target_word": "取り入れた", "complexity_tier": "T3", "furigana": "この店[みせ]は、和風[わふう]の雰囲気[ふんいき]を取[と]り入[い]れた内装[ないそう]が人気[にんき]だ。", "sentence_source": "generated"}, {"text": "監督は若い選手の考えも取り入れるつもりだと話した。", "target_word": "取り入れる", "complexity_tier": "T3", "furigana": "監督[かんとく]は若[わか]い選手[せんしゅ]の考[かんが]えも取[と]り入[い]れるつもりだと話[はな]した。", "sentence_source": "generated"}, {"text": "母は毎日の食事に野菜を多く取り入れるようにしている。", "target_word": "取り入れる", "complexity_tier": "T3", "furigana": "母[はは]は毎日[まいにち]の食事[しょくじ]に野菜[やさい]を多[おお]く取[と]り入[い]れるようにしている。", "sentence_source": "generated"}, {"text": "先生は生徒の提案を取り入れなかったので、生徒は少し残念そうだった。", "target_word": "取り入れなかった", "complexity_tier": "T4", "furigana": "先生[せんせい]は生徒[せいと]の提案[ていあん]を取[と]り入[い]れなかったので、生徒[せいと]は少[すこ]し残念[ざんねん]そうだった。", "sentence_source": "generated"}, {"text": "外国の文化を取り入れることで、この町の祭りはさらに楽しくなった。", "target_word": "取り入れる", "complexity_tier": "T4", "furigana": "外国[がいこく]の文化[ぶんか]を取[と]り入[い]れることで、この町[まち]の祭[まつ]りはさらに楽[たの]しくなった。", "sentence_source": "generated"}, {"text": "彼は流行を取り入れた服を着ているが、自分らしさも忘れない。", "target_word": "取り入れた", "complexity_tier": "T4", "furigana": "彼[かれ]は流行[りゅうこう]を取[と]り入[い]れた服[ふく]を着[き]ているが、自分[じぶん]らしさも忘[わす]れない。", "sentence_source": "generated"}, {"text": "会社は社員の声を取り入れ、休みの取り方を見直した。", "target_word": "取り入れ", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]の声[こえ]を取[と]り入[い]れ、休[やす]みの取[と]り方[かた]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "この料理は、南の国の香辛料を取り入れて、独特の味になっている。", "target_word": "取り入れて", "complexity_tier": "T4", "furigana": "この料理[りょうり]は、南[みなみ]の国[くに]の香辛料[こうしんりょう]を取[と]り入[い]れて、独特[どくとく]の味[あじ]になっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り入れる", "label": "辞書形"}, {"form": "取り入れ", "label": "連用形"}, {"form": "取り入れた", "label": "過去形"}, {"form": "取り入れて", "label": "て形"}, {"form": "取り入れない", "label": "否定形"}, {"form": "取り入れれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "外から考えや雰囲気を取り込み自分のものにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91bf9503-6e90-4a50-bc73-1b4ba1d76038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51658, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り入れた", "is_correct": true, "explanation": "「雰囲気を取り入れた」で、外の雰囲気を小屋の内装に生かす意味に合う。"}, {"text": "避けた", "is_correct": false, "explanation": "雰囲気を避けたとすると、雰囲気を生かして小屋が完成する流れと逆になる。"}, {"text": "断った", "is_correct": false, "explanation": "雰囲気を断ったとすると、雰囲気を生かした小屋が完成する流れと合わない。"}, {"text": "逃した", "is_correct": false, "explanation": "雰囲気を逃したとすると、その雰囲気を生かした小屋ができる流れに合わない。"}], "explanations": {"取り入れた": "「雰囲気を取り入れた」で、外の雰囲気を小屋の内装に生かす意味に合う。", "避けた": "雰囲気を避けたとすると、雰囲気を生かして小屋が完成する流れと逆になる。", "断った": "雰囲気を断ったとすると、雰囲気を生かした小屋が完成する流れと合わない。", "逃した": "雰囲気を逃したとすると、その雰囲気を生かした小屋ができる流れに合わない。"}, "sentence_index": 0, "correct_answer": "取り入れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議で、古くなった規則を取り入れて、すべて削除した。", "explanation": "ここは〈取り除く・削除する〉の意味。不要になったものを外す場面は「取り除く」で表し、「取り入れる」は受け入れて利用する意味なので合わない。"}, {"text": "警察は違法な業者を取り入れて、厳しく処分した。", "explanation": "ここは〈取り締まる〉の意味。違法な業者を罰する場面は「取り締まる」で表し、「取り入れる」は受け入れて利用する意味なので合わない。"}, {"text": "先生は生徒の提案を取り入れて、聞き流してしまった。", "explanation": "ここは〈無視する・聞き流す〉の意味。提案を聞き流す場面は「無視する」で表し、「取り入れる」は受け入れて利用する意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51658, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り入れなかった", "is_correct": true, "explanation": "「提案を取り入れなかった」で、先生が提案を採らず生徒が残念に思う流れに合う。"}, {"text": "歩かなかった", "is_correct": false, "explanation": "提案は歩くものではないので、「提案を歩かなかった」は成り立たない。"}, {"text": "眠らなかった", "is_correct": false, "explanation": "提案は眠るものではないので、「提案を眠らなかった」は成り立たない。"}, {"text": "泳がなかった", "is_correct": false, "explanation": "提案は泳ぐものではないので、「提案を泳がなかった」は成り立たない。"}], "explanations": {"取り入れなかった": "「提案を取り入れなかった」で、先生が提案を採らず生徒が残念に思う流れに合う。", "歩かなかった": "提案は歩くものではないので、「提案を歩かなかった」は成り立たない。", "眠らなかった": "提案は眠るものではないので、「提案を眠らなかった」は成り立たない。", "泳がなかった": "提案は泳ぐものではないので、「提案を泳がなかった」は成り立たない。"}, "sentence_index": 6, "correct_answer": "取り入れなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "頼まれた仕事を取り入れて、きっぱり断った。", "explanation": "ここは〈断る〉の意味。依頼を退ける場面は「断る」で表し、「取り入れる」は受け入れて利用する意味なので合わない。"}, {"text": "図書館で借りた本を、期限までに取り入れて返した。", "explanation": "ここは〈返却する〉の意味。借りたものを返す場面は「返却する」で表し、「取り入れる」は内へ持ち込む意味なので合わない。"}, {"text": "友人がおいしそうなケーキを注文し、店員に取り入れてもらった。", "explanation": "ここは〈注文する〉の意味。料理や品物を頼む場面は「注文する」を使い、「取り入れる」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51658, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最新の技術を取り壊して、生産量を増やした。", "corrected_sentence": "最新の技術を取り入れて、生産量を増やした。", "error_description": "誤りは「取り壊して」。正しくは「技術を取り入れる」。「取り壊す」は建物などを壊す意味で、技術には使わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り入れて", "is_correct": true, "explanation": "て形。「取り入れて、仕事の進め方を変えた」と後ろの文へ続ける形。"}, {"text": "取り入れる", "is_correct": false, "explanation": "辞書形。「て」で続ける形ではないので、ここでは文がつながらない。"}, {"text": "取り入れよう", "is_correct": false, "explanation": "意志形。「、仕事の進め方を変えた」と続かず、文が成り立たない。"}, {"text": "取り入れない", "is_correct": false, "explanation": "否定形。取り入れた内容と逆になり、文の意味が合わない。"}], "correct_form": "取り入れて", "base_form": "取り入れる", "form_label": "て形", "sentence_index": 1, "explanations": {"取り入れて": "て形。「取り入れて、仕事の進め方を変えた」と後ろの文へ続ける形。", "取り入れる": "辞書形。「て」で続ける形ではないので、ここでは文がつながらない。", "取り入れよう": "意志形。「、仕事の進め方を変えた」と続かず、文が成り立たない。", "取り入れない": "否定形。取り入れた内容と逆になり、文の意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51658, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩の助言を取り入れので、仕事が速くなった。", "corrected_sentence": "先輩の助言を取り入れたので、仕事が速くなった。", "error_description": "誤りは「取り入れので」。正しくは「取り入れた」（過去形）。「た」が抜けると文法として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り入れる", "is_correct": true, "explanation": "辞書形。「取り入れることで」と名詞句に続く形。"}, {"text": "取り入れよう", "is_correct": false, "explanation": "意志形。「ことで」には続かず、文が成り立たない。"}, {"text": "取り入れて", "is_correct": false, "explanation": "て形。「ことで」に続かず、文が成り立たない。"}, {"text": "取り入れれば", "is_correct": false, "explanation": "仮定形。「ことで」には続かず、文の意味も変わる。"}], "correct_form": "取り入れる", "base_form": "取り入れる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"取り入れる": "辞書形。「取り入れることで」と名詞句に続く形。", "取り入れよう": "意志形。「ことで」には続かず、文が成り立たない。", "取り入れて": "て形。「ことで」に続かず、文が成り立たない。", "取り入れれば": "仮定形。「ことで」には続かず、文の意味も変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51661, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51661, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「扉が開放されたまま」の主語を示す。扉が受身の主語になる自然な形。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「開放されたまま」は受身なので扉は主語になる。「を」では成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "着点や相手を示すが、ここでは扉が主語なので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、扉が主語の文では合わない。"}], "correct_answer": "が", "explanations": {"が": "「扉が開放されたまま」の主語を示す。扉が受身の主語になる自然な形。", "を": "目的語を示すが、「開放されたまま」は受身なので扉は主語になる。「を」では成り立たない。", "に": "着点や相手を示すが、ここでは扉が主語なので合わない。", "で": "手段や場所を示すが、扉が主語の文では合わない。"}, "error_tags": {"を": "対象", "に": "着点", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51661, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "開け放って、人や風が出入りできるようにすること。", "primary_collocate": null, "pronunciation": "かいほう", "ipa": "kaihoː", "syllable_count": 4, "sentences": [{"text": "夏は玄関のドアを開放して、風を通している。", "target_word": "開放", "complexity_tier": "T3", "furigana": "夏[なつ]は玄関[げんかん]のドアを開放[かいほう]して、風[かぜ]を通[とお]している。", "sentence_source": "generated"}, {"text": "屋上は昼休みだけ開放されている。", "target_word": "開放", "complexity_tier": "T2", "furigana": "屋上[おくじょう]は昼休[ひるやす]みだけ開放[かいほう]されている。", "sentence_source": "generated"}, {"text": "学校の校庭は日曜日に地域の人へ開放される。", "target_word": "開放", "complexity_tier": "T3", "furigana": "学校[がっこう]の校庭[こうてい]は日曜日[にちようび]に地域[ちいき]の人[ひと]へ開放[かいほう]される。", "sentence_source": "generated"}, {"text": "窓を開放したまま寝ると、夜は少し寒い。", "target_word": "開放", "complexity_tier": "T3", "furigana": "窓[まど]を開放[かいほう]したまま寝[ね]ると、夜[よる]は少[すこ]し寒[さむ]い。", "sentence_source": "generated"}, {"text": "博物館の庭は、無料で開放されている。", "target_word": "開放", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]の庭[にわ]は、無料[むりょう]で開放[かいほう]されている。", "sentence_source": "generated"}, {"text": "この図書館は、一階の広い部屋を自由に使えるように開放している。", "target_word": "開放", "complexity_tier": "T4", "furigana": "この図書館[としょかん]は、一階[いっかい]の広[ひろ]い部屋[へや]を自由[じゆう]に使[つか]えるように開放[かいほう]している。", "sentence_source": "generated"}, {"text": "祭りの日は、お寺の門が開放され、だれでも中に入れる。", "target_word": "開放", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]は、お寺[てら]の門[もん]が開放[かいほう]され、だれでも中[なか]に入[はい]れる。", "sentence_source": "generated"}, {"text": "倉庫の扉が開放されたままになっていたので、猫が入ってしまった。", "target_word": "開放", "complexity_tier": "T4", "furigana": "倉庫[そうこ]の扉[とびら]が開放[かいほう]されたままになっていたので、猫[ねこ]が入[はい]ってしまった。", "sentence_source": "generated"}, {"text": "空港の展望台は夜まで開放されているので、夜景を見に行った。", "target_word": "開放", "complexity_tier": "T4", "furigana": "空港[くうこう]の展望台[てんぼうだい]は夜[よる]まで開放[かいほう]されているので、夜景[やけい]を見[み]に行[い]った。", "sentence_source": "generated"}, {"text": "新しい体育館は、壁をすべて開放して、外の風が通るようになっている。", "target_word": "開放", "complexity_tier": "T4", "furigana": "新[あたら]しい体育館[たいいくかん]は、壁[かべ]をすべて開放[かいほう]して、外[そと]の風[かぜ]が通[とお]るようになっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "開放", "label": "名詞形"}, {"form": "開放する", "label": "辞書形"}, {"form": "開放した", "label": "過去形"}, {"form": "開放して", "label": "て形"}, {"form": "開放される", "label": "受身形"}, {"form": "開放されている", "label": "状態形"}], "register": "neutral", "sense_fingerprint": "開け放って人や風が出入りできるようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91bf9503-6e90-4a50-bc73-1b4ba1d76038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51661, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "開放", "is_correct": true, "explanation": "サ変名詞。「開放して」の形でドアを開けた状態にする動作を表し、風を通す文脈に合う。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける意味。風を通す文脈と矛盾するので、この空欄には合わない。"}, {"text": "閉鎖", "is_correct": false, "explanation": "閉じて使えなくする意味。風を通すという文脈と矛盾する。"}, {"text": "封印", "is_correct": false, "explanation": "封をして開かないようにする意味。風を通す文脈と矛盾する。"}], "explanations": {"開放": "サ変名詞。「開放して」の形でドアを開けた状態にする動作を表し、風を通す文脈に合う。", "施錠": "鍵をかける意味。風を通す文脈と矛盾するので、この空欄には合わない。", "閉鎖": "閉じて使えなくする意味。風を通すという文脈と矛盾する。", "封印": "封をして開かないようにする意味。風を通す文脈と矛盾する。"}, "sentence_index": 0, "correct_answer": "開放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犯人は警察の突入後、人質を全員開放した。", "explanation": "ここは〈解放〉の意味（人質を解き放つ）。〈開放〉は開いていて狭くない状態を指すので合わない。"}, {"text": "台風が去り、大雨警報が開放された。", "explanation": "ここは「警報を取り除く」の意味で、〈解除〉を使う語。〈開放〉は開いている状態に使うので合わない。"}, {"text": "古い看板を開放して、通りがすっきりした。", "explanation": "ここは「看板などを取り除く」の意味で、〈撤去〉を使う語。〈開放〉は開いている状態を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51661, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "開放", "is_correct": true, "explanation": "サ変名詞。「開放され」の形で受身になり、門が開け放たれている状態を表す。"}, {"text": "開放的", "is_correct": false, "explanation": "形容動詞の語幹。「され」に続かないので、「門が開放的され」となり成り立たない。"}, {"text": "開放し", "is_correct": false, "explanation": "連用形。「され」に続けられず、「門が開放しされ」となり成り立たない。"}, {"text": "開放する", "is_correct": false, "explanation": "辞書形。「され」に続かないので、「門が開放するされ」となり成り立たない。"}], "explanations": {"開放": "サ変名詞。「開放され」の形で受身になり、門が開け放たれている状態を表す。", "開放的": "形容動詞の語幹。「され」に続かないので、「門が開放的され」となり成り立たない。", "開放し": "連用形。「され」に続けられず、「門が開放しされ」となり成り立たない。", "開放する": "辞書形。「され」に続かないので、「門が開放するされ」となり成り立たない。"}, "sentence_index": 6, "correct_answer": "開放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "携帯会社との契約を開放して、料金の支払いをやめた。", "explanation": "ここは「契約を終わらせる」の意味で、〈解約〉を使う語。〈開放〉は場所や心が開いている状態に使うので合わない。"}, {"text": "彼は前の発言を開放して、なかったことにした。", "explanation": "ここは「言ったことを取り消す」の意味で、〈撤回〉を使う語。〈開放〉は開いている状態に使うので合わない。"}, {"text": "役所は申請を開放し、すぐ手続きを進めた。", "explanation": "ここは「申請を受け付ける」の意味で、〈受理〉を使う語。〈開放〉は開いている状態に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51661, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の間、体育館の入り口に開放しているので、涼しい風が入る。", "corrected_sentence": "夏の間、体育館の入り口を開放しているので、涼しい風が入る。", "error_description": "「開放する」は「〜を開放する」と目的語に「を」を取る。「入り口に」は誤りで、「入り口を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51661, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みの間、この公園の裏門も開放れている。", "corrected_sentence": "夏休みの間、この公園の裏門も開放されている。", "error_description": "サ変動詞「開放する」の受身は「開放される」。「開放れている」は「さ」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51662, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閉鎖", "is_correct": true, "explanation": "「開放」の対義語。遮るものがなく開いている状態と、閉じて塞がれた状態が反対になる。"}, {"text": "完成", "is_correct": false, "explanation": "物事が仕上がることを表し、「開放」の対義語ではない。"}, {"text": "保存", "is_correct": false, "explanation": "物をそのまま保つことを表し、「開放」の対義語ではない。"}, {"text": "集中", "is_correct": false, "explanation": "一点に集まることを表し、「開放」の対義語ではない。"}], "correct_answer": "閉鎖", "explanations": {"閉鎖": "「開放」の対義語。遮るものがなく開いている状態と、閉じて塞がれた状態が反対になる。", "完成": "物事が仕上がることを表し、「開放」の対義語ではない。", "保存": "物をそのまま保つことを表し、「開放」の対義語ではない。", "集中": "一点に集まることを表し、「開放」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51662, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閉鎖", "is_correct": true, "explanation": "「開放」の対義語。空間を閉じて出入りを止める状態が、開いて自由に入れる状態と反対になる。"}, {"text": "約束", "is_correct": false, "explanation": "将来のことを取り決める意味で、「開放」の対義語ではない。"}, {"text": "修復", "is_correct": false, "explanation": "壊れたものを直す意味で、「開放」の対義語ではない。"}, {"text": "集計", "is_correct": false, "explanation": "数を合わせて計算する意味で、「開放」の対義語ではない。"}], "correct_answer": "閉鎖", "explanations": {"閉鎖": "「開放」の対義語。空間を閉じて出入りを止める状態が、開いて自由に入れる状態と反対になる。", "約束": "将来のことを取り決める意味で、「開放」の対義語ではない。", "修復": "壊れたものを直す意味で、「開放」の対義語ではない。", "集計": "数を合わせて計算する意味で、「開放」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51662, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "さえぎるものがなく、ひらけていること。また、心が広く、かたよらないこと。", "primary_collocate": null, "pronunciation": "かいほう", "ipa": "kaihoː", "syllable_count": 4, "sentences": [{"text": "最終的に、その雰囲気を取り入れた、木漏れ日が差し込む開放的な小屋が完成し、家族の新たな憩いの場となった。", "target_word": "開放的な", "complexity_tier": "T4", "furigana": "最終的[さいしゅうてき]に、その雰囲気[ふんいき]を取[と]り入[い]れた、木漏[こも]れ日[び]が差[さ]し込[こ]む開放的[かいほうてき]な小屋[こや]が完成[かんせい]し、家族[かぞく]の新[あら]たな憩[いこ]いの場[ば]となった。", "sentence_source": "mined"}, {"text": "この部屋は一面が開放されていて、遮るものなく海が見える。", "target_word": "開放されていて", "complexity_tier": "T3", "furigana": "この部屋[へや]は一面[いちめん]が開放[かいほう]されていて、遮[さえぎ]るものなく海[うみ]が見[み]える。", "sentence_source": "generated"}, {"text": "彼は心を開放して話すので、初めて会う人ともすぐ打ち解けられる。", "target_word": "開放して", "complexity_tier": "T3", "furigana": "彼[かれ]は心[こころ]を開放[かいほう]して話[はな]すので、初[はじ]めて会[あ]う人[ひと]ともすぐ打[う]ち解[と]けられる。", "sentence_source": "generated"}, {"text": "壁がなく四方が開放されたカフェは、風が通って気持ちがいい。", "target_word": "開放された", "complexity_tier": "T3", "furigana": "壁[かべ]がなく四方[しほう]が開放[かいほう]されたカフェは、風[かぜ]が通[とお]って気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "山頂に着くと、周りに遮るものがなく、視界が開放されていた。", "target_word": "開放されていた", "complexity_tier": "T3", "furigana": "山頂[さんちょう]に着[つ]くと、周[まわ]りに遮[さえぎ]るものがなく、視界[しかい]が開放[かいほう]されていた。", "sentence_source": "generated"}, {"text": "田中さんの一家は心を開放していて、近所の人もよく遊びに来る。", "target_word": "開放していて", "complexity_tier": "T3", "furigana": "田中[たなか]さんの一家[いっか]は心[こころ]を開放[かいほう]していて、近所[きんじょ]の人[ひと]もよく遊[あそ]びに来[く]る。", "sentence_source": "generated"}, {"text": "天井が高く開放された駅の広場は、待ち合わせの場所として人気がある。", "target_word": "開放された", "complexity_tier": "T3", "furigana": "天井[てんじょう]が高[たか]く開放[かいほう]された駅[えき]の広場[ひろば]は、待[ま]ち合[あ]わせの場所[ばしょ]として人気[にんき]がある。", "sentence_source": "generated"}, {"text": "彼は心を開放できる人で、新しい意見にも耳を傾ける。", "target_word": "開放できる", "complexity_tier": "T3", "furigana": "彼[かれ]は心[こころ]を開放[かいほう]できる人[ひと]で、新[あたら]しい意見[いけん]にも耳[みみ]を傾[かたむ]ける。", "sentence_source": "generated"}, {"text": "窓を大きくしたので、部屋が開放されて広く感じる。", "target_word": "開放されて", "complexity_tier": "T3", "furigana": "窓[まど]を大[おお]きくしたので、部屋[へや]が開放[かいほう]されて広[ひろ]く感[かん]じる。", "sentence_source": "generated"}, {"text": "壁を取り払い、教室の空間を開放したので、生徒が自由に動けるようになった。", "target_word": "開放した", "complexity_tier": "T3", "furigana": "壁[かべ]を取[と]り払[はら]い、教室[きょうしつ]の空間[くうかん]を開放[かいほう]したので、生徒[せいと]が自由[じゆう]に動[うご]けるようになった。", "sentence_source": "generated"}, {"text": "広いベランダがあり、前が開放されている家に引っ越して、毎日が楽しい。", "target_word": "開放されている", "complexity_tier": "T3", "furigana": "広[ひろ]いベランダがあり、前[まえ]が開放[かいほう]されている家[いえ]に引[ひ]っ越[こ]して、毎日[まいにち]が楽[たの]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "開放", "label": "名詞形"}, {"form": "開放的", "label": "形容動詞語幹"}, {"form": "開放的な", "label": "連体形"}, {"form": "開放的に", "label": "連用形"}, {"form": "開放的で", "label": "て形"}, {"form": "開放的だ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "さえぎるものがなく広々している、心が偏らない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 取り払い (Zipf 2.15)']::text[], '91bf9503-6e90-4a50-bc73-1b4ba1d76038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51662, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "開放的な", "is_correct": true, "explanation": "連体形。直後の名詞「小屋」を修飾する形で、この位置に入る。"}, {"text": "開放的に", "is_correct": false, "explanation": "連用形。副詞的に使う形なので、名詞「小屋」を直接修飾できない。"}, {"text": "開放的で", "is_correct": false, "explanation": "て形。後ろの用言へつなぐ形なので、名詞の前には置けない。"}, {"text": "開放的だ", "is_correct": false, "explanation": "終止形。文を言い切る形なので、「小屋」の前では文が成り立たない。"}], "explanations": {"開放的な": "連体形。直後の名詞「小屋」を修飾する形で、この位置に入る。", "開放的に": "連用形。副詞的に使う形なので、名詞「小屋」を直接修飾できない。", "開放的で": "て形。後ろの用言へつなぐ形なので、名詞の前には置けない。", "開放的だ": "終止形。文を言い切る形なので、「小屋」の前では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "開放的な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察が突入し、犯人は人質を全員開放した。", "explanation": "ここは〈解放〉の意味（人質を解き放つ）。〈開放〉は遮るものなく開いている状態を指すので合わない。"}, {"text": "台風が去り、大雨警報が開放された。", "explanation": "ここは「警報を取り除く」の意味で、〈解除〉を使う語。〈開放〉は場所や心が遮るものなく開いている状態に使うので合わない。"}, {"text": "古い看板を開放して、通りがすっきりした。", "explanation": "ここは「看板などを取り除く」の意味で、〈撤去〉を使う語。〈開放〉は遮るものがなく開いている状態を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51662, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "開放された", "is_correct": true, "explanation": "受身の連体形。直後の「広場」を修飾し、「天井が高く開放された駅の広場」として成り立つ。"}, {"text": "開放して", "is_correct": false, "explanation": "て形。名詞の前に置けず、「駅の広場」を修飾できない。"}, {"text": "開放しよう", "is_correct": false, "explanation": "意志形。名詞を修飾できず、「開放しよう駅の広場」は文が成り立たない。"}, {"text": "開放されず", "is_correct": false, "explanation": "否定の連用形。名詞を修飾できず、「開放されず駅の広場」は文がつながらない。"}], "explanations": {"開放された": "受身の連体形。直後の「広場」を修飾し、「天井が高く開放された駅の広場」として成り立つ。", "開放して": "て形。名詞の前に置けず、「駅の広場」を修飾できない。", "開放しよう": "意志形。名詞を修飾できず、「開放しよう駅の広場」は文が成り立たない。", "開放されず": "否定の連用形。名詞を修飾できず、「開放されず駅の広場」は文がつながらない。"}, "sentence_index": 6, "correct_answer": "開放された"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は前の発言を開放して、なかったことにした。", "explanation": "ここは「言ったことを取り消す」の意味で、〈撤回〉を使う語。〈開放〉は場所や心が遮るものなく開いている状態に使うので合わない。"}, {"text": "冷凍の肉を開放して、そのまま料理に使った。", "explanation": "ここは「凍った食品を溶かす」の意味で、〈解凍〉を使う語。〈開放〉は合わない。"}, {"text": "役所は申請を開放し、すぐ手続きを進めた。", "explanation": "ここは「申請を受け付ける」の意味で、〈受理〉を使う語。〈開放〉は場所が開いている状態に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51662, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山あいに開放的の小屋が建っていて、旅人が休めるようになっている。", "corrected_sentence": "山あいに開放的な小屋が建っていて、旅人が休めるようになっている。", "error_description": "名詞を修飾する形は「開放的な」。「開放的の」は形容動詞の語幹に「の」を付けた誤りで、「の」では名詞「小屋」を修飾できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51662, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ホールの扉に開放したので、参加者が入れるようになった。", "corrected_sentence": "ホールの扉を開放したので、参加者が入れるようになった。", "error_description": "「開放する」は「〜を開放する」と目的語に「を」を取る。「扉に」は誤りで、「扉を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51663, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「白い光が差し込んで」の主語を示す。光が出口から入ってくる主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「光を差し込んだ」は目的語を取る用法になり、光が自分から入る意味と合わない。"}, {"text": "に", "is_correct": false, "explanation": "着点を示すが、光が主語の文では不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「光で差し込んで」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「白い光が差し込んで」の主語を示す。光が出口から入ってくる主語になる。", "を": "「光を差し込んだ」は目的語を取る用法になり、光が自分から入る意味と合わない。", "に": "着点を示すが、光が主語の文では不自然になる。", "で": "手段や場所を示すが、「光で差し込んで」は意味が通らない。"}, "error_tags": {"を": "対象", "に": "着点", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51663, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「光が差し込んだ」の主語を示す。光が戸のすきまから入った主語になる。"}, {"text": "と", "is_correct": false, "explanation": "「光と差し込んだ」は並列や相手を示すが、光自身が入ってくる主語になる文とは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「光へ差し込んだ」は方向を示し、光が自分から入る主語の文と合わず、主語が崩れる。"}, {"text": "より", "is_correct": false, "explanation": "「光より差し込んだ」は比較を示すが、この文には比べる対象がなく意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「光が差し込んだ」の主語を示す。光が戸のすきまから入った主語になる。", "と": "「光と差し込んだ」は並列や相手を示すが、光自身が入ってくる主語になる文とは合わない。", "へ": "「光へ差し込んだ」は方向を示し、光が自分から入る主語の文と合わず、主語が崩れる。", "より": "「光より差し込んだ」は比較を示すが、この文には比べる対象がなく意味が通らない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51663, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ひかりが、すきまから、なかにはいること。", "primary_collocate": null, "pronunciation": "さしこむ", "ipa": "saɕikomɯ", "syllable_count": 4, "sentences": [{"text": "朝になると、障子のすきまから光が差し込んできた。", "target_word": "差し込んで", "complexity_tier": "T3", "furigana": "朝[あさ]になると、障子[しょうじ]のすきまから光[ひかり]が差[さ]し込[こ]んできた。", "sentence_source": "generated"}, {"text": "トンネルの出口から、白い光が差し込んでくる。", "target_word": "差し込んで", "complexity_tier": "T3", "furigana": "トンネルの出口[でぐち]から、白[しろ]い光[ひかり]が差[さ]し込[こ]んでくる。", "sentence_source": "generated"}, {"text": "雨がやむと、雲のすきまから日が差し込んだ。", "target_word": "差し込んだ", "complexity_tier": "T2", "furigana": "雨[あめ]がやむと、雲[くも]のすきまから日[ひ]が差[さ]し込[こ]んだ。", "sentence_source": "generated"}, {"text": "教室の窓から、やわらかい光が差し込んでいる。", "target_word": "差し込んで", "complexity_tier": "T2", "furigana": "教室[きょうしつ]の窓[まど]から、やわらかい光[ひかり]が差[さ]し込[こ]んでいる。", "sentence_source": "generated"}, {"text": "屋根の穴から月の光が差し込み、床が青白く見えた。", "target_word": "差し込み", "complexity_tier": "T4", "furigana": "屋根[やね]の穴[あな]から月[つき]の光[ひかり]が差[さ]し込[こ]み、床[ゆか]が青白[あおじろ]く見[み]えた。", "sentence_source": "generated"}, {"text": "木の間から差し込む光の中を、犬が走っていった。", "target_word": "差し込む", "complexity_tier": "T3", "furigana": "木[き]の間[あいだ]から差[さ]し込[こ]む光[ひかり]の中[なか]を、犬[いぬ]が走[はし]っていった。", "sentence_source": "generated"}, {"text": "夕方になると、窓から夕日が差し込んで、壁の色が変わる。", "target_word": "差し込んで", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]になると、窓[まど]から夕日[ゆうひ]が差[さ]し込[こ]んで、壁[かべ]の色[いろ]が変[か]わる。", "sentence_source": "generated"}, {"text": "戸のすきまから光が差し込んだので、まだ誰か起きているとわかった。", "target_word": "差し込んだ", "complexity_tier": "T4", "furigana": "戸[と]のすきまから光[ひかり]が差[さ]し込[こ]んだので、まだ誰[だれ]か起[お]きているとわかった。", "sentence_source": "generated"}, {"text": "天窓があるので、昼は電気をつけなくても光が差し込んで明るい。", "target_word": "差し込んで", "complexity_tier": "T4", "furigana": "天窓[てんまど]があるので、昼[ひる]は電気[でんき]をつけなくても光[ひかり]が差[さ]し込[こ]んで明[あか]るい。", "sentence_source": "generated"}, {"text": "朝日が差し込む台所で、母はいつもお茶をいれている。", "target_word": "差し込む", "complexity_tier": "T3", "furigana": "朝日[あさひ]が差[さ]し込[こ]む台所[だいどころ]で、母[はは]はいつもお茶[ちゃ]をいれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "差し込む", "label": "辞書形"}, {"form": "差し込み", "label": "連用形"}, {"form": "差し込んだ", "label": "過去形"}, {"form": "差し込んで", "label": "て形"}, {"form": "差し込まない", "label": "否定形"}, {"form": "差し込めば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "光がすきまから中に入る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91bf9503-6e90-4a50-bc73-1b4ba1d76038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51663, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差し込んで", "is_correct": true, "explanation": "て形。「きた」に続けて、光が入ってくる動きを表す。"}, {"text": "差し込み", "is_correct": false, "explanation": "連用形。「きた」へ続けると文がつながらない。"}, {"text": "差し込ませ", "is_correct": false, "explanation": "使役形。「光が〜させる」となり、文の主語と合わない。"}, {"text": "差し込まれ", "is_correct": false, "explanation": "受身の連用形。光が誰かに入れられる意味になり、文脈に合わない。"}], "explanations": {"差し込んで": "て形。「きた」に続けて、光が入ってくる動きを表す。", "差し込み": "連用形。「きた」へ続けると文がつながらない。", "差し込ませ": "使役形。「光が〜させる」となり、文の主語と合わない。", "差し込まれ": "受身の連用形。光が誰かに入れられる意味になり、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "差し込んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜中、泥棒が窓から差し込んで、部屋に入った。", "explanation": "ここは人が窓などからこっそり入る意味で、〈忍び込む〉を使う語。〈差し込む〉は光がすきまから入る場合に使うので合わない。"}, {"text": "時計の長針が十二を差し込んで、正午を知らせた。", "explanation": "ここは〈指す〉の意味（針が数字を示す）。〈差し込む〉は光がすきまから入る場合に使うので合わない。"}, {"text": "夜、天井の電球が差し込んで、部屋が明るくなった。", "explanation": "ここは電灯がつく意味で、〈点く〉を使う語。〈差し込む〉は光がすきまから入る場合に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51663, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差し込んで", "is_correct": true, "explanation": "て形。「〜て、」と後続の文へ続ける形で、「壁の色が変わる」へつながる。"}, {"text": "差し込め", "is_correct": false, "explanation": "命令形。文の途中の「夕日が〜、」に入らず、文が成り立たない。"}, {"text": "差し込ませ", "is_correct": false, "explanation": "使役形。「夕日が〜させる」となり、文脈に合わない。"}, {"text": "差し込もう", "is_correct": false, "explanation": "意志形。「夕日が〜、」と続かず、文が成り立たない。"}], "explanations": {"差し込んで": "て形。「〜て、」と後続の文へ続ける形で、「壁の色が変わる」へつながる。", "差し込め": "命令形。文の途中の「夕日が〜、」に入らず、文が成り立たない。", "差し込ませ": "使役形。「夕日が〜させる」となり、文脈に合わない。", "差し込もう": "意志形。「夕日が〜、」と続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "差し込んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもが池に差し込んで、水しぶきが上がった。", "explanation": "ここは〈飛び込む〉の意味（勢いよく中へ入る）。〈差し込む〉は光がすきまから入る場合に使うので合わない。"}, {"text": "山の斜面から温泉が差し込んで、あたりに湯けむりが立った。", "explanation": "ここは〈湧き出る〉の意味（地中から外へ出てくる）。〈差し込む〉は光や風がすきまから入る場合に使うので合わない。"}, {"text": "コップに水を差し込んで、一気に飲んだ。", "explanation": "ここは液体を器に入れる意味で、〈注ぐ〉を使う語。〈差し込む〉は光や風がすきまから入る場合に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51663, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨戸のすきまから朝の光が差し込みている。", "corrected_sentence": "雨戸のすきまから朝の光が差し込んでいる。", "error_description": "「差し込む」は五段動詞で、「ている」の前は音便の「差し込んでいる」になる。「差し込みている」は「ん」が抜けた誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "差し込んで", "is_correct": true, "explanation": "て形。「くる」に続けて、光が入ってくる動きを表す。"}, {"text": "差し込んだ", "is_correct": false, "explanation": "過去形。「くる」に続けられず、「差し込んだくる」は成り立たない。"}, {"text": "差し込む", "is_correct": false, "explanation": "辞書形。「くる」と続けるには不自然で、文がつながらない。"}, {"text": "差し込め", "is_correct": false, "explanation": "命令・可能の形。「くる」に続かないので、文が成り立たない。"}], "correct_form": "差し込んで", "base_form": "差し込む", "form_label": "て形", "sentence_index": 1, "explanations": {"差し込んで": "て形。「くる」に続けて、光が入ってくる動きを表す。", "差し込んだ": "過去形。「くる」に続けられず、「差し込んだくる」は成り立たない。", "差し込む": "辞書形。「くる」と続けるには不自然で、文がつながらない。", "差し込め": "命令・可能の形。「くる」に続かないので、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51663, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の夜、ベランダの窓から月の光が差し込んて、畳が白く見える。", "corrected_sentence": "夏の夜、ベランダの窓から月の光が差し込んで、畳が白く見える。", "error_description": "「む」で終わる五段動詞のて形は「んで」。「差し込んて」は誤りで、「差し込んで」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "差し込んだ", "is_correct": true, "explanation": "過去形。「ので」に続けて、差し込んだ結果を示す。"}, {"text": "差し込んで", "is_correct": false, "explanation": "て形。「ので」の前に置くと「差し込んでので」となり、文が成り立たない。"}, {"text": "差し込め", "is_correct": false, "explanation": "命令の形。「ので」に続けられず、「差し込めので」となり文が成り立たない。"}, {"text": "差し込み", "is_correct": false, "explanation": "連用形。「ので」に続けられず、文が成り立たない。"}], "correct_form": "差し込んだ", "base_form": "差し込む", "form_label": "過去形", "sentence_index": 7, "explanations": {"差し込んだ": "過去形。「ので」に続けて、差し込んだ結果を示す。", "差し込んで": "て形。「ので」の前に置くと「差し込んでので」となり、文が成り立たない。", "差し込め": "命令の形。「ので」に続けられず、「差し込めので」となり文が成り立たない。", "差し込み": "連用形。「ので」に続けられず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d3222f-8610-487c-ba7e-f92b2a30cc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
