INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51665, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51665, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "やすむことや、やすむためのばしょ。", "primary_collocate": null, "pronunciation": "いこい", "ipa": "ikoi", "syllable_count": 3, "sentences": [{"text": "川のそばに、みんなの憩いの場所がある。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "川[かわ]のそばに、みんなの憩[いこ]いの場所[ばしょ]がある。", "sentence_source": "generated"}, {"text": "昼休みの屋上は、社員の憩いの場です。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "昼休[ひるやす]みの屋上[おくじょう]は、社員[しゃいん]の憩[いこ]いの場[ば]です。", "sentence_source": "generated"}, {"text": "子どもたちにとって、この公園は楽しい憩いの場だ。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "子[こ]どもたちにとって、この公園[こうえん]は楽[たの]しい憩[いこ]いの場[ば]だ。", "sentence_source": "generated"}, {"text": "おふろは、一日の終わりの憩いの時間です。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "おふろは、一日[いちにち]の終[お]わりの憩[いこ]いの時間[じかん]です。", "sentence_source": "generated"}, {"text": "疲れた旅人は、小さな茶店で憩いを求めた。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "疲[つか]れた旅人[たびびと]は、小[ちい]さな茶店[ちゃみせ]で憩[いこ]いを求[もと]めた。", "sentence_source": "generated"}, {"text": "学校の図書室は、本好きの生徒の憩いの場になっている。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "学校[がっこう]の図書室[としょしつ]は、本好[ほんず]きの生徒[せいと]の憩[いこ]いの場[ば]になっている。", "sentence_source": "generated"}, {"text": "母にとって、日曜の午後の昼寝が何よりの憩いだ。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "母[はは]にとって、日曜[にちよう]の午後[ごご]の昼寝[ひるね]が何[なに]よりの憩[いこ]いだ。", "sentence_source": "generated"}, {"text": "山のふもとに、登山者の憩いの小屋がある。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "山[やま]のふもとに、登山者[とざんしゃ]の憩[いこ]いの小屋[こや]がある。", "sentence_source": "generated"}, {"text": "町の中心にある池は、お年寄りの憩いの場として人気がある。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "町[まち]の中心[ちゅうしん]にある池[いけ]は、お年寄[としよ]りの憩[いこ]いの場[ば]として人気[にんき]がある。", "sentence_source": "generated"}, {"text": "そのカフェは、仕事帰りの人に憩いを与える。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "そのカフェは、仕事帰[しごとがえ]りの人[ひと]に憩[いこ]いを与[あた]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "憩い", "label": "基本形"}, {"form": "憩いの", "label": "連体形（の）"}], "register": "neutral", "sense_fingerprint": "やすむこと、やすむ場所を指す基本的な名詞（憩いの場）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51665, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "憩い", "is_correct": true, "explanation": "正解。「みんなの〇〇の場所」として、みんなが休む場所を指し、文意に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様の意味。「天気の場所」は場所として成り立たず、文が通らない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の温度の意味。場所を修飾する語としては成り立たない。"}, {"text": "色", "is_correct": false, "explanation": "色は色彩の意味。「色の場所」では文の内容が通らない。"}], "explanations": {"憩い": "正解。「みんなの〇〇の場所」として、みんなが休む場所を指し、文意に合う。", "天気": "天気は空模様の意味。「天気の場所」は場所として成り立たず、文が通らない。", "体温": "体温は体の温度の意味。場所を修飾する語としては成り立たない。", "色": "色は色彩の意味。「色の場所」では文の内容が通らない。"}, "sentence_index": 0, "correct_answer": "憩い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この憩いは、主人公の心の揺れを丁寧に描いている。", "explanation": "ここは〈小説〉の意味。心の揺れを丁寧に描くのは小説で、くつろぎを表す憩いは合わない。"}, {"text": "午後の空に、大きな憩いが一つ浮かんでいた。", "explanation": "ここは〈雲〉の意味。空に浮かぶのは雲で、くつろぎを表す憩いは空に浮かばない。"}, {"text": "町の大きな祭りの夜、憩いが夜空を彩った。", "explanation": "ここは〈花火〉の意味。夜空を彩るのは〈花火〉で、くつろぎを指す憩いは光を放つものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51665, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "憩い", "is_correct": true, "explanation": "正解。「何よりの〇〇だ」の形で、日曜の昼寝をくつろぎの時間として表す語として合う。"}, {"text": "湿気", "is_correct": false, "explanation": "湿気は空気中の水分の意味。昼寝を指す語としては合わない。"}, {"text": "配達", "is_correct": false, "explanation": "配達は品物を届ける行為。昼寝には当てはまらない。"}, {"text": "包装", "is_correct": false, "explanation": "包装は品物を包む行為。昼寝を表す語とは合わない。"}], "explanations": {"憩い": "正解。「何よりの〇〇だ」の形で、日曜の昼寝をくつろぎの時間として表す語として合う。", "湿気": "湿気は空気中の水分の意味。昼寝を指す語としては合わない。", "配達": "配達は品物を届ける行為。昼寝には当てはまらない。", "包装": "包装は品物を包む行為。昼寝を表す語とは合わない。"}, "sentence_index": 6, "correct_answer": "憩い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方の憩いが、町いっぱいに響いた。", "explanation": "ここは〈鐘〉の意味。町に響くのは〈鐘〉の音で、くつろぎを表す憩いは音を発するものではない。"}, {"text": "駅の入口に、古い憩いが掲げられていた。", "explanation": "ここは〈看板〉の意味。掲げられるのは看板で、くつろぎを表す憩いは掲げるものではない。"}, {"text": "帰り道、雨で憩いが遅れた。", "explanation": "ここは〈電車〉の意味。運行が遅れるのは〈電車〉で、くつろぎを表す憩いは遅れるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51665, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この川べりは、みんなの憩いを場所だ。", "corrected_sentence": "この川べりは、みんなの憩いの場所だ。", "error_description": "誤: 「憩い」に「を」が付き、「場所」と続かない。正: 「憩いの場所」の「の」。「の場所」で、くつろぐための場所を表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51665, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この神社の境内は、参拝の人に憩いが与えている。", "corrected_sentence": "この神社の境内は、参拝の人に憩いを与えている。", "error_description": "誤: 「憩い」に「が」が付き、「与える」の目的語になっていない。正: 「憩いを与える」の「を」。「与える」はものに「を」を取る。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
