INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51666, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "休息、くつろぎ。また、そのための場所。", "primary_collocate": null, "pronunciation": "いこい", "ipa": "ikoi", "syllable_count": 3, "sentences": [{"text": "最終的に、その雰囲気を取り入れた、木漏れ日が差し込む開放的な小屋が完成し、家族の新たな憩いの場となった。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "最終的[さいしゅうてき]に、その雰囲気[ふんいき]を取[と]り入[い]れた、木漏[こも]れ日[び]が差[さ]し込[こ]む開放的[かいほうてき]な小屋[こや]が完成[かんせい]し、家族[かぞく]の新[あら]たな憩[いこ]いの場[ば]となった。", "sentence_source": "mined"}, {"text": "この公園は、町の人々にとって大切な憩いの場所だ。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "この公園[こうえん]は、町[まち]の人々[ひとびと]にとって大切[たいせつ]な憩[いこ]いの場所[ばしょ]だ。", "sentence_source": "generated"}, {"text": "仕事の後、庭でお茶を飲む時間が私の憩いです。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "仕事[しごと]の後[あと]、庭[にわ]でお茶[ちゃ]を飲[の]む時間[じかん]が私[わたし]の憩[いこ]いです。", "sentence_source": "generated"}, {"text": "駅前に小さな広場ができ、買い物客の憩いの場になっている。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "駅前[えきまえ]に小[ちい]さな広場[ひろば]ができ、買[か]い物客[ものきゃく]の憩[いこ]いの場[ば]になっている。", "sentence_source": "generated"}, {"text": "忙しい毎日の中で、犬と散歩する時間がいちばんの憩いだ。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "忙[いそが]しい毎日[まいにち]の中[なか]で、犬[いぬ]と散歩[さんぽ]する時間[じかん]がいちばんの憩[いこ]いだ。", "sentence_source": "generated"}, {"text": "木陰のベンチは、暑い日に歩き疲れた人たちに憩いを与えてくれる。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "木陰[こかげ]のベンチは、暑[あつ]い日[ひ]に歩[ある]き疲[つか]れた人[ひと]たちに憩[いこ]いを与[あた]えてくれる。", "sentence_source": "generated"}, {"text": "祖父にとって、縁側で庭を眺めることは何よりの憩いだった。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "祖父[そふ]にとって、縁側[えんがわ]で庭[にわ]を眺[なが]めることは何[なに]よりの憩[いこ]いだった。", "sentence_source": "generated"}, {"text": "病院の中庭は、患者と家族の憩いの空間として作られた。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "病院[びょういん]の中庭[なかにわ]は、患者[かんじゃ]と家族[かぞく]の憩[いこ]いの空間[くうかん]として作[つく]られた。", "sentence_source": "generated"}, {"text": "この喫茶店は静かで、近所の人々の憩いの場として長く愛されている。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "この喫茶店[きっさてん]は静[しず]かで、近所[きんじょ]の人々[ひとびと]の憩[いこ]いの場[ば]として長[なが]く愛[あい]されている。", "sentence_source": "generated"}, {"text": "週末の温泉旅行は、疲れた体と心に憩いをもたらした。", "target_word": "憩い", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]の温泉[おんせん]旅行[りょこう]は、疲[つか]れた体[からだ]と心[こころ]に憩[いこ]いをもたらした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "憩い", "label": "基本形"}, {"form": "憩いの", "label": "連体形（の）"}], "register": "neutral", "sense_fingerprint": "休息やくつろぎ、またそれを得る場所を指す名詞（憩いの場）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51666, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "憩い", "is_correct": true, "explanation": "正解。家族がくつろぐ場所を指す「憩いの場」として、文意に合う。"}, {"text": "材料", "is_correct": false, "explanation": "材料は素材の意味。「材料の場」では場所として成り立たず、小屋の完成と結びつかない。"}, {"text": "湿気", "is_correct": false, "explanation": "湿気は空気中の水分の意味。くつろぎの場所を表す語としては成り立たない。"}, {"text": "配達", "is_correct": false, "explanation": "配達は品物を届ける行為。「配達の場」は意味が通らず、文の内容と合わない。"}], "explanations": {"憩い": "正解。家族がくつろぐ場所を指す「憩いの場」として、文意に合う。", "材料": "材料は素材の意味。「材料の場」では場所として成り立たず、小屋の完成と結びつかない。", "湿気": "湿気は空気中の水分の意味。くつろぎの場所を表す語としては成り立たない。", "配達": "配達は品物を届ける行為。「配達の場」は意味が通らず、文の内容と合わない。"}, "sentence_index": 0, "correct_answer": "憩い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週の参加者の憩いが、予想より多かった。", "explanation": "ここは〈数〉の意味。人の数は〈数〉で表し、くつろぎを指す憩いは人数の意味にならない。"}, {"text": "川には、夏になると大きな憩いが泳いでいた。", "explanation": "ここは〈魚〉の意味。泳ぐのは魚で、くつろぎを表す憩いは泳がない。"}, {"text": "子どもたちの明るい憩いが、ホールいっぱいに響いた。", "explanation": "ここは〈声〉の意味。ホールに響くのは〈声〉で、くつろぎを表す憩いは音として響くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51666, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "憩い", "is_correct": true, "explanation": "正解。「何よりの〇〇だった」の形で、縁側で庭を眺める安らぎの時間を表す語として合う。"}, {"text": "作業", "is_correct": false, "explanation": "作業は手を動かす仕事を指し、ぼんやり庭を眺める行為とは合わない。"}, {"text": "段取り", "is_correct": false, "explanation": "段取りは物事の事前の準備の順序で、庭を眺めることには当てはまらない。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は汚れを落とす家事で、庭を眺めることを掃除とは言わない。"}], "explanations": {"憩い": "正解。「何よりの〇〇だった」の形で、縁側で庭を眺める安らぎの時間を表す語として合う。", "作業": "作業は手を動かす仕事を指し、ぼんやり庭を眺める行為とは合わない。", "段取り": "段取りは物事の事前の準備の順序で、庭を眺めることには当てはまらない。", "掃除": "掃除は汚れを落とす家事で、庭を眺めることを掃除とは言わない。"}, "sentence_index": 6, "correct_answer": "憩い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この憩いは、主人公の心の動きを丁寧に描いている。", "explanation": "ここは〈文章〉の意味。心の動きを言葉で描くのは〈文章〉で、くつろぎを表す憩いは合わない。"}, {"text": "台所の鍋に、大きな憩いが煮えていた。", "explanation": "ここは〈料理〉の意味。煮えるのは料理で、くつろぎを表す憩いは煮えない。"}, {"text": "工場の入口で、大きな憩いが鳴り響いた。", "explanation": "ここは〈警報〉の意味。鳴り響くのは警報で、くつろぎを表す憩いは音を出さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51666, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この広場は、地域の人たちの憩いを場になっている。", "corrected_sentence": "この広場は、地域の人たちの憩いの場になっている。", "error_description": "誤: 「憩い」に「を」が付き、「場」と続かない。正: 「憩いの場」の「の」。「憩い」は名詞で、「の場」でくつろぐ場所を表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51666, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この古い宿は、旅人に憩いに与えてきた。", "corrected_sentence": "この古い宿は、旅人に憩いを与えてきた。", "error_description": "誤: 「憩い」に「に」が付いている。正: 「憩いを与える」の「を」。「与える」は相手に「に」、ものに「を」を取り、「憩い」はものにあたる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51667, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「庭に空いたスペースがある」で、存在する場所を示します。"}, {"text": "を", "is_correct": false, "explanation": "「庭を空いたスペースがある」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「ある」の存在場所に「へ」は使えません。"}, {"text": "から", "is_correct": false, "explanation": "「庭から空いたスペースがある」は文として成り立ちません。存在の場所は「に」で示します。"}], "correct_answer": "に", "explanations": {"に": "「庭に空いたスペースがある」で、存在する場所を示します。", "を": "「庭を空いたスペースがある」は文として成り立ちません。", "へ": "「ある」の存在場所に「へ」は使えません。", "から": "「庭から空いたスペースがある」は文として成り立ちません。存在の場所は「に」で示します。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "starting_point"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51667, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「壁のスペースに絵をかける」で、絵をかける場所を示します。"}, {"text": "が", "is_correct": false, "explanation": "「スペースが絵をかけたい」は文として成り立ちません。"}, {"text": "を", "is_correct": false, "explanation": "「スペースを絵をかけたい」は「を」が二つ重なり、文として成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「スペースと絵をかけたい」は文として成り立ちません。"}], "correct_answer": "に", "explanations": {"に": "「壁のスペースに絵をかける」で、絵をかける場所を示します。", "が": "「スペースが絵をかけたい」は文として成り立ちません。", "を": "「スペースを絵をかけたい」は「を」が二つ重なり、文として成り立ちません。", "と": "「スペースと絵をかけたい」は文として成り立ちません。"}, "error_tags": {"が": "subject_marker", "を": "object_marker", "と": "companion"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51667, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "スペースは、もののない場所のことです。", "primary_collocate": null, "pronunciation": "すぺーす", "ipa": "sɯpeːsɯ", "syllable_count": 4, "sentences": [{"text": "部屋にスペースを作ります。", "target_word": "スペース", "complexity_tier": "T2", "furigana": "部屋[へや]にスペースを作[つく]ります。", "sentence_source": "generated"}, {"text": "庭に空いたスペースがある。", "target_word": "スペース", "complexity_tier": "T2", "furigana": "庭[にわ]に空[あ]いたスペースがある。", "sentence_source": "generated"}, {"text": "棚のスペースに花を置いた。", "target_word": "スペース", "complexity_tier": "T3", "furigana": "棚[たな]のスペースに花[はな]を置[お]いた。", "sentence_source": "generated"}, {"text": "スペースがなくて入れない。", "target_word": "スペース", "complexity_tier": "T3", "furigana": "スペースがなくて入[はい]れない。", "sentence_source": "generated"}, {"text": "机の上のスペースを片付けた。", "target_word": "スペース", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]のスペースを片付[かたづ]けた。", "sentence_source": "generated"}, {"text": "少しスペースを空けてもらえますか。", "target_word": "スペース", "complexity_tier": "T4", "furigana": "少[すこ]しスペースを空[あ]けてもらえますか。", "sentence_source": "generated"}, {"text": "駐車のスペースは二台分です。", "target_word": "スペース", "complexity_tier": "T3", "furigana": "駐車[ちゅうしゃ]のスペースは二台分[にだいぶん]です。", "sentence_source": "generated"}, {"text": "壁のスペースに絵をかけたい。", "target_word": "スペース", "complexity_tier": "T3", "furigana": "壁[かべ]のスペースに絵[え]をかけたい。", "sentence_source": "generated"}, {"text": "スペースが広ければ、テーブルも置ける。", "target_word": "スペース", "complexity_tier": "T4", "furigana": "スペースが広[ひろ]ければ、テーブルも置[お]ける。", "sentence_source": "generated"}, {"text": "何もないスペースが広がっている。", "target_word": "スペース", "complexity_tier": "T3", "furigana": "何[なに]もないスペースが広[ひろ]がっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "空きスペース", "label": "派生"}, {"form": "駐車スペース", "label": "派生"}, {"form": "収納スペース", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 何も置かれていない空き場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 広けれ (Zipf 1.64)']::text[], '5be06c00-e07b-4845-a5a1-5b9d6c46fb56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51667, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スペース", "is_correct": true, "explanation": "「部屋にスペースを作る」で、空き場所を作る意味が合います。"}, {"text": "雨", "is_correct": false, "explanation": "形は合うが、部屋に雨を作るのは意味が合わない。"}, {"text": "夢", "is_correct": false, "explanation": "形は合うが、部屋に夢を作るのは意味が合わない。"}, {"text": "返事", "is_correct": false, "explanation": "形は合うが、部屋に返事を作るのは意味が合わない。"}], "explanations": {"スペース": "「部屋にスペースを作る」で、空き場所を作る意味が合います。", "雨": "形は合うが、部屋に雨を作るのは意味が合わない。", "夢": "形は合うが、部屋に夢を作るのは意味が合わない。", "返事": "形は合うが、部屋に返事を作るのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "スペース"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スペースを読んで勉強した。", "explanation": "スペースは何もない場所なので、本のように「読む」ものではありません。"}, {"text": "スペースが笑って、私に話しかけた。", "explanation": "スペースは場所で、人のように笑ったり話しかけたりしません。"}, {"text": "彼はスペースを着て出かけた。", "explanation": "スペースは空き場所で、服のように「着る」ものではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51667, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スペース", "is_correct": true, "explanation": "「駐車のスペースは二台分」で、車を止める空き場所の意味が合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気が二台分という数え方は意味が合わない。"}, {"text": "言葉", "is_correct": false, "explanation": "形は合うが、駐車の言葉が二台分とは言えず、意味が合わない。"}, {"text": "歴史", "is_correct": false, "explanation": "形は合うが、駐車の歴史が二台分とは言えず、意味が合わない。"}], "explanations": {"スペース": "「駐車のスペースは二台分」で、車を止める空き場所の意味が合います。", "天気": "形は合うが、天気が二台分という数え方は意味が合わない。", "言葉": "形は合うが、駐車の言葉が二台分とは言えず、意味が合わない。", "歴史": "形は合うが、駐車の歴史が二台分とは言えず、意味が合わない。"}, "sentence_index": 6, "correct_answer": "スペース"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕食にスペースを焼いて食べた。", "explanation": "スペースは空き場所なので、料理のように「焼いて食べる」ものではありません。"}, {"text": "彼女はスペースを書いて試験に合格した。", "explanation": "スペースは何もない場所であり、答えのように「書く」ものではありません。"}, {"text": "スペースが走って、私の前を通り過ぎた。", "explanation": "スペースは場所や範囲で、人や車のように走ることはありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
