INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51668, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を置いたり、人が動いたりするための、空いている場所や範囲。", "primary_collocate": null, "pronunciation": "すぺーす", "ipa": "sɯpeːsɯ", "syllable_count": 4, "sentences": [{"text": "都会の限られたスペースを持つアパートメントでは、モダンなインテリアデザインが空間の印象を大きく左右します。", "target_word": "スペース", "complexity_tier": "T6", "furigana": "都会[とかい]の限[かぎ]られたスペースを持[も]つアパートメントでは、モダンなインテリアデザインが空間[くうかん]の印象[いんしょう]を大[おお]きく左右[さゆう]します。", "sentence_source": "mined"}, {"text": "ここにスペースがあります。", "target_word": "スペース", "complexity_tier": "T2", "furigana": "ここにスペースがあります。", "sentence_source": "generated"}, {"text": "机のスペースが足りない。", "target_word": "スペース", "complexity_tier": "T2", "furigana": "机[つくえ]のスペースが足[た]りない。", "sentence_source": "generated"}, {"text": "車を置くスペースを探している。", "target_word": "スペース", "complexity_tier": "T3", "furigana": "車[くるま]を置[お]くスペースを探[さが]している。", "sentence_source": "generated"}, {"text": "狭い部屋でもスペースを上手に使える。", "target_word": "スペース", "complexity_tier": "T3", "furigana": "狭[せま]い部屋[へや]でもスペースを上手[じょうず]に使[つか]える。", "sentence_source": "generated"}, {"text": "本棚のために壁にスペースを空けた。", "target_word": "スペース", "complexity_tier": "T3", "furigana": "本棚[ほんだな]のために壁[かべ]にスペースを空[あ]けた。", "sentence_source": "generated"}, {"text": "スペースがあれば、ソファを置きたい。", "target_word": "スペース", "complexity_tier": "T4", "furigana": "スペースがあれば、ソファを置[お]きたい。", "sentence_source": "generated"}, {"text": "荷物でスペースが埋まってしまった。", "target_word": "スペース", "complexity_tier": "T3", "furigana": "荷物[にもつ]でスペースが埋[う]まってしまった。", "sentence_source": "generated"}, {"text": "倉庫のスペースは広くて便利だ。", "target_word": "スペース", "complexity_tier": "T3", "furigana": "倉庫[そうこ]のスペースは広[ひろ]くて便利[べんり]だ。", "sentence_source": "generated"}, {"text": "狭いスペースで運動できる方法を調べた。", "target_word": "スペース", "complexity_tier": "T4", "furigana": "狭[せま]いスペースで運動[うんどう]できる方法[ほうほう]を調[しら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "収納スペース", "label": "派生"}, {"form": "駐車スペース", "label": "派生"}, {"form": "空きスペース", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物や人が動く空いた場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: アパートメント (Zipf 2.37)']::text[], '5be06c00-e07b-4845-a5a1-5b9d6c46fb56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51668, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スペース", "is_correct": true, "explanation": "「限られたスペース」で、狭い空き場所の意味が合います。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが、アパートメントが時間を持つのは意味が合わない。"}, {"text": "予算", "is_correct": false, "explanation": "形は合うが、アパートメントが予算を持つのは意味が合わない。"}, {"text": "速度", "is_correct": false, "explanation": "形は合うが、アパートメントが速度を持つのは意味が合わない。"}], "explanations": {"スペース": "「限られたスペース」で、狭い空き場所の意味が合います。", "時間": "形は合うが、アパートメントが時間を持つのは意味が合わない。", "予算": "形は合うが、アパートメントが予算を持つのは意味が合わない。", "速度": "形は合うが、アパートメントが速度を持つのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "スペース"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんにスペースを食べた。", "explanation": "スペースは空いた場所であり、食べ物ではないので「食べる」とは使えません。"}, {"text": "スペースが怒って部屋を出ていった。", "explanation": "スペースは場所や範囲で、人のように怒って出ていくことはありません。"}, {"text": "このスペースはとても甘くておいしい。", "explanation": "スペースは味のある物ではないので、「甘い」「おいしい」とは言えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51668, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スペース", "is_correct": true, "explanation": "「スペースがあればソファを置きたい」で、置く場所の意味が合います。"}, {"text": "雨", "is_correct": false, "explanation": "形は合うが、雨があればソファを置きたいとは言えず、意味が合わない。"}, {"text": "電話", "is_correct": false, "explanation": "形は合うが、電話とソファを置くことは結びつかず、意味が合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "形は合うが、眠気があればソファを置きたいとは言えず、意味が合わない。"}], "explanations": {"スペース": "「スペースがあればソファを置きたい」で、置く場所の意味が合います。", "雨": "形は合うが、雨があればソファを置きたいとは言えず、意味が合わない。", "電話": "形は合うが、電話とソファを置くことは結びつかず、意味が合わない。", "眠気": "形は合うが、眠気があればソファを置きたいとは言えず、意味が合わない。"}, "sentence_index": 6, "correct_answer": "スペース"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達にスペースを書いて手紙を送った。", "explanation": "スペースは空いた場所なので、手紙のように「書く」ものではありません。"}, {"text": "スペースが速く走って電車に乗り遅れた。", "explanation": "スペースは場所や範囲で、人のように走ることはありません。"}, {"text": "昨日、雨のスペースが空から降ってきた。", "explanation": "スペースは空き場所で、雨のように空から降る物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
