INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51669, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まちのなか", "primary_collocate": null, "pronunciation": "とかい", "ipa": "tokai", "syllable_count": 3, "sentences": [{"text": "都会は夜も明るい。", "target_word": "都会", "complexity_tier": "T1", "furigana": "都会[とかい]は夜[よる]も明[あか]るい。", "sentence_source": "generated"}, {"text": "都会の夜はにぎやかです。", "target_word": "都会", "complexity_tier": "T2", "furigana": "都会[とかい]の夜[よる]はにぎやかです。", "sentence_source": "generated"}, {"text": "休みの日は都会へ買い物に行く。", "target_word": "都会", "complexity_tier": "T2", "furigana": "休[やす]みの日[ひ]は都会[とかい]へ買[か]い物[もの]に行[い]く。", "sentence_source": "generated"}, {"text": "都会には高い建物が多い。", "target_word": "都会", "complexity_tier": "T2", "furigana": "都会[とかい]には高[たか]い建物[たてもの]が多[おお]い。", "sentence_source": "generated"}, {"text": "都会で電車に乗ると、人が多くて疲れる。", "target_word": "都会", "complexity_tier": "T3", "furigana": "都会[とかい]で電車[でんしゃ]に乗[の]ると、人[ひと]が多[おお]くて疲[つか]れる。", "sentence_source": "generated"}, {"text": "田舎と都会では、時間の流れ方が違う。", "target_word": "都会", "complexity_tier": "T3", "furigana": "田舎[いなか]と都会[とかい]では、時間[じかん]の流[なが]れ方[かた]が違[ちが]う。", "sentence_source": "generated"}, {"text": "都会を歩いていたら、昔の友達に会った。", "target_word": "都会", "complexity_tier": "T3", "furigana": "都会[とかい]を歩[ある]いていたら、昔[むかし]の友達[ともだち]に会[あ]った。", "sentence_source": "generated"}, {"text": "都会の空気はあまりきれいではない。", "target_word": "都会", "complexity_tier": "T3", "furigana": "都会[とかい]の空気[くうき]はあまりきれいではない。", "sentence_source": "generated"}, {"text": "都会に出かけるときは、いつも早く家を出る。", "target_word": "都会", "complexity_tier": "T3", "furigana": "都会[とかい]に出[で]かけるときは、いつも早[はや]く家[いえ]を出[で]る。", "sentence_source": "generated"}, {"text": "都会で働く人は、朝がとても早い。", "target_word": "都会", "complexity_tier": "T3", "furigana": "都会[とかい]で働[はたら]く人[ひと]は、朝[あさ]がとても早[はや]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "都会的", "label": "派生"}, {"form": "大都会", "label": "派生"}, {"form": "都会人", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 田舎に対する人の多い街の中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51669, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "都会", "is_correct": true, "explanation": "見出し語の「とかい」そのものです。"}, {"text": "とけい", "is_correct": false, "explanation": "「か」が「け」に変わった別の語(時計)です。"}, {"text": "たかい", "is_correct": false, "explanation": "最初の「と」が「た」に変わった別の語(高い)です。"}, {"text": "ちかい", "is_correct": false, "explanation": "最初の「と」が「ち」に変わった別の語(近い)です。"}, {"text": "つかい", "is_correct": false, "explanation": "最初の「と」が「つ」に変わった別の語(使い)です。"}], "explanations": {"都会": "見出し語の「とかい」そのものです。", "とけい": "「か」が「け」に変わった別の語(時計)です。", "たかい": "最初の「と」が「た」に変わった別の語(高い)です。", "ちかい": "最初の「と」が「ち」に変わった別の語(近い)です。", "つかい": "最初の「と」が「つ」に変わった別の語(使い)です。"}, "sentence_index": null, "correct_answer": "都会"}, "level_3": {"options": [{"text": "都会", "is_correct": true, "explanation": "夜も明るい場所として意味が合います。"}, {"text": "山", "is_correct": false, "explanation": "形は合うが意味が合わない。山は夜になると暗い所です。"}, {"text": "洞窟", "is_correct": false, "explanation": "形は合うが意味が合わない。洞窟は夜も昼も暗い所です。"}, {"text": "森", "is_correct": false, "explanation": "形は合うが意味が合わない。森は夜は暗いので意味が合いません。"}], "explanations": {"都会": "夜も明るい場所として意味が合います。", "山": "形は合うが意味が合わない。山は夜になると暗い所です。", "洞窟": "形は合うが意味が合わない。洞窟は夜も昼も暗い所です。", "森": "形は合うが意味が合わない。森は夜は暗いので意味が合いません。"}, "sentence_index": 0, "correct_answer": "都会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "都会には牛や羊の牧場が多く、静かな畑が広がっている。", "explanation": "牧場や畑が広がるのは田舎の特徴で、「都会」の意味に合いません。"}, {"text": "都会は高い建物で、中に三つの部屋があります。", "explanation": "「都会」は街全体を指し、一つの建物のことではありません。"}, {"text": "私は毎日、都会を二つ食べます。", "explanation": "「都会」は食べ物ではなく、「二つ」と数えることもできません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.