INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51670, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「都会は人が多い」と主題を示します。"}, {"text": "を", "is_correct": false, "explanation": "「多い」に対して「を」は使えません。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では文が成り立ちません。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では文が成り立ちません。"}], "correct_answer": "は", "explanations": {"は": "「都会は人が多い」と主題を示します。", "を": "「多い」に対して「を」は使えません。", "へ": "方向の「へ」では文が成り立ちません。", "から": "起点の「から」では文が成り立ちません。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "origin"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51670, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「都会の騒がしさ」と名詞をつなぎます。"}, {"text": "を", "is_correct": false, "explanation": "「都会を騒がしさ」では名詞同士がつながりません。"}, {"text": "へ", "is_correct": false, "explanation": "「都会へ騒がしさ」は文法的に成り立ちません。"}, {"text": "から", "is_correct": false, "explanation": "「都会から騒がしさ」は文法的に成り立ちません。"}], "correct_answer": "の", "explanations": {"の": "「都会の騒がしさ」と名詞をつなぎます。", "を": "「都会を騒がしさ」では名詞同士がつながりません。", "へ": "「都会へ騒がしさ」は文法的に成り立ちません。", "から": "「都会から騒がしさ」は文法的に成り立ちません。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "origin"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51670, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "都市。人が多く住み、商業や文化が発達した地域。", "primary_collocate": null, "pronunciation": "とかい", "ipa": "tokai", "syllable_count": 3, "sentences": [{"text": "都会の限られたスペースを持つアパートメントでは、モダンなインテリアデザインが空間の印象を大きく左右します。", "target_word": "都会", "complexity_tier": "T6", "furigana": "都会[とかい]の限[かぎ]られたスペースを持[も]つアパートメントでは、モダンなインテリアデザインが空間[くうかん]の印象[いんしょう]を大[おお]きく左右[さゆう]します。", "sentence_source": "mined"}, {"text": "都会は人が多いです。", "target_word": "都会", "complexity_tier": "T2", "furigana": "都会[とかい]は人[ひと]が多[おお]いです。", "sentence_source": "generated"}, {"text": "私は都会に住んでいます。", "target_word": "都会", "complexity_tier": "T3", "furigana": "私[わたし]は都会[とかい]に住[す]んでいます。", "sentence_source": "generated"}, {"text": "都会の生活は便利ですが、家賃が高いです。", "target_word": "都会", "complexity_tier": "T3", "furigana": "都会[とかい]の生活[せいかつ]は便利[べんり]ですが、家賃[やちん]が高[たか]いです。", "sentence_source": "generated"}, {"text": "祖父は都会で働くために村を出た。", "target_word": "都会", "complexity_tier": "T3", "furigana": "祖父[そふ]は都会[とかい]で働[はたら]くために村[むら]を出[で]た。", "sentence_source": "generated"}, {"text": "都会には大きな店や美術館がたくさんある。", "target_word": "都会", "complexity_tier": "T3", "furigana": "都会[とかい]には大[おお]きな店[みせ]や美術館[びじゅつかん]がたくさんある。", "sentence_source": "generated"}, {"text": "都会へ出てから、ずっと一人で暮らしている。", "target_word": "都会", "complexity_tier": "T3", "furigana": "都会[とかい]へ出[で]てから、ずっと一人[ひとり]で暮[く]らしている。", "sentence_source": "generated"}, {"text": "彼は都会の騒がしさに疲れてしまった。", "target_word": "都会", "complexity_tier": "T3", "furigana": "彼[かれ]は都会[とかい]の騒[さわ]がしさに疲[つか]れてしまった。", "sentence_source": "generated"}, {"text": "都会を離れて、海の近くの町に引っ越した。", "target_word": "都会", "complexity_tier": "T3", "furigana": "都会[とかい]を離[はな]れて、海[うみ]の近[ちか]くの町[まち]に引[ひ]っ越[こ]した。", "sentence_source": "generated"}, {"text": "もし都会で育っていたら、星を見る機会は少なかっただろう。", "target_word": "都会", "complexity_tier": "T4", "furigana": "もし都会[とかい]で育[そだ]っていたら、星[ほし]を見[み]る機会[きかい]は少[すく]なかっただろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "都会的", "label": "派生"}, {"form": "大都会", "label": "派生"}, {"form": "都会人", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人が多く商業や文化が栄える大きな街", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51670, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "都会", "is_correct": true, "explanation": "見出し語の「とかい」そのものです。"}, {"text": "とけい", "is_correct": false, "explanation": "「か」が「け」に変わった別の語(時計)です。"}, {"text": "たかい", "is_correct": false, "explanation": "最初の「と」が「た」に変わった別の語(高い)です。"}, {"text": "ちかい", "is_correct": false, "explanation": "最初の「と」が「ち」に変わった別の語(近い)です。"}, {"text": "つかい", "is_correct": false, "explanation": "最初の「と」が「つ」に変わった別の語(使い)です。"}], "explanations": {"都会": "見出し語の「とかい」そのものです。", "とけい": "「か」が「け」に変わった別の語(時計)です。", "たかい": "最初の「と」が「た」に変わった別の語(高い)です。", "ちかい": "最初の「と」が「ち」に変わった別の語(近い)です。", "つかい": "最初の「と」が「つ」に変わった別の語(使い)です。"}, "sentence_index": null, "correct_answer": "都会"}, "level_3": {"options": [{"text": "都会", "is_correct": true, "explanation": "限られたスペースのアパートメントがある場所として意味が合います。"}, {"text": "山奥", "is_correct": false, "explanation": "形は合うが意味が合わない。山奥でスペースが限られたアパートメントという文脈は不自然です。"}, {"text": "砂漠", "is_correct": false, "explanation": "形は合うが意味が合わない。砂漠にはアパートメントの空間事情という話が合いません。"}, {"text": "無人島", "is_correct": false, "explanation": "形は合うが意味が合わない。無人島にアパートメントは普通ありません。"}], "explanations": {"都会": "限られたスペースのアパートメントがある場所として意味が合います。", "山奥": "形は合うが意味が合わない。山奥でスペースが限られたアパートメントという文脈は不自然です。", "砂漠": "形は合うが意味が合わない。砂漠にはアパートメントの空間事情という話が合いません。", "無人島": "形は合うが意味が合わない。無人島にアパートメントは普通ありません。"}, "sentence_index": 0, "correct_answer": "都会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "都会は人が少なくて、店も学校もほとんどありません。", "explanation": "「都会」は人が多く商業が発達した所なので、人や店が少ないという使い方は意味が逆です。"}, {"text": "毎朝、都会を食べてから学校に行きます。", "explanation": "「都会」は場所なので、「食べる」の目的語にはなりません。"}, {"text": "昨日、都会を二本買いました。", "explanation": "「都会」は買える物ではなく、「二本」という数え方も合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXC