INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51670, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "都会", "is_correct": true, "explanation": "見出し語の「とかい」そのものです。"}, {"text": "とかげ", "is_correct": false, "explanation": "最後の「い」が「げ」に変わった別の語(トカゲ)です。"}, {"text": "しかい", "is_correct": false, "explanation": "最初の「と」が「し」に変わった別の語(司会)です。"}, {"text": "さかい", "is_correct": false, "explanation": "最初の「と」が「さ」に変わった別の語(境)です。"}, {"text": "あかい", "is_correct": false, "explanation": "最初の「と」が「あ」に変わった別の語(赤い)です。"}], "explanations": {"都会": "見出し語の「とかい」そのものです。", "とかげ": "最後の「い」が「げ」に変わった別の語(トカゲ)です。", "しかい": "最初の「と」が「し」に変わった別の語(司会)です。", "さかい": "最初の「と」が「さ」に変わった別の語(境)です。", "あかい": "最初の「と」が「あ」に変わった別の語(赤い)です。"}, "sentence_index": null, "correct_answer": "都会"}, "level_3": {"options": [{"text": "都会", "is_correct": true, "explanation": "「都会へ出る」は、人が多い大きな街に移り住むという意味で、一人で暮らし始める流れに合います。"}, {"text": "屋根", "is_correct": false, "explanation": "形は合うが意味が合わない。屋根へ出てずっと暮らすことはできません。"}, {"text": "廊下", "is_correct": false, "explanation": "形は合うが意味が合わない。廊下へ出てから暮らし続けるという意味になりません。"}, {"text": "天井", "is_correct": false, "explanation": "形は合うが意味が合わない。天井へ出るという状況が不自然です。"}], "explanations": {"都会": "「都会へ出る」は、人が多い大きな街に移り住むという意味で、一人で暮らし始める流れに合います。", "屋根": "形は合うが意味が合わない。屋根へ出てずっと暮らすことはできません。", "廊下": "形は合うが意味が合わない。廊下へ出てから暮らし続けるという意味になりません。", "天井": "形は合うが意味が合わない。天井へ出るという状況が不自然です。"}, "sentence_index": 6, "correct_answer": "都会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "もし都会で育っていたら、広い畑や山で毎日遊べただろう。", "explanation": "都会は畑や山のある所ではないので、「都会」の意味に合いません。"}, {"text": "もし都会を育てていたら、星を見る機会は少なかっただろう。", "explanation": "「都会」は育てる対象ではなく、育つ場所を表す語です。"}, {"text": "もし都会を泳いでいたら、星を見る機会は少なかっただろう。", "explanation": "「都会」は泳ぐ場所ではないので、動詞との組み合わせが不自然です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET 