INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51671, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が住むための、建物の中にある部屋です。", "primary_collocate": null, "pronunciation": "あぱーとめんと", "ipa": "apaːtomento", "syllable_count": 7, "sentences": [{"text": "アパートメントは駅から近い。", "target_word": "アパートメント", "complexity_tier": "T2", "furigana": "アパートメントは駅[えき]から近[ちか]い。", "sentence_source": "generated"}, {"text": "友達のアパートメントに遊びに行った。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "友達[ともだち]のアパートメントに遊[あそ]びに行[い]った。", "sentence_source": "generated"}, {"text": "このアパートメントには、エレベーターがありません。", "target_word": "アパートメント", "complexity_tier": "T4", "furigana": "このアパートメントには、エレベーターがありません。", "sentence_source": "generated"}, {"text": "昨日、アパートメントの鍵をなくしてしまった。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "昨日[きのう]、アパートメントの鍵[かぎ]をなくしてしまった。", "sentence_source": "generated"}, {"text": "アパートメントの部屋は二つあります。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "アパートメントの部屋[へや]は二[ふた]つあります。", "sentence_source": "generated"}, {"text": "私はアパートメントで猫と暮らしている。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "私[わたし]はアパートメントで猫[ねこ]と暮[く]らしている。", "sentence_source": "generated"}, {"text": "隣のアパートメントから音楽が聞こえる。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "隣[となり]のアパートメントから音楽[おんがく]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "アパートメントを出るとき、電気を消してください。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "アパートメントを出[で]るとき、電気[でんき]を消[け]してください。", "sentence_source": "generated"}, {"text": "彼女は海が見えるアパートメントを選んだ。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は海[うみ]が見[み]えるアパートメントを選[えら]んだ。", "sentence_source": "generated"}, {"text": "このアパートメントに住んで、もう五年になる。", "target_word": "アパートメント", "complexity_tier": "T4", "furigana": "このアパートメントに住[す]んで、もう五年[ごねん]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アパート", "label": "派生"}, {"form": "アパートメントホテル", "label": "派生"}, {"form": "アパートメントハウス", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人が住む建物の中の部屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51671, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アパートメント", "is_correct": true, "explanation": "駅から近い住まいとして意味が合います。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが意味が合わない。宿題が駅から近いという意味になりません。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気が駅から近いとは言えません。"}, {"text": "歌", "is_correct": false, "explanation": "形は合うが意味が合わない。歌が駅から近いという意味になりません。"}], "explanations": {"アパートメント": "駅から近い住まいとして意味が合います。", "宿題": "形は合うが意味が合わない。宿題が駅から近いという意味になりません。", "天気": "形は合うが意味が合わない。天気が駅から近いとは言えません。", "歌": "形は合うが意味が合わない。歌が駅から近いという意味になりません。"}, "sentence_index": 0, "correct_answer": "アパートメント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、アパートメントを一口で食べてしまった。", "explanation": "「アパートメント」は人が住む部屋で、食べる物ではありません。"}, {"text": "昨日、アパートメントを鍵の中になくしてしまった。", "explanation": "「アパートメント」は建物の部屋で、鍵の中になくせる物ではありません。"}, {"text": "昨日、アパートメントを財布に入れてしまった。", "explanation": "「アパートメント」は住むための部屋で、財布に入れられる物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51671, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アパートメント", "is_correct": true, "explanation": "隣の部屋(住まい)から音楽が聞こえるという意味が合います。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが意味が合わない。約束から音楽が聞こえることはありません。"}, {"text": "計画", "is_correct": false, "explanation": "形は合うが意味が合わない。計画から音楽が聞こえることはありません。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが意味が合わない。隣の辞書から音楽が聞こえるという状況は不自然です。"}], "explanations": {"アパートメント": "隣の部屋(住まい)から音楽が聞こえるという意味が合います。", "約束": "形は合うが意味が合わない。約束から音楽が聞こえることはありません。", "計画": "形は合うが意味が合わない。計画から音楽が聞こえることはありません。", "辞書": "形は合うが意味が合わない。隣の辞書から音楽が聞こえるという状況は不自然です。"}, "sentence_index": 6, "correct_answer": "アパートメント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このアパートメントを住んで、もう五年になる。", "explanation": "住む場所には「に」を使うので、「を」を使うのは誤りです。"}, {"text": "このアパートメントは、毎日空を飛んで五年になる。", "explanation": "「アパートメント」は建物の部屋で、空を飛ぶものではありません。"}, {"text": "このアパートメントを歌って、もう五年になる。", "explanation": "「アパートメント」は歌う対象ではなく、住む場所を表す語です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51671, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私はアパートメントを猫と暮らしている。", "corrected_sentence": "私はアパートメントで猫と暮らしている。", "error_description": "暮らす場所を表すには「を」ではなく「で」を使います。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51671, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "アパートメントが部屋は三つあります。", "corrected_sentence": "アパートメントの部屋は三つあります。", "error_description": "「アパートメントの部屋」と所属を表すには「が」ではなく「の」を使います。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51672, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「アパートメントでは」と場所を表します。"}, {"text": "を", "is_correct": false, "explanation": "「アパートメントをは」は文法的に成り立ちません。"}, {"text": "が", "is_correct": false, "explanation": "「アパートメントがは」は文法的に成り立ちません。"}, {"text": "の", "is_correct": false, "explanation": "「アパートメントのは」はこの位置で文法的に成り立ちません。"}], "correct_answer": "で", "explanations": {"で": "「アパートメントでは」と場所を表します。", "を": "「アパートメントをは」は文法的に成り立ちません。", "が": "「アパートメントがは」は文法的に成り立ちません。", "の": "「アパートメントのは」はこの位置で文法的に成り立ちません。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "の": "possessive"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51672, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「アパートメントで一人暮らし」と場所を表します。"}, {"text": "を", "is_correct": false, "explanation": "「アパートメントを一人暮らし」は文法的に成り立ちません。"}, {"text": "が", "is_correct": false, "explanation": "「アパートメントが一人暮らし」では意味が成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「アパートメントへ一人暮らし」は文法的に成り立ちません。"}], "correct_answer": "で", "explanations": {"で": "「アパートメントで一人暮らし」と場所を表します。", "を": "「アパートメントを一人暮らし」は文法的に成り立ちません。", "が": "「アパートメントが一人暮らし」では意味が成り立ちません。", "へ": "「アパートメントへ一人暮らし」は文法的に成り立ちません。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51672, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "一つの建物の中に、いくつかの独立した住居がある集合住宅の一室。", "primary_collocate": null, "pronunciation": "あぱーとめんと", "ipa": "apaːtomento", "syllable_count": 7, "sentences": [{"text": "都会の限られたスペースを持つアパートメントでは、モダンなインテリアデザインが空間の印象を大きく左右します。", "target_word": "アパートメント", "complexity_tier": "T6", "furigana": "都会[とかい]の限[かぎ]られたスペースを持[も]つアパートメントでは、モダンなインテリアデザインが空間[くうかん]の印象[いんしょう]を大[おお]きく左右[さゆう]します。", "sentence_source": "mined"}, {"text": "アパートメントを借りました。", "target_word": "アパートメント", "complexity_tier": "T2", "furigana": "アパートメントを借[か]りました。", "sentence_source": "generated"}, {"text": "私のアパートメントは三階にあります。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "私[わたし]のアパートメントは三階[さんがい]にあります。", "sentence_source": "generated"}, {"text": "駅の近くにアパートメントを探している。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くにアパートメントを探[さが]している。", "sentence_source": "generated"}, {"text": "このアパートメントはペットが飼えない。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "このアパートメントはペットが飼[か]えない。", "sentence_source": "generated"}, {"text": "アパートメントの家賃は毎月五万円だ。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "アパートメントの家賃[やちん]は毎月[まいつき]五万円[ごまんえん]だ。", "sentence_source": "generated"}, {"text": "新しいアパートメントに引っ越す予定だ。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "新[あたら]しいアパートメントに引[ひ]っ越[こ]す予定[よてい]だ。", "sentence_source": "generated"}, {"text": "兄はアパートメントで一人暮らしだ。", "target_word": "アパートメント", "complexity_tier": "T3", "furigana": "兄[あに]はアパートメントで一人暮[ひとりぐ]らしだ。", "sentence_source": "generated"}, {"text": "アパートメントが古くなったので、大家さんが直してくれた。", "target_word": "アパートメント", "complexity_tier": "T4", "furigana": "アパートメントが古[ふる]くなったので、大家[おおや]さんが直[なお]してくれた。", "sentence_source": "generated"}, {"text": "広いアパートメントに住めたら、犬を飼いたい。", "target_word": "アパートメント", "complexity_tier": "T4", "furigana": "広[ひろ]いアパートメントに住[す]めたら、犬[いぬ]を飼[か]いたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アパート", "label": "派生"}, {"form": "アパートメントホテル", "label": "派生"}, {"form": "アパートメントハウス", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 集合住宅の中にある独立した一室", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51672, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アパートメント", "is_correct": true, "explanation": "都会の限られたスペースを持つ住居として意味が合います。"}, {"text": "牧場", "is_correct": false, "explanation": "形は合うが意味が合わない。牧場のインテリアデザインという文脈は不自然です。"}, {"text": "滑走路", "is_correct": false, "explanation": "形は合うが意味が合わない。滑走路にインテリアデザインは関係ありません。"}, {"text": "墓地", "is_correct": false, "explanation": "形は合うが意味が合わない。墓地でモダンなインテリアを考える文脈になりません。"}], "explanations": {"アパートメント": "都会の限られたスペースを持つ住居として意味が合います。", "牧場": "形は合うが意味が合わない。牧場のインテリアデザインという文脈は不自然です。", "滑走路": "形は合うが意味が合わない。滑走路にインテリアデザインは関係ありません。", "墓地": "形は合うが意味が合わない。墓地でモダンなインテリアを考える文脈になりません。"}, "sentence_index": 0, "correct_answer": "アパートメント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅の近くにアパートメントを食べている。", "explanation": "「アパートメント」は住む建物の部屋で、食べる物ではありません。"}, {"text": "駅の近くのアパートメントは、水の中にだけ住む魚の名前だ。", "explanation": "「アパートメント」は魚の名前ではなく、住居の意味です。"}, {"text": "駅の近くにアパートメントを着ている。", "explanation": "「アパートメント」は着る物ではないので、動詞との組み合わせが誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51672, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アパートメント", "is_correct": true, "explanation": "引っ越す先の住居として意味が合います。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが意味が合わない。財布に引っ越すことはできません。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。新しい天気に引っ越すという意味になりません。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが意味が合わない。辞書に引っ越すことはできません。"}], "explanations": {"アパートメント": "引っ越す先の住居として意味が合います。", "財布": "形は合うが意味が合わない。財布に引っ越すことはできません。", "天気": "形は合うが意味が合わない。新しい天気に引っ越すという意味になりません。", "辞書": "形は合うが意味が合わない。辞書に引っ越すことはできません。"}, "sentence_index": 6, "correct_answer": "アパートメント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "広いアパートメントを食べられたら、犬を飼いたい。", "explanation": "「アパートメント」は住むための部屋で、食べる物ではありません。"}, {"text": "広いアパートメントを着られたら、犬を飼いたい。", "explanation": "「アパートメント」は着る物ではないので、動詞との組み合わせが誤りです。"}, {"text": "広いアパートメントが空を飛べたら、犬を飼いたい。", "explanation": "「アパートメント」は建物の中の部屋で、空を飛ぶものではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
