INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51673, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "新しい感じの、今のじだいの。", "primary_collocate": null, "pronunciation": "もだん", "ipa": "modan", "syllable_count": 3, "sentences": [{"text": "この店はモダンです。", "target_word": "モダン", "complexity_tier": "T2", "furigana": "この店[みせ]はモダンです。", "sentence_source": "generated"}, {"text": "モダンな服を着たい。", "target_word": "モダン", "complexity_tier": "T1", "furigana": "モダンな服[ふく]を着[き]たい。", "sentence_source": "generated"}, {"text": "このいすは形がモダンだ。", "target_word": "モダン", "complexity_tier": "T2", "furigana": "このいすは形[かたち]がモダンだ。", "sentence_source": "generated"}, {"text": "新しい駅はモダンで、きれいだ。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "新[あたら]しい駅[えき]はモダンで、きれいだ。", "sentence_source": "generated"}, {"text": "モダンな絵が好きな人が多い。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "モダンな絵[え]が好[す]きな人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "部屋をモダンにしたいと思っている。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "部屋[へや]をモダンにしたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "兄の家はモダンな作りだ。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "兄[あに]の家[いえ]はモダンな作[つく]りだ。", "sentence_source": "generated"}, {"text": "昔の家よりモダンな家のほうが住みやすい。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "昔[むかし]の家[いえ]よりモダンな家[いえ]のほうが住[す]みやすい。", "sentence_source": "generated"}, {"text": "古いお寺とモダンなビルが並んでいる。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "古[ふる]いお寺[てら]とモダンなビルが並[なら]んでいる。", "sentence_source": "generated"}, {"text": "この町は思ったよりモダンではなかった。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "この町[まち]は思[おも]ったよりモダンではなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "モダンな", "label": "活用"}, {"form": "モダンに", "label": "活用"}, {"form": "モダンさ", "label": "派生"}, {"form": "モダニズム", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 新しい感じで今の時代らしい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51673, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "モダン", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "むだん", "is_correct": false, "explanation": "「無断」。最初の一拍がモとムで違う。"}, {"text": "よだん", "is_correct": false, "explanation": "「予断」。最初の一拍がモとヨで違う。"}, {"text": "ごだん", "is_correct": false, "explanation": "「五段」。最初の一拍がモとゴで違う。"}, {"text": "セダン", "is_correct": false, "explanation": "車の種類。最初の一拍がモとセで違う。"}], "explanations": {"モダン": "見出し語そのもの。", "むだん": "「無断」。最初の一拍がモとムで違う。", "よだん": "「予断」。最初の一拍がモとヨで違う。", "ごだん": "「五段」。最初の一拍がモとゴで違う。", "セダン": "車の種類。最初の一拍がモとセで違う。"}, "sentence_index": null, "correct_answer": "モダン"}, "level_3": {"options": [{"text": "モダン", "is_correct": true, "explanation": "店が新しい感じで今風だという意味が合う。"}, {"text": "臆病", "is_correct": false, "explanation": "形は合うが、臆病は人や動物の性質で、店の様子として意味が合わない。"}, {"text": "乱暴", "is_correct": false, "explanation": "形は合うが、店の説明として意味が合わない。"}, {"text": "器用", "is_correct": false, "explanation": "形は合うが、器用は人の手先や能力を表し、店の様子として意味が合わない。"}], "explanations": {"モダン": "店が新しい感じで今風だという意味が合う。", "臆病": "形は合うが、臆病は人や動物の性質で、店の様子として意味が合わない。", "乱暴": "形は合うが、店の説明として意味が合わない。", "器用": "形は合うが、器用は人の手先や能力を表し、店の様子として意味が合わない。"}, "sentence_index": 0, "correct_answer": "モダン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "モダンな熱が出て、学校を休んだ。", "explanation": "熱をモダンとは言わない。新しい感じの物や様子に使う語である。"}, {"text": "弟はモダンに怒った。", "explanation": "怒り方の様子にモダンは使わない。新しい感じの物や様子に使う語である。"}, {"text": "犬がモダンに鳴いている。", "explanation": "鳴き方の様子にモダンは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51673, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "モダン", "is_correct": true, "explanation": "家の作りが新しく今風だという意味が合う。"}, {"text": "臆病", "is_correct": false, "explanation": "形は合うが、臆病は人や動物の性質で、家の作りとして意味が合わない。"}, {"text": "生意気", "is_correct": false, "explanation": "形は合うが、生意気は人の態度を表し、家の作りとして意味が合わない。"}, {"text": "熱心", "is_correct": false, "explanation": "形は合うが、家の作りとして意味が合わない。"}], "explanations": {"モダン": "家の作りが新しく今風だという意味が合う。", "臆病": "形は合うが、臆病は人や動物の性質で、家の作りとして意味が合わない。", "生意気": "形は合うが、生意気は人の態度を表し、家の作りとして意味が合わない。", "熱心": "形は合うが、家の作りとして意味が合わない。"}, "sentence_index": 6, "correct_answer": "モダン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "モダンな足が痛くて歩けない。", "explanation": "体の部位や痛みをモダンとは言わない。"}, {"text": "この古い寺は、モダンで昔の雰囲気が残っている。", "explanation": "昔の雰囲気が残る様子は、新しい今風の意味と矛盾する。"}, {"text": "雨がモダンに降っている。", "explanation": "雨の降り方にモダンは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51673, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町の新しい駅はモダンくてきれいだ。", "corrected_sentence": "この町の新しい駅はモダンできれいだ。", "error_description": "モダンは形容詞ではないので「モダンくて」は誤りで、「モダンで」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "モダン", "is_correct": true, "explanation": "語幹モダンに「な」が付いて、「モダンな服」になる。"}, {"text": "モダンな", "is_correct": false, "explanation": "すでに「な」を含むため、後ろの「な」と重なってしまう。"}, {"text": "モダンに", "is_correct": false, "explanation": "連用形で、後ろの「な」とつながらない。"}, {"text": "モダンさ", "is_correct": false, "explanation": "名詞化した形で、後ろの「な」とつながらない。"}], "correct_form": "モダン", "base_form": "モダン", "form_label": "語幹（な接続）", "sentence_index": 1, "explanations": {"モダン": "語幹モダンに「な」が付いて、「モダンな服」になる。", "モダンな": "すでに「な」を含むため、後ろの「な」と重なってしまう。", "モダンに": "連用形で、後ろの「な」とつながらない。", "モダンさ": "名詞化した形で、後ろの「な」とつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51673, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄の部屋はモダンの家具が多い。", "corrected_sentence": "兄の部屋はモダンな家具が多い。", "error_description": "形状詞のモダンが名詞を修飾するときは「モダンな」で、「モダンの」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "モダン", "is_correct": true, "explanation": "語幹モダンに「な」が付いて、「モダンな家」になる。"}, {"text": "モダンな", "is_correct": false, "explanation": "すでに「な」を含むため、後ろの「な」と重なる。"}, {"text": "モダンに", "is_correct": false, "explanation": "連用形で、後ろの「な」とつながらない。"}, {"text": "モダンさ", "is_correct": false, "explanation": "名詞化した形で、後ろの「な」とつながらない。"}], "correct_form": "モダン", "base_form": "モダン", "form_label": "語幹（な接続）", "sentence_index": 7, "explanations": {"モダン": "語幹モダンに「な」が付いて、「モダンな家」になる。", "モダンな": "すでに「な」を含むため、後ろの「な」と重なる。", "モダンに": "連用形で、後ろの「な」とつながらない。", "モダンさ": "名詞化した形で、後ろの「な」とつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
