INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51674, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "伝統的", "is_correct": true, "explanation": "昔から受け継がれた様子で、モダンの反対。"}, {"text": "有名", "is_correct": false, "explanation": "知られている様子で、モダンの反対ではない。"}, {"text": "安全", "is_correct": false, "explanation": "危険がない様子で、モダンの反対ではない。"}, {"text": "便利", "is_correct": false, "explanation": "役に立つ様子で、モダンの反対ではない。"}], "correct_answer": "伝統的", "explanations": {"伝統的": "昔から受け継がれた様子で、モダンの反対。", "有名": "知られている様子で、モダンの反対ではない。", "安全": "危険がない様子で、モダンの反対ではない。", "便利": "役に立つ様子で、モダンの反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51674, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "現代的な、最新の流行（りゅうこう）やデザインを取り入れた様子。", "primary_collocate": null, "pronunciation": "もだん", "ipa": "modan", "syllable_count": 3, "sentences": [{"text": "都会の限られたスペースを持つアパートメントでは、モダンなインテリアデザインが空間の印象を大きく左右します。", "target_word": "モダン", "complexity_tier": "T6", "furigana": "都会[とかい]の限[かぎ]られたスペースを持[も]つアパートメントでは、モダンなインテリアデザインが空間[くうかん]の印象[いんしょう]を大[おお]きく左右[さゆう]します。", "sentence_source": "mined"}, {"text": "このビルはとてもモダンです。", "target_word": "モダン", "complexity_tier": "T2", "furigana": "このビルはとてもモダンです。", "sentence_source": "generated"}, {"text": "モダンな家具が好きです。", "target_word": "モダン", "complexity_tier": "T2", "furigana": "モダンな家具[かぐ]が好[す]きです。", "sentence_source": "generated"}, {"text": "彼女の部屋はモダンで明るい。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の部屋[へや]はモダンで明[あか]るい。", "sentence_source": "generated"}, {"text": "古い建物をモダンに作り直した。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]をモダンに作[つく]り直[なお]した。", "sentence_source": "generated"}, {"text": "モダンなデザインのいすを買った。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "モダンなデザインのいすを買[か]った。", "sentence_source": "generated"}, {"text": "その店は外から見るとモダンだが、中は昔のままだ。", "target_word": "モダン", "complexity_tier": "T4", "furigana": "その店[みせ]は外[そと]から見[み]るとモダンだが、中[なか]は昔[むかし]のままだ。", "sentence_source": "generated"}, {"text": "私が育った家は、あまりモダンではなかった。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "私[わたし]が育[そだ]った家[いえ]は、あまりモダンではなかった。", "sentence_source": "generated"}, {"text": "モダンな建築で知られる美術館に行った。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "モダンな建築[けんちく]で知[し]られる美術館[びじゅつかん]に行[い]った。", "sentence_source": "generated"}, {"text": "祖母の着物をモダンに着こなす女性が増えた。", "target_word": "モダン", "complexity_tier": "T3", "furigana": "祖母[そぼ]の着物[きもの]をモダンに着[き]こなす女性[じょせい]が増[ふ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "モダンな", "label": "活用"}, {"form": "モダンに", "label": "活用"}, {"form": "モダンさ", "label": "派生"}, {"form": "モダニズム", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 流行を取り入れた現代的な様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51674, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "モダン", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "むだん", "is_correct": false, "explanation": "「無断」。最初の一拍がモとムで違う。"}, {"text": "よだん", "is_correct": false, "explanation": "「予断」。最初の一拍がモとヨで違う。"}, {"text": "ごだん", "is_correct": false, "explanation": "「五段」。最初の一拍がモとゴで違う。"}, {"text": "セダン", "is_correct": false, "explanation": "車の種類。最初の一拍がモとセで違う。"}], "explanations": {"モダン": "見出し語そのもの。", "むだん": "「無断」。最初の一拍がモとムで違う。", "よだん": "「予断」。最初の一拍がモとヨで違う。", "ごだん": "「五段」。最初の一拍がモとゴで違う。", "セダン": "車の種類。最初の一拍がモとセで違う。"}, "sentence_index": null, "correct_answer": "モダン"}, "level_3": {"options": [{"text": "モダン", "is_correct": true, "explanation": "インテリアデザインを修飾でき、現代的という意味が合う。"}, {"text": "臆病", "is_correct": false, "explanation": "形は合うが、臆病は人や動物の性質で、インテリアデザインの説明として意味が合わない。"}, {"text": "器用", "is_correct": false, "explanation": "形は合うが、器用は人の能力を表し、デザインの様子として意味が合わない。"}, {"text": "勤勉", "is_correct": false, "explanation": "形は合うが、勤勉は人の性格を表し、デザインの特徴として意味が合わない。"}], "explanations": {"モダン": "インテリアデザインを修飾でき、現代的という意味が合う。", "臆病": "形は合うが、臆病は人や動物の性質で、インテリアデザインの説明として意味が合わない。", "器用": "形は合うが、器用は人の能力を表し、デザインの様子として意味が合わない。", "勤勉": "形は合うが、勤勉は人の性格を表し、デザインの特徴として意味が合わない。"}, "sentence_index": 0, "correct_answer": "モダン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "モダンな歯が痛くて、歯医者に行った。", "explanation": "体の部位をモダンとは言わない。デザインや雰囲気が現代的な様子を表す語である。"}, {"text": "千年前から変わらないモダンな習慣を守っている。", "explanation": "モダンは新しい、現代的という意味なので、千年変わらない習慣とは矛盾する。"}, {"text": "彼は毎朝モダンに走っている。", "explanation": "モダンに走るという使い方はない。走り方の様子は現代的とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51674, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "モダン", "is_correct": true, "explanation": "外観が現代的で、中は昔のままという対比が成り立つ。"}, {"text": "正直", "is_correct": false, "explanation": "形は合うが、店の外観の説明として意味が合わない。"}, {"text": "乱暴", "is_correct": false, "explanation": "形は合うが、外から見た店の様子として意味が合わない。"}, {"text": "大切", "is_correct": false, "explanation": "形は合うが、中が昔のままという対比として意味が合わない。"}], "explanations": {"モダン": "外観が現代的で、中は昔のままという対比が成り立つ。", "正直": "形は合うが、店の外観の説明として意味が合わない。", "乱暴": "形は合うが、外から見た店の様子として意味が合わない。", "大切": "形は合うが、中が昔のままという対比として意味が合わない。"}, "sentence_index": 6, "correct_answer": "モダン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨がモダンに降っている。", "explanation": "モダンは雨の降り方を表す語ではない。デザインなどが現代的な様子に使う。"}, {"text": "モダンな風邪をひいてしまった。", "explanation": "病気をモダンとは言わない。流行やデザインに関する語である。"}, {"text": "昔ながらの方法をそのまま使う、とてもモダンな人だ。", "explanation": "昔ながらを守る人はモダンの意味と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51674, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その美術館はモダンの建築で有名だ。", "corrected_sentence": "その美術館はモダンな建築で有名だ。", "error_description": "形状詞のモダンが名詞を修飾するときは「モダンな」で、「モダンの」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "モダン", "is_correct": true, "explanation": "語幹のままで「です」に続く。"}, {"text": "モダンな", "is_correct": false, "explanation": "連体形なので、「です」の前には置けない。"}, {"text": "モダンに", "is_correct": false, "explanation": "連用形なので、「です」の前には置けない。"}, {"text": "モダンさ", "is_correct": false, "explanation": "名詞化した形なので、「とても…です」の形に合わない。"}], "correct_form": "モダン", "base_form": "モダン", "form_label": "語幹（です接続）", "sentence_index": 1, "explanations": {"モダン": "語幹のままで「です」に続く。", "モダンな": "連体形なので、「です」の前には置けない。", "モダンに": "連用形なので、「です」の前には置けない。", "モダンさ": "名詞化した形なので、「とても…です」の形に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51674, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい店の内装はモダンくて素敵だ。", "corrected_sentence": "新しい店の内装はモダンで素敵だ。", "error_description": "モダンは形容詞ではないので「モダンくて」とは言えず、「モダンで」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "モダン", "is_correct": true, "explanation": "語幹のままで「ではなかった」に続く。"}, {"text": "モダンな", "is_correct": false, "explanation": "連体形なので「ではなかった」に続かない。"}, {"text": "モダンに", "is_correct": false, "explanation": "連用形なので「ではなかった」に続かない。"}, {"text": "モダンさ", "is_correct": false, "explanation": "名詞化した形で「ではなかった」に続かない。"}], "correct_form": "モダン", "base_form": "モダン", "form_label": "語幹（ではない接続）", "sentence_index": 7, "explanations": {"モダン": "語幹のままで「ではなかった」に続く。", "モダンな": "連体形なので「ではなかった」に続かない。", "モダンに": "連用形なので「ではなかった」に続かない。", "モダンさ": "名詞化した形で「ではなかった」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51675, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「好き」の対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "「インテリアに好きで」は文にならない。"}, {"text": "と", "is_correct": false, "explanation": "「インテリアと好きで」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "へは方向を表すので、好きの対象には使えない。"}], "correct_answer": "が", "explanations": {"が": "「好き」の対象を表す。", "に": "「インテリアに好きで」は文にならない。", "と": "「インテリアと好きで」は文として成り立たない。", "へ": "へは方向を表すので、好きの対象には使えない。"}, "error_tags": {"に": "target", "と": "comitative", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "エクステリア", "is_correct": true, "explanation": "建物の外まわりのことで、室内のインテリアの反対。"}, {"text": "内装", "is_correct": false, "explanation": "インテリアと近い意味で、反対ではない。"}, {"text": "色", "is_correct": false, "explanation": "装飾の要素で、反対の関係ではない。"}, {"text": "飾り", "is_correct": false, "explanation": "インテリアに近い意味で、反対ではない。"}], "correct_answer": "エクステリア", "explanations": {"エクステリア": "建物の外まわりのことで、室内のインテリアの反対。", "内装": "インテリアと近い意味で、反対ではない。", "色": "装飾の要素で、反対の関係ではない。", "飾り": "インテリアに近い意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51675, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "インテリアを主題として取り上げ、「性格を表す」とつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "後ろにも「を」があり、目的語が重なって文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "へは方向を表すので、主題として使えない。"}, {"text": "と", "is_correct": false, "explanation": "「インテリアと、…性格を表す」では主語がなく文にならない。"}], "correct_answer": "は", "explanations": {"は": "インテリアを主題として取り上げ、「性格を表す」とつなぐ。", "を": "後ろにも「を」があり、目的語が重なって文にならない。", "へ": "へは方向を表すので、主題として使えない。", "と": "「インテリアと、…性格を表す」では主語がなく文にならない。"}, "error_tags": {"を": "object", "へ": "direction", "と": "comitative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外観", "is_correct": true, "explanation": "外から見た様子で、中の見た目のインテリアの反対。"}, {"text": "照明", "is_correct": false, "explanation": "室内の要素で、反対の関係ではない。"}, {"text": "床", "is_correct": false, "explanation": "部屋の一部で、反対の関係ではない。"}, {"text": "雑貨", "is_correct": false, "explanation": "飾りに使う物で、反対の関係ではない。"}], "correct_answer": "外観", "explanations": {"外観": "外から見た様子で、中の見た目のインテリアの反対。", "照明": "室内の要素で、反対の関係ではない。", "床": "部屋の一部で、反対の関係ではない。", "雑貨": "飾りに使う物で、反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51675, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "部屋の中の見た目や飾りつけのこと。", "primary_collocate": null, "pronunciation": "いんてりあ", "ipa": "interia", "syllable_count": 5, "sentences": [{"text": "この部屋のインテリアは素敵です。", "target_word": "インテリア", "complexity_tier": "T2", "furigana": "この部屋[へや]のインテリアは素敵[すてき]です。", "sentence_source": "generated"}, {"text": "インテリアが好きで、よく店を見に行く。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "インテリアが好[す]きで、よく店[みせ]を見[み]に行[い]く。", "sentence_source": "generated"}, {"text": "彼は部屋のインテリアに合う花を選んだ。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "彼[かれ]は部屋[へや]のインテリアに合[あ]う花[はな]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "友達の家はインテリアがおしゃれだ。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "友達[ともだち]の家[いえ]はインテリアがおしゃれだ。", "sentence_source": "generated"}, {"text": "新しいインテリアで、部屋がずいぶん変わった。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "新[あたら]しいインテリアで、部屋[へや]がずいぶん変[か]わった。", "sentence_source": "generated"}, {"text": "インテリアにお金をかけすぎてしまった。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "インテリアにお金[かね]をかけすぎてしまった。", "sentence_source": "generated"}, {"text": "雑誌のインテリア写真を見ながら、ソファを探した。", "target_word": "インテリア", "complexity_tier": "T4", "furigana": "雑誌[ざっし]のインテリア写真[しゃしん]を見[み]ながら、ソファを探[さが]した。", "sentence_source": "generated"}, {"text": "部屋のインテリアは、住む人の性格を表す。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "部屋[へや]のインテリアは、住[す]む人[ひと]の性格[せいかく]を表[あらわ]す。", "sentence_source": "generated"}, {"text": "インテリアを楽しむために、毎月花を飾っている。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "インテリアを楽[たの]しむために、毎月[まいつき]花[はな]を飾[かざ]っている。", "sentence_source": "generated"}, {"text": "インテリアの色を変えたら、気分も明るくなった。", "target_word": "インテリア", "complexity_tier": "T4", "furigana": "インテリアの色[いろ]を変[か]えたら、気分[きぶん]も明[あか]るくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "インテリアデザイン", "label": "派生"}, {"form": "インテリアショップ", "label": "派生"}, {"form": "インテリアコーディネーター", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 部屋の中の見た目や飾りつけ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51675, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インテリア", "is_correct": true, "explanation": "部屋の飾りつけが素敵だという意味が合う。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、部屋の「野菜が素敵」では意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、部屋の天気という意味が合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが、部屋の宿題を素敵と言うのは意味が合わない。"}], "explanations": {"インテリア": "部屋の飾りつけが素敵だという意味が合う。", "野菜": "形は合うが、部屋の「野菜が素敵」では意味が合わない。", "天気": "形は合うが、部屋の天気という意味が合わない。", "宿題": "形は合うが、部屋の宿題を素敵と言うのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "インテリア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夜、インテリアを歌って練習した。", "explanation": "インテリアは歌うものではなく、部屋の飾りつけを指す。"}, {"text": "駅の近くにインテリアが泳いでいる。", "explanation": "インテリアは生き物ではなく、泳がない。"}, {"text": "インテリアが痛くて病院に行った。", "explanation": "インテリアは体の部位ではなく、痛くならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
